CREATE OR REPLACE FUNCTION "public"."_award_badge_if_absent"("p_user" "uuid", "p_badge_key" "text", "p_rule_key" "text", "p_sport" "text", "p_context" "jsonb" DEFAULT '{}'::"jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare bid uuid;
begin
  select public.badge_id_by_key(p_badge_key) into bid;
  if bid is null then
    return false;
  end if;

  insert into public.user_badges(user_id, badge_id, sport, source_rule_key, context)
  values (p_user, bid, p_sport, p_rule_key, coalesce(p_context, '{}'::jsonb))
  on conflict (user_id, badge_id) do nothing;

  return found;
end;
$$;


ALTER FUNCTION "public"."_award_badge_if_absent"("p_user" "uuid", "p_badge_key" "text", "p_rule_key" "text", "p_sport" "text", "p_context" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_award_points"("p_user" "uuid", "p_points" integer, "p_reason_key" "text", "p_rule_key" "text", "p_sport" "text", "p_event_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare rid uuid;
begin
  if p_points = 0 then
    return null;
  end if;

  insert into public.point_ledger(user_id, sport, delta, reason_key, rule_key, source_event_id, created_by)
  values (p_user, p_sport, p_points, p_reason_key, p_rule_key, p_event_id, auth.uid())
  returning id into rid;

  return rid;
exception when unique_violation then
  -- Idempotent when same (user,rule,event_id) already recorded
  return null;
end;
$$;


ALTER FUNCTION "public"."_award_points"("p_user" "uuid", "p_points" integer, "p_reason_key" "text", "p_rule_key" "text", "p_sport" "text", "p_event_id" "uuid") OWNER TO "postgres";


