CREATE OR REPLACE FUNCTION "public"."_clamp01"("x" numeric) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select case
           when x < 0 then 0::numeric
           when x > 1 then 1::numeric
           else x
         end
$$;


