CREATE OR REPLACE FUNCTION "public"."_compute_slot_price_for_window"("p_space_id" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone) RETURNS numeric
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with ctx as (
    select v.timezone tz
    from public.venue_spaces s
    join public.venues v on v.id = s.venue_id
    where s.id = p_space_id
  ),
  wd as (
    select extract(dow from p_start at time zone (select tz from ctx))::int as weekday
  )
  select round(
           coalesce((
             select sp.price_per_hour_aed * (extract(epoch from (p_end - p_start)) / 3600.0)
             from public.space_prices sp
             where sp.venue_space_id = p_space_id
               and sp.is_active = true
               and sp.weekday = (select weekday from wd)
               and (p_start::time >= sp.start_time and p_end::time <= sp.end_time)
             order by sp.start_time asc
             limit 1
           ), 0)::numeric, 2
         )
$$;


ALTER FUNCTION "public"."_compute_slot_price_for_window"("p_space_id" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_conditions_match"("p_conditions" "jsonb", "p_sport" "text", "p_ctx" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare sport_ok boolean := true;
begin
  if (p_conditions ? 'sport') then
    sport_ok := (p_conditions->>'sport') is not distinct from p_sport;
    if not sport_ok then return false; end if;
  end if;

  if (p_conditions ? 'min_capacity') then
    if coalesce((p_ctx->>'capacity')::int, 0) < (p_conditions->>'min_capacity')::int then
      return false;
    end if;
  end if;

  if (p_conditions ? 'min_team_size') then
    if coalesce((p_ctx->>'team_size')::int, 0) < (p_conditions->>'min_team_size')::int then
      return false;
    end if;
  end if;

  return true;
end;
$$;


ALTER FUNCTION "public"."_conditions_match"("p_conditions" "jsonb", "p_sport" "text", "p_ctx" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_consume_link_token"("p_game" "uuid", "p_token" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  UPDATE public.game_link_tokens
  SET used_count = used_count + 1
  WHERE game_id = p_game AND token = p_token AND active = true
    AND (expires_at IS NULL OR now() < expires_at)
    AND (max_uses IS NULL OR used_count < max_uses);
  IF NOT FOUND THEN
    RAISE EXCEPTION USING errcode='P0001', message='invalid_or_expired_link';
  END IF;
END;
$$;


