    AS $$
DECLARE
  v_sub text;
  v_uid uuid;
  v_claims text;
BEGIN
  v_sub := current_setting('request.jwt.claim.sub', true);
  v_uid := auth.uid();
  v_claims := current_setting('request.jwt.claims', true);
  
  RAISE LOG 'DEBUG_CAN_VIEW: post_id=%, sub=%, uid=%, claims=%', 
    p_post_id, v_sub, v_uid, LEFT(v_claims, 200);
    
  RETURN can_view_post(p_post_id, v_uid, NULL::uuid);
END;
$$;


