CREATE OR REPLACE FUNCTION "public"."_decay_factor"("p_event_at" timestamp with time zone, "p_half_life_days" integer) RETURNS numeric
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select case when coalesce(p_half_life_days,0) <= 0
              then 1.0
              else power(0.5, greatest(0.0, extract(epoch from (now() - p_event_at))/86400.0) / p_half_life_days)
         end::numeric
$$;


ALTER FUNCTION "public"."_decay_factor"("p_event_at" timestamp with time zone, "p_half_life_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_engagement_score"("p_post_id" "uuid", "p_half_life_hours" integer DEFAULT 24, "p_cap" integer DEFAULT 100) RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH l AS (
    SELECT count(*) AS n,
           coalesce(sum(public._time_decay(lk.created_at, p_half_life_hours)), 0)::numeric AS decayed
    FROM public.likes lk
    WHERE lk.parent_activity_id = p_post_id
  ),
  c AS (
    SELECT count(*) AS n,
           coalesce(sum(public._time_decay(pc.created_at, p_half_life_hours)), 0)::numeric AS decayed
    FROM public.comments pc
    WHERE pc.parent_activity_id = p_post_id
      AND pc.is_hidden_admin = false AND pc.is_deleted = false
  )
  SELECT
    public._clamp01((LEAST((SELECT n FROM l) + (SELECT n FROM c)*2, p_cap::numeric)) / p_cap) * 0.5
  + public._clamp01(((SELECT decayed FROM l) + 2*(SELECT decayed FROM c)) / p_cap::numeric) * 0.5;
$$;


ALTER FUNCTION "public"."_engagement_score"("p_post_id" "uuid", "p_half_life_hours" integer, "p_cap" integer) OWNER TO "postgres";


