    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with u1f as (
    select case when user_a = u1 then user_b else user_a end as friend
    from public.friend_edges
    where status='accepted' and u1 in (user_a,user_b)
  ),
  u2f as (
    select case when user_a = u2 then user_b else user_a end as friend
    from public.friend_edges
    where status='accepted' and u2 in (user_a,user_b)
  )
  select count(*) from u1f join u2f using (friend)
