CREATE OR REPLACE FUNCTION "public"."_post_search_vector"("p_post_id" "uuid") RETURNS "tsvector"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH post_data AS (
    SELECT p.body, p.vibe_id
    FROM public.posts p
    WHERE p.id = p_post_id
  ),
  vocab AS (
    SELECT string_agg(v.label_en || ' ' || coalesce(v.label_ar, ''), ' ') AS txt
    FROM public.vibes v
    WHERE v.id = (SELECT vibe_id FROM post_data)
  )
  SELECT
    setweight(
      to_tsvector('simple', unaccent(coalesce((SELECT txt FROM vocab), ''))),
      'B'
    ) ||
    setweight(
      to_tsvector('simple', unaccent(coalesce((SELECT body FROM post_data), ''))),
      'A'
    )
$$;


