CREATE OR REPLACE FUNCTION "public"."_squad_link_consume"("p_squad" "uuid", "p_token" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  UPDATE public.squad_link_tokens
     SET used_count = used_count + 1
   WHERE squad_id=p_squad AND token=p_token AND active=true
     AND (expires_at IS NULL OR now() < expires_at)
     AND (max_uses IS NULL OR used_count < max_uses);
  IF NOT FOUND THEN
    RAISE EXCEPTION USING errcode='P0001', message='invalid_or_expired_link';
  END IF;
END;
$$;


