CREATE OR REPLACE FUNCTION "public"."_time_decay"("p_ts" timestamp with time zone, "p_half_life_hours" integer) RETURNS numeric
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select case
    when p_ts is null or p_half_life_hours <= 0 then 1.0
    else power(0.5, greatest(0.0, extract(epoch from (now() - p_ts)) / 3600.0) / p_half_life_hours)
  end::numeric
$$;


