CREATE OR REPLACE FUNCTION "public"."_you_invited"("p_game_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  has_to_user    boolean := public._column_exists('public','game_invites','to_user_id');
  has_to_profile boolean := public._column_exists('public','game_invites','to_profile_id');
  v_sql text;
  v_bool boolean;
begin
  if has_to_user and has_to_profile then
    v_sql := $q$
      select exists (
        select 1 from public.game_invites i
        where i.game_id = $1
          and i.status  = 'pending'
          and (i.to_user_id = auth.uid()
               or i.to_profile_id in (select id from public.profiles where user_id = auth.uid()))
      )
    $q$;
  elsif has_to_profile then
    v_sql := $q$
      select exists (
        select 1 from public.game_invites i
        where i.game_id = $1
          and i.status  = 'pending'
          and i.to_profile_id in (select id from public.profiles where user_id = auth.uid())
      )
    $q$;
  elsif has_to_user then
    v_sql := $q$
      select exists (
        select 1 from public.game_invites i
        where i.game_id = $1
          and i.status  = 'pending'
          and i.to_user_id = auth.uid()
      )
    $q$;
  else
    return false;
  end if;

  execute v_sql using p_game_id into v_bool;
  return coalesce(v_bool,false);
end;
$_$;


