CREATE OR REPLACE FUNCTION "public"."actor_can"("p_profile_id" "uuid", "p_action" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  case p_action
    when 'host' then
      return public.actor_is_organiser(p_profile_id);
    when 'join_game' then
      return public.actor_is_player(p_profile_id);
    when 'create_squad' then
      -- Player: max 1 active per sport (enforced later in Squads spec) OR Organiser: unlimited
      return public.actor_is_player(p_profile_id) or public.actor_is_organiser(p_profile_id);
    when 'post' then
      -- Both can post; context labels in content layer
      return public.actor_is_player(p_profile_id) or public.actor_is_organiser(p_profile_id);
    else
      return false;
  end case;
end;
$$;


