CREATE OR REPLACE FUNCTION "public"."admin_actor"() RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v uuid;
begin
  -- normal path (app / PostgREST): JWT present
  v := public.whoami_effective();
  if v is not null then
    return v;
  end if;

  -- editor convenience: if running as database superuser in SQL editor, pick an admin
  if current_user = 'postgres' then
    select rg.user_id
    into v
    from public.role_grants rg
    where rg.role = 'admin'
    order by rg.granted_at desc
    limit 1;

    return v; -- can still be NULL if no admin exists yet
  end if;

  return null;
end;
$$;


