COMMENT ON TABLE "public"."payouts" IS 'User-initiated withdrawals. Approval/processing by admin or automated ops moves money and posts ledger debits.';



CREATE OR REPLACE FUNCTION "public"."admin_approve_payout"("p_payout_id" "uuid") RETURNS "public"."payouts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  po public.payouts;
begin
  if not public.is_admin(me) then raise exception using errcode='P0001', message='forbidden'; end if;

  update public.payouts
  set status='approved', approved_at=now()
  where id = p_payout_id and status='requested'
  returning * into po;

  if po.id is null then raise exception using errcode='P0001', message='invalid_state'; end if;

  -- Flip pending debit to posted
  update public.wallet_ledger
  set status='posted'
  where ref_type='payout' and ref_id = p_payout_id and status='pending';

  return po;
end;
$$;


