CREATE OR REPLACE FUNCTION "public"."admin_mark_payout_paid"("p_payout_id" "uuid", "p_meta" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."payouts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  po public.payouts;
begin
  if not public.is_admin(me) then raise exception using errcode='P0001', message='forbidden'; end if;

  update public.payouts
  set status='paid', paid_at=now(), meta = coalesce(meta,'{}'::jsonb) || p_meta
  where id = p_payout_id and status in ('processing','approved')
  returning * into po;

  if po.id is null then raise exception using errcode='P0001', message='invalid_state'; end if;
  return po;
end;
$$;


