CREATE OR REPLACE FUNCTION "public"."admin_resolve_report"("p_report_id" "uuid", "p_status" "public"."report_status", "p_resolution" "text" DEFAULT NULL::"text", "p_duplicate_of" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."moderation_reports"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  row public.moderation_reports;
begin
  if not public.is_admin(auth.uid()) then
    raise exception using errcode = 'P0001', message = 'forbidden';
  end if;

  if p_status not in ('triage','escalated','resolved','dismissed','duplicate') then
    raise exception using errcode = 'P0001', message = 'invalid_status';
  end if;

  update public.moderation_reports
  set status      = p_status,
      resolution  = p_resolution,
      duplicate_of = p_duplicate_of,
      reviewed_by = auth.uid(),
      reviewed_at = now()
  where id = p_report_id
  returning * into row;

  if row.id is null then
    raise exception using errcode = 'P0001', message = 'not_found';
  end if;

  perform public.audit_log(
    'mod.report_status',
    row.target_type,
    row.target_id,
    row.target_user_id,
    jsonb_build_object(
      'report_id',  row.id,
      'status',     row.status,
      'resolution', row.resolution
    )
  );

  return row;
end;
$$;


