CREATE OR REPLACE FUNCTION "public"."admin_scrub_posts_body"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $_$
declare
  v_count  int  := 0;
  v_sample jsonb := '[]'::jsonb;
begin
  with cand as (
    select
      p.id,
      p.body,
      -- 1) drop trailing time block after an em dash
      -- 2) drop preposition+sport (" at|for|في Padel…")
      -- 3) drop any remaining standalone sport tokens
      -- 4) trim stray trailing em dash, collapse spaces, trim ends
      btrim(
        regexp_replace(                                      -- collapse multi-spaces
          regexp_replace(                                    -- drop trailing lone em dash (if any)
            regexp_replace(                                  -- drop remaining standalone sport tokens
              regexp_replace(                                -- drop " at|for|في <sport>"
                regexp_replace(                              -- drop "— Ddd Mon DD HH:MI" at end
                  p.body,
                  E'\\s*—\\s*(Mon|Tue|Wed|Thu|Fri|Sat|Sun)\\s+[A-Za-z]{3}\\s+\\d{1,2}\\s+\\d{2}:\\d{2}\\s*$',
                  '',
                  'i'
                ),
                '(?i)(\\s+(at|for|في)\\s+)(Padel Doubles|Indoor Cricket|Football|Cricket|Padel)(?=\\b)',
                ' ',
                'g'
              ),
              '(?i)\\b(Padel Doubles|Indoor Cricket|Football|Cricket|Padel)\\b',
              '',
              'g'
            ),
            '\\s*—\\s*$',
            '',
            'g'
          ),
          '\\s{2,}',
          ' ',
          'g'
        )
      ) as cleaned
    from public.posts p
    where p.body is not null
      and (
        p.body ~* '(Padel Doubles|Indoor Cricket|Football|Cricket|Padel)'
        or p.body ~ E'—\\s*(Mon|Tue|Wed|Thu|Fri|Sat|Sun)\\s+[A-Za-z]{3}\\s+\\d{1,2}\\s+\\d{2}:\\d{2}\\s*$'
      )
  ),
  upd as (
    update public.posts p
       set body = c.cleaned
    from cand c
    where p.id = c.id
      and p.body is distinct from c.cleaned
    returning p.id, left(p.body, 80) as before, left(c.cleaned, 80) as after
  )
  select
    count(*)::int,
    coalesce(
      (select jsonb_agg(jsonb_build_object('id', id, 'before', before, 'after', after))
         from (select * from upd limit 12) s),
      '[]'::jsonb
    )
  into v_count, v_sample;

  return jsonb_build_object('rows_updated', v_count, 'sample', v_sample);
end;
$_$;


ALTER FUNCTION "public"."admin_scrub_posts_body"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_scrub_posts_body_v3"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $_$
declare
  v_count  int  := 0;
  v_sample jsonb := '[]'::jsonb;
begin
  with cand as (
    select
      p.id,
      p.body,
      -- Order: 1) drop trailing time; 2) drop "<prep> <sport>" anywhere; 3) drop standalone sport tokens;
      --        4) drop dangling trailing em dash; 5) collapse spaces; 6) trim ends.
      btrim(
        regexp_replace(                                      -- collapse multi-spaces
          regexp_replace(                                    -- drop trailing em dash if left alone
            regexp_replace(                                  -- drop standalone sport tokens
              regexp_replace(                                -- drop "<prep> <sport>" anywhere
                regexp_replace(                              -- drop trailing "— Ddd Mon DD HH:MI"
                  p.body,
                  E'\\s*—\\s*(Mon|Tue|Wed|Thu|Fri|Sat|Sun)\\s+[A-Za-z]{3}\\s+\\d{1,2}\\s+\\d{2}:\\d{2}\\s*$',
                  '',
                  'i'
                ),
                -- optional start or whitespace, then preposition (EN/AR), then sport name
                -- replace with a single space; later we collapse spaces.
                '(?i)(^|\\s+)(?:at|for|في|من\\s+أجواء)\\s+(?:Padel Doubles|Indoor Cricket|Football|Cricket|Padel)(?=($|\\s|[[:punct:]]))',
                ' ',
                'g'
              ),
              '(?i)\\b(Padel Doubles|Indoor Cricket|Football|Cricket|Padel)\\b',
              '',
              'g'
            ),
            '\\s*—\\s*$',
            '',
            'g'
          ),
          '\\s{2,}',
          ' ',
          'g'
        )
      ) as cleaned
    from public.posts p
    where p.body is not null
      and (
        p.body ~* '(Padel Doubles|Indoor Cricket|Football|Cricket|Padel)'
        or p.body ~ E'—\\s*(Mon|Tue|Wed|Thu|Fri|Sat|Sun)\\s+[A-Za-z]{3}\\s+\\d{1,2}\\s+\\d{2}:\\d{2}\\s*$'
      )
  ),
  upd as (
    update public.posts p
       set body = c.cleaned
    from cand c
    where p.id = c.id
      and p.body is distinct from c.cleaned
    returning p.id, left(p.body, 80) as before, left(c.cleaned, 80) as after
  ),
  cnt as (
    select count(*)::int as c from upd
  ),
  smp as (
    select jsonb_agg(jsonb_build_object('id', id, 'before', before, 'after', after)) as s
    from (select * from upd limit 12) x
  )
  select coalesce(cnt.c,0), coalesce(smp.s, '[]'::jsonb)
    into v_count, v_sample
  from cnt full join smp on true;

  return jsonb_build_object('rows_updated', v_count, 'sample', v_sample);
end;
$_$;


ALTER FUNCTION "public"."admin_scrub_posts_body_v3"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_scrub_posts_body_v4"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $_$
declare
  v_count  int  := 0;
  v_sample jsonb := '[]'::jsonb;
begin
  with cand as (
    select
      p.id,
      p.body,
      -- Stepwise cleaning in simpler, robust passes
      btrim(
        regexp_replace(                                              -- 6) collapse multi-spaces
          regexp_replace(                                            -- 5) drop trailing em dash if left alone
            regexp_replace(                                          -- 4) drop any remaining standalone sport tokens (EN list)
              regexp_replace(                                        -- 3b) AR preposition + sport
                regexp_replace(                                      -- 3a) EN preposition + sport
                  regexp_replace(                                    -- 2) drop trailing time block
                    p.body,
                    E'\\s*—\\s*(Mon|Tue|Wed|Thu|Fri|Sat|Sun)\\s+[A-Za-z]{3}\\s+\\d{1,2}\\s+\\d{2}:\\d{2}\\s*$',
                    '',
                    'i'
                  ),
                  '(?i)\\s+(?:at|for)\\s+(?:Padel(?:\\s+Doubles)?|Indoor\\s+Cricket|Football|Cricket)',
                  '',
                  'g'
                ),
                '\\s+(?:في|من\\s+أجواء)\\s+(?:Padel(?:\\s+Doubles)?|Indoor\\s+Cricket|Football|Cricket)',
                '',
                'g'
              ),
              '(?i)(^|\\s+)(?:Padel(?:\\s+Doubles)?|Indoor\\s+Cricket|Football|Cricket)(?=($|\\s|[[:punct:]]))',
              ' ',
              'g'
            ),
            '\\s*—\\s*$',
            '',
            'g'
          ),
          '\\s{2,}',
          ' ',
          'g'
        )
      ) as cleaned
    from public.posts p
    where p.body is not null
      and (
        p.body ~* '(Padel Doubles|Indoor Cricket|Football|Cricket|Padel)'
        or p.body ~ E'—\\s*(Mon|Tue|Wed|Thu|Fri|Sat|Sun)\\s+[A-Za-z]{3}\\s+\\d{1,2}\\s+\\d{2}:\\d{2}\\s*$'
      )
  ),
  upd as (
    update public.posts p
       set body = c.cleaned
    from cand c
    where p.id = c.id
      and p.body is distinct from c.cleaned
    returning p.id, left(p.body, 80) as before, left(c.cleaned, 80) as after
  ),
  cnt as (select count(*)::int as c from upd),
  smp as (
    select jsonb_agg(jsonb_build_object('id', id, 'before', before, 'after', after)) as s
    from (select * from upd limit 12) x
  )
  select coalesce(cnt.c,0), coalesce(smp.s, '[]'::jsonb)
    into v_count, v_sample
  from cnt full join smp on true;

  return jsonb_build_object('rows_updated', v_count, 'sample', v_sample);
end;
$_$;


