CREATE OR REPLACE FUNCTION "public"."admin_take_action"("p_action" "public"."mod_action", "p_target_type" "public"."mod_target", "p_target_id" "uuid", "p_target_user_id" "uuid" DEFAULT NULL::"uuid", "p_reason" "text" DEFAULT NULL::"text", "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_meta" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."moderation_actions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  row public.moderation_actions;
begin
  if not public.is_admin(auth.uid()) then
    raise exception using errcode = 'P0001', message = 'forbidden';
  end if;

  insert into public.moderation_actions(
    action, actor_user_id, target_type, target_id,
    target_user_id, reason, created_at, expires_at, meta
  )
  values(
    p_action,
    auth.uid(),
    p_target_type,
    p_target_id,
    p_target_user_id,
    p_reason,
    now(),
    p_expires_at,
    coalesce(p_meta, '{}'::jsonb)
  )
  returning * into row;

  -- reflect takedown registry
  if p_action = 'takedown' then
    insert into public.safety_takedowns(
      target_type, target_id, reason, expires_at, created_by
    )
    values (
      p_target_type,
      p_target_id,
      coalesce(p_reason, 'takedown'),
      p_expires_at,
      auth.uid()
    )
    on conflict (target_type, target_id) do update
      set reason     = excluded.reason,
          expires_at = excluded.expires_at,
          created_at = now(),
          created_by = excluded.created_by;
  elsif p_action = 'restore' then
    delete from public.safety_takedowns
    where target_type = p_target_type
      and target_id   = p_target_id;
  end if;

  perform public.audit_log(
    'mod.action_' || p_action::text,
    p_target_type,
    p_target_id,
    p_target_user_id,
    p_meta
  );

  return row;
end;
$$;


ALTER FUNCTION "public"."admin_take_action"("p_action" "public"."mod_action", "p_target_type" "public"."mod_target", "p_target_id" "uuid", "p_target_user_id" "uuid", "p_reason" "text", "p_expires_at" timestamp with time zone, "p_meta" "jsonb") OWNER TO "postgres";


