CREATE OR REPLACE FUNCTION "public"."apply_xp_progression"("xp_total" integer, "current_level" integer) RETURNS TABLE("new_level" integer, "new_next_xp" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  req int;
  lvl int := current_level;
BEGIN
  LOOP
    req := public.compute_next_level_xp(lvl);

    EXIT WHEN xp_total < req;

    lvl := lvl + 1;
  END LOOP;

  RETURN QUERY SELECT lvl, public.compute_next_level_xp(lvl);
END;
$$;


