CREATE OR REPLACE FUNCTION "public"."assert_actor"("p_profile_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  ok boolean;
begin
  if me is null then
    raise exception 'not_authenticated' using errcode='P0001';
  end if;

  select exists(
    select 1 from public.profiles
    where id = p_profile_id
      and user_id = me
      and is_active = true
  ) into ok;

  if not ok then
    raise exception using errcode = 'P0001', message = 'actor_not_owned_or_inactive';
  end if;

  return p_profile_id;
end;
$$;


