CREATE OR REPLACE FUNCTION "public"."audit_venue_submission_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  insert into public.audit_events (
    target_type,
    target_id,
    action,
    actor_user_id,
    meta,
    created_at
  )
  values (
    'venue'::public.mod_target,
    new.id,
    case
      when old.status is distinct from new.status then
        concat('status:', old.status, '→', new.status)
      else
        'update'
    end,
    auth.uid(),
    jsonb_build_object(
      'old_status', old.status,
      'new_status', new.status,
      'reviewed_by', new.reviewed_by
    ),
    now()
  );

  return new;
end;
$$;


