CREATE OR REPLACE FUNCTION "public"."calculate_notification_rank"("p_notification_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_record RECORD;
    v_rank numeric := 0;
    v_hours_since numeric;
BEGIN

    SELECT *
    INTO v_record
    FROM public.notifications
    WHERE id = p_notification_id;

    IF NOT FOUND THEN
        RETURN 0;
    END IF;

    -- Base AI score
    v_rank := COALESCE(v_record.ai_score, 1);

    -- Unread boost
    IF v_record.is_read = false THEN
        v_rank := v_rank + 2;
    END IF;

    -- Recency decay (hours)
    v_hours_since := EXTRACT(EPOCH FROM (now() - v_record.created_at)) / 3600;

    -- Apply decay
    v_rank := v_rank - (v_hours_since * 0.1);

    IF v_rank < 0 THEN
        v_rank := 0;
    END IF;

    RETURN v_rank;

END;
$$;


ALTER FUNCTION "public"."calculate_notification_rank"("p_notification_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_notification_score"("p_to_user" "uuid", "p_kind_key" "text", "p_actor_user" "uuid", "p_entity_id" "uuid", "p_total_count" integer) RETURNS numeric
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_rule RECORD;
    v_score numeric := 0;
    v_is_prime boolean := false;
    v_relationship numeric := 0;
BEGIN

    SELECT *
    INTO v_rule
    FROM public.notification_scores
    WHERE kind_key = p_kind_key
      AND is_enabled = true;

    IF NOT FOUND THEN
        RETURN 1;
    END IF;

    -- Base
    v_score := v_score + v_rule.base_weight;

    -- Actor count boost (scaled)
    v_score := v_score + (p_total_count * v_rule.actor_weight);

    -- Relationship boost (follower example)
    IF EXISTS (
        SELECT 1
        FROM public.profile_follows pf
        JOIN public.profiles p ON p.user_id = p_to_user
        WHERE pf.following_profile_id = p.id
    ) THEN
        v_relationship := 1;
    END IF;

    v_score := v_score + (v_relationship * v_rule.relationship_weight);

    -- Prime boost
    SELECT (plan_key = 'prime')
    INTO v_is_prime
    FROM public.user_subscriptions
    WHERE user_id = p_to_user
      AND is_active = true;

    IF v_is_prime THEN
        v_score := v_score + v_rule.plan_boost_weight;
    END IF;

    -- Recency boost
    v_score := v_score + v_rule.recency_weight;

    RETURN v_score;

END;
$$;


ALTER FUNCTION "public"."calculate_notification_score"("p_to_user" "uuid", "p_kind_key" "text", "p_actor_user" "uuid", "p_entity_id" "uuid", "p_total_count" integer) OWNER TO "postgres";


