CREATE OR REPLACE FUNCTION "public"."can_receive_friend_requests"("p_user" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select case when public.is_benched(p_user) then not coalesce(us.block_friend_requests, true) else true end
  from public.user_status us
  where us.user_id = p_user
  union all
  select true
  where not exists (select 1 from public.user_status where user_id = p_user)
  limit 1
$$;


