CREATE OR REPLACE FUNCTION "public"."can_send_notification_now"("p_user_id" "uuid", "p_priority" "public"."notify_priority") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_plan text;
    v_cap integer;
    v_sent_count integer;
BEGIN

    -- Get active plan
    SELECT plan_key
    INTO v_plan
    FROM public.user_subscriptions
    WHERE user_id = p_user_id
      AND is_active = true
    LIMIT 1;

    IF v_plan IS NULL THEN
        v_plan := 'kickoff';
    END IF;

    -- Get cap
    SELECT max_per_hour
    INTO v_cap
    FROM public.notification_hourly_caps
    WHERE plan_key = v_plan
      AND priority = p_priority;

    IF v_cap IS NULL THEN
        RETURN true; -- no cap rule = allow
    END IF;

    -- Count last hour notifications
    SELECT count(*)
    INTO v_sent_count
    FROM public.notifications
    WHERE to_user_id = p_user_id
      AND priority = p_priority
      AND created_at >= now() - interval '1 hour';

    RETURN v_sent_count < v_cap;

END;
$$;


