COMMENT ON FUNCTION "public"."can_user_rename"("p_user" "uuid") IS 'Rate limit: allow <3 username changes per 30 days.';



CREATE OR REPLACE FUNCTION "public"."can_view_circle"("p_circle_id" "uuid", "p_profile_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    -- Owner can always see
    IF EXISTS (
        SELECT 1
        FROM public.circles
        WHERE id = p_circle_id
        AND owner_profile_id = p_profile_id
    ) THEN
        RETURN true;
    END IF;

    -- Member can see
    IF EXISTS (
        SELECT 1
        FROM public.circle_members
        WHERE circle_id = p_circle_id
        AND member_profile_id = p_profile_id
    ) THEN
        RETURN true;
    END IF;

    RETURN false;
END;
$$;


