CREATE TABLE IF NOT EXISTS "public"."posts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "author_profile_id" "uuid" NOT NULL,
    "author_user_id" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "kind" "public"."post_kind" NOT NULL,
    "visibility" "text" NOT NULL,
    "link_token" "text",
    "body" "text",
    "lang" "text",
    "sport" "text",
    "venue_id" "uuid",
    "geo_lat" double precision NOT NULL,
    "geo_lng" double precision NOT NULL,
    "media" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "like_count" integer DEFAULT 0 NOT NULL,
    "comment_count" integer DEFAULT 0 NOT NULL,
    "is_deleted" boolean DEFAULT false NOT NULL,
    "is_hidden_admin" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "vibe_id" "uuid",
    "search_tsv" "tsvector",
    "author_display_name" "text" NOT NULL,
    "location_tag_id" "uuid",
    "game_id" "uuid",
    "sport_id" "uuid",
    "tags" "text"[] DEFAULT '{}'::"text"[],
    "content_class" "public"."content_class_enum" DEFAULT 'social'::"public"."content_class_enum",
    "post_type" "public"."post_type_enum" DEFAULT 'dab'::"public"."post_type_enum",
    "origin_type" "public"."origin_type_enum" DEFAULT 'manual'::"public"."origin_type_enum",
    "origin_id" "uuid",
    "persona_type_snapshot" "text",
    "expires_at" timestamp with time zone,
    "is_active" boolean DEFAULT true,
    "allow_reposts" boolean DEFAULT true,
    "is_pinned" boolean DEFAULT false,
    "priority_score" integer DEFAULT 0,
    "reaction_breakdown" "jsonb" DEFAULT '{}'::"jsonb",
    "view_count" integer DEFAULT 0,
    "edited_at" timestamp with time zone,
    "is_edited" boolean DEFAULT false,
    "requires_moderation" boolean DEFAULT false,
    "repost_count" integer DEFAULT 0 NOT NULL,
    "location_name" "text",
    "post_theme_id" "uuid",
    "geo_location_id" "uuid" NOT NULL,
    "area_id" "uuid" NOT NULL,
    CONSTRAINT "posts_body_not_hashtags_only" CHECK (("body" !~ '^(#[a-zA-Z0-9_]+\s*)+$'::"text")),
    CONSTRAINT "posts_content_model_check" CHECK (((("origin_type" = 'manual'::"public"."origin_type_enum") AND ("post_type" = ANY (ARRAY['moment'::"public"."post_type_enum", 'dab'::"public"."post_type_enum", 'kick_in'::"public"."post_type_enum"])) AND ("kind" = 'original'::"public"."post_kind")) OR (("origin_type" = 'system'::"public"."origin_type_enum") AND ("post_type" = 'allocated'::"public"."post_type_enum") AND ("kind" = ANY (ARRAY['news'::"public"."post_kind", 'announcement'::"public"."post_kind", 'alert'::"public"."post_kind", 'highlight'::"public"."post_kind", 'general'::"public"."post_kind", 'feature'::"public"."post_kind"]))) OR (("origin_type" = 'venue'::"public"."origin_type_enum") AND ("post_type" = 'allocated'::"public"."post_type_enum") AND ("kind" = ANY (ARRAY['announcement'::"public"."post_kind", 'commercial'::"public"."post_kind"]))) OR (("origin_type" = 'game'::"public"."origin_type_enum") AND ("post_type" = 'allocated'::"public"."post_type_enum") AND ("kind" = ANY (ARRAY['general'::"public"."post_kind", 'highlight'::"public"."post_kind"]))) OR (("origin_type" = 'repost'::"public"."origin_type_enum") AND ("kind" = 'original'::"public"."post_kind")))),
    CONSTRAINT "posts_visibility_check" CHECK (("visibility" = ANY (ARRAY['public'::"text", 'followers'::"text", 'circle'::"text", 'squad'::"text", 'link'::"text", 'private'::"text"])))
);

ALTER TABLE ONLY "public"."posts" REPLICA IDENTITY FULL;


ALTER TABLE "public"."posts" OWNER TO "postgres";


COMMENT ON COLUMN "public"."posts"."tags" IS 'Array of sport/activity tags attached to the post (e.g. Football, Basketball)';



CREATE OR REPLACE FUNCTION "public"."can_view_post"("p_viewer" "uuid", "p_post" "public"."posts") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT CASE
    WHEN p_post.is_deleted OR p_post.is_hidden_admin THEN false
    WHEN p_post.author_user_id = p_viewer THEN true
    WHEN public.is_benched(p_post.author_user_id) OR public.is_frozen(p_post.author_user_id) THEN false
    WHEN public._is_hidden(p_viewer, p_post.author_user_id) THEN false
    WHEN p_post.visibility IN ('public','private','circle','link')
      THEN public.can_view_with_scope(p_viewer, p_post.author_user_id, p_post.visibility, NULL)
    ELSE false
  END;
$$;


ALTER FUNCTION "public"."can_view_post"("p_viewer" "uuid", "p_post" "public"."posts") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_view_post"("p_post_id" "uuid", "p_user_id" "uuid", "p_profile_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_author_user uuid; v_author_profile uuid; v_visibility text; v_resolved_profile_id uuid;
BEGIN
  SELECT author_user_id, author_profile_id, visibility INTO v_author_user, v_author_profile, v_visibility
  FROM public.posts WHERE id = p_post_id;
  IF NOT FOUND THEN RETURN false; END IF;
  IF v_author_user = p_user_id THEN RETURN true; END IF;
  IF v_visibility = 'public' THEN RETURN true; END IF;
  v_resolved_profile_id := p_profile_id;
  IF v_resolved_profile_id IS NULL AND p_user_id IS NOT NULL THEN
    SELECT id INTO v_resolved_profile_id FROM public.profiles
    WHERE user_id = p_user_id AND is_active = true ORDER BY created_at ASC LIMIT 1;
  END IF;
  IF v_visibility = 'followers' THEN
    IF v_resolved_profile_id IS NULL THEN RETURN false; END IF;
    RETURN EXISTS (SELECT 1 FROM public.profile_follows pf WHERE pf.follower_profile_id = v_resolved_profile_id AND pf.following_profile_id = v_author_profile);
  END IF;
  IF v_visibility = 'circle' THEN
    IF v_resolved_profile_id IS NULL THEN RETURN false; END IF;
    RETURN EXISTS (
      SELECT 1 FROM public.post_circles pc
      JOIN public.circles c ON c.id = pc.circle_id
      LEFT JOIN public.circle_members cm ON cm.circle_id = c.id AND cm.member_profile_id = v_resolved_profile_id
      WHERE pc.post_id = p_post_id AND (
        (c.circle_type = 'private' AND cm.member_profile_id IS NOT NULL)
        OR (c.circle_type = 'followers' AND EXISTS (
            SELECT 1 FROM public.profile_follows pf
            WHERE pf.follower_profile_id = v_resolved_profile_id AND pf.following_profile_id = c.owner_profile_id))
        OR (c.circle_type = 'public')
      )
    );
  END IF;
  IF v_visibility = 'squad' THEN
    IF v_resolved_profile_id IS NULL THEN RETURN false; END IF;
    RETURN EXISTS (
      SELECT 1 FROM public.post_squads ps
      JOIN public.squad_members sm ON sm.squad_id = ps.squad_id
      WHERE ps.post_id = p_post_id AND sm.profile_id = v_resolved_profile_id AND sm.status = 'active'
    );
  END IF;
  RETURN false;
END;
$$;


