CREATE OR REPLACE FUNCTION "public"."can_view_with_scope"("viewer_user_id" "uuid", "owner_user_id" "uuid", "scope" "text", "p_squad_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if viewer_user_id is not null and public.is_blocked(viewer_user_id, owner_user_id) then return false; end if;
  case scope
    when 'public' then return true;
    when 'followers' then
      if viewer_user_id is null then return false; end if;
      if viewer_user_id = owner_user_id then return true; end if;
      return exists (
        select 1
        from public.profile_follows pf
        join public.profiles fp on fp.id = pf.follower_profile_id
        join public.profiles op on op.id = pf.following_profile_id
        where fp.user_id = viewer_user_id
          and op.user_id = owner_user_id
      );
    when 'private' then
      if viewer_user_id is null then return false; end if;
      return viewer_user_id = owner_user_id;
    when 'circle' then
      if viewer_user_id is null then return false; end if;
      return public.are_synced(viewer_user_id, owner_user_id);
    when 'hidden' then
      if viewer_user_id is null then return false; end if;
      return viewer_user_id = owner_user_id;
    when 'invite' then
      if viewer_user_id is null then return false; end if;
      return viewer_user_id = owner_user_id or public.is_admin(viewer_user_id);
    when 'link' then
      if viewer_user_id is null then return false; end if;
      return viewer_user_id = owner_user_id or public.is_admin(viewer_user_id);
    when 'squad' then
      if viewer_user_id is null or p_squad_id is null then return false; end if;
      return public.is_in_squad(viewer_user_id, p_squad_id);
    else return false;
  end case;
end;
$$;


ALTER FUNCTION "public"."can_view_with_scope"("viewer_user_id" "uuid", "owner_user_id" "uuid", "scope" "text", "p_squad_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_view_with_scope3"("viewer_user_id" "uuid", "owner_user_id" "uuid", "scope" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
begin
  -- Hard block wins
  if viewer_user_id is not null and public.is_blocked(viewer_user_id, owner_user_id) then
    return false;
  end if;

  if scope = 'public' then
    return true;

  elsif scope = 'circle' then
    if viewer_user_id is null then
      return false;
    end if;
    return public.are_synced(viewer_user_id, owner_user_id);

  elsif scope = 'hidden' then
    if viewer_user_id is null then
      return false;
    end if;
    return viewer_user_id = owner_user_id;

  else
    return false;
  end if;
end;
$$;


ALTER FUNCTION "public"."can_view_with_scope3"("viewer_user_id" "uuid", "owner_user_id" "uuid", "scope" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."can_view_with_scope3"("viewer_user_id" "uuid", "owner_user_id" "uuid", "scope" "text") IS '3-arg visibility resolver used by RLS (public|circle|hidden).';



