CREATE OR REPLACE FUNCTION "public"."check_and_bump_cooldown"("p_key" "text", "p_window_seconds" integer, "p_limit_count" integer) RETURNS TABLE("allowed" boolean, "remaining" integer, "reset_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  me        uuid := auth.uid();
  rec       public.safety_cooldowns;
  now_      timestamptz := now();
  reset_    timestamptz;
  remaining_ int;
begin
  if me is null then
    raise exception using errcode = 'P0001', message = 'auth_required';
  end if;

  -- upsert row
  insert into public.safety_cooldowns(
    user_id, key, window_seconds, limit_count, used_count, window_start
  )
  values(
    me, p_key, p_window_seconds, p_limit_count, 0, now_
  )
  on conflict (user_id, key) do update
    set window_seconds = excluded.window_seconds,
        limit_count    = excluded.limit_count
  returning * into rec;

  -- reset window if expired
  if rec.window_start + make_interval(secs => rec.window_seconds) <= now_ then
    update public.safety_cooldowns
    set used_count   = 0,
        window_start = now_,
        updated_at   = now_
    where user_id = me
      and key     = p_key
    returning * into rec;
  end if;

  if rec.used_count < rec.limit_count then
    update public.safety_cooldowns
    set used_count = used_count + 1,
        updated_at = now_
    where user_id = me
      and key     = p_key
    returning * into rec;

    remaining_ := rec.limit_count - rec.used_count;
    reset_     := rec.window_start + make_interval(secs => rec.window_seconds);

    return query
      select true, remaining_, reset_;
  else
    reset_     := rec.window_start + make_interval(secs => rec.window_seconds);
    remaining_ := 0;

    return query
      select false, remaining_, reset_;
  end if;
end;
$$;


ALTER FUNCTION "public"."check_and_bump_cooldown"("p_key" "text", "p_window_seconds" integer, "p_limit_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_user_exists_by_identifier"("identifier" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Check auth.users table for email or phone
  RETURN EXISTS (
    SELECT 1 
    FROM auth.users
    WHERE email = identifier
       OR phone = identifier
       OR phone = REPLACE(identifier, '+', '')
       OR CONCAT('+', phone) = identifier
  );
END;
$$;


