CREATE OR REPLACE FUNCTION "public"."choose_actor"("p_profile_type" "text" DEFAULT 'player'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := public.effective_actor_uid();
  v_pid uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION USING errcode='P0001', message='not_authenticated'; END IF;
  SELECT p.id INTO v_pid FROM public.profiles p
  WHERE p.user_id = v_uid AND p.persona_type = p_profile_type AND p.is_active = true
  ORDER BY p.created_at LIMIT 1;
  IF v_pid IS NULL THEN RAISE EXCEPTION USING errcode='P0001', message='no_profile_of_requested_type'; END IF;
  RETURN v_pid;
END;
$$;


