CREATE OR REPLACE FUNCTION "public"."compute_challenge_fingerprint"("p_payload" "jsonb") RETURNS TABLE("hash" "text", "fields" "jsonb")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  sport text;
  kind text;                 -- 'round_robin'|'knockout'|'ladder'|'league'|...
  squads int;                -- number of squads
  rounds_per_week int;
  default_slot text;         -- preferred slot for fixtures (optional)
  f jsonb;
begin
  sport := lower(coalesce(p_payload->>'sport',''));
  kind  := lower(coalesce(p_payload->>'challenge_type',''));
  squads := coalesce((p_payload->>'squads')::int, 0);
  rounds_per_week := coalesce((p_payload->>'rounds_per_week')::int, 0);
  default_slot := coalesce(p_payload->>'default_slot', null);

  f := jsonb_build_object(
    'sport', sport,
    'challenge_type', kind,
    'squads', squads,
    'rounds_per_week', rounds_per_week,
    'default_slot', default_slot
  );

  hash := encode(digest(f::text,'sha256'),'hex');
  fields := f;
  return next;
end;
$$;


ALTER FUNCTION "public"."compute_challenge_fingerprint"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_form_score"("last_matches" integer[]) RETURNS numeric
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  score numeric;
  match_count int;
BEGIN
  match_count := array_length(last_matches, 1);

  IF match_count IS NULL OR match_count = 0 THEN
    RETURN 0;
  END IF;

  -- Weighted average: more recent match has higher weight
  -- Example: last_5_matches = [6,7,8,7,9]
  -- Weight pattern: 1,2,3,4,5
  SELECT
    SUM(last_matches[i] * i)::numeric / SUM(i)
  INTO score
  FROM generate_subscripts(last_matches, 1) s(i);

  RETURN score;
END;
$$;


ALTER FUNCTION "public"."compute_form_score"("last_matches" integer[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_game_fingerprint"("p_payload" "jsonb") RETURNS TABLE("hash" "text", "fields" "jsonb")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  sport text; venue_space uuid; start_at timestamptz; end_at timestamptz;
  capacity int; listing text; joinp text; dur int; slot text; f jsonb;
BEGIN
  sport := lower(COALESCE(p_payload->>'sport', ''));
  venue_space := nullif(p_payload->>'venue_space_id', '')::uuid;
  start_at := (p_payload->>'start_at')::timestamptz;
  end_at := (p_payload->>'end_at')::timestamptz;
  capacity := COALESCE((p_payload->>'capacity')::int, 0);
  listing := COALESCE(p_payload->>'listing_visibility', 'public');
  joinp := COALESCE(p_payload->>'join_policy', 'request');
  dur := GREATEST(30, COALESCE(((extract(epoch from (end_at - start_at)) / 60)::int), 60));
  slot := public._slot_key(start_at, 30);
  f := jsonb_build_object(
    'sport', sport, 'venue_space_id', venue_space,
    'weekday', extract(dow from start_at)::int,
    'slot', slot, 'duration_mins', dur, 'capacity', capacity,
    'listing_visibility', listing, 'join_policy', joinp);
  hash := encode(digest(COALESCE(f::text, ''), 'sha256'), 'hex');
  fields := f;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."compute_game_fingerprint"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_meetup_fingerprint"("p_payload" "jsonb") RETURNS TABLE("hash" "text", "fields" "jsonb")
