CREATE OR REPLACE FUNCTION "public"."compute_overall_level"("attrs" "jsonb") RETURNS numeric
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  avg_level numeric;
BEGIN
  IF attrs IS NULL OR attrs = '{}'::jsonb THEN
    RETURN NULL;
  END IF;

  SELECT AVG((value)::numeric)
  INTO avg_level
  FROM jsonb_each(attrs)
  WHERE (value::text) ~ '^[0-9]+$';   -- FIXED CAST

  RETURN avg_level;
END;
$_$;


