CREATE OR REPLACE FUNCTION "public"."compute_reliability_score"("attendance" numeric, "cancellations" numeric, "punctuality" numeric, "teamwork" numeric, "rating_total" integer, "rating_count" integer) RETURNS numeric
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  rating_avg numeric := 5;
BEGIN
  -- Defensive ratings fallback
  IF rating_count > 0 THEN
    rating_avg := rating_total::numeric / rating_count;
  END IF;

  -- Weighted reputation formula (tweakable anytime)
  RETURN
      (attendance * 4)         -- 40%
    + ((1 - cancellations) * 2) -- 20%
    + (punctuality * 0.5)       -- 5%
    + (teamwork * 0.5)          -- 5%
    + (rating_avg * 2);         -- 20%
END;
$$;


