CREATE OR REPLACE FUNCTION "public"."create_seed_user"("p_email" "text", "p_display_name" "text", "p_username" "text", "p_age" integer, "p_gender" "text", "p_city" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid;
  v_profile_id uuid;
BEGIN
  -- Insert into auth.users
  v_user_id := gen_random_uuid();

  INSERT INTO auth.users (
    id, aud, role, email,
    encrypted_password,
    email_confirmed_at,
    raw_app_meta_data,
    raw_user_meta_data,
    created_at
  ) VALUES (
    v_user_id,
    'authenticated',
    'authenticated',
    p_email,
    crypt('SeedBot!2025', gen_salt('bf')),
    now(),
    '{"provider":"email","providers":["email"]}'::jsonb,
    jsonb_build_object('is_seed', true, 'city', p_city),
    now()
  );

  -- Insert into profiles
  INSERT INTO public.profiles (
    user_id, profile_type, username, display_name,
    age, gender, city, country, persona_type,
    is_player, is_original, language
  ) VALUES (
    v_user_id, 'personal', p_username, p_display_name,
    p_age, p_gender, p_city, 'AE', 'player',
    true, false, 'en'
  )
  RETURNING id INTO v_profile_id;

  RETURN json_build_object(
    'user_id', v_user_id,
    'profile_id', v_profile_id
  );
END;
$$;


