CREATE OR REPLACE FUNCTION "public"."create_system_post"("p_profile_id" "uuid", "p_body" "text", "p_kind" "public"."post_kind", "p_visibility" "text" DEFAULT 'public'::"text", "p_vibe_id" "uuid" DEFAULT NULL::"uuid", "p_sport_id" "uuid" DEFAULT NULL::"uuid", "p_post_type" "public"."post_type_enum" DEFAULT 'dab'::"public"."post_type_enum", "p_origin_type" "public"."origin_type_enum" DEFAULT 'system'::"public"."origin_type_enum", "p_origin_id" "uuid" DEFAULT NULL::"uuid", "p_location_name" "text" DEFAULT NULL::"text", "p_geo_lat" double precision DEFAULT NULL::double precision, "p_geo_lng" double precision DEFAULT NULL::double precision, "p_media" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "public"."posts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    SET "row_security" TO 'off'
    AS $$
declare
  v_user_id uuid;
  v_theme_id uuid;
  v_post public.posts;
begin
  select user_id
  into v_user_id
  from public.profiles
  where id = p_profile_id;

  if v_user_id is null then
    raise exception 'user_id is NULL for profile %', p_profile_id;
  end if;

  -- Auto-assign the first system theme
  select id into v_theme_id
  from public.post_themes
  where is_system = true
  order by created_at asc
  limit 1;

  insert into public.posts (
    author_profile_id,
    author_user_id,
    body,
    kind,
    visibility,
    vibe_id,
    sport_id,
    post_type,
    origin_type,
    origin_id,
    location_name,
    geo_lat,
    geo_lng,
    media,
    post_theme_id,
    link_token
  )
  values (
    p_profile_id,
    v_user_id,
    p_body,
    p_kind,
    p_visibility,
    p_vibe_id,
    p_sport_id,
    p_post_type,
    p_origin_type,
    p_origin_id,
    p_location_name,
    p_geo_lat,
    p_geo_lng,
    p_media,
    v_theme_id,
    case
      when p_visibility = 'link'
      then encode(gen_random_bytes(6), 'hex')
      else null
    end
  )
  returning * into v_post;

  return v_post;
end;
$$;


