CREATE OR REPLACE FUNCTION "public"."debug_assume_user"("p_sub" "uuid", "p_role" "text" DEFAULT 'authenticated'::"text") RETURNS TABLE("claims_guc" "text", "who_am_i" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform set_config(
           'request.jwt.claims',
           json_build_object('sub', p_sub::text, 'role', coalesce(p_role,'authenticated'))::text,
           true
         );
  return query select current_setting('request.jwt.claims', true), auth.uid();
end;
$$;


