CREATE OR REPLACE FUNCTION "public"."effective_actor_uid"() RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_claims text; v_sub text; v_uid uuid;
BEGIN
  BEGIN v_sub := nullif(current_setting('request.jwt.claim.sub', true), ''); EXCEPTION WHEN OTHERS THEN v_sub := NULL; END;
  IF v_sub IS NULL THEN
    BEGIN v_claims := nullif(current_setting('request.jwt.claims', true), ''); EXCEPTION WHEN OTHERS THEN v_claims := NULL; END;
    IF v_claims IS NOT NULL THEN v_sub := COALESCE((v_claims::jsonb)->>'sub', (v_claims::jsonb)->>'user_id'); END IF;
  END IF;
  IF v_sub IS NOT NULL THEN BEGIN v_uid := v_sub::uuid; EXCEPTION WHEN OTHERS THEN v_uid := NULL; END; END IF;
  RETURN COALESCE(v_uid, auth.uid());
END;
$$;


ALTER FUNCTION "public"."effective_actor_uid"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."effective_actor_uid"() IS 'Evaluates the acting user: auth.uid() in app; or dbg.actor_uid (GUC) when set in SQL console for testing.';



CREATE OR REPLACE FUNCTION "public"."effective_actor_uid_debug"() RETURNS TABLE("sub_guc" "text", "claims_guc" "text", "parsed_sub" "text", "auth_uid" "uuid", "result" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_claims jsonb;
  v_sub text;
  v_uid uuid;
begin
  sub_guc   := nullif(current_setting('request.jwt.claim.sub', true), '');
  claims_guc:= nullif(current_setting('request.jwt.claims', true), '');
  if claims_guc is not null then
    v_claims := claims_guc::jsonb;
    parsed_sub := coalesce(v_claims->>'sub', v_claims->>'user_id');
  end if;

  if sub_guc is not null then
    begin v_uid := sub_guc::uuid; exception when others then v_uid := null; end;
  elsif parsed_sub is not null then
    begin v_uid := parsed_sub::uuid; exception when others then v_uid := null; end;
  end if;

  auth_uid := auth.uid();
  result   := coalesce(v_uid, auth_uid);

  return next;
end;
$$;


ALTER FUNCTION "public"."effective_actor_uid_debug"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."effective_uid"() RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_uid uuid;
  v_claims text;
  v_sub text;
begin
  -- Try auth.uid() first (works in Supabase RPCs)
  begin
    v_uid := auth.uid();
  exception when others then
    v_uid := null;
  end;

  if v_uid is not null then
    return v_uid;
  end if;

  -- Fallback to request.jwt.claims if present in this session
  v_claims := current_setting('request.jwt.claims', true);
  if v_claims is null or v_claims = '' then
    return null;
  end if;

  v_sub := (v_claims::jsonb ->> 'sub');
  if v_sub is null or v_sub = '' then
    return null;
  end if;

  return v_sub::uuid;
end;
$$;


ALTER FUNCTION "public"."effective_uid"() OWNER TO "postgres";


