CREATE OR REPLACE FUNCTION "public"."enforce_single_level_reply"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    parent_parent_id uuid;
BEGIN
    -- If this is a reply
    IF NEW.parent_comment_id IS NOT NULL THEN

        -- Check if parent itself is already a reply
        SELECT parent_comment_id
        INTO parent_parent_id
        FROM public.post_comments
        WHERE id = NEW.parent_comment_id;

        IF parent_parent_id IS NOT NULL THEN
            RAISE EXCEPTION 'Replies to replies are not allowed (single-level threading only)';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_single_level_reply"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_single_visibility_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_visibility text;
BEGIN
    SELECT visibility
    INTO v_visibility
    FROM public.posts
    WHERE id = NEW.post_id;

    -- If inserting into post_circles
    IF TG_TABLE_NAME = 'post_circles' THEN
        IF v_visibility <> 'circle' THEN
            RAISE EXCEPTION 'Post visibility must be circle to assign circles';
        END IF;

        -- prevent squad mix
        IF EXISTS (
            SELECT 1 FROM public.post_squads
            WHERE post_id = NEW.post_id
        ) THEN
            RAISE EXCEPTION 'Post cannot belong to both circles and squads';
        END IF;
    END IF;

    -- If inserting into post_squads
    IF TG_TABLE_NAME = 'post_squads' THEN
        IF v_visibility <> 'squad' THEN
            RAISE EXCEPTION 'Post visibility must be squad to assign squads';
        END IF;

        -- prevent circle mix
        IF EXISTS (
            SELECT 1 FROM public.post_circles
            WHERE post_id = NEW.post_id
        ) THEN
            RAISE EXCEPTION 'Post cannot belong to both squads and circles';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_single_visibility_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fill_game_with_seed_profiles"("p_game_id" "uuid", "p_sport_id" "uuid", "p_city" "text", "p_spots" integer, "p_existing_profiles" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_profile record;
  v_inserted int := 0;
  result jsonb;
BEGIN
  FOR v_profile IN
    SELECT p.id AS profile_id, p.user_id
    FROM public.profiles p
    WHERE p.is_original = false
      AND p.primary_sport = p_sport_id
      AND p.city = p_city
      AND (p_existing_profiles IS NULL OR p.id != ALL(p_existing_profiles))
    ORDER BY random()
    LIMIT p_spots
  LOOP
    INSERT INTO public.game_roster (
      game_id, profile_id, user_id, role, status, joined_at
    ) VALUES (
      p_game_id, v_profile.profile_id, v_profile.user_id,
      'player', 'active', now()
    )
    ON CONFLICT DO NOTHING;

    v_inserted := v_inserted + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'game_id', p_game_id,
    'players_added', v_inserted
  );
END;
$$;


ALTER FUNCTION "public"."fill_game_with_seed_profiles"("p_game_id" "uuid", "p_sport_id" "uuid", "p_city" "text", "p_spots" integer, "p_existing_profiles" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."find_slots"("p_venue_space_id" "uuid", "p_on_date" "date", "p_step_minutes" integer DEFAULT 30) RETURNS TABLE("slot_start" timestamp with time zone, "slot_end" timestamp with time zone, "is_booked" boolean, "price_aed" numeric)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
  vdow int;
  open_t time;
  close_t time;
  is_open boolean;
  cur timestamptz;
  nxt timestamptz;
  blk int;
  booked boolean;
  p numeric;
begin
  -- Get venue + hours
  select s.venue_id into v_id from public.venue_spaces s where s.id=p_venue_space_id and s.is_active=true;
  if not found then
    return;
  end if;

  vdow := extract(dow from p_on_date); -- 0..6, 0=Sunday

  select oh.open_time, oh.close_time, oh.is_open
    into open_t, close_t, is_open
  from public.venue_opening_hours oh
  where oh.venue_id = v_id and oh.weekday = vdow;

  if not coalesce(is_open, false) then
    return; -- closed that day
  end if;

  cur := timestamptz at time zone 'UTC'; -- we will construct from date+time
  cur := (p_on_date::timestamptz + open_t);
  while cur < (p_on_date::timestamptz + close_t) loop
    nxt := cur + make_interval(mins => p_step_minutes);

    -- Skip past-end partial
    if nxt > (p_on_date::timestamptz + close_t) then
      exit;
    end if;

    -- Blackouts?
    select count(*) into blk
    from public.venue_blackouts b
    where b.venue_id = v_id
      and (b.venue_space_id is null or b.venue_space_id = p_venue_space_id)
      and tstzrange(b.starts_at, b.ends_at, '[)') && tstzrange(cur, nxt, '[)');

    if blk = 0 then
      -- Booked?
      select exists (
        select 1 from public.venue_bookings bk
        where bk.venue_space_id = p_venue_space_id
          and bk.status in ('tentative','confirmed')
          and tstzrange(bk.starts_at, bk.ends_at, '[)') && tstzrange(cur, nxt, '[)')
      ) into booked;

      -- Price hint: pick first rule matching DOW + time
      select pr.price_aed into p
      from public.venue_price_rules pr
      where pr.venue_space_id = p_venue_space_id
        and (pr.dow is null or vdow = any(pr.dow))
        and pr.start_time <= (cur::time)
        and pr.end_time   >  (cur::time)
      order by pr.start_time desc
      limit 1;

      slot_start := cur;
      slot_end   := nxt;
      is_booked  := booked;
      price_aed  := p;
      return next;
    end if;

    cur := nxt;
  end loop;
end;
$$;


ALTER FUNCTION "public"."find_slots"("p_venue_space_id" "uuid", "p_on_date" "date", "p_step_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."flush_notification_aggregates"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_record RECORD;
    v_count integer := 0;
    v_title text;
    v_body text;
    v_route text;
    v_context jsonb;
    v_display_name text;
BEGIN

FOR v_record IN
    SELECT *
    FROM public.notification_aggregates
    WHERE is_flushed = false
      AND window_expires_at <= now()
LOOP

    -- Look up the first actor's display name
    SELECT display_name INTO v_display_name
    FROM public.profiles
    WHERE user_id = v_record.actors[1] AND is_active = true
    LIMIT 1;

    v_display_name := COALESCE(v_display_name, 'Someone');
    v_body := NULL;

    -- ==============================
    -- SOCIAL: POST LIKED
    -- ==============================
    IF v_record.kind_key = 'social.post_liked' THEN

        IF v_record.total_count = 1 THEN
            v_title := v_display_name || ' liked your post';
        ELSE
            v_title := v_display_name || ' and ' || (v_record.total_count - 1) || ' others liked your post';
        END IF;

        v_route := '/social-post-detail/' || v_record.entity_id::text;

        v_context := jsonb_build_object(
            'entity_type', v_record.entity_type,
            'entity_id', v_record.entity_id,
            'post_id', v_record.entity_id,
            'actor_user_id', v_record.actors[1],
            'actor_display_name', v_display_name,
            'actor_user_ids', to_jsonb(v_record.actors),
            'total_count', v_record.total_count
        );

    -- ==============================
    -- SOCIAL: POST COMMENTED
    -- ==============================
    ELSIF v_record.kind_key = 'social.post_commented' THEN

        IF v_record.total_count = 1 THEN
            v_title := v_display_name || ' commented on your post';
        ELSE
            v_title := v_display_name || ' and ' || (v_record.total_count - 1) || ' others commented on your post';
        END IF;

        v_route := '/social-post-detail/' || v_record.entity_id::text;

        v_context := jsonb_build_object(
            'entity_type', v_record.entity_type,
            'entity_id', v_record.entity_id,
            'post_id', v_record.entity_id,
            'actor_user_id', v_record.actors[1],
            'actor_display_name', v_display_name,
            'actor_user_ids', to_jsonb(v_record.actors),
            'total_count', v_record.total_count
        );

    -- ==============================
    -- SOCIAL: POST REACTED
    -- ==============================
    ELSIF v_record.kind_key = 'social.post_reacted' THEN

        IF v_record.total_count = 1 THEN
            v_title := v_display_name || ' reacted to your post';
        ELSE
            v_title := v_display_name || ' and ' || (v_record.total_count - 1) || ' others reacted to your post';
        END IF;

        v_route := '/social-post-detail/' || v_record.entity_id::text;

        v_context := jsonb_build_object(
            'entity_type', v_record.entity_type,
            'entity_id', v_record.entity_id,
            'post_id', v_record.entity_id,
            'actor_user_id', v_record.actors[1],
            'actor_display_name', v_display_name,
            'actor_user_ids', to_jsonb(v_record.actors),
            'total_count', v_record.total_count
        );

    -- ==============================
    -- SOCIAL: FOLLOWED
    -- ==============================
    ELSIF v_record.kind_key = 'social.followed' THEN

        IF v_record.total_count = 1 THEN
            v_title := v_display_name || ' started following you';
        ELSE
            v_title := v_display_name || ' and ' || (v_record.total_count - 1) || ' others started following you';
        END IF;

        v_route := '/user-profile/' || v_record.actors[1]::text;

        v_context := jsonb_build_object(
            'entity_type', v_record.entity_type,
            'entity_id', v_record.entity_id,
            'actor_user_id', v_record.actors[1],
            'actor_display_name', v_display_name,
            'follower_user_ids', to_jsonb(v_record.actors),
            'total_count', v_record.total_count
        );

    -- ==============================
    -- SOCIAL: CIRCLE JOINED
    -- ==============================
    ELSIF v_record.kind_key = 'social.circle_joined' THEN

        IF v_record.total_count = 1 THEN
            v_title := v_display_name || ' joined your circle';
        ELSE
            v_title := v_display_name || ' and ' || (v_record.total_count - 1) || ' others joined your circle';
        END IF;

        v_route := '/user-profile/' || v_record.actors[1]::text;

        v_context := jsonb_build_object(
            'entity_type', v_record.entity_type,
            'entity_id', v_record.entity_id,
            'actor_user_id', v_record.actors[1],
            'actor_display_name', v_display_name,
            'actor_user_ids', to_jsonb(v_record.actors),
            'total_count', v_record.total_count
        );

    -- ==============================
    -- DEFAULT FALLBACK: catalog label, never a generic title
    -- ==============================
    ELSE
        SELECT label_en INTO v_title
        FROM public.notification_kinds
        WHERE key = v_record.kind_key;
        v_title := COALESCE(v_title, 'Notification');
        v_route := null;
        v_context := jsonb_build_object(
            'entity_type', v_record.entity_type,
            'entity_id', v_record.entity_id,
            'actor_user_id', v_record.actors[1],
            'actor_display_name', v_display_name,
            'actor_user_ids', to_jsonb(v_record.actors),
            'total_count', v_record.total_count
        );
    END IF;

    -- ==============================
    -- INSERT FINAL NOTIFICATION
    -- ==============================

    INSERT INTO public.notifications (
        to_user_id,
        kind_key,
        title,
        body,
        action_route,
        context,
        priority,
        ai_score,
        interaction_count,
        created_at
    )
    VALUES (
        v_record.to_user_id,
        v_record.kind_key,
        v_title,
        v_body,
        v_route,
        v_context,
        'normal',
        1,
        0,
        now()
    );

    -- mark as flushed
    UPDATE public.notification_aggregates
    SET is_flushed = true
    WHERE id = v_record.id;

    v_count := v_count + 1;

END LOOP;

RETURN v_count;

END;
$$;


ALTER FUNCTION "public"."flush_notification_aggregates"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_activity_log_sync"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.actor_user_id IS NULL THEN RETURN NEW; END IF;  -- skip system events (news)

  INSERT INTO public.activity_log
    (actor_user_id, event_type, activity_id, source_table, is_private, occurred_at, created_at)
  VALUES
    (NEW.actor_user_id, NEW.activity_type, NEW.id, NEW.source_table, false, NEW.occurred_at, now())
  ON CONFLICT DO NOTHING;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_activity_log_sync"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_feed_items_fanout"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_threshold      integer;
  v_follower_count integer;
BEGIN
  -- Only fan out feed-visible top-level types (not comments/reactions/joins which nest)
  IF NEW.activity_type NOT IN ('post', 'news', 'repost', 'game_create', 'meetup_create') THEN
    RETURN NEW;
  END IF;

  IF NEW.is_deleted OR NEW.is_hidden_admin THEN RETURN NEW; END IF;
  IF NEW.actor_profile_id IS NULL THEN RETURN NEW; END IF;

  -- Read threshold from singleton config
  SELECT push_pull_threshold INTO v_threshold FROM public.feed_rank_config LIMIT 1;
  v_threshold := COALESCE(v_threshold, 1000);

  -- Count actor's followers
  SELECT COUNT(*) INTO v_follower_count
  FROM public.profile_follows
  WHERE following_profile_id = NEW.actor_profile_id;

  -- Only push if below threshold (high-follower actors are pulled at read time)
  IF v_follower_count >= v_threshold THEN
    RETURN NEW;
  END IF;

  -- Fan out to all followers
  INSERT INTO public.feed_items
    (recipient_profile_id, activity_id, actor_profile_id,
     activity_type, parent_activity_id, created_at)
  SELECT
    pf.follower_profile_id,
    NEW.id,
    NEW.actor_profile_id,
    NEW.activity_type,
    NEW.parent_activity_id,
    NEW.created_at
  FROM public.profile_follows pf
  WHERE pf.following_profile_id = NEW.actor_profile_id
  ON CONFLICT (recipient_profile_id, activity_id) DO NOTHING;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_feed_items_fanout"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_game_roster_activity_sync"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT'
     AND NEW.role IN ('player', 'host')
     AND NEW.status = 'active' THEN

    INSERT INTO public.public_activities
      (id, activity_type, source_table,
       parent_activity_id,
       actor_user_id, actor_profile_id, target_profile_id,
       visibility,
       occurred_at, created_at, updated_at)
    VALUES (
      NEW.id, 'game_join', 'game_roster',
      NEW.game_id,   -- game_id = game's public_activities.id (shared UUID)
      NEW.user_id, NEW.profile_id,
      (SELECT creator_profile_id FROM public.games WHERE id = NEW.game_id),
      'public',
      COALESCE(NEW.joined_at, now()), COALESCE(NEW.joined_at, now()), COALESCE(NEW.joined_at, now())
    )
    ON CONFLICT (id) DO NOTHING;

    -- Bump the game's reply_count as a proxy for "participants"
    UPDATE public.public_activities
    SET reply_count = reply_count + 1, updated_at = now()
    WHERE id = NEW.game_id;

  ELSIF TG_OP = 'UPDATE' AND NEW.status IN ('left', 'kicked') AND OLD.status = 'active' THEN
    UPDATE public.public_activities
    SET is_deleted = true, updated_at = now()
    WHERE id = NEW.id;

    UPDATE public.public_activities
    SET reply_count = GREATEST(reply_count - 1, 0), updated_at = now()
    WHERE id = NEW.game_id;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_game_roster_activity_sync"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_games_activity_sync"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.public_activities
      (id, activity_type, source_table,
       actor_user_id, actor_profile_id, target_profile_id,
       visibility, sport_id, area_id, geo_location_id,
       is_deleted, is_hidden_admin, is_pinned,
       occurred_at, created_at, updated_at)
    VALUES (
      NEW.id, 'game_create', 'games',
      NEW.creator_user_id, NEW.creator_profile_id, NEW.creator_profile_id,
      'public', NEW.sport_id, NEW.area_id, NEW.geo_location_id,
      false, false, false,
      NEW.created_at, NEW.created_at, NEW.updated_at
    )
    ON CONFLICT (id) DO NOTHING;

  ELSIF TG_OP = 'UPDATE' THEN
    UPDATE public.public_activities
    SET is_deleted  = COALESCE(NEW.is_cancelled, false),
        updated_at  = NEW.updated_at
    WHERE id = NEW.id;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_games_activity_sync"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_games_inherit_geo"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_geo_location_id uuid;
  v_area_id         uuid;
BEGIN
  -- Priority 1: venue_space_id
  IF NEW.venue_space_id IS NOT NULL THEN
    SELECT v.geo_location_id, gl.area_id
      INTO v_geo_location_id, v_area_id
      FROM venue_spaces  vs
      JOIN venues        v  ON v.id  = vs.venue_id
      JOIN geo_locations gl ON gl.id = v.geo_location_id
     WHERE vs.id = NEW.venue_space_id;

  -- Priority 2: venue_id
  ELSIF NEW.venue_id IS NOT NULL THEN
    SELECT v.geo_location_id, gl.area_id
      INTO v_geo_location_id, v_area_id
      FROM venues        v
      JOIN geo_locations gl ON gl.id = v.geo_location_id
     WHERE v.id = NEW.venue_id;
  END IF;

  IF v_geo_location_id IS NOT NULL THEN
    NEW.geo_location_id := v_geo_location_id;
    NEW.area_id         := v_area_id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_games_inherit_geo"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_games_sync_joining_rule"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_joining_rule text;
BEGIN
  IF NEW.venue_space_id IS NOT NULL THEN
    SELECT vs.joining_rule INTO v_joining_rule
      FROM public.venue_spaces vs WHERE vs.id = NEW.venue_space_id;
    NEW.joining_rule := COALESCE(v_joining_rule, 'free');
    IF TG_OP = 'INSERT' THEN
      NEW.cost_cover := NEW.joining_rule;
    ELSIF TG_OP = 'UPDATE' AND OLD.joining_rule <> NEW.joining_rule THEN
      NEW.cost_cover := NEW.joining_rule;
    END IF;
  ELSE
    NEW.joining_rule := 'free';
    IF TG_OP = 'INSERT' THEN NEW.cost_cover := 'free'; END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_games_sync_joining_rule"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_get_wallet"("p_owner_type" "text", "p_owner_id" "uuid", "p_currency" "text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_wallet_id uuid;
BEGIN
  SELECT id
  INTO v_wallet_id
  FROM public.wallets
  WHERE owner_type = p_owner_type
    AND owner_id = p_owner_id
    AND currency = p_currency;

  IF v_wallet_id IS NULL THEN
    INSERT INTO public.wallets (owner_type, owner_id, currency)
    VALUES (p_owner_type, p_owner_id, p_currency)
    RETURNING id INTO v_wallet_id;
  END IF;

  RETURN v_wallet_id;
END;
$$;


