CREATE OR REPLACE FUNCTION "public"."fn_likes_notify"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_target_uid   uuid;
  v_activity_type text;
BEGIN
  IF TG_OP != 'INSERT' THEN RETURN NEW; END IF;

  SELECT pa.actor_user_id, pa.activity_type
    INTO v_target_uid, v_activity_type
  FROM public.public_activities pa
  WHERE pa.id = NEW.parent_activity_id;

  -- Don't notify if liking your own content
  IF v_target_uid IS NULL OR v_target_uid = NEW.actor_user_id THEN RETURN NEW; END IF;

  PERFORM public.process_notification_event(
    v_target_uid,
    CASE v_activity_type
      WHEN 'comment' THEN 'social.comment_liked'
      ELSE 'social.post_liked'
    END,
    v_activity_type,
    NEW.parent_activity_id,
    NEW.actor_user_id,
    NULL,
    NULL
  );
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_likes_notify"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_likes_sync"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_source_table text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE public.public_activities
      SET like_count = like_count + 1, updated_at = now()
    WHERE id = NEW.parent_activity_id;

    SELECT source_table INTO v_source_table
      FROM public.public_activities WHERE id = NEW.parent_activity_id;

    IF v_source_table = 'posts' THEN
      UPDATE public.posts SET like_count = like_count + 1 WHERE id = NEW.parent_activity_id;
    ELSIF v_source_table = 'published_news' THEN
      UPDATE public.published_news SET like_count = like_count + 1 WHERE id = NEW.parent_activity_id;
    ELSIF v_source_table = 'comments' THEN
      UPDATE public.comments SET like_count = like_count + 1 WHERE id = NEW.parent_activity_id;
    END IF;

  ELSIF TG_OP = 'DELETE' THEN
    UPDATE public.public_activities
      SET like_count = GREATEST(like_count - 1, 0), updated_at = now()
    WHERE id = OLD.parent_activity_id;

    SELECT source_table INTO v_source_table
      FROM public.public_activities WHERE id = OLD.parent_activity_id;

    IF v_source_table = 'posts' THEN
      UPDATE public.posts
        SET like_count = GREATEST(like_count - 1, 0) WHERE id = OLD.parent_activity_id;
    ELSIF v_source_table = 'published_news' THEN
      UPDATE public.published_news
        SET like_count = GREATEST(like_count - 1, 0) WHERE id = OLD.parent_activity_id;
    ELSIF v_source_table = 'comments' THEN
      UPDATE public.comments
        SET like_count = GREATEST(like_count - 1, 0) WHERE id = OLD.parent_activity_id;
    END IF;
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


