CREATE OR REPLACE FUNCTION "public"."fn_news_activity_sync"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- Only emit an activity row when the article is published and feed-visible
    IF NEW.status = 'published' AND NEW.show_in_feed = true THEN
      INSERT INTO public.public_activities
        (id, activity_type, source_table,
         actor_user_id, actor_profile_id, target_profile_id,
         visibility, sport_id, area_id, geo_location_id,
         is_deleted, is_hidden_admin, is_pinned,
         occurred_at, created_at, updated_at)
      VALUES (
        NEW.id, 'news', 'news',
        NEW.created_by,   -- nullable: system-published news has no user
        NULL, NULL,
        'public', NEW.sport_id, NEW.area_id, NULL,
        false, false, COALESCE(NEW.is_pinned, false),
        COALESCE(NEW.published_at, NEW.created_at), NEW.created_at, NEW.updated_at
      )
      ON CONFLICT (id) DO NOTHING;
    END IF;

  ELSIF TG_OP = 'UPDATE' THEN
    -- If it just became published+feed-visible, insert the activity row
    IF NEW.status = 'published' AND NEW.show_in_feed = true
       AND (OLD.status <> 'published' OR OLD.show_in_feed = false) THEN
      INSERT INTO public.public_activities
        (id, activity_type, source_table,
         actor_user_id, actor_profile_id, target_profile_id,
         visibility, sport_id, area_id, geo_location_id,
         is_deleted, is_hidden_admin, is_pinned,
         occurred_at, created_at, updated_at)
      VALUES (
        NEW.id, 'news', 'news',
        NEW.created_by, NULL, NULL,
        'public', NEW.sport_id, NEW.area_id, NULL,
        false, false, COALESCE(NEW.is_pinned, false),
        COALESCE(NEW.published_at, NEW.created_at), NEW.created_at, NEW.updated_at
      )
      ON CONFLICT (id) DO NOTHING;
    ELSE
      -- Sync mutable fields on existing activity row
      UPDATE public.public_activities
      SET is_pinned  = COALESCE(NEW.is_pinned, is_pinned),
          updated_at = NEW.updated_at
      WHERE id = NEW.id;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


