CREATE OR REPLACE FUNCTION "public"."fn_normalize_area_location"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Only attempt snap when codes are missing
  IF NEW.city_code IS NULL OR NEW.country_code IS NULL THEN
    SELECT a.city_code, a.country_code
    INTO   NEW.city_code, NEW.country_code
    FROM   public.areas a
    WHERE  a.city_code    IS NOT NULL
      AND  a.country_code IS NOT NULL
      AND  a.is_verified  = true
      AND  (
        (NEW.center_lat - a.center_lat)^2 +
        (NEW.center_lng - a.center_lng)^2
      ) < (0.9)^2   -- ~100 km bounding box fast pre-filter
    ORDER BY
      (NEW.center_lat - a.center_lat)^2 +
      (NEW.center_lng - a.center_lng)^2
    ASC
    LIMIT 1;
  END IF;

  RETURN NEW;
END;
$$;


