CREATE OR REPLACE FUNCTION "public"."fn_post_comments_activity_sync"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.public_activities
      (id, activity_type, source_table, parent_activity_id,
       actor_user_id, actor_profile_id, target_profile_id,
       visibility, sport_id, area_id, geo_location_id,
       is_deleted, is_hidden_admin, occurred_at, created_at, updated_at)
    VALUES (
      NEW.id, 'comment', 'comments', NEW.parent_activity_id,
      NEW.author_user_id, NEW.author_profile_id,
      (SELECT actor_profile_id FROM public.public_activities WHERE id = NEW.parent_activity_id),
      'public',
      (SELECT sport_id        FROM public.public_activities WHERE id = NEW.parent_activity_id),
      (SELECT area_id         FROM public.public_activities WHERE id = NEW.parent_activity_id),
      (SELECT geo_location_id FROM public.public_activities WHERE id = NEW.parent_activity_id),
      false, false, NEW.created_at, NEW.created_at, NEW.created_at
    ) ON CONFLICT (id) DO NOTHING;
    UPDATE public.public_activities
      SET reply_count = reply_count + 1, updated_at = now()
    WHERE id = NEW.parent_activity_id;
  ELSIF TG_OP = 'UPDATE' THEN
    UPDATE public.public_activities
      SET is_deleted = NEW.is_deleted, is_hidden_admin = NEW.is_hidden_admin, updated_at = now()
    WHERE id = NEW.id;
    IF NEW.is_deleted = true AND OLD.is_deleted = false THEN
      UPDATE public.public_activities
        SET reply_count = GREATEST(reply_count - 1, 0), updated_at = now()
      WHERE id = NEW.parent_activity_id;
    ELSIF NEW.is_deleted = false AND OLD.is_deleted = true THEN
      UPDATE public.public_activities
        SET reply_count = reply_count + 1, updated_at = now()
      WHERE id = NEW.parent_activity_id;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


