CREATE OR REPLACE FUNCTION "public"."game_rating_rebuild_all"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare gid uuid; n int := 0;
begin
  for gid in select id from public.games loop
    perform public.game_rating_recompute(gid); n := n + 1;
  end loop;
  return n;
end $$;


ALTER FUNCTION "public"."game_rating_rebuild_all"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."game_rating_recompute"("p_game_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  cfg record;
  dim record;
  dim_sum numeric; dim_cnt numeric; dim_mean numeric;
  sum_map jsonb := '{}'::jsonb;
  cnt_map jsonb := '{}'::jsonb;
  comp numeric := 0.0; total_w numeric := 0.0;
  evt_count int;
begin
  select * into cfg from public._get_context_config('game');

  for dim in select key, weight from public.game_rating_dimensions where is_active loop
    select
      coalesce(sum( public._clamp_star((e.scores ->> dim.key)::numeric) *
                    public._decay_factor(e.created_at, cfg.half_life_days) ), 0.0),
      coalesce(sum( case when e.scores ? dim.key then public._decay_factor(e.created_at, cfg.half_life_days) else 0 end ), 0.0)
    into dim_sum, dim_cnt
    from public.game_rating_events e
    where e.game_id = p_game_id;

    sum_map := sum_map || jsonb_build_object(dim.key, round(dim_sum::numeric,3));
    cnt_map := cnt_map || jsonb_build_object(dim.key, round(dim_cnt::numeric,3));

    dim_mean := case when (cfg.prior_weight + dim_cnt) > 0
                     then (cfg.prior_mean * cfg.prior_weight + dim_sum) / (cfg.prior_weight + dim_cnt)
                     else cfg.prior_mean
                end;

    comp := comp + coalesce(dim.weight,0.0) * dim_mean;
    total_w := total_w + coalesce(dim.weight,0.0);
  end loop;

  if total_w > 0 then comp := comp / total_w; else comp := coalesce(cfg.prior_mean,4.5); end if;

  select count(*) into evt_count from public.game_rating_events where game_id=p_game_id;

  insert into public.game_rating_aggregate(game_id,event_count,dim_sums,dim_counts,composite_score,last_event_at,updated_at)
  values (
    p_game_id, evt_count, sum_map, cnt_map, round(comp::numeric,2),
    (select max(created_at) from public.game_rating_events where game_id=p_game_id),
    now()
  )
  on conflict (game_id) do update set
    event_count     = excluded.event_count,
    dim_sums        = excluded.dim_sums,
    dim_counts      = excluded.dim_counts,
    composite_score = excluded.composite_score,
    last_event_at   = excluded.last_event_at,
    updated_at      = excluded.updated_at;
end;
$$;


ALTER FUNCTION "public"."game_rating_recompute"("p_game_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."game_slots_left"("p_game" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH g AS (SELECT capacity, game_type FROM public.games WHERE id = p_game),
  active AS (
    SELECT count(*)::int AS c
    FROM public.game_roster r
    JOIN g ON true
    WHERE r.game_id = p_game AND r.status = 'active'
      AND (r.role = 'player' OR (r.role = 'host' AND g.game_type = 'hosted'))
  )
  SELECT GREATEST((SELECT capacity FROM g) - (SELECT c FROM active), 0)
$$;


ALTER FUNCTION "public"."game_slots_left"("p_game" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."game_slots_left"("p_game" "uuid") IS 'Remaining player slots (capacity - active players).';



