CREATE OR REPLACE FUNCTION "public"."generate_slot_grid_range"("p_from" "date", "p_to" "date", "p_granularity_minutes" integer DEFAULT 60, "p_sport" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  rec record;           -- <- record variable
  d   date;
  total int := 0;
begin
  if p_to < p_from then
    raise exception using errcode='P0001', message='invalid_date_range';
  end if;

  for rec in
    select sp.id as space_id
    from public.venue_spaces sp
    join public.venues v on v.id = sp.venue_id
    where sp.is_active = true
      and v.is_active = true
      and (p_sport is null or sp.sport = p_sport)
      and (p_city  is null or v.city  = p_city)
  loop
    d := p_from;
    while d <= p_to loop
      total := total + public.generate_space_slot_grid(rec.space_id, d, p_granularity_minutes);
      d := d + 1;
    end loop;
  end loop;

  return total;
end;
$$;


ALTER FUNCTION "public"."generate_slot_grid_range"("p_from" "date", "p_to" "date", "p_granularity_minutes" integer, "p_sport" "text", "p_city" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_space_slot_grid"("p_space_id" "uuid", "p_date" "date", "p_granularity_minutes" integer DEFAULT 60) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  tz text;
  wd int;
  open_t time; close_t time; open_flag boolean;
  day_start timestamptz; day_end timestamptz;
  cur timestamptz; nxt timestamptz;
  inserted int := 0;
begin
  if p_granularity_minutes not in (30,45,60,90,120) then
    raise exception using errcode='P0001', message='invalid_granularity';
  end if;

  select v.timezone into tz
  from public.venue_spaces s join public.venues v on v.id = s.venue_id
  where s.id = p_space_id;
  if tz is null then tz := 'Asia/Dubai'; end if;

  day_start := (p_date::timestamptz at time zone tz);
  day_end   := ((p_date + 1)::timestamptz at time zone tz);
  wd := extract(dow from day_start at time zone tz);

  select open_time, close_time, is_open
    into open_t, close_t, open_flag
  from public.opening_hours
  where venue_space_id = p_space_id and weekday = wd;

  delete from public.space_slot_grid
   where venue_space_id = p_space_id
     and slot_date = p_date
     and granularity_minutes = p_granularity_minutes
     and version = 1;

  if open_flag is distinct from true or open_t is null or close_t is null or close_t <= open_t then
    return 0;
  end if;

  cur := (date_trunc('day', day_start at time zone tz) + open_t) at time zone tz;
  nxt := cur + make_interval(mins => p_granularity_minutes);

  while nxt <= (date_trunc('day', day_start at time zone tz) + close_t) at time zone tz loop
    insert into public.space_slot_grid(
      venue_space_id, slot_date, slot_start, slot_end,
      granularity_minutes, base_price_aed, version
    )
    values (
      p_space_id, p_date, cur, nxt,
      p_granularity_minutes,
      public._compute_slot_price_for_window(p_space_id, cur, nxt),
      1
    )
    on conflict do nothing;

    inserted := inserted + 1;
    cur := nxt;
    nxt := cur + make_interval(mins => p_granularity_minutes);
  end loop;

  return inserted;
end;
$$;


ALTER FUNCTION "public"."generate_space_slot_grid"("p_space_id" "uuid", "p_date" "date", "p_granularity_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."geo_nearby_venues"("in_lat" double precision, "in_lng" double precision, "in_radius_m" double precision DEFAULT 5000, "in_limit" integer DEFAULT 20, "in_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "name" "text", "description" "text", "address" "text", "city" "text", "district" "text", "lat" double precision, "lng" double precision, "is_active" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "distance_m" double precision)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    v.id,
    v.name_en        AS name,
    v.description_en AS description,
    v.address_en     AS address,
    a.city           AS city,
    a.district       AS district,
    ST_Y(gl.location::geometry) AS lat,
    ST_X(gl.location::geometry) AS lng,
    v.is_active,
    v.created_at,
    v.updated_at,
    ST_Distance(
      gl.location,
      ST_SetSRID(ST_MakePoint(in_lng, in_lat), 4326)::geography
    ) AS distance_m
  FROM   venues v
  JOIN   geo_locations gl ON v.geo_location_id = gl.id
  LEFT   JOIN areas a ON v.area_id = a.id
  WHERE  v.is_active = true
    AND  ST_DWithin(
           gl.location,
           ST_SetSRID(ST_MakePoint(in_lng, in_lat), 4326)::geography,
           in_radius_m
         )
  ORDER  BY distance_m ASC
  LIMIT  in_limit
  OFFSET in_offset;
$$;


ALTER FUNCTION "public"."geo_nearby_venues"("in_lat" double precision, "in_lng" double precision, "in_radius_m" double precision, "in_limit" integer, "in_offset" integer) OWNER TO "postgres";


