CREATE OR REPLACE FUNCTION "public"."get_check_in_status"("p_user_id" "uuid") RETURNS TABLE("streak_count" integer, "total_days_completed" integer, "is_completed" boolean, "last_check_in" timestamp with time zone, "checked_in_today" boolean, "days_remaining" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_today DATE := CURRENT_DATE;
BEGIN
    -- Security check
    IF auth.uid() != p_user_id THEN
        RETURN;
    END IF;
    
    RETURN QUERY
    SELECT 
        COALESCE(uc.streak_count, 0)::INTEGER,
        COALESCE(uc.total_days_completed, 0)::INTEGER,
        COALESCE(uc.is_completed, FALSE)::BOOLEAN,
        uc.last_check_in,
        EXISTS(SELECT 1 FROM public.check_in_logs WHERE user_id = p_user_id AND check_in_date = v_today)::BOOLEAN,
        GREATEST(14 - COALESCE(uc.total_days_completed, 0), 0)::INTEGER
    FROM public.user_check_ins uc
    WHERE uc.user_id = p_user_id;
END;
$$;


ALTER FUNCTION "public"."get_check_in_status"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_feed"("p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS SETOF "public"."posts"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    SET "row_security" TO 'off'
    AS $$
  SELECT p.* FROM public.posts p
  WHERE p.is_deleted = false AND p.is_hidden_admin = false AND p.is_active = true
    AND can_view_post(p.id, auth.uid(), current_setting('request.jwt.claim.profile_id', true)::uuid)
    AND NOT public.is_blocked(auth.uid(), p.author_user_id)
  ORDER BY (
    (p.like_count * 2) + (p.comment_count * 3) + (p.repost_count * 4)
    + (p.view_count * 0.2) + (p.priority_score * 5)
    + get_freshness_score(p.created_at)
  ) DESC
  LIMIT p_limit OFFSET p_offset;
$$;


ALTER FUNCTION "public"."get_feed"("p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_freshness_score"("ts" timestamp with time zone) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN CASE
    WHEN ts > now() - interval '2 hours' THEN 50
    WHEN ts > now() - interval '24 hours' THEN 20
    ELSE 0
  END;
END;
$$;


ALTER FUNCTION "public"."get_freshness_score"("ts" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_games_needing_players"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_agg(row_to_json(t)) INTO result
  FROM (
    SELECT
      g.id                                      AS game_id,
      g.sport_id,
      g.area_id,
      g.capacity,
      s.sport_key,
      a.city,
      COUNT(gr.profile_id)                      AS current_players,
      g.capacity - COUNT(gr.profile_id)         AS spots_remaining,
      -- get all profile_ids already in this game as array
      ARRAY_AGG(gr.profile_id) FILTER (WHERE gr.profile_id IS NOT NULL) AS existing_profiles
    FROM public.games g
    JOIN public.sports s       ON s.id = g.sport_id
    JOIN public.areas a        ON a.id = g.area_id
    LEFT JOIN public.game_roster gr
                               ON gr.game_id = g.id AND gr.status = 'active'
    WHERE g.is_cancelled = false
      AND g.start_at > now()
    GROUP BY g.id, g.sport_id, g.area_id, g.capacity, s.sport_key, a.city
    HAVING g.capacity - COUNT(gr.profile_id) > 0
    ORDER BY spots_remaining DESC
  ) t;

  RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."get_games_needing_players"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_home_feed"("p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS SETOF "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  -- CTE: original posts (no repost metadata)
  WITH originals AS (
    SELECT
      p.*,
      NULL::uuid     AS repost_id,
      NULL::text     AS reposter_display_name,
      NULL::text     AS reposter_username,
      NULL::text     AS reposter_avatar_url,
      NULL::uuid     AS reposter_user_id,
      NULL::uuid     AS reposter_profile_id,
      NULL::text     AS repost_commentary,
      NULL::timestamptz AS repost_created_at,
      p.created_at   AS sort_time
    FROM posts p
    WHERE p.is_deleted = false
      AND p.is_hidden_admin = false
  ),
  -- CTE: reposts — only for PUBLIC original posts
  reposts AS (
    SELECT
      p.*,
      r.id           AS repost_id,
      prof.display_name AS reposter_display_name,
      prof.username     AS reposter_username,
      prof.avatar_url   AS reposter_avatar_url,
      r.reposter_user_id,
      r.reposter_profile_id,
      r.commentary      AS repost_commentary,
      r.created_at      AS repost_created_at,
      r.created_at      AS sort_time
    FROM post_reposts r
    JOIN posts p ON p.id = r.original_post_id
    JOIN profiles prof ON prof.id = r.reposter_profile_id
    WHERE p.is_deleted = false
      AND p.is_hidden_admin = false
      AND p.visibility = 'public'
  ),
  combined AS (
    SELECT * FROM originals
    UNION ALL
    SELECT * FROM reposts
  )
  SELECT to_jsonb(c) FROM combined c
  ORDER BY c.sort_time DESC, c.id DESC
  LIMIT p_limit
  OFFSET p_offset;
$$;


ALTER FUNCTION "public"."get_home_feed"("p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_home_feed"("p_limit" integer DEFAULT 50, "p_cursor" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("activity_id" "uuid", "activity_type" "text", "parent_activity_id" "uuid", "actor_profile_id" "uuid", "created_at" timestamp with time zone, "seen_at" timestamp with time zone, "source" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_my_profile_id  uuid;
  v_my_uid         uuid := auth.uid();
  v_threshold      integer;
BEGIN
  SELECT id INTO v_my_profile_id
  FROM public.profiles WHERE user_id = v_my_uid LIMIT 1;

  IF v_my_profile_id IS NULL THEN RETURN; END IF;

  SELECT push_pull_threshold INTO v_threshold FROM public.feed_rank_config LIMIT 1;
  v_threshold := COALESCE(v_threshold, 1000);

  RETURN QUERY
  WITH blocked_profile_ids AS (
    SELECT p.id
    FROM public.profiles p
    JOIN public.user_blocks ub
      ON (ub.blocker_user_id = v_my_uid AND ub.blocked_user_id = p.user_id)
      OR (ub.blocked_user_id = v_my_uid AND ub.blocker_user_id = p.user_id)
  ),
  combined AS (
    -- Push path: pre-materialised rows for this recipient
    SELECT
      fi.activity_id,
      fi.activity_type,
      fi.parent_activity_id,
      fi.actor_profile_id,
      fi.created_at,
      fi.seen_at,
      1 AS path_priority,
      'push'::text AS source
    FROM public.feed_items fi
    WHERE fi.recipient_profile_id = v_my_profile_id
      AND fi.hidden_at IS NULL
      AND (p_cursor IS NULL OR fi.created_at < p_cursor)
      AND fi.actor_profile_id NOT IN (SELECT id FROM blocked_profile_ids)

    UNION ALL

    -- Pull path: activities from high-follower users the caller follows
    SELECT
      pa.id,
      pa.activity_type,
      pa.parent_activity_id,
      pa.actor_profile_id,
      pa.created_at,
      NULL::timestamptz,
      2,
      'pull'::text
    FROM public.public_activities pa
    WHERE pa.activity_type IN ('post', 'news', 'repost', 'game_create', 'meetup_create')
      AND NOT pa.is_deleted
      AND NOT pa.is_hidden_admin
      AND (p_cursor IS NULL OR pa.created_at < p_cursor)
      AND pa.actor_profile_id NOT IN (SELECT id FROM blocked_profile_ids)
      AND pa.actor_profile_id IN (
        SELECT pf.following_profile_id
        FROM public.profile_follows pf
        WHERE pf.follower_profile_id = v_my_profile_id
          AND (
            SELECT COUNT(*) FROM public.profile_follows
            WHERE following_profile_id = pf.following_profile_id
          ) >= v_threshold
      )

    UNION ALL

    -- Discovery path: all recent public activities (ensures feed is never empty)
    SELECT
      pa.id,
      pa.activity_type,
      pa.parent_activity_id,
      pa.actor_profile_id,
      pa.created_at,
      NULL::timestamptz,
      3,
      'discovery'::text
    FROM public.public_activities pa
    WHERE pa.activity_type IN ('post', 'news', 'repost', 'game_create', 'meetup_create')
      AND NOT pa.is_deleted
      AND NOT pa.is_hidden_admin
      AND pa.visibility = 'public'
      AND (p_cursor IS NULL OR pa.created_at < p_cursor)
      AND pa.actor_profile_id NOT IN (SELECT id FROM blocked_profile_ids)
  ),
  -- Deduplicate: keep highest-priority path per activity, then sort by recency
  deduped AS (
    SELECT DISTINCT ON (c.activity_id)
      c.activity_id,
      c.activity_type,
      c.parent_activity_id,
      c.actor_profile_id,
      c.created_at,
      c.seen_at,
      c.source
    FROM combined c
    ORDER BY c.activity_id, c.path_priority ASC, c.created_at DESC
  )
  SELECT
    d.activity_id,
    d.activity_type,
    d.parent_activity_id,
    d.actor_profile_id,
    d.created_at,
    d.seen_at,
    d.source
  FROM deduped d
  ORDER BY d.created_at DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."get_home_feed"("p_limit" integer, "p_cursor" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_nearby_games"("p_lat" double precision, "p_lng" double precision, "p_radius" double precision DEFAULT 5000) RETURNS TABLE("id" "uuid", "title" "text", "lat" double precision, "lng" double precision, "start_at" timestamp with time zone, "capacity" integer, "sport_id" "uuid", "area_id" "uuid", "distance_meters" double precision)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    g.id,
    g.title,
    g.lat,
    g.lng,
    g.start_at,
    g.capacity,
    g.sport_id,
    g.area_id,
    ST_Distance(
      gl.location,
      ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography
    ) AS distance_meters
  FROM games g
  JOIN geo_locations gl ON g.geo_location_id = gl.id
  WHERE
    g.is_cancelled = false
    AND g.start_at > now()
    AND ST_DWithin(
      gl.location,
      ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography,
      p_radius
    )
  ORDER BY
    distance_meters ASC,
    g.start_at ASC
  LIMIT 20;
END;
$$;


