CREATE OR REPLACE FUNCTION "public"."get_nearby_posts"("p_lat" double precision, "p_lng" double precision, "p_radius" integer DEFAULT 5000) RETURNS TABLE("id" "uuid", "body" "text", "author_profile_id" "uuid", "created_at" timestamp with time zone, "like_count" integer, "comment_count" integer, "lat" double precision, "lng" double precision, "distance_meters" double precision, "is_nearby" boolean, "score" double precision)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY

  SELECT
    p.id,
    p.body,
    p.author_profile_id,
    p.created_at,
    p.like_count,
    p.comment_count,

    COALESCE(ST_Y(gl.location::geometry), p.geo_lat) AS lat,
    COALESCE(ST_X(gl.location::geometry), p.geo_lng) AS lng,

    -- distance
    CASE
      WHEN gl.location IS NOT NULL THEN
        ST_Distance(
          gl.location,
          ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography
        )
      ELSE NULL
    END AS distance_meters,

    (gl.location IS NOT NULL) AS is_nearby,

    -- 🔥 FINAL SCORE
    (
      -- GEO SCORE
      (
        CASE
          WHEN gl.location IS NULL THEN 0.2
          ELSE 1 / (1 + (
            ST_Distance(
              gl.location,
              ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography
            ) / 1000
          ))
        END
      ) * 0.5

      +

      -- RECENCY SCORE
      (
        EXP(
          - EXTRACT(EPOCH FROM (now() - p.created_at)) / 3600 / 24
        )
      ) * 0.3

      +

      -- ENGAGEMENT SCORE
      (
        LN(1 + p.like_count + p.comment_count * 2)
      ) * 0.2

    ) AS score

  FROM posts p
  LEFT JOIN geo_locations gl ON p.geo_location_id = gl.id

  WHERE
    p.is_deleted = false
    AND p.is_hidden_admin = false
    AND p.is_active = true

  ORDER BY
    score DESC

  LIMIT 30;
END;
$$;


ALTER FUNCTION "public"."get_nearby_posts"("p_lat" double precision, "p_lng" double precision, "p_radius" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_nearby_profiles"("p_lat" double precision, "p_lng" double precision, "p_radius" integer DEFAULT 5000) RETURNS TABLE("id" "uuid", "username" "text", "avatar" "text", "lat" double precision, "lng" double precision, "distance_meters" double precision)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    p.id,
    p.username,
    p.avatar_url AS avatar,
    p.latitude   AS lat,
    p.longitude  AS lng,
    ST_Distance(
      ST_SetSRID(ST_MakePoint(p.longitude, p.latitude), 4326)::geography,
      ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography
    ) AS distance_meters
  FROM public.profiles p
  LEFT JOIN public.privacy_settings ps ON ps.user_id = p.user_id
  WHERE p.latitude IS NOT NULL
    AND p.longitude IS NOT NULL
    AND COALESCE(ps.show_location, true) = true
    AND (auth.uid() IS NULL OR p.user_id IS DISTINCT FROM auth.uid())
    AND ST_DWithin(
      ST_SetSRID(ST_MakePoint(p.longitude, p.latitude), 4326)::geography,
      ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography,
      p_radius
    )
  ORDER BY distance_meters ASC
  LIMIT 50;
$$;


