CREATE OR REPLACE FUNCTION "public"."get_recent_posts_for_engagement"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE result jsonb;
BEGIN
  SELECT jsonb_agg(row_to_json(t)) INTO result
  FROM (
    SELECT DISTINCT ON (po.id)
      po.id AS post_id, po.sport_id, po.area_id,
      s.sport_key, a.city, a.name AS area_name,
      p.id AS engager_profile_id, p.user_id AS engager_user_id,
      p.display_name AS engager_display_name
    FROM public.posts po
    JOIN public.sports s   ON s.id = po.sport_id
    JOIN public.areas a    ON a.id = po.area_id
    JOIN public.profiles p ON p.city = a.city AND p.primary_sport = po.sport_id
                          AND p.is_original = false AND p.id != po.author_profile_id
    LEFT JOIN public.comments pc
           ON pc.parent_activity_id = po.id AND pc.author_profile_id = p.id
    WHERE po.is_deleted = false AND po.created_at > now() - interval '30 days' AND pc.id IS NULL
    ORDER BY po.id, random()
    LIMIT 15
  ) t;
  RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


