  is_first boolean;
begin
  select count(*) = 1 into is_first
  from posts
  where author_user_id = new.author_user_id;

  insert into activity_events (
    event_type,
    actor_user_id,
    post_id,
    metadata
  )
  values (
    (case when is_first then 'first_post_created' else 'post_created' end)::activity_event_type,
    new.author_profile_id,   -- ← was: new.author_user_id (wrong FK target)
    new.id,
    jsonb_build_object('is_first', is_first)
  );

  return new;
end;
$$;


