CREATE OR REPLACE FUNCTION "public"."is_in_quiet_hours"("p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_settings RECORD;
    v_now_min integer;
BEGIN

    SELECT *
    INTO v_settings
    FROM public.notification_settings
    WHERE user_id = p_user_id;

    IF NOT FOUND OR v_settings.quiet_start_min IS NULL THEN
        RETURN false;
    END IF;

    v_now_min :=
        EXTRACT(HOUR FROM now())::int * 60 +
        EXTRACT(MINUTE FROM now())::int;

    IF v_settings.quiet_start_min <= v_settings.quiet_end_min THEN
        RETURN v_now_min BETWEEN
            v_settings.quiet_start_min AND v_settings.quiet_end_min;
    ELSE
        RETURN v_now_min >= v_settings.quiet_start_min
            OR v_now_min <= v_settings.quiet_end_min;
    END IF;

END;
$$;


ALTER FUNCTION "public"."is_in_quiet_hours"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_in_quiet_hours"("p_now" timestamp with time zone, "p_tz" "text", "p_start_min" integer, "p_end_min" integer) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with m as (
    select public._minutes_since_midnight(p_now, p_tz) as cur
  )
  select case
    when p_start_min is null or p_end_min is null then false
    when p_start_min = p_end_min then false                     -- 0-length = disabled
    when p_start_min < p_end_min then (select cur between p_start_min and p_end_min-1 from m)
    else (select cur >= p_start_min or cur < p_end_min from m)  -- wraps midnight
  end
$$;


ALTER FUNCTION "public"."is_in_quiet_hours"("p_now" timestamp with time zone, "p_tz" "text", "p_start_min" integer, "p_end_min" integer) OWNER TO "postgres";


