CREATE OR REPLACE FUNCTION "public"."is_quiet_hour"("p_user" "uuid", "p_at" timestamp with time zone DEFAULT "now"()) RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  tz text;
  qs time;
  qe time;
  local_time time;
begin
  select timezone, quiet_start, quiet_end into tz, qs, qe
  from public.user_settings where user_id = p_user;

  if tz is null or qs is null or qe is null then
    return false; -- no quiet hours configured
  end if;

  -- Convert p_at to user's local time
  local_time := (p_at at time zone tz)::time;

  if qs < qe then
    -- same-day window (e.g., 22:00–08:00 doesn't fit here; handled below)
    return local_time >= qs and local_time < qe;
  else
    -- overnight window (e.g., 23:00–08:00)
    return (local_time >= qs) or (local_time < qe);
  end if;
end;
$$;


