CREATE OR REPLACE FUNCTION "public"."is_username_available"("p_username" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
  u text := public.normalize_username(p_username);
  reserved_active boolean;
  taken_active boolean;
begin
  -- banned?
  if exists (select 1 from public.username_banned b where b.username = u) then
    return false;
  end if;

  -- reserved active?
  select exists (
    select 1 from public.username_reserved r
    where r.username = u
      and (r."until" is null or r."until" > now())
  ) into reserved_active;

  if reserved_active then
    return false;
  end if;

  -- taken in registry?
  select exists (
    select 1 from public.username_registry reg
    where reg.username = u and reg.released_at is null
  ) into taken_active;

  if taken_active then
    return false;
  end if;

  return true;
end;
$$;


ALTER FUNCTION "public"."is_username_available"("p_username" "text") OWNER TO "postgres";


