CREATE OR REPLACE FUNCTION "public"."list_challenge_statuses"() RETURNS SETOF "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  t_oid   oid;
  atttyp  oid;
  def     text;
  vals    text[] := '{}';
begin
  select 'public.challenges'::regclass::oid into t_oid;
  select a.atttypid
  into atttyp
  from pg_attribute a
  where a.attrelid = t_oid and a.attname = 'status' and a.attnum > 0 and not a.attisdropped;

  -- If ENUM: return enum labels
  if atttyp::regtype::text !~* 'text' then
    return query
    select e.enumlabel
    from pg_enum e
    where e.enumtypid = atttyp
    order by e.enumsortorder;
    return;
  end if;

  -- Else parse CHECK constraints that mention status
  for def in
    select pg_get_constraintdef(c.oid)
    from pg_constraint c
    where c.conrelid = t_oid
      and c.contype = 'c'
      and pg_get_constraintdef(c.oid) ilike '%status%'
  loop
    vals := vals || (
      select array_agg(m[1])
      from regexp_matches(def, '''([^'']+)''(?:::?[a-zA-Z0-9_.]+)?', 'g') m
    );
  end loop;

  if vals is not null and array_length(vals,1) is not null then
    return query select distinct v from unnest(vals) v;
  end if;

  return;
end;
$$;


ALTER FUNCTION "public"."list_challenge_statuses"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_space_slots"("p_space_id" "uuid", "p_from_utc" timestamp with time zone DEFAULT "now"(), "p_days" integer DEFAULT 3, "p_slot_minutes" integer DEFAULT 60, "p_step_minutes" integer DEFAULT 60) RETURNS TABLE("venue_space_id" "uuid", "venue_id" "uuid", "venue_tz" "text", "local_date" "date", "local_weekday" integer, "local_start" timestamp without time zone, "local_end" timestamp without time zone, "start_utc" timestamp with time zone, "end_utc" timestamp with time zone, "minutes" integer, "is_open" boolean, "is_blackout" boolean, "hourly_aed" numeric, "price_aed" numeric, "reason" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
with s as (
  select sp.id as space_id, v.id as venue_id, v.timezone as tz
  from public.venue_spaces sp
  join public.venues v on v.id = sp.venue_id
  where sp.id = p_space_id and sp.is_active
),
days as (
  select gs::int as d
  from generate_series(0, greatest(p_days,1)-1) gs
),
oh as (
  select o.weekday, o.open_time, o.close_time
  from public.opening_hours o
  where o.venue_space_id = p_space_id
),
grid as (
  select
    (p_from_utc at time zone s.tz)::date + d.d as ldate,
    s.tz,
    s.space_id,
    s.venue_id
  from s, days d
),
slots as (
  select
    g.space_id,
    g.venue_id,
    g.tz,
    g.ldate,
    extract(dow from g.ldate)::int as wd,
    o.open_time,
    o.close_time,
    generate_series(
      g.ldate + o.open_time,
      g.ldate + (o.close_time - make_interval(mins => p_slot_minutes)),
      make_interval(mins => p_step_minutes)
    ) as lstart
  from grid g
  join oh o on o.weekday = extract(dow from g.ldate)::int
),
prepared as (
  select
    space_id,
    venue_id,
    tz,
    ldate,
    wd,
    lstart,
    lstart + make_interval(mins => p_slot_minutes) as lend
  from slots
),
quoted as (
  -- IMPORTANT: only expand the pricing function result to avoid duplicate column names
  select
    (public.quote_space_slot_price(
      p.space_id,
      (p.lstart at time zone p.tz),
      (p.lend   at time zone p.tz)
    )).*
  from prepared p
)
select
  q.venue_space_id,
  q.venue_id,
  q.venue_tz,
  q.local_date,
  q.local_weekday,
  q.local_start,
  q.local_end,
  (q.local_start at time zone q.venue_tz) as start_utc,
  (q.local_end   at time zone q.venue_tz) as end_utc,
  q.minutes,
  q.is_open,
  q.is_blackout,
  q.hourly_aed,
  q.price_aed,
  q.reason
from quoted q
order by q.local_date, q.local_start;
$$;


ALTER FUNCTION "public"."list_space_slots"("p_space_id" "uuid", "p_from_utc" timestamp with time zone, "p_days" integer, "p_slot_minutes" integer, "p_step_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_all_read_before"("p_cutoff" timestamp with time zone DEFAULT "now"()) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  n int;
begin
  update public.notifications
  set is_read = true,
      read_at = now()
  where to_user_id = me
    and is_read = false
    and created_at <= p_cutoff;

  get diagnostics n = row_count;
  return n;
end;
$$;


