CREATE OR REPLACE FUNCTION "public"."nearby_games"("p_lat" double precision, "p_lng" double precision, "p_radius" integer DEFAULT 10000, "p_sport" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "sport" "text", "title" "text", "start_at" timestamp with time zone, "geo_location_id" "uuid", "area_id" "uuid", "lat" double precision, "lng" double precision, "district" "text", "city" "text", "capacity" integer, "slots_available" integer, "distance_m" double precision)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    g.id, g.sport, g.title, g.start_at,
    g.geo_location_id, g.area_id,
    ST_Y(gl.location::geometry) AS lat,
    ST_X(gl.location::geometry) AS lng,
    a.district, a.city,
    g.capacity,
    (g.capacity - COALESCE((
      SELECT COUNT(*)::integer FROM public.game_roster gr
      WHERE gr.game_id = g.id AND gr.status = 'confirmed'
    ), 0)) AS slots_available,
    ST_Distance(
      ST_MakePoint(p_lng, p_lat)::geography,
      gl.location
    ) AS distance_m
  FROM public.games g
  JOIN public.geo_locations gl ON gl.id = g.geo_location_id
  JOIN public.areas a ON a.id = g.area_id
  WHERE g.is_cancelled = false
    AND g.start_at > now()
    AND ST_DWithin(gl.location, ST_MakePoint(p_lng, p_lat)::geography, p_radius)
    AND (p_sport IS NULL OR g.sport = p_sport)
  ORDER BY distance_m ASC, g.start_at ASC
  LIMIT p_limit OFFSET p_offset;
$$;


ALTER FUNCTION "public"."nearby_games"("p_lat" double precision, "p_lng" double precision, "p_radius" integer, "p_sport" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nearby_posts"("p_lat" double precision, "p_lng" double precision, "p_radius" integer DEFAULT 10000, "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "author_profile_id" "uuid", "body" "text", "post_type" "text", "geo_location_id" "uuid", "area_id" "uuid", "location_name" "text", "lat" double precision, "lng" double precision, "district" "text", "city" "text", "created_at" timestamp with time zone, "distance_m" double precision)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    p.id, p.author_profile_id, p.body, p.post_type::text,
    p.geo_location_id, p.area_id, p.location_name,
    ST_Y(gl.location::geometry) AS lat,
    ST_X(gl.location::geometry) AS lng,
    a.district, a.city,
    p.created_at,
    ST_Distance(
      ST_MakePoint(p_lng, p_lat)::geography,
      gl.location
    ) AS distance_m
  FROM public.posts p
  JOIN public.geo_locations gl ON gl.id = p.geo_location_id
  JOIN public.areas a ON a.id = p.area_id
  WHERE p.visibility = 'public'
    AND (p.is_deleted IS NULL OR p.is_deleted = false)
    AND (p.is_active IS NULL OR p.is_active = true)
    AND ST_DWithin(gl.location, ST_MakePoint(p_lng, p_lat)::geography, p_radius)
  ORDER BY distance_m ASC, p.created_at DESC
  LIMIT p_limit OFFSET p_offset;
$$;


