CREATE OR REPLACE FUNCTION "public"."nearby_venues"("p_lat" double precision, "p_lng" double precision, "p_radius" integer DEFAULT 10000, "p_sport" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "name_en" "text", "district" "text", "city" "text", "geo_location_id" "uuid", "area_id" "uuid", "lat" double precision, "lng" double precision, "is_verified" boolean, "is_indoor" boolean, "surface_type" "text", "min_price_per_hour" numeric, "rating" numeric, "rating_count" integer, "sports" "text"[], "distance_m" double precision)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    v.id, v.name_en,
    a.district, a.city,
    v.geo_location_id, v.area_id,
    ST_Y(gl.location::geometry) AS lat,
    ST_X(gl.location::geometry) AS lng,
    v.is_verified, v.is_indoor, v.surface_type,
    v.min_price_per_hour, v.rating, v.rating_count,
    COALESCE(array_agg(DISTINCT sp.sport_key) FILTER (WHERE sp.sport_key IS NOT NULL), ARRAY[]::text[]) AS sports,
    ST_Distance(
      ST_MakePoint(p_lng, p_lat)::geography,
      gl.location
    ) AS distance_m
  FROM public.venues v
  JOIN public.geo_locations gl ON gl.id = v.geo_location_id
  JOIN public.areas a ON a.id = v.area_id
  LEFT JOIN public.venue_spaces vs ON vs.venue_id = v.id AND vs.is_active = true
  LEFT JOIN public.sports sp ON sp.id = vs.sport_id
  WHERE v.is_active IS DISTINCT FROM false
    AND ST_DWithin(gl.location, ST_MakePoint(p_lng, p_lat)::geography, p_radius)
    AND (p_sport IS NULL OR sp.sport_key = p_sport)
  GROUP BY v.id, v.name_en, a.district, a.city, v.geo_location_id, v.area_id,
           gl.location, v.is_verified, v.is_indoor, v.surface_type,
           v.min_price_per_hour, v.rating, v.rating_count
  ORDER BY distance_m ASC
  LIMIT p_limit OFFSET p_offset;
$$;


ALTER FUNCTION "public"."nearby_venues"("p_lat" double precision, "p_lng" double precision, "p_radius" integer, "p_sport" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."next_quiet_exit"("p_now" timestamp with time zone, "p_tz" "text", "p_start_min" integer, "p_end_min" integer) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  cur_min int := public._minutes_since_midnight(p_now, p_tz);
  base date := (p_now at time zone p_tz)::date;
begin
  if not public.is_in_quiet_hours(p_now, p_tz, p_start_min, p_end_min) then
    return p_now;
  end if;

  if p_start_min < p_end_min then
    -- window today
    return (base + make_interval(mins => p_end_min)) at time zone p_tz;
  else
    -- window wraps midnight → next day end_min
    return (base + interval '1 day' + make_interval(mins => p_end_min)) at time zone p_tz;
  end if;
end;
$$;


ALTER FUNCTION "public"."next_quiet_exit"("p_now" timestamp with time zone, "p_tz" "text", "p_start_min" integer, "p_end_min" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_display_name"("p" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  d text;
begin
  if p is null then
    return null;
  end if;

  -- Trim and collapse internal whitespace to single spaces
  d := regexp_replace(trim(p), '\s+', ' ', 'g');

  -- Lowercase (works fine for Latin; neutral for Arabic)
  d := lower(d);

  -- Enforce length 2..50 after trim/collapse
  if length(d) < 2 or length(d) > 50 then
    raise exception using errcode = 'P0001', message = 'display_name_invalid_length';
  end if;

  -- Disallow strings that are only punctuation or whitespace
  if d ~ '^[[:punct:][:space:]]+$' then
    raise exception using errcode = 'P0001', message = 'display_name_invalid_chars';
  end if;

  return d;
end;
$_$;


ALTER FUNCTION "public"."normalize_display_name"("p" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."normalize_display_name"("p" "text") IS 'Normalizes display_name by trimming, collapsing spaces, and lowercasing; enforces 2..50 length and rejects pure punctuation.';



CREATE OR REPLACE FUNCTION "public"."normalize_game_scores"("_scores" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  keys text[] := array['organization','fairness','competition','fun'];
  k   text;
  x   numeric;
  vals numeric[] := array[]::numeric[];
  avg_val numeric := 4.5;
  out jsonb := '{}'::jsonb;
begin
  -- collect provided dims
  foreach k in array keys loop
    begin
      x := (_scores->>k)::numeric;
    exception when others then x := null;
    end;
    if x is not null then
      vals := vals || x;
    end if;
  end loop;

  if array_length(vals,1) is not null then
    select avg(v) into avg_val from unnest(vals) v;
  end if;

  -- build normalized payload
  foreach k in array keys loop
    begin
      x := (_scores->>k)::numeric;
    exception when others then x := null;
    end;
    x := coalesce(x, avg_val, 4.5);
    if x < 1 then x := 1; end if;
    if x > 5 then x := 5; end if;
    x := round(x, 1);
    out := out || jsonb_build_object(k, x);
  end loop;

  return out;
end
$$;


ALTER FUNCTION "public"."normalize_game_scores"("_scores" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_username"("p" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  u text;
begin
  if p is null then
    raise exception using errcode = 'P0001', message = 'username_invalid';
  end if;

  -- lowercase, replace non [a-z0-9_] with _, collapse repeats, trim edges
  u := lower(p);
  u := regexp_replace(u, '[^a-z0-9_]', '_', 'g');
  u := regexp_replace(u, '_{2,}', '_', 'g');
  u := regexp_replace(u, '^_+|_+$', '', 'g');

  if length(u) < 3 or length(u) > 20 or u !~ '^[a-z0-9_]+$' then
    raise exception using errcode = 'P0001', message = 'username_invalid';
  end if;

  return u;
end;
$_$;


ALTER FUNCTION "public"."normalize_username"("p" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."normalize_username"("p" "text") IS 'Normalizes input to lowercase ASCII [a-z0-9_], 3..20 chars, collapses underscores, trims edges; raises username_invalid on failure.';



