CREATE OR REPLACE FUNCTION "public"."perform_check_in"("p_user_id" "uuid", "p_device_info" "jsonb" DEFAULT NULL::"jsonb") RETURNS TABLE("total_days_completed" integer, "streak_count" integer, "is_completed" boolean, "is_first_check_in_today" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  rec RECORD;
  new_total INTEGER;
  new_streak INTEGER;
  is_first BOOLEAN;
  today_date DATE := CURRENT_DATE;
BEGIN
  -- Get current status
  SELECT * INTO rec FROM user_check_ins WHERE user_id = p_user_id;

  -- Already checked in today?
  IF rec.last_check_in IS NOT NULL AND DATE(rec.last_check_in) = today_date THEN
    RETURN QUERY SELECT rec.total_days_completed, rec.streak_count, (rec.total_days_completed >= 14), FALSE;
    RETURN;
  END IF;

  is_first := TRUE;

  -- New user
  IF rec.user_id IS NULL THEN
    new_total := 1;
    new_streak := 1;
    INSERT INTO user_check_ins (user_id, total_days_completed, streak_count, last_check_in)
    VALUES (p_user_id, new_total, new_streak, NOW());
  ELSE
    -- Existing user
    IF today_date - DATE(rec.last_check_in) = 1 THEN
      new_streak := rec.streak_count + 1;
    ELSE
      new_streak := 1;
    END IF;
    new_total := rec.total_days_completed + 1;
    UPDATE user_check_ins
    SET total_days_completed = new_total, streak_count = new_streak, last_check_in = NOW()
    WHERE user_id = p_user_id;
  END IF;

  -- Log it with streak_at_time
  INSERT INTO check_in_logs (user_id, check_in_date, device_info, streak_at_time)
  VALUES (p_user_id, today_date, p_device_info, new_streak);

  RETURN QUERY SELECT new_total, new_streak, (new_total >= 14), is_first;
END;
$$;


ALTER FUNCTION "public"."perform_check_in"("p_user_id" "uuid", "p_device_info" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pick_challenge_status"() RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  s text;
  pref text[] := array['open','active','published','ready','created'];
begin
  foreach s in array pref loop
    if exists (select 1 from public.list_challenge_statuses() x where x = s) then
      return s;
    end if;
  end loop;

  select x into s from public.list_challenge_statuses() x limit 1;
  if s is not null then
    return s;
  end if;

  raise exception using errcode = 'P0001', message = 'no_allowed_challenge_status_found';
end;
$$;


