CREATE OR REPLACE FUNCTION "public"."process_notification_event"("p_to_user_id" "uuid", "p_kind_key" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_actor_user_id" "uuid", "p_title" "text" DEFAULT NULL::"text", "p_body" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_rule RECORD;
    v_existing RECORD;
    v_last_event timestamptz;
    v_new_actors uuid[];
    v_display_name text;
    v_final_title text;
    v_action_route text;
BEGIN

    -- Prevent rapid duplicate spam (10 sec window)
    SELECT updated_at
    INTO v_last_event
    FROM public.notification_aggregates
    WHERE to_user_id = p_to_user_id
      AND kind_key = p_kind_key
      AND entity_type = p_entity_type
      AND entity_id = p_entity_id
      AND is_flushed = false
      AND p_actor_user_id = ANY(actors)
    ORDER BY updated_at DESC
    LIMIT 1;

    IF v_last_event IS NOT NULL
       AND v_last_event > now() - interval '10 seconds'
    THEN
        RETURN;
    END IF;

    -- Look up actor display name for title generation
    SELECT display_name INTO v_display_name
    FROM public.profiles
    WHERE user_id = p_actor_user_id AND is_active = true
    LIMIT 1;

    v_display_name := COALESCE(v_display_name, 'Someone');

    -- Generate title if not provided
    IF p_title IS NOT NULL THEN
        v_final_title := p_title;
    ELSE
        v_final_title := CASE p_kind_key
            WHEN 'social.post_liked'           THEN v_display_name || ' liked your post'
            WHEN 'social.post_commented'       THEN v_display_name || ' commented on your post'
            WHEN 'social.post_reacted'         THEN v_display_name || ' reacted to your post'
            WHEN 'social.comment_liked'        THEN v_display_name || ' liked your comment'
            WHEN 'social.followed'             THEN v_display_name || ' started following you'
            WHEN 'social.circle_joined'        THEN v_display_name || ' joined your circle'
            WHEN 'social.mentioned_in_post'    THEN v_display_name || ' mentioned you in a post'
            WHEN 'social.mentioned_in_comment' THEN v_display_name || ' mentioned you in a comment'
            WHEN 'friend.requested'            THEN v_display_name || ' sent you a friend request'
            WHEN 'friend.accepted'             THEN v_display_name || ' accepted your friend request'
            WHEN 'game.invited'                THEN v_display_name || ' invited you to a game'
            WHEN 'game.join_request'           THEN v_display_name || ' wants to join your game'
            WHEN 'game.player_joined'          THEN v_display_name || ' joined your game'
            WHEN 'game.updated'                THEN 'A game you joined was updated'
            WHEN 'game.waitlist_promoted'      THEN 'You''ve been promoted from the waitlist'
            WHEN 'meetup.invited'              THEN v_display_name || ' invited you to a meetup'
            WHEN 'meetup.player_joined'        THEN v_display_name || ' joined your meet-up'
            WHEN 'squad.invited'               THEN v_display_name || ' invited you to a squad'
            WHEN 'arena.payment_required'      THEN 'Payment required for your booking'
            WHEN 'reward.badge_awarded'        THEN 'You earned a new badge!'
            ELSE NULL
        END;

        -- Unknown/future kinds: fall back to the catalog label, never a
        -- generic "New notification".
        IF v_final_title IS NULL THEN
            SELECT label_en INTO v_final_title
            FROM public.notification_kinds
            WHERE key = p_kind_key;
            v_final_title := COALESCE(v_final_title, 'Notification');
        END IF;
    END IF;

    -- Deep-link route for game notifications (real detail route; the host's
    -- join-request notification lands on the pending-requests card).
    v_action_route := CASE
        WHEN p_entity_type = 'game' AND p_kind_key LIKE 'game.%' THEN
            '/sports/games/' || p_entity_id::text ||
            CASE WHEN p_kind_key = 'game.join_request'
                 THEN '?focus=requests' ELSE '' END
        ELSE NULL
    END;

    -- Try to get aggregation rule
    SELECT *
    INTO v_rule
    FROM public.notification_aggregation_rules
    WHERE kind_key = p_kind_key
      AND enabled = true;

    -- If NO aggregation rule → instant insert
    IF NOT FOUND THEN
        INSERT INTO public.notifications (
            to_user_id,
            kind_key,
            title,
            body,
            action_route,
            context,
            priority,
            is_read,
            created_at
        )
        VALUES (
            p_to_user_id,
            p_kind_key,
            v_final_title,
            p_body,
            v_action_route,
            jsonb_build_object(
                'entity_type', p_entity_type,
                'entity_id', p_entity_id,
                'actor_user_id', p_actor_user_id,
                'actor_display_name', v_display_name
            ),
            'normal',
            false,
            now()
        );

        RETURN;
    END IF;

    -- Aggregated path
    SELECT *
    INTO v_existing
    FROM public.notification_aggregates
    WHERE to_user_id = p_to_user_id
      AND kind_key = p_kind_key
      AND entity_type = p_entity_type
      AND entity_id = p_entity_id
      AND is_flushed = false
      AND window_expires_at > now()
    LIMIT 1;

    IF FOUND THEN

        SELECT ARRAY(
            SELECT DISTINCT x
            FROM unnest(v_existing.actors || p_actor_user_id) AS t(x)
        )
        INTO v_new_actors;

        UPDATE public.notification_aggregates
        SET actors = v_new_actors,
            total_count = array_length(v_new_actors, 1),
            updated_at = now()
        WHERE id = v_existing.id;

    ELSE

        INSERT INTO public.notification_aggregates (
            to_user_id,
            kind_key,
            entity_type,
            entity_id,
            actors,
            total_count,
            window_started_at,
            window_expires_at
        )
        VALUES (
            p_to_user_id,
            p_kind_key,
            p_entity_type,
            p_entity_id,
            ARRAY[p_actor_user_id],
            1,
            now(),
            now() + make_interval(secs => v_rule.aggregation_window_seconds)
        );

    END IF;

END;
$$;


ALTER FUNCTION "public"."process_notification_event"("p_to_user_id" "uuid", "p_kind_key" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_actor_user_id" "uuid", "p_title" "text", "p_body" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."quote_space_slot_price"("p_space_id" "uuid", "p_start_utc" timestamp with time zone, "p_end_utc" timestamp with time zone) RETURNS TABLE("venue_space_id" "uuid", "venue_id" "uuid", "venue_tz" "text", "local_date" "date", "local_weekday" integer, "local_start" timestamp without time zone, "local_end" timestamp without time zone, "minutes" integer, "is_open" boolean, "is_blackout" boolean, "hourly_aed" numeric, "price_aed" numeric, "reason" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_tz   text;
  v_vid  uuid;
  v_ls   timestamp;  -- local start (no tz)
  v_le   timestamp;  -- local end (no tz)
  v_wd   int;        -- 0..6
  v_open time;
  v_close time;
  v_rate numeric(10,2);
  v_minutes int;
  v_reason text := null;
  v_is_open boolean := false;
  v_is_blackout boolean := false;
begin
  if p_end_utc <= p_start_utc then
    venue_space_id := p_space_id;
    reason := 'end <= start';
    return next; return;
  end if;

  -- ✅ fixed alias here: s.venue_id (not v.venue_id)
  select s.venue_id, ven.timezone
  into v_vid, v_tz
  from public.venue_spaces s
  join public.venues ven on ven.id = s.venue_id
  where s.id = p_space_id;

  if v_tz is null then
    venue_space_id := p_space_id;
    reason := 'space_or_venue_not_found';
    return next; return;
  end if;

  v_ls := (p_start_utc at time zone v_tz);
  v_le := (p_end_utc   at time zone v_tz);

  if v_ls::date <> v_le::date then
    venue_space_id := p_space_id; venue_id := v_vid; venue_tz := v_tz;
    local_date := v_ls::date; local_weekday := extract(dow from v_ls)::int;
    local_start := v_ls; local_end := v_le; minutes := extract(epoch from (p_end_utc - p_start_utc))::int / 60;
    reason := 'slot_crosses_midnight_local';
    return next; return;
  end if;

  v_wd := extract(dow from v_ls)::int;

  select oh.open_time, oh.close_time
  into v_open, v_close
  from public.opening_hours oh
  where oh.venue_space_id = p_space_id and oh.weekday = v_wd;

  if v_open is null then
    venue_space_id := p_space_id; venue_id := v_vid; venue_tz := v_tz;
    local_date := v_ls::date; local_weekday := v_wd; local_start := v_ls; local_end := v_le;
    minutes := extract(epoch from (p_end_utc - p_start_utc))::int / 60;
    reason := 'no_opening_hours_for_weekday';
    return next; return;
  end if;

  v_is_open := (v_ls::time >= v_open) and (v_le::time <= v_close);

  select exists (
    select 1
    from public.blackouts b
    where b.venue_space_id = p_space_id
      and b.starts_at < p_end_utc
      and b.ends_at   > p_start_utc
  ) into v_is_blackout;

  select sp.price_per_hour_aed
  into v_rate
  from public.space_prices sp
  where sp.venue_space_id = p_space_id
    and sp.weekday = v_wd
    and sp.is_active = true
    and sp.start_time <= v_ls::time
    and sp.end_time   >= v_le::time
  order by sp.start_time asc
  limit 1;

  v_minutes := (extract(epoch from (p_end_utc - p_start_utc)) / 60)::int;

  if not v_is_open then
    v_reason := 'outside_opening_hours';
  elsif v_is_blackout then
    v_reason := 'blackout';
  elsif v_rate is null then
    v_reason := 'no_price_rule_covers_slot';
  end if;

  venue_space_id := p_space_id;
  venue_id := v_vid;
  venue_tz := v_tz;
  local_date := v_ls::date;
  local_weekday := v_wd;
  local_start := v_ls;
  local_end := v_le;
  minutes := v_minutes;
  is_open := v_is_open;
  is_blackout := v_is_blackout;
  hourly_aed := v_rate;
  price_aed := case when v_rate is not null and v_is_open and not v_is_blackout
                    then round((v_minutes::numeric / 60.0) * v_rate, 2)
                    else null end;
  reason := v_reason;

  return next;
end
$$;


ALTER FUNCTION "public"."quote_space_slot_price"("p_space_id" "uuid", "p_start_utc" timestamp with time zone, "p_end_utc" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recalculate_hashtag_trending"() RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
    UPDATE public.hashtags
    SET trending_score =
        (usage_last_24h * 3)
        + (usage_last_7d * 1)
        + (unique_user_count * 0.5)
        - (EXTRACT(EPOCH FROM (now() - COALESCE(last_used_at, now()))) / 3600 * 0.1);
END;
$$;


ALTER FUNCTION "public"."recalculate_hashtag_trending"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recompute_sport_user_counts"() RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  UPDATE public.sports
  SET primary_user_count = 0, interested_user_count = 0
  WHERE true;

  -- primary sport count — explicit uuid::text cast avoids btrim(uuid) error
  UPDATE public.sports s
  SET primary_user_count = sub.cnt
  FROM (
    SELECT
      lower(trim(primary_sport::text)) AS sport_key,
      COUNT(*) AS cnt
    FROM public.profiles
    WHERE primary_sport IS NOT NULL
      AND is_active = true
    GROUP BY lower(trim(primary_sport::text))
  ) sub
  WHERE s.sport_key = sub.sport_key;

  -- interested sport count — sport_id is uuid vs uuid, no citext involved
  UPDATE public.sports s
  SET interested_user_count = sub.cnt
  FROM (
    SELECT sp.sport_id, COUNT(DISTINCT sp.profile_id) AS cnt
    FROM public.sport_profiles sp
    JOIN public.profiles p ON p.id = sp.profile_id
    WHERE p.is_active = true
    GROUP BY sp.sport_id
  ) sub
  WHERE s.id = sub.sport_id;
END;
$$;


ALTER FUNCTION "public"."recompute_sport_user_counts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."render_notification"("p_type_key" "text", "p_user" "uuid", "p_context" "jsonb") RETURNS TABLE("title" "text", "body" "text", "action_route" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  loc text := coalesce((select locale from public.user_settings where user_id=p_user),'en');
  tt text; bt text; aroute text;
begin
  select title_template, body_template, action_route
  into tt, bt, aroute
  from public.notification_templates
  where key = p_type_key and locale = loc
  order by version desc
  limit 1;

  if tt is null then
    -- Fallback EN
    select title_template, body_template, action_route
    into tt, bt, aroute
    from public.notification_templates
    where key = p_type_key and locale = 'en'
    order by version desc
    limit 1;
  end if;

  -- VERY basic rendering: replace {{key}} with context->>key
  -- For anything complex, do it in the edge worker.
  title := coalesce(tt,'Notification');
  body  := coalesce(bt,'You have an update');
  action_route := coalesce(aroute,'/inbox');

  -- Replace {{..}} tokens present in title/body/route
  -- token list from keys in p_context
  perform 1; -- no-op

  -- simple replace loop in SQL:
  declare k text; v text;
  begin
    for k, v in
      select key, value from json_each_text(coalesce(p_context,'{}'::jsonb))
    loop
      title := replace(title, '{{'||k||'}}', v);
      body  := replace(body,  '{{'||k||'}}', v);
      action_route := replace(action_route, '{{'||k||'}}', v);
    end loop;
  end;

  return next;
end;
$$;


ALTER FUNCTION "public"."render_notification"("p_type_key" "text", "p_user" "uuid", "p_context" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."report_content"("p_target_type" "public"."mod_target", "p_target_id" "uuid", "p_reason" "public"."report_reason", "p_details" "text" DEFAULT NULL::"text", "p_snapshot" "jsonb" DEFAULT NULL::"jsonb") RETURNS "public"."moderation_reports"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  me  uuid := auth.uid();
  row public.moderation_reports;
begin
  if me is null then
    raise exception using errcode = 'P0001', message = 'auth_required';
  end if;

  insert into public.moderation_reports(
    reporter_user_id, target_type, target_id, reason, details, content_snapshot
  )
  values (
    me, p_target_type, p_target_id, p_reason, p_details, p_snapshot
  )
  returning * into row;

  perform public.audit_log(
    'mod.report',
    p_target_type,
    p_target_id,
    null,
    jsonb_build_object('reason', p_reason, 'details', p_details)
  );

  return row;
end;
$$;


ALTER FUNCTION "public"."report_content"("p_target_type" "public"."mod_target", "p_target_id" "uuid", "p_reason" "public"."report_reason", "p_details" "text", "p_snapshot" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reputation_decay_factor"("p_event_at" timestamp with time zone) RETURNS numeric
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with cfg as (select half_life_days from public.reputation_config where id=true),
  dt as (select greatest(0.0, extract(epoch from (now() - p_event_at))/86400.0) as days)
  select case when (select half_life_days from cfg) <= 0
              then 1.0
              else power(0.5, (select days from dt) / (select half_life_days from cfg))
         end::numeric
$$;


ALTER FUNCTION "public"."reputation_decay_factor"("p_event_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reputation_rebuild_all"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare uid uuid; n int := 0;
begin
  for uid in select distinct ratee_user_id from public.user_reputation_events loop
    perform public.reputation_recompute(uid);
    n := n + 1;
  end loop;
  return n;
end;
$$;


ALTER FUNCTION "public"."reputation_rebuild_all"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reputation_recompute"("p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  prior_m numeric; prior_w int;
  dim record;
  sum_map jsonb := '{}'::jsonb;
  cnt_map jsonb := '{}'::jsonb;
  comp numeric := 0.0;
  total_w numeric := 0.0;
  dim_sum numeric; dim_cnt numeric; dim_mean numeric;
  evt_count int;
begin
  select prior_mean, prior_weight into prior_m, prior_w from public.reputation_config where id=true;

  for dim in select key, weight from public.reputation_dimensions where is_active loop
    select
      coalesce(sum( public._clamp_star((e.scores ->> dim.key)::numeric) * public.reputation_decay_factor(e.created_at) ), 0.0),
      coalesce(sum( case when e.scores ? dim.key then public.reputation_decay_factor(e.created_at) else 0 end ), 0.0)
    into dim_sum, dim_cnt
    from public.user_reputation_events e
    where e.ratee_user_id = p_user_id;

    sum_map := sum_map || jsonb_build_object(dim.key, round(dim_sum::numeric,3));
    cnt_map := cnt_map || jsonb_build_object(dim.key, round(dim_cnt::numeric,3));

    dim_mean := case when (prior_w + dim_cnt) > 0
                     then (prior_m * prior_w + dim_sum) / (prior_w + dim_cnt)
                     else prior_m
                end;

    comp := comp + coalesce(dim.weight,0.0) * dim_mean;
    total_w := total_w + coalesce(dim.weight,0.0);
  end loop;

  if total_w > 0 then comp := comp / total_w; else comp := prior_m; end if;

  select count(*) into evt_count from public.user_reputation_events where ratee_user_id=p_user_id;

  insert into public.user_reputation_aggregate(user_id,event_count,dim_sums,dim_counts,composite_score,last_event_at,updated_at)
  values (
    p_user_id, evt_count, sum_map, cnt_map, round(comp::numeric,2),
    (select max(created_at) from public.user_reputation_events where ratee_user_id=p_user_id),
    now()
  )
  on conflict (user_id) do update set
    event_count     = excluded.event_count,
    dim_sums        = excluded.dim_sums,
    dim_counts      = excluded.dim_counts,
    composite_score = excluded.composite_score,
    last_event_at   = excluded.last_event_at,
    updated_at      = excluded.updated_at;
end;
$$;


ALTER FUNCTION "public"."reputation_recompute"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_payout"("p_amount_aed" numeric, "p_beneficiary_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."payouts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  ben uuid;
  bal numeric(12,2);
  po public.payouts;
begin
  if me is null then raise exception using errcode='P0001', message='auth_required'; end if;
  if p_amount_aed is null or p_amount_aed <= 0 then raise exception using errcode='P0001', message='invalid_amount'; end if;

  -- Beneficiary: explicit or default
  if p_beneficiary_id is not null then
    select id into ben from public.payout_beneficiaries where id = p_beneficiary_id and user_id = me;
    if ben is null then raise exception using errcode='P0001', message='beneficiary_not_found'; end if;
  else
    select id into ben from public.payout_beneficiaries where user_id = me and is_default = true limit 1;
    if ben is null then raise exception using errcode='P0001', message='no_default_beneficiary'; end if;
  end if;

  -- Check available balance
  select balance_aed into bal from public.wallets where user_id = me;
  if bal is null then bal := 0; end if;
  if p_amount_aed > bal then raise exception using errcode='P0001', message='insufficient_funds'; end if;

  -- Create payout row
  insert into public.payouts(user_id, beneficiary_id, amount_aed, status)
  values (me, ben, p_amount_aed, 'requested')
  returning * into po;

  -- Move funds to held: ledger pending debit (hold)
  insert into public.wallet_ledger(user_id, direction, amount_aed, status, ref_type, ref_id, memo)
  values (me, 'debit', p_amount_aed, 'pending', 'payout', po.id, 'Payout hold');

  return po;
end;
$$;


ALTER FUNCTION "public"."request_payout"("p_amount_aed" numeric, "p_beneficiary_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_commission"("p_organiser_user_id" "uuid", "p_sport" "text", "p_at" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("rate" numeric, "min_fee" numeric, "max_fee" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  with ranked as (
    select
      commission_rate as rate,
      min_app_fee_aed as min_fee,
      max_app_fee_aed as max_fee,
      row_number() over (
        order by
          (organiser_user_id is null)::int asc,   -- prefer specific organiser
          (sport is null)::int asc,               -- prefer specific sport
          starts_at desc
      ) as rnk
    from public.commission_rules
    where is_active = true
      and (organiser_user_id is null or organiser_user_id = p_organiser_user_id)
      and (sport is null or sport = p_sport)
      and (starts_at is null or starts_at <= p_at)
      and (ends_at   is null or ends_at   >  p_at)
  )
  select rate, min_fee, max_fee
  from ranked
  where rnk = 1;
$$;


ALTER FUNCTION "public"."resolve_commission"("p_organiser_user_id" "uuid", "p_sport" "text", "p_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_nearest_area"("p_lat" double precision, "p_lng" double precision) RETURNS TABLE("id" "uuid", "name" "text", "district" "text", "city" "text", "country" "text", "center_lat" double precision, "center_lng" double precision, "is_verified" boolean, "distance_m" double precision)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    a.id, a.name, a.district, a.city, a.country,
    a.center_lat, a.center_lng, a.is_verified,
    ST_Distance(
      ST_MakePoint(p_lng, p_lat)::geography,
      ST_MakePoint(a.center_lng, a.center_lat)::geography
    ) AS distance_m
  FROM public.areas a
  WHERE a.is_active = true
  ORDER BY distance_m ASC
  LIMIT 1;
$$;


ALTER FUNCTION "public"."resolve_nearest_area"("p_lat" double precision, "p_lng" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_sport_variant"("p_sport_id" "uuid", "p_min_players" integer, "p_is_indoor" boolean, "p_surface_key" "text") RETURNS "uuid"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT sv.id
  FROM public.sport_variants sv
  WHERE sv.sport_id = p_sport_id
    AND (sv.min_players IS NULL OR sv.min_players <= p_min_players)
    AND (sv.is_indoor IS NULL OR sv.is_indoor = p_is_indoor)
    AND (sv.surface_key IS NULL OR sv.surface_key = p_surface_key)
  ORDER BY
    sv.min_players DESC NULLS LAST
  LIMIT 1;
$$;


ALTER FUNCTION "public"."resolve_sport_variant"("p_sport_id" "uuid", "p_min_players" integer, "p_is_indoor" boolean, "p_surface_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."respond_vibe_request"("p_other_user" "uuid", "p_action" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  a uuid; b uuid; e friend_edges%rowtype;
begin
  if me is null then raise exception using errcode='P0001', message='auth_required'; end if;
  if p_action not in ('accept','reject') then
    raise exception using errcode='P0001', message='invalid_action';
  end if;

  select a,b into a,b from public._pair(me, p_other_user);
  select * into e from public.friend_edges
   where least(user_a,user_b)=a and greatest(user_a,user_b)=b;

  if e.id is null or e.status <> 'pending' then
    raise exception using errcode='P0001', message='no_pending_request';
  end if;

  -- Only the non-requester can respond
  if e.requested_by = me then
    raise exception using errcode='P0001', message='requester_cannot_respond';
  end if;

  if p_action = 'accept' then
    update public.friend_edges
      set status='accepted', responded_by=me, updated_at=now()
    where id=e.id;
    insert into public.friend_requests_audit(from_user,to_user,action,edge_id)
    values (e.requested_by, me, 'accepted', e.id);
    -- TODO: notification friend.accepted
    return 'synced';
  else
    update public.friend_edges
      set status='rejected', responded_by=me, updated_at=now()
    where id=e.id;
    insert into public.friend_requests_audit(from_user,to_user,action,edge_id)
    values (e.requested_by, me, 'rejected', e.id);
    -- TODO: notification friend.rejected
    return 'vibe_missed';
  end if;
end;
$$;


ALTER FUNCTION "public"."respond_vibe_request"("p_other_user" "uuid", "p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reuse_touch"("p_context" "text", "p_fields" "jsonb", "p_hash" "text", "p_version" integer, "p_user" "uuid", "p_payload" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  INSERT INTO public.reuse_fingerprints(context, version, hash, fields)
  VALUES (p_context, p_version, p_hash, p_fields)
  ON CONFLICT (context, version, hash) DO NOTHING;
  INSERT INTO public.reuse_user_stats(user_id, context, version, fingerprint_hash, use_count, last_used_at, last_payload)
  VALUES (p_user, p_context, p_version, p_hash, 1, now(), p_payload)
  ON CONFLICT (user_id, context, version, fingerprint_hash)
  DO UPDATE SET use_count = public.reuse_user_stats.use_count + 1, last_used_at = now(), last_payload = p_payload;
  INSERT INTO public.reuse_global_stats(context, version, fingerprint_hash, use_count, last_used_at)
  VALUES (p_context, p_version, p_hash, 1, now())
  ON CONFLICT (context, version, fingerprint_hash)
  DO UPDATE SET use_count = public.reuse_global_stats.use_count + 1, last_used_at = now();
END;
$$;


ALTER FUNCTION "public"."reuse_touch"("p_context" "text", "p_fields" "jsonb", "p_hash" "text", "p_version" integer, "p_user" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_act_as"("p_profile_type" "text" DEFAULT NULL::"text") RETURNS TABLE("profile_id" "uuid", "profile_type" "text", "username" "public"."citext", "display_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  pid uuid;
begin
  if me is null then
    raise exception 'not_authenticated' using errcode='P0001';
  end if;

  pid := public.choose_actor(p_profile_type);
  return query
  select p.id, p.profile_type, p.username, p.display_name
  from public.profiles p
  where p.id = pid;
end;
$$;


