CREATE OR REPLACE FUNCTION "public"."rpc_add_comment"("p_post_id" "uuid", "p_author_profile_id" "uuid", "p_body" "text", "p_parent_comment_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  prof   record;
  new_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION USING errcode='P0001', message='auth_required'; END IF;
  SELECT id, user_id INTO prof FROM public.profiles WHERE id = p_author_profile_id;
  IF NOT FOUND OR prof.user_id <> auth.uid() THEN
    RAISE EXCEPTION USING errcode='P0001', message='not_profile_owner';
  END IF;
  INSERT INTO public.comments(parent_activity_id, author_profile_id, author_user_id, parent_comment_id, body)
  VALUES (p_post_id, p_author_profile_id, auth.uid(), p_parent_comment_id, left(p_body, 2000))
  RETURNING id INTO new_id;
  RETURN new_id;
END;
$$;


