CREATE OR REPLACE FUNCTION "public"."rpc_admin_reject_venue_submission"("p_submission_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
DECLARE
  v_admin_id uuid;
BEGIN
  v_admin_id :=
    (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub')::uuid;

  IF v_admin_id IS NULL OR NOT public.is_admin(v_admin_id) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  UPDATE public.venue_submissions
  SET
    status = 'rejected',
    rejected_at = now(),
    rejected_by = v_admin_id,
    rejected_reason = p_reason,
    updated_at = now()
  WHERE id = p_submission_id
    AND status = 'pending';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Submission not pending';
  END IF;
END;
$$;


