CREATE OR REPLACE FUNCTION "public"."rpc_admin_revoke_venue"("p_submission_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
declare
  v_submission public.venue_submissions%rowtype;
  v_actor_user_id uuid;
begin
  -- Extract admin identity
  v_actor_user_id :=
    (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub')::uuid;

  if v_actor_user_id is null or not public.is_admin(v_actor_user_id) then
    raise exception 'Not authorized';
  end if;

  -- Lock submission
  select *
  into v_submission
  from public.venue_submissions
  where id = p_submission_id
  for update;

  if not found then
    raise exception 'Submission not found';
  end if;

  if v_submission.status <> 'approved' then
    raise exception 'Only approved submissions can be revoked';
  end if;

  if v_submission.approved_venue_id is null then
    raise exception 'Approved venue missing';
  end if;

  -- Disable venue
  update public.venues
  set is_active = false,
      is_verified = false
  where id = v_submission.approved_venue_id;

  -- Move submission back to workflow
  update public.venue_submissions
  set status = 'revoked',
      revoked_at = now(),
      revoked_by = v_actor_user_id,
      revoke_reason = p_reason,
      updated_at = now()
  where id = p_submission_id;

  return v_submission.approved_venue_id;
end;
$$;


ALTER FUNCTION "public"."rpc_admin_revoke_venue"("p_submission_id" "uuid", "p_reason" "text") OWNER TO "postgres";


