CREATE OR REPLACE FUNCTION "public"."rpc_admin_submission_action_state"("p_submission_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_status venue_submission_status;
begin
  select status into v_status
  from public.venue_submissions
  where id = p_submission_id;

  return jsonb_build_object(
    'status', v_status,
    'can_approve', v_status = 'pending',
    'can_reject',  v_status = 'pending',
    'can_return',  v_status = 'pending',
    'can_revoke',  v_status = 'approved',
    'reason', case
      when v_status = 'approved' then 'Already approved'
      when v_status = 'rejected' then 'Already rejected'
      when v_status = 'revoked'  then 'Already revoked'
      else null
    end
  );
end;
$$;


