CREATE OR REPLACE FUNCTION "public"."rpc_autocomplete_entities"("p_prefix" "text", "p_scope" "text"[] DEFAULT ARRAY['venues'::"text", 'squads'::"text", 'games'::"text", 'arenas'::"text"], "p_sport" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 10) RETURNS TABLE("entity_type" "text", "entity_id" "uuid", "title" "text", "subtitle" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  me   uuid := auth.uid();
  pref text := public._norm_prefix(p_prefix);
  take int  := greatest(1, p_limit);
begin
  if me is null then
    raise exception using errcode='P0001', message='auth_required';
  end if;

  if pref is null or length(pref) < 2 then
    return;
  end if;

  -- VENUES
  if 'venues' = any(p_scope) then
    return query
    select
      'venue',
      v.id,
      v.name_en,
      coalesce(v.district,'') || 
        case 
          when v.city is not null and v.district is not null then ', '
          else ''
        end ||
        coalesce(v.city,'')
    from public.venues v
    where (p_sport is null or (v.sports is not null and p_sport = any(v.sports)))
      and (
        lower(unaccent_immutable(v.name_en)) like pref || '%' or
        lower(unaccent_immutable(coalesce(v.name_ar, ''))) like pref || '%'
      )
    order by v.created_at desc
    limit take;
  end if;

  -- SQUADS
  if 'squads' = any(p_scope) then
    return query
    select 
      'squad',
      s.id,
      coalesce(s.display_name, s.name),
      '@' || s.name || coalesce(' · ' || s.sport, '')
    from public.squads s
    where (p_sport is null or s.sport = p_sport)
      and (
        lower(unaccent_immutable(s.name)) like pref || '%' or
        lower(unaccent_immutable(coalesce(s.display_name,''))) like pref || '%'
      )
    order by s.created_at desc
    limit take;
  end if;

  -- GAMES (respect visibility)
  if 'games' = any(p_scope) then
    return query
    with g as (
      select g.id, g.title, g.sport, g.start_at
      from public.games g
      where (p_sport is null or g.sport = p_sport)
        and lower(unaccent_immutable(coalesce(g.title,''))) like pref || '%'
        and public.can_view_game(me, g.id)
      order by g.start_at desc
      limit take
    )
    select 
      'game',
      id,
      coalesce(title, initcap(sport) || ' game'),
      to_char(start_at at time zone 'UTC','YYYY-MM-DD HH24:MI UTC')
    from g;
  end if;

  -- ARENAS (if exist)
  if 'arenas' = any(p_scope)
     and exists (select 1 from information_schema.tables where table_schema='public' and table_name='arenas')
  then
    return query
    select
      'arena',
      a.id,
      a.title,
      a.name || coalesce(' · ' || a.sport, '')
    from public.arenas a
    where (p_sport is null or a.sport = p_sport)
      and (
        lower(unaccent_immutable(a.title)) like pref || '%' or
        lower(unaccent_immutable(a.name))  like pref || '%'
      )
    order by a.created_at desc
    limit take;
  end if;

end;
$$;


ALTER FUNCTION "public"."rpc_autocomplete_entities"("p_prefix" "text", "p_scope" "text"[], "p_sport" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_autocomplete_people"("p_prefix" "text", "p_roles" "text"[] DEFAULT ARRAY['player'::"text", 'organiser'::"text"], "p_sport" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 10) RETURNS TABLE("profile_id" "uuid", "profile_type" "text", "username" "text", "display_name" "text", "sport_key" "text", "avatar_url" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  me   uuid := auth.uid();
  pref text := public._norm_prefix(p_prefix);
  take int  := greatest(1, coalesce(p_limit,10));
begin
  -- Require auth
  if me is null then
    raise exception using errcode='P0001', message='auth_required';
  end if;

  -- Minimum prefix length
  if pref is null or length(pref) < 2 then
    return;
  end if;

  -- Fast prefix scan via text_pattern_ops
  return query
  with prefix_hits as (
    select
      pr.id,
      pr.profile_type,
      pr.username,
      pr.display_name,
      pr.sport_key,
      pr.avatar_url
    from public.profiles pr
    where (p_roles is null or pr.profile_type = any(p_roles))
      and (p_sport is null or pr.profile_type='organiser' or pr.sport_key = p_sport)
      and (
        lower(unaccent_immutable(pr.username))     like pref || '%' or
        lower(unaccent_immutable(pr.display_name)) like pref || '%'
      )
      and public.can_view_profile(me, pr.id)
    order by
      (lower(unaccent_immutable(pr.username)) like pref || '%') desc,
      pr.created_at desc
    limit take
  )
  select * from prefix_hits;

  -- If prefix results < limit/2, do fuzzy tail
  if (select count(*) from (
        select 1
        from public.profiles pr
        where (p_roles is null or pr.profile_type = any(p_roles))
          and (p_sport is null or pr.profile_type='organiser' or pr.sport_key = p_sport)
          and public.can_view_profile(me, pr.id)
          and (
            similarity(lower(pr.username), pref) > 0.4 or
            similarity(lower(pr.display_name), pref) > 0.4
          )
      ) x) > 0 then

    return query
    with fuzzy as (
      select
        pr.id,
        pr.profile_type,
        pr.username,
        pr.display_name,
        pr.sport_key,
        pr.avatar_url,
        greatest(
          similarity(lower(pr.username), pref),
          similarity(lower(pr.display_name), pref)
        ) as sim
      from public.profiles pr
      where (p_roles is null or pr.profile_type = any(p_roles))
        and (p_sport is null or pr.profile_type='organiser' or pr.sport_key = p_sport)
        and public.can_view_profile(me, pr.id)
        and not (
          lower(unaccent_immutable(pr.username))     like pref || '%' or
          lower(unaccent_immutable(pr.display_name)) like pref || '%'
        )
    )
    select id, profile_type, username, display_name, sport_key, avatar_url
    from fuzzy
    where sim > 0.45
    order by sim desc
    limit greatest(0, take - (
      select count(*) from (
        select 1
        from public.profiles pr
        where (p_roles is null or pr.profile_type = any(p_roles))
          and (p_sport is null or pr.profile_type='organiser' or pr.sport_key = p_sport)
          and (
            lower(unaccent_immutable(pr.username))     like pref || '%' or
            lower(unaccent_immutable(pr.display_name)) like pref || '%'
          )
          and public.can_view_profile(me, pr.id)
      ) c
    ));
  end if;
end;
$$;


ALTER FUNCTION "public"."rpc_autocomplete_people"("p_prefix" "text", "p_roles" "text"[], "p_sport" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_ban_display_name"("p_display_name" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor uuid := public.admin_actor();
  dn      text;
begin
  if v_actor is null then raise exception using errcode='P0001', message='not_authenticated'; end if;
  if not public.is_admin(v_actor) then raise exception using errcode='P0001', message='not_admin'; end if;

  dn := public.normalize_display_name(p_display_name);

  insert into public.display_name_banned(pattern, reason)
  values (dn, coalesce(p_reason,'moderation_ban'))
  on conflict (pattern) do nothing;

  insert into public.moderation_actions(actor_admin_id, action_type, target_table, target_id, reason, metadata)
  values (v_actor, 'ban_display_name', 'profiles', gen_random_uuid(), p_reason, jsonb_build_object('display_name_norm', dn));
end;
$$;


ALTER FUNCTION "public"."rpc_ban_display_name"("p_display_name" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_ban_term_upsert"("p_scope" "text", "p_term" "text", "p_lang" "text" DEFAULT NULL::"text", "p_severity" "text" DEFAULT 'warn'::"text", "p_is_regex" boolean DEFAULT false, "p_note" "text" DEFAULT NULL::"text", "p_active" boolean DEFAULT true, "p_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare rid uuid;
begin
  if not (
      public.is_admin(auth.uid())
      or public.is_admin_claimed(auth.uid())
      or exists (select 1 from public.app_admins a where a.user_id = auth.uid())
    )
  then
    raise exception using errcode='P0001', message='admin_only';
  end if;

  if p_id is null then
    insert into public.moderation_ban_terms(scope,term,lang,severity,is_regex,note,is_active,created_by)
    values (p_scope, p_term, p_lang, p_severity, p_is_regex, p_note, p_active, auth.uid())
    returning id into rid;
  else
    update public.moderation_ban_terms
       set scope=p_scope, term=p_term, lang=p_lang, severity=p_severity,
           is_regex=p_is_regex, note=p_note, is_active=p_active
     where id=p_id
    returning id into rid;
  end if;

  return rid;
end;
$$;


ALTER FUNCTION "public"."rpc_ban_term_upsert"("p_scope" "text", "p_term" "text", "p_lang" "text", "p_severity" "text", "p_is_regex" boolean, "p_note" "text", "p_active" boolean, "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_ban_username"("p_username" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor uuid := public.admin_actor();
  norm    text;
begin
  if v_actor is null then raise exception using errcode='P0001', message='not_authenticated'; end if;
  if not public.is_admin(v_actor) then raise exception using errcode='P0001', message='not_admin'; end if;

  norm := public.normalize_username(p_username);

  insert into public.username_banned(username, reason, created_at)
  values (norm, coalesce(p_reason,'moderation_ban'), now())
  on conflict (username) do nothing;

  insert into public.moderation_actions(actor_admin_id, action_type, target_table, target_id, reason, metadata)
  values (v_actor, 'ban_username', 'username_registry', gen_random_uuid(), p_reason, jsonb_build_object('username', norm));
end;
$$;


ALTER FUNCTION "public"."rpc_ban_username"("p_username" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_block_user"("p_peer" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller UUID := auth.uid();
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF v_caller = p_peer THEN RAISE EXCEPTION 'Cannot block yourself'; END IF;
  INSERT INTO public.user_blocks (blocker_user_id, blocked_user_id)
  VALUES (v_caller, p_peer)
  ON CONFLICT (blocker_user_id, blocked_user_id) DO NOTHING;
  DELETE FROM public.profile_follows
  WHERE (follower_profile_id IN (SELECT id FROM profiles WHERE user_id = v_caller)
     AND following_profile_id IN (SELECT id FROM profiles WHERE user_id = p_peer))
     OR (follower_profile_id IN (SELECT id FROM profiles WHERE user_id = p_peer)
     AND following_profile_id IN (SELECT id FROM profiles WHERE user_id = v_caller));
  BEGIN
    DELETE FROM public.friendships
    WHERE (user_id IN (SELECT id FROM profiles WHERE user_id = v_caller)
       AND peer_user_id IN (SELECT id FROM profiles WHERE user_id = p_peer))
       OR (user_id IN (SELECT id FROM profiles WHERE user_id = p_peer)
       AND peer_user_id IN (SELECT id FROM profiles WHERE user_id = v_caller));
  EXCEPTION WHEN undefined_table THEN NULL;
  END;
END;
$$;


ALTER FUNCTION "public"."rpc_block_user"("p_peer" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_block_user"("p_peer" "uuid", "p_block" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE me uuid := auth.uid();
BEGIN
  IF me IS NULL THEN RAISE EXCEPTION USING errcode='P0001', message='not_authenticated'; END IF;
  IF p_block THEN
    INSERT INTO public.restrictions(user_id, target_user_id, type)
    VALUES (me, p_peer, 'blocked')
    ON CONFLICT (user_id, target_user_id, type) DO NOTHING;
  ELSE
    DELETE FROM public.restrictions
    WHERE user_id = me AND target_user_id = p_peer AND type='blocked';
  END IF;
END;
$$;


ALTER FUNCTION "public"."rpc_block_user"("p_peer" "uuid", "p_block" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_booking_cancel"("p_booking_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  b          record;
  vid        uuid;
  owner_user uuid;
BEGIN
  SELECT * INTO b FROM public.venue_bookings WHERE id = p_booking_id;
  IF NOT FOUND THEN RAISE EXCEPTION USING errcode='P0001', message='booking_not_found'; END IF;

  SELECT s.venue_id INTO vid FROM public.venue_spaces s WHERE s.id = b.venue_space_id;

  owner_user := CASE
    WHEN b.source_type = 'game'   THEN (SELECT creator_user_id FROM public.games   WHERE id = b.source_id)
    WHEN b.source_type = 'meetup' THEN (SELECT creator_user_id FROM public.meetups WHERE id = b.source_id)
    ELSE NULL
  END;

  IF NOT (public.is_venue_admin(auth.uid(), vid)
          OR public.is_admin(auth.uid())
          OR owner_user = auth.uid()) THEN
    RAISE EXCEPTION USING errcode='P0001', message='not_authorized';
  END IF;

  UPDATE public.venue_bookings SET status = 'cancelled'
  WHERE id = p_booking_id AND status <> 'cancelled';

  RETURN 'ok';
END;
$$;


ALTER FUNCTION "public"."rpc_booking_cancel"("p_booking_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_booking_hold_for_game"("p_game_id" "uuid", "p_space_id" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  g   record;
  vid uuid;
  bid uuid;
BEGIN
  SELECT * INTO g FROM public.games WHERE id = p_game_id;
  IF NOT FOUND THEN RAISE EXCEPTION USING errcode='P0001', message='game_not_found'; END IF;

  SELECT s.venue_id INTO vid FROM public.venue_spaces s WHERE s.id = p_space_id;
  IF vid IS NULL THEN RAISE EXCEPTION USING errcode='P0001', message='space_not_found'; END IF;

  IF NOT (g.creator_user_id = auth.uid()
          OR public.is_venue_admin(auth.uid(), vid)
          OR public.is_admin(auth.uid())) THEN
    RAISE EXCEPTION USING errcode='P0001', message='not_authorized';
  END IF;

  INSERT INTO public.venue_bookings(venue_space_id, starts_at, ends_at, source_type, source_id, status, created_by)
  VALUES (p_space_id, p_start, p_end, 'game', p_game_id, 'confirmed', auth.uid())
  RETURNING id INTO bid;

  UPDATE public.games SET venue_space_id = p_space_id WHERE id = p_game_id;

  RETURN bid;
END;
$$;


ALTER FUNCTION "public"."rpc_booking_hold_for_game"("p_game_id" "uuid", "p_space_id" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_booking_hold_for_meetup"("p_meetup_id" "uuid", "p_space_id" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  m record;
  vid uuid;
  bid uuid;
begin
  select * into m from public.meetups where id = p_meetup_id;
  if not found then raise exception using errcode='P0001', message='meetup_not_found'; end if;

  select s.venue_id into vid from public.venue_spaces s where s.id = p_space_id;
  if vid is null then raise exception using errcode='P0001', message='space_not_found'; end if;

  if not (m.owner_user_id = auth.uid() or public.is_venue_admin(auth.uid(), vid) or public.is_admin(auth.uid())) then
    raise exception using errcode='P0001', message='not_authorized';
  end if;

  insert into public.venue_bookings(venue_space_id, starts_at, ends_at, source_type, source_id, status, created_by)
  values (p_space_id, p_start, p_end, 'meetup', p_meetup_id, 'confirmed', auth.uid())
  returning id into bid;

  -- (optional) store human location on meetup side already; no FK change here.
  return bid;
end;
$$;


ALTER FUNCTION "public"."rpc_booking_hold_for_meetup"("p_meetup_id" "uuid", "p_space_id" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_broadcast_inapp_notification"("p_title" "text", "p_body" "text", "p_route" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_inserted integer;
BEGIN
  IF p_title IS NULL OR length(trim(p_title)) = 0 THEN
    RAISE EXCEPTION 'title is required';
  END IF;

  INSERT INTO public.notifications (to_user_id, kind_key, title, body, action_route, context, priority)
  SELECT p.user_id,
         'system.announcement',
         p_title,
         p_body,
         p_route,
         jsonb_build_object('broadcast', true),
         'normal'
  FROM public.profiles p
  WHERE p.is_active = true;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  RETURN v_inserted;
END;
$$;


ALTER FUNCTION "public"."rpc_broadcast_inapp_notification"("p_title" "text", "p_body" "text", "p_route" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_cancel_game"("p_game_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE public.games
  SET is_cancelled = true, cancelled_at = now(), cancelled_reason = p_reason
  WHERE id = p_game_id
    AND (creator_user_id = auth.uid() OR public.is_admin(auth.uid()));
  IF NOT FOUND THEN
    RAISE EXCEPTION USING errcode='P0001', message='not_host_or_not_found';
  END IF;
  RETURN 'cancelled';
END$$;


ALTER FUNCTION "public"."rpc_cancel_game"("p_game_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_challenge_add_squad"("p_challenge_id" "uuid", "p_squad_id" "uuid", "p_seed" integer DEFAULT NULL::integer) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare c record;
begin
  select * into c from public.challenges where id = p_challenge_id;
  if not found then raise exception using errcode='P0001', message='challenge_not_found'; end if;
  if c.owner_user_id <> auth.uid() and not public.is_admin(auth.uid()) then
    raise exception using errcode='P0001', message='not_owner';
  end if;

  if public._squad_sport(p_squad_id) is distinct from c.sport then
    raise exception using errcode='P0001', message='sport_mismatch';
  end if;

  insert into public.challenge_squads(challenge_id, squad_id, seed)
  values (p_challenge_id, p_squad_id, p_seed)
  on conflict do nothing;

  perform public.emit_event('challenge.squad_added','challenge', p_challenge_id, auth.uid(), jsonb_build_object('squad_id', p_squad_id));
  return 'ok';
end;
$$;


ALTER FUNCTION "public"."rpc_challenge_add_squad"("p_challenge_id" "uuid", "p_squad_id" "uuid", "p_seed" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_challenge_create"("p_profile_type" "text", "p_title" "text", "p_visibility" "text", "p_description" "text") RETURNS TABLE("id" "uuid", "title" "text", "visibility" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  me  uuid := auth.uid();
  pid uuid;
begin
  if me is null then
    raise exception using errcode='P0001', message='not_authenticated';
  end if;

  if p_profile_type not in ('player','organiser') then
    raise exception using errcode='P0001', message='actor_type_invalid';
  end if;

  if p_visibility not in ('public','circle','hidden') then
    raise exception using errcode='P0001', message='visibility_invalid';
  end if;

  -- pick the caller’s actor and require organiser to create challenges
  pid := public.choose_actor(p_profile_type);
  if not public.actor_is_organiser(pid) then
    raise exception using errcode='P0001', message='organiser_required';
  end if;

  -- rely on table defaults for: type ('challenge'), status ('draft'), etc.
  insert into public.challenges as c
    (owner_user_id, owner_profile_id, title, visibility, description)
  values
    (me,            pid,              p_title, p_visibility, p_description)
  returning c.id, c.title, c.visibility
  into id, title, visibility;

  return next;
end;
$$;


ALTER FUNCTION "public"."rpc_challenge_create"("p_profile_type" "text", "p_title" "text", "p_visibility" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_challenge_generate_fixtures"("p_challenge_id" "uuid", "p_type" "text" DEFAULT NULL::"text", "p_start_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_rounds" integer DEFAULT 1) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  c record;
  t text;
  squads uuid[];
  n int;
  created int := 0;
  stg uuid;
  i int;
  j int;
  round int;
  slots int;
  padded int;
  fix_id uuid;  -- <-- new variable to capture inserted id
begin
  select * into c from public.challenges where id = p_challenge_id;
  if not found then raise exception using errcode='P0001', message='challenge_not_found'; end if;
  if c.owner_user_id <> auth.uid() and not public.is_admin(auth.uid()) then
    raise exception using errcode='P0001', message='not_owner';
  end if;

  t := coalesce(p_type, c.type);
  if t not in ('round_robin','knockout') then
    raise exception using errcode='P0001', message='unsupported_type';
  end if;

  insert into public.challenge_stages(challenge_id, stage_type, name, ordinal)
  values (p_challenge_id, t, initcap(replace(t,'_',' ')), coalesce((select max(ordinal)+1 from public.challenge_stages where challenge_id=p_challenge_id),1))
  returning id into stg;

  select array_agg(sq.squad_id order by coalesce(sq.seed, 9999), sq.joined_at)
  into squads
  from public.challenge_squads sq
  where sq.challenge_id = p_challenge_id and sq.status='active';

  n := coalesce(array_length(squads,1), 0);
  if n < 2 then
    raise exception using errcode='P0001', message='not_enough_squads';
  end if;

  if t = 'round_robin' then
    if (n % 2) = 1 then
      squads := squads || null;
      n := n + 1;
    end if;

    for round in 1..greatest(p_rounds,1) loop
      for i in 1..(n-1) loop
        for j in 1..(n/2) loop
          declare
            idxL int;
            idxR int;
            home uuid;
            away uuid;
          begin
            idxL := case when j=1 then 1 else ((i + j - 2) % (n-1)) + 2 end;
            idxR := n - j + 1;

            home := squads[idxL];
            away := squads[idxR];

            if home is not null and away is not null then
              insert into public.challenge_fixtures(challenge_id, stage_id, round_no, home_squad_id, away_squad_id, best_of, scheduled_at)
              values (p_challenge_id, stg, ((round-1)*(n-1))+i, home, away, coalesce((c.rules->>'best_of')::int,1), p_start_at)
              returning id into fix_id;  -- <-- capture uuid, not into j
              created := created + 1;
            end if;
          end;
        end loop;
        -- rotate [1 | 2..n] → [1 | n, 2..n-1]
        squads := array_cat(ARRAY[squads[1]], ARRAY[squads[n]] || squads[2:n-1]);
      end loop;
    end loop;

  elsif t = 'knockout' then
    slots := 1; while slots < n loop slots := slots * 2; end loop;
    padded := slots - n;

    for i in 1..(slots/2) loop
      declare
        a_idx int := i;
        b_idx int := slots - i + 1;
        home uuid := case when a_idx <= n then squads[a_idx] else null end;
        away uuid := case when b_idx <= n then squads[b_idx] else null end;
      begin
        if home is null and away is null then
          continue;
        elsif home is null then
          insert into public.challenge_fixtures(challenge_id, stage_id, round_no, home_squad_id, away_squad_id, best_of, scheduled_at, status, winner_squad_id)
          values (p_challenge_id, stg, 1, null, away, coalesce((c.rules->>'best_of')::int,1), p_start_at, 'completed', away)
          returning id into fix_id;
        elsif away is null then
          insert into public.challenge_fixtures(challenge_id, stage_id, round_no, home_squad_id, away_squad_id, best_of, scheduled_at, status, winner_squad_id)
          values (p_challenge_id, stg, 1, home, null, coalesce((c.rules->>'best_of')::int,1), p_start_at, 'completed', home)
          returning id into fix_id;
        else
          insert into public.challenge_fixtures(challenge_id, stage_id, round_no, home_squad_id, away_squad_id, best_of, scheduled_at)
          values (p_challenge_id, stg, 1, home, away, coalesce((c.rules->>'best_of')::int,1), p_start_at)
          returning id into fix_id;
        end if;
        created := created + 1;
      end;
    end loop;
  end if;

  update public.challenges
  set status = case when status='draft' then 'published' else status end
  where id = p_challenge_id;

  perform public.emit_event('challenge.fixtures_generated','challenge', p_challenge_id, auth.uid(),
    jsonb_build_object('count', created, 'type', t));
  return created;
end;
$$;


ALTER FUNCTION "public"."rpc_challenge_generate_fixtures"("p_challenge_id" "uuid", "p_type" "text", "p_start_at" timestamp with time zone, "p_rounds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_challenge_invite_squad"("p_challenge_id" "uuid", "p_to_squad_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  c record;
  inviter_profile uuid;
  inv_id uuid;
begin
  select * into c from public.challenges where id = p_challenge_id;
  if not found then raise exception using errcode='P0001', message='challenge_not_found'; end if;
  if c.owner_user_id <> auth.uid() and not public.is_admin(auth.uid()) then
    raise exception using errcode='P0001', message='not_owner';
  end if;

  if public._squad_sport(p_to_squad_id) is distinct from c.sport then
    raise exception using errcode='P0001', message='sport_mismatch';
  end if;

  inviter_profile := c.owner_profile_id;

  insert into public.challenge_invites(challenge_id, to_squad_id, created_by_profile_id)
  values (p_challenge_id, p_to_squad_id, inviter_profile)
  returning id into inv_id;

  perform public.emit_event('challenge.invite_sent','challenge', p_challenge_id, auth.uid(), jsonb_build_object('invite_id', inv_id, 'to_squad_id', p_to_squad_id));
  return inv_id;
end;
$$;


ALTER FUNCTION "public"."rpc_challenge_invite_squad"("p_challenge_id" "uuid", "p_to_squad_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_challenge_record_result"("p_fixture_id" "uuid", "p_home_score" integer, "p_away_score" integer) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  f record;
  c record;
  winner uuid;
begin
  select * into f from public.challenge_fixtures where id = p_fixture_id for update;
  if not found then raise exception using errcode='P0001', message='fixture_not_found'; end if;

  select * into c from public.challenges where id = f.challenge_id;
  if c.owner_user_id <> auth.uid() and not public.is_admin(auth.uid()) then
    raise exception using errcode='P0001', message='not_owner';
  end if;

  if p_home_score is null or p_away_score is null then
    raise exception using errcode='P0001', message='score_required';
  end if;

  winner := case
    when p_home_score > p_away_score then f.home_squad_id
    when p_away_score > p_home_score then f.away_squad_id
    else null
  end;

  update public.challenge_fixtures
  set home_score = p_home_score,
      away_score = p_away_score,
      winner_squad_id = winner,
      status = 'completed'
  where id = p_fixture_id;

  perform public.emit_event('challenge.fixture_completed','challenge', f.challenge_id, auth.uid(),
    jsonb_build_object('fixture_id', p_fixture_id, 'home', f.home_squad_id, 'away', f.away_squad_id,
                       'home_score', p_home_score, 'away_score', p_away_score, 'winner', winner));
  return 'ok';
end;
$$;


ALTER FUNCTION "public"."rpc_challenge_record_result"("p_fixture_id" "uuid", "p_home_score" integer, "p_away_score" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_challenge_respond_invite"("p_invite_id" "uuid", "p_decision" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare inv record;
begin
  select * into inv from public.challenge_invites where id = p_invite_id for update;
  if not found then raise exception using errcode='P0001', message='invite_not_found'; end if;
  if inv.status <> 'pending' then raise exception using errcode='P0001', message='invite_not_pending'; end if;

  if not exists (select 1 from public.squad_members m where m.squad_id = inv.to_squad_id and m.user_id = auth.uid() and m.status='active') then
    raise exception using errcode='P0001', message='not_squad_member';
  end if;

  if p_decision = 'accepted' then
    insert into public.challenge_squads(challenge_id, squad_id)
    values (inv.challenge_id, inv.to_squad_id)
    on conflict do nothing;
    update public.challenge_invites set status='accepted' where id = p_invite_id;
    perform public.emit_event('challenge.invite_accepted','challenge', inv.challenge_id, auth.uid(), jsonb_build_object('invite_id', p_invite_id));
    return 'accepted';
  elsif p_decision = 'declined' then
    update public.challenge_invites set status='declined' where id = p_invite_id;
    perform public.emit_event('challenge.invite_declined','challenge', inv.challenge_id, auth.uid(), jsonb_build_object('invite_id', p_invite_id));
    return 'declined';
  else
    raise exception using errcode='P0001', message='invalid_decision';
  end if;
end;
$$;


ALTER FUNCTION "public"."rpc_challenge_respond_invite"("p_invite_id" "uuid", "p_decision" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_challenge_set_status"("p_challenge_id" "uuid", "p_status" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare c record;
begin
  select * into c from public.challenges where id=p_challenge_id;
  if not found then raise exception using errcode='P0001', message='challenge_not_found'; end if;
  if c.owner_user_id <> auth.uid() and not public.is_admin(auth.uid()) then
    raise exception using errcode='P0001', message='not_owner';
  end if;
  if p_status not in ('published','active','completed','cancelled') then
    raise exception using errcode='P0001', message='invalid_status';
  end if;

  update public.challenges set status = p_status where id = p_challenge_id;

  perform public.emit_event('challenge.status_changed','challenge', p_challenge_id, auth.uid(),
    jsonb_build_object('status', p_status));
  return 'ok';
end;
$$;


ALTER FUNCTION "public"."rpc_challenge_set_status"("p_challenge_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_challenge_spawn_game"("p_fixture_id" "uuid", "p_start_at" timestamp with time zone, "p_venue_space_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  f record; c record; gid uuid; title text;
BEGIN
  SELECT * INTO f FROM public.challenge_fixtures WHERE id = p_fixture_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING errcode='P0001', message='fixture_not_found'; END IF;

  SELECT * INTO c FROM public.challenges WHERE id = f.challenge_id;
  IF c.owner_user_id <> auth.uid() AND NOT public.is_admin(auth.uid()) THEN
    RAISE EXCEPTION USING errcode='P0001', message='not_owner';
  END IF;

  title := COALESCE(c.title, 'Challenge') || ' — Fixture ' || f.id::text;

  INSERT INTO public.games(
    game_type, title,
    creator_profile_id, creator_user_id,
    start_at, end_at, capacity,
    listing_visibility, join_policy,
    venue_space_id, squad_id
  )
  VALUES (
    'hosted', title,
    c.owner_profile_id, c.owner_user_id,
    p_start_at, p_start_at + interval '90 minutes', 22,
    'hidden', 'squad',
    p_venue_space_id, null
  )
  RETURNING id INTO gid;

  UPDATE public.challenge_fixtures
  SET game_id = gid, scheduled_at = p_start_at
  WHERE id = p_fixture_id;

  PERFORM public.emit_event('challenge.fixture_spawned', 'challenge', f.challenge_id, auth.uid(),
    jsonb_build_object('fixture_id', p_fixture_id, 'game_id', gid));

  RETURN gid;
END;
$$;


ALTER FUNCTION "public"."rpc_challenge_spawn_game"("p_fixture_id" "uuid", "p_start_at" timestamp with time zone, "p_venue_space_id" "uuid") OWNER TO "postgres";


