CREATE OR REPLACE FUNCTION "public"."rpc_create_game"("p_actor_type" "text", "p_sport_id" "uuid", "p_sport_variant_id" "uuid", "p_title" "text" DEFAULT NULL::"text", "p_venue_space_id" "uuid" DEFAULT NULL::"uuid", "p_start_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_end_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_bench_slots" integer DEFAULT 0, "p_listing_visibility" "text" DEFAULT 'public'::"text", "p_join_policy" "text" DEFAULT 'open'::"text", "p_min_skill" integer DEFAULT NULL::integer, "p_max_skill" integer DEFAULT NULL::integer, "p_rules" "jsonb" DEFAULT NULL::"jsonb", "p_squad_id" "uuid" DEFAULT NULL::"uuid", "p_allow_spectators" boolean DEFAULT false, "p_allows_waitlist" boolean DEFAULT false, "p_sport_specific_data" "jsonb" DEFAULT NULL::"jsonb", "p_cost_cover" "text" DEFAULT NULL::"text", "p_geo_location_id" "uuid" DEFAULT NULL::"uuid", "p_area_id" "uuid" DEFAULT NULL::"uuid", "p_lat" double precision DEFAULT NULL::double precision, "p_lng" double precision DEFAULT NULL::double precision, "p_min_players" integer DEFAULT NULL::integer, "p_max_players" integer DEFAULT NULL::integer) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  pid uuid; uid uuid; gid uuid; gtype text;
  v_sport record; v_variant record;
  v_required integer; v_players_per_side integer;
  v_geo_id uuid; v_area_id uuid; v_venue_id uuid;
  v_joining_rule text; v_cost_cover text;
  v_capacity integer; v_rules jsonb;
BEGIN
  pid := public.choose_actor(p_actor_type);
  IF p_end_at <= p_start_at THEN RAISE EXCEPTION USING errcode='P0001', message='invalid_time_range'; END IF;
  SELECT * INTO v_sport FROM public.sports WHERE id = p_sport_id AND is_active = true;
  IF NOT FOUND THEN RAISE EXCEPTION USING errcode='P0001', message='invalid_sport'; END IF;
  IF v_sport.is_challenge_sport IS DISTINCT FROM true THEN RAISE EXCEPTION USING errcode='P0001', message='sport_not_challenge_eligible'; END IF;
  SELECT * INTO v_variant FROM public.sport_variants WHERE id = p_sport_variant_id AND sport_id = p_sport_id AND is_active = true;
  IF NOT FOUND THEN RAISE EXCEPTION USING errcode='P0001', message='invalid_sport_variant'; END IF;
  v_required := v_variant.required_players;
  v_players_per_side := v_variant.players_per_side;
  IF p_bench_slots < 0 OR p_bench_slots > v_players_per_side THEN RAISE EXCEPTION USING errcode='P0001', message='invalid_bench_slots'; END IF;

  -- Optional player-count overrides (UI-editable Min/Max players)
  IF p_max_players IS NOT NULL AND p_max_players < 1 THEN
    RAISE EXCEPTION USING errcode='P0001', message='invalid_max_players';
  END IF;
  IF p_min_players IS NOT NULL AND p_min_players < 1 THEN
    RAISE EXCEPTION USING errcode='P0001', message='invalid_min_players';
  END IF;
  IF p_min_players IS NOT NULL AND p_max_players IS NOT NULL AND p_min_players > p_max_players THEN
    RAISE EXCEPTION USING errcode='P0001', message='invalid_player_range';
  END IF;
  v_capacity := COALESCE(p_max_players, v_required);
  v_rules := COALESCE(p_rules, '{}'::jsonb);
  IF p_min_players IS NOT NULL THEN
    v_rules := v_rules || jsonb_build_object('min_players', p_min_players);
  END IF;
  IF p_max_players IS NOT NULL THEN
    v_rules := v_rules || jsonb_build_object('max_players', p_max_players);
  END IF;

  SELECT user_id INTO uid FROM public.profiles WHERE id = pid;
  IF uid IS NULL THEN RAISE EXCEPTION USING errcode='P0001', message='creator_profile_not_found'; END IF;
  IF p_venue_space_id IS NOT NULL THEN
    SELECT v.geo_location_id, v.area_id, v.id INTO v_geo_id, v_area_id, v_venue_id
      FROM public.venue_spaces vs JOIN public.venues v ON v.id = vs.venue_id
     WHERE vs.id = p_venue_space_id;
  END IF;
  IF v_geo_id IS NULL AND p_geo_location_id IS NOT NULL THEN
    v_geo_id := p_geo_location_id; v_area_id := p_area_id;
  END IF;
  IF v_geo_id IS NULL AND p_lat IS NOT NULL AND p_lng IS NOT NULL THEN
    SELECT id, area_id INTO v_geo_id, v_area_id FROM public.geo_locations
     ORDER BY ST_Distance(location, ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)) LIMIT 1;
  END IF;
  IF v_geo_id IS NULL THEN
    SELECT id, area_id INTO v_geo_id, v_area_id FROM public.geo_locations ORDER BY created_at LIMIT 1;
  END IF;
  IF p_venue_space_id IS NOT NULL THEN
    SELECT joining_rule INTO v_joining_rule FROM public.venue_spaces WHERE id = p_venue_space_id;
    v_cost_cover := COALESCE(p_cost_cover, v_joining_rule);
  ELSE
    v_joining_rule := 'free'; v_cost_cover := COALESCE(p_cost_cover, 'free');
  END IF;
  gtype := CASE WHEN p_actor_type = 'organiser' THEN 'hosted' ELSE 'casual' END;
  INSERT INTO public.games (
    game_type, sport_id, sport_variant_id, title,
    creator_profile_id, creator_user_id, venue_space_id, venue_id,
    start_at, end_at, capacity, bench_slots,
    listing_visibility, join_policy, min_skill, max_skill, rules,
    squad_id, allow_spectators, allows_waitlist,
    sport_specific_data, joining_rule, cost_cover,
    geo_location_id, area_id
  ) VALUES (
    gtype, p_sport_id, p_sport_variant_id, p_title,
    pid, uid, p_venue_space_id, v_venue_id,
    p_start_at, p_end_at, v_capacity, p_bench_slots,
    p_listing_visibility, p_join_policy, p_min_skill, p_max_skill, v_rules,
    p_squad_id, p_allow_spectators, p_allows_waitlist,
    COALESCE(p_sport_specific_data, '{}'), v_joining_rule, v_cost_cover,
    v_geo_id, COALESCE(v_area_id, p_area_id)
  ) RETURNING id INTO gid;
  INSERT INTO public.game_roster (game_id, profile_id, user_id, role, status)
  VALUES (gid, pid, uid, 'host', 'active')
  ON CONFLICT (game_id, profile_id) DO UPDATE SET status='active', left_at=NULL;
  RETURN gid;
END;
$$;


ALTER FUNCTION "public"."rpc_create_game"("p_actor_type" "text", "p_sport_id" "uuid", "p_sport_variant_id" "uuid", "p_title" "text", "p_venue_space_id" "uuid", "p_start_at" timestamp with time zone, "p_end_at" timestamp with time zone, "p_bench_slots" integer, "p_listing_visibility" "text", "p_join_policy" "text", "p_min_skill" integer, "p_max_skill" integer, "p_rules" "jsonb", "p_squad_id" "uuid", "p_allow_spectators" boolean, "p_allows_waitlist" boolean, "p_sport_specific_data" "jsonb", "p_cost_cover" "text", "p_geo_location_id" "uuid", "p_area_id" "uuid", "p_lat" double precision, "p_lng" double precision, "p_min_players" integer, "p_max_players" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_create_meetup"("p_actor_type" "text", "p_sport_id" "uuid", "p_sport_variant_id" "uuid", "p_title" "text", "p_description" "text" DEFAULT NULL::"text", "p_venue_id" "uuid" DEFAULT NULL::"uuid", "p_location_name" "text" DEFAULT NULL::"text", "p_geo_location_id" "uuid" DEFAULT NULL::"uuid", "p_area_id" "uuid" DEFAULT NULL::"uuid", "p_start_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_end_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_capacity" integer DEFAULT NULL::integer, "p_listing_visibility" "text" DEFAULT 'public'::"text", "p_rsvp_policy" "text" DEFAULT 'open'::"text", "p_members_only" boolean DEFAULT false, "p_min_skill" integer DEFAULT NULL::integer, "p_max_skill" integer DEFAULT NULL::integer, "p_vibe_key" "text" DEFAULT NULL::"text", "p_meta" "jsonb" DEFAULT NULL::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  pid               uuid;
  uid               uuid;
  mid               uuid;
  v_sport           record;
  v_variant         record;
  v_required        integer;
  v_final_capacity  integer;
BEGIN
  pid := public.choose_actor(p_actor_type);

  IF p_location_name IS NULL OR trim(p_location_name) = '' THEN
    RAISE EXCEPTION USING errcode='P0001', message='location_name_required';
  END IF;

  IF p_title IS NULL OR trim(p_title) = '' THEN
    RAISE EXCEPTION USING errcode='P0001', message='title_required';
  END IF;

  IF p_start_at IS NOT NULL AND p_end_at IS NOT NULL
     AND p_end_at <= p_start_at THEN
    RAISE EXCEPTION USING errcode='P0001', message='invalid_time_range';
  END IF;

  SELECT * INTO v_sport
    FROM public.sports
   WHERE id = p_sport_id AND is_active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING errcode='P0001', message='invalid_sport';
  END IF;

  SELECT * INTO v_variant
    FROM public.sport_variants
   WHERE id = p_sport_variant_id
     AND sport_id = p_sport_id
     AND is_active = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING errcode='P0001', message='invalid_sport_variant';
  END IF;

  v_required := v_variant.required_players;

  IF p_capacity IS NOT NULL THEN
    IF p_capacity < v_required THEN
      RAISE EXCEPTION USING errcode='P0001', message='capacity_below_required_players';
    END IF;
    v_final_capacity := p_capacity;
  ELSE
    v_final_capacity := NULL;
  END IF;

  SELECT user_id INTO uid FROM public.profiles WHERE id = pid;
  IF uid IS NULL THEN
    RAISE EXCEPTION USING errcode='P0001', message='creator_profile_not_found';
  END IF;

  INSERT INTO public.meetups (
    creator_profile_id,
    creator_user_id,
    sport_id,
    title,
    description,
    venue_id,
    location_name,
    geo_location_id,
    area_id,
    start_at,
    end_at,
    capacity,
    listing_visibility,
    rsvp_policy,
    members_only,
    min_skill,
    max_skill,
    vibe_key,
    meta
  )
  VALUES (
    pid,
    uid,
    p_sport_id,
    p_title,
    p_description,
    p_venue_id,
    p_location_name,
    p_geo_location_id,
    p_area_id,
    p_start_at,
    p_end_at,
    v_final_capacity,
    p_listing_visibility,
    p_rsvp_policy,
    p_members_only,
    p_min_skill,
    p_max_skill,
    p_vibe_key,
    COALESCE(p_meta, '{}')
  )
  RETURNING id INTO mid;

  INSERT INTO public.meetup_attendees (meetup_id, actor_profile_id, user_id, status)
  VALUES (mid, pid, uid, 'going')
  ON CONFLICT (meetup_id, actor_profile_id) DO UPDATE
    SET status = 'going';

  RETURN mid;
END;
$$;


ALTER FUNCTION "public"."rpc_create_meetup"("p_actor_type" "text", "p_sport_id" "uuid", "p_sport_variant_id" "uuid", "p_title" "text", "p_description" "text", "p_venue_id" "uuid", "p_location_name" "text", "p_geo_location_id" "uuid", "p_area_id" "uuid", "p_start_at" timestamp with time zone, "p_end_at" timestamp with time zone, "p_capacity" integer, "p_listing_visibility" "text", "p_rsvp_policy" "text", "p_members_only" boolean, "p_min_skill" integer, "p_max_skill" integer, "p_vibe_key" "text", "p_meta" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_create_post"("p_author_profile_id" "uuid", "p_kind" "text", "p_visibility" "text", "p_body" "text" DEFAULT NULL::"text", "p_lang" "text" DEFAULT NULL::"text", "p_sport_key" "text" DEFAULT NULL::"text", "p_venue_id" "uuid" DEFAULT NULL::"uuid", "p_geo_lat" double precision DEFAULT NULL::double precision, "p_geo_lng" double precision DEFAULT NULL::double precision, "p_media" "jsonb" DEFAULT '[]'::"jsonb", "p_vibe_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  prof record;
  new_id uuid;
  ltoken text := null;
begin
  if auth.uid() is null then raise exception using errcode='P0001', message='auth_required'; end if;

  select id, user_id, profile_type into prof from public.profiles where id=p_author_profile_id;
  if not found or prof.user_id <> auth.uid() then
    raise exception using errcode='P0001', message='not_profile_owner';
  end if;
  if p_kind not in ('moment','dab','kickin') then raise exception using errcode='P0001', message='invalid_kind'; end if;
  if p_visibility not in ('public','circle','link','private') then raise exception using errcode='P0001', message='invalid_visibility'; end if;

  if p_visibility='link' then ltoken := public._gen_link_token(); end if;

  insert into public.posts(
    author_profile_id, author_user_id, kind, visibility, link_token,
    body, lang, sport_key, venue_id, geo_lat, geo_lng, media
  )
  values (
    p_author_profile_id, prof.user_id, p_kind, p_visibility, ltoken,
    left(p_body, 2000), p_lang, p_sport_key, p_venue_id, p_geo_lat, p_geo_lng,
    coalesce(p_media, '[]'::jsonb)
  )
  returning id into new_id;

  if p_vibe_ids is not null and array_length(p_vibe_ids,1) is not null then
    insert into public.post_vibes(post_id, vibe_id)
    select new_id, unnest(p_vibe_ids)::uuid
    on conflict do nothing;
  end if;

  return new_id;
end;
$$;


ALTER FUNCTION "public"."rpc_create_post"("p_author_profile_id" "uuid", "p_kind" "text", "p_visibility" "text", "p_body" "text", "p_lang" "text", "p_sport_key" "text", "p_venue_id" "uuid", "p_geo_lat" double precision, "p_geo_lng" double precision, "p_media" "jsonb", "p_vibe_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_create_profile"("profile_type" "text", "username" "text", "display_name" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  pid uuid;
  v_uid uuid := auth.uid();
  v_username citext := nullif(btrim(username), '')::citext;
  v_display_name text := public.normalize_display_name(coalesce(display_name, username));
  v_constraint text;
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode='P0001';
  end if;

  if rpc_create_profile.profile_type not in ('player','organiser') then
    raise exception 'invalid_profile_type' using errcode='P0001';
  end if;

  if v_display_name is null or char_length(v_display_name) < 2 or char_length(v_display_name) > 50 then
    raise exception 'display_name_length' using errcode='P0001',
      detail = 'display_name must be 2..50 chars';
  end if;

  -- >>> KEY CHANGE: collision guard using canonical forms (strip non-alnum)
  if v_username is not null
     and public.username_canon(v_display_name) = public.username_canon(v_username::text)
  then
    -- Auto-adjust to keep constraint happy while staying user-friendly
    v_display_name := left(
      initcap(regexp_replace(v_display_name, '\s+', ' ', 'g')) || ' • ' || rpc_create_profile.profile_type,
      50
    );
  end if;

  -- Pre-checks (still backstopped by unique indexes)
  if exists (
    select 1 from public.profiles p
    where p.user_id = v_uid and p.profile_type = rpc_create_profile.profile_type
  ) then
    raise exception 'profile_type_exists' using errcode='P0001';
  end if;

  if v_username is not null and exists (
    select 1 from public.profiles p
    where p.username = v_username
  ) then
    raise exception 'username_taken' using errcode='P0001';
  end if;

  insert into public.profiles (user_id, profile_type, username, display_name)
  values (v_uid, rpc_create_profile.profile_type, v_username, v_display_name)
  returning id into pid;

  return pid;

exception
  when unique_violation then
    get stacked diagnostics v_constraint = CONSTRAINT_NAME;
    if     v_constraint = 'profiles_user_id_profile_type_key' then
      raise exception 'profile_type_exists' using errcode='P0001';
    elseif v_constraint = 'profiles_username_key' then
      raise exception 'username_taken' using errcode='P0001';
    else
      raise;
    end if;
end;
$$;


ALTER FUNCTION "public"."rpc_create_profile"("profile_type" "text", "username" "text", "display_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_create_sport_profile"("p_profile_id" "uuid", "p_sport_id" "uuid", "p_sport_key" "text", "p_skill_level" integer DEFAULT 1) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = p_profile_id AND persona_type = 'player') THEN
    RAISE EXCEPTION 'sport_profile requires persona_type=player';
  END IF;
  INSERT INTO public.sport_profiles (profile_id, sport, sport_id, skill_level)
  VALUES (p_profile_id, p_sport_key, p_sport_id, p_skill_level)
  ON CONFLICT (profile_id, sport) DO UPDATE SET skill_level = EXCLUDED.skill_level;
END;
$$;


ALTER FUNCTION "public"."rpc_create_sport_profile"("p_profile_id" "uuid", "p_sport_id" "uuid", "p_sport_key" "text", "p_skill_level" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_create_squad"("p_actor_profile_id" "uuid", "p_sport" "text", "p_name" "text", "p_bio" "text" DEFAULT NULL::"text", "p_logo_url" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_user uuid;
  actor_type text;
  sid uuid;
  founder_is_player boolean;
begin
  if auth.uid() is null then
    raise exception using errcode='P0001', message='auth_required';
  end if;
  if public.is_frozen(auth.uid()) then
    raise exception using errcode='P0001', message='user_frozen';
  end if;

  select user_id, profile_type into actor_user, actor_type from public.profiles where id = p_actor_profile_id;
  if actor_user is null or actor_user <> auth.uid() then
    raise exception using errcode='P0001', message='not_profile_owner';
  end if;

  if actor_type not in ('player','organiser') then
    raise exception using errcode='P0001', message='invalid_actor_type';
  end if;

  founder_is_player := (actor_type = 'player');

  if founder_is_player then
    -- Enforce: player can found at most 1 squad per sport
    if exists (select 1 from public.squads s where s.owner_user_id = actor_user and s.sport = p_sport) then
      raise exception using errcode='P0001', message='founder_limit_reached';
    end if;
  end if;

  insert into public.squads(sport, owner_profile_id, owner_user_id, name, bio, logo_url)
  values (p_sport, p_actor_profile_id, actor_user, p_name, p_bio, p_logo_url)
  returning id into sid;

  -- If founder is player, auto-join as captain
  if founder_is_player then
    insert into public.squad_members(squad_id, profile_id, user_id, role, status)
    values (sid, p_actor_profile_id, actor_user, 'captain', 'active');
  end if;

  -- Emit event
  perform public.emit_event('squad.created','squad', sid, actor_user, jsonb_build_object('sport', p_sport));

  return sid;
end;
$$;


ALTER FUNCTION "public"."rpc_create_squad"("p_actor_profile_id" "uuid", "p_sport" "text", "p_name" "text", "p_bio" "text", "p_logo_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_decide_join_request"("p_request_id" "uuid", "p_approve" boolean) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  req   record;
  slots int;
BEGIN
  SELECT jr.*, g.creator_user_id
  INTO req
  FROM public.game_join_requests jr
  JOIN public.games g ON g.id = jr.game_id
  WHERE jr.id = p_request_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING errcode='P0001', message='request_not_found';
  END IF;

  IF req.creator_user_id <> auth.uid() AND NOT public.is_admin(auth.uid()) THEN
    RAISE EXCEPTION USING errcode='P0001', message='not_host';
  END IF;

  IF req.status <> 'pending' THEN RETURN 'already_decided'; END IF;

  IF p_approve THEN
    slots := public.game_slots_left(req.game_id);

    UPDATE public.game_join_requests
       SET status = 'approved', decided_at = now()
     WHERE id = p_request_id;

    IF slots > 0 THEN
      INSERT INTO public.game_roster(game_id, profile_id, role, status)
      VALUES (req.game_id, req.from_profile_id, 'player', 'active')
      ON CONFLICT (game_id, profile_id) DO UPDATE
        SET status = 'active', left_at = null;

      -- Notify the requester (entity_type 'game' also yields the
      -- /sports/games/<id> deep link). Never let notification failure
      -- roll back the approval itself.
      BEGIN
        PERFORM public.process_notification_event(
          req.from_user_id,
          'game.join_accepted',
          'game',
          req.game_id,
          auth.uid(),
          'You''re in! Your request to join was accepted'
        );
      EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'join_accepted notification failed: %', SQLERRM;
      END;

      RETURN 'approved_joined';
    ELSE
      INSERT INTO public.game_waitlist(game_id, profile_id, user_id, position)
      SELECT req.game_id, req.from_profile_id, req.from_user_id,
             COALESCE((SELECT MAX(position)+1 FROM public.game_waitlist WHERE game_id = req.game_id), 1)
      ON CONFLICT DO NOTHING;

      BEGIN
        PERFORM public.process_notification_event(
          req.from_user_id,
          'game.join_accepted',
          'game',
          req.game_id,
          auth.uid(),
          'Request approved — the game is full, you''re on the waitlist'
        );
      EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'join_accepted (waitlist) notification failed: %', SQLERRM;
      END;

      RETURN 'approved_waitlisted';
    END IF;
  ELSE
    UPDATE public.game_join_requests
       SET status = 'denied', decided_at = now()
     WHERE id = p_request_id;
    RETURN 'denied';
  END IF;
END;
$$;


ALTER FUNCTION "public"."rpc_decide_join_request"("p_request_id" "uuid", "p_approve" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_delete_post"("p_post_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  p public.posts%rowtype;
begin
  if auth.uid() is null then raise exception using errcode='P0001', message='auth_required'; end if;
  select * into p from public.posts where id=p_post_id;
  if not found then raise exception using errcode='P0001', message='not_found'; end if;

  if p.author_user_id <> auth.uid() and not public.is_admin(auth.uid()) then
    raise exception using errcode='P0001', message='forbidden';
  end if;

  update public.posts set is_deleted = true where id=p_post_id;
  insert into public.moderation_actions(target_kind,target_id,action,actor_user_id,notes)
  values ('post', p_post_id, 'delete', auth.uid(), 'soft-delete');
  return 'deleted';
end;
$$;


