CREATE OR REPLACE FUNCTION "public"."rpc_draft_archive"("p_draft_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  update public.content_drafts
     set status='archived', updated_at=now()
   where id=p_draft_id and owner_user_id=auth.uid() and status in ('draft','published');

  if not found then
    raise exception using errcode='P0001', message='not_found';
  end if;

  insert into public.content_draft_events(draft_id, owner_user_id, action)
  values (p_draft_id, auth.uid(), 'archived');
  return 'ok';
end;
$$;


