    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare did uuid;
begin
  if auth.uid() is null then raise exception using errcode='P0001', message='auth_required'; end if;
  if p_context not in ('game','meetup','challenge') then
    raise exception using errcode='P0001', message='invalid_context';
  end if;

  insert into public.content_drafts(owner_user_id, context, payload, status)
  values (auth.uid(), p_context, coalesce(p_payload,'{}'::jsonb), 'draft')
  returning id into did;

  insert into public.content_draft_events(draft_id, owner_user_id, action)
  values (did, auth.uid(), 'created');

  return did;
end;
$$;


