CREATE OR REPLACE FUNCTION "public"."rpc_draft_update"("p_draft_id" "uuid", "p_patch" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare cur jsonb;
begin
  update public.content_drafts
     set payload = coalesce(payload,'{}'::jsonb) || coalesce(p_patch,'{}'::jsonb),
         updated_at = now()
   where id = p_draft_id and owner_user_id = auth.uid() and status='draft'
  returning payload into cur;

  if cur is null then
    raise exception using errcode='P0001', message='not_found_or_not_editable';
  end if;

  insert into public.content_draft_events(draft_id, owner_user_id, action, details)
  values (p_draft_id, auth.uid(), 'updated', p_patch);

  return cur;
end;
$$;


