CREATE OR REPLACE FUNCTION "public"."rpc_ensure_profile"("profile_type" "text", "username" "text", "display_name" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_id  uuid;
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode='P0001';
  end if;

  -- Return existing profile id if present
  select p.id into v_id
  from public.profiles p
  where p.user_id = v_uid
    and p.profile_type = rpc_ensure_profile.profile_type
  limit 1;

  if v_id is not null then
    return v_id;
  end if;

  -- Otherwise, create one via the strict RPC (will enforce all checks)
  return public.rpc_create_profile(profile_type, username, display_name);
end;
$$;


