CREATE OR REPLACE FUNCTION "public"."rpc_friend_request_send"("p_peer_profile_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_my_profile_id UUID;
  v_user_id UUID;
  v_peer_user_id UUID;
  v_display_name text;
BEGIN
  SELECT user_id INTO v_my_profile_id
  FROM profiles
  WHERE user_id = auth.uid()
  LIMIT 1;

  IF v_my_profile_id IS NULL THEN
    RAISE EXCEPTION 'Profile not found for current user';
  END IF;

  -- Ensure correct ordering: user_id < peer_user_id to satisfy check constraint
  IF v_my_profile_id < p_peer_profile_id THEN
    v_user_id := v_my_profile_id;
    v_peer_user_id := p_peer_profile_id;
  ELSE
    v_user_id := p_peer_profile_id;
    v_peer_user_id := v_my_profile_id;
  END IF;

  INSERT INTO friendships (user_id, peer_user_id, requested_by, status, created_at, updated_at)
  VALUES (v_user_id, v_peer_user_id, v_my_profile_id, 'pending', NOW(), NOW())
  ON CONFLICT (user_id, peer_user_id) DO UPDATE
  SET status = 'pending', requested_by = v_my_profile_id, updated_at = NOW();

  SELECT display_name INTO v_display_name
  FROM profiles
  WHERE user_id = v_my_profile_id AND is_active = true
  LIMIT 1;
  v_display_name := COALESCE(v_display_name, 'Someone');

  -- Push-capable friend.requested kind (was social.friend_request, in-app only).
  INSERT INTO notifications (to_user_id, kind_key, title, body, context, action_route, created_at)
  VALUES (
    p_peer_profile_id,
    'friend.requested',
    v_display_name || ' sent you a friend request',
    NULL,
    jsonb_build_object('from_user_id', v_my_profile_id),
    '/user-profile/' || v_my_profile_id,
    NOW()
  );
END;
$$;


ALTER FUNCTION "public"."rpc_friend_request_send"("p_peer_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_friend_requests_inbox"() RETURNS TABLE("user_id" "uuid", "peer_user_id" "uuid", "requested_by" "uuid", "status" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "peer_profile" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_my_profile_id UUID;
BEGIN
  SELECT p.user_id INTO v_my_profile_id FROM profiles p WHERE p.user_id = auth.uid() LIMIT 1;
  IF v_my_profile_id IS NULL THEN RAISE EXCEPTION 'Profile not found for current user'; END IF;
  RETURN QUERY
  SELECT f.user_id, f.peer_user_id, f.requested_by, f.status, f.created_at, f.updated_at,
    jsonb_build_object('user_id', p.user_id, 'display_name', p.display_name, 'avatar_url', p.avatar_url, 'username', p.username) AS peer_profile
  FROM friendships f LEFT JOIN profiles p ON p.user_id = f.user_id
  WHERE f.peer_user_id = v_my_profile_id AND f.status = 'pending' AND f.requested_by != v_my_profile_id
  ORDER BY f.created_at DESC;
END;
$$;


