CREATE OR REPLACE FUNCTION "public"."rpc_friend_unfriend"("p_peer" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_my_profile_id UUID; v_user_id UUID; v_peer_user_id UUID;
BEGIN
  SELECT user_id INTO v_my_profile_id FROM profiles WHERE user_id = auth.uid() LIMIT 1;
  IF v_my_profile_id IS NULL THEN RAISE EXCEPTION 'Profile not found for current user'; END IF;
  IF v_my_profile_id < p_peer THEN v_user_id := v_my_profile_id; v_peer_user_id := p_peer;
  ELSE v_user_id := p_peer; v_peer_user_id := v_my_profile_id; END IF;
  DELETE FROM friendships WHERE user_id = v_user_id AND peer_user_id = v_peer_user_id;
END;
$$;


