CREATE OR REPLACE FUNCTION "public"."rpc_get_activity_feed"("_period" "text" DEFAULT 'all'::"text", "_limit" integer DEFAULT 50, "_cursor" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("id" "uuid", "subject_type" "text", "subject_id" "uuid", "verb" "text", "status" "text", "time_bucket" "text", "happened_at" timestamp with time zone, "scheduled_for" timestamp with time zone, "priority" integer, "payload" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  WITH me AS (
    SELECT auth.uid() AS user_id
  ),
  game_created AS (
    SELECT
      g.id                                                          AS id,
      'game'::text                                                  AS subject_type,
      g.id                                                          AS subject_id,
      'created'::text                                               AS verb,
      NULL::text                                                    AS status,
      CASE
        WHEN g.end_at < NOW()                              THEN 'past'
        WHEN g.start_at <= NOW() AND g.end_at >= NOW()    THEN 'present'
        WHEN g.start_at > NOW()                           THEN 'upcoming'
        ELSE 'past'
      END                                                           AS time_bucket,
      g.created_at                                                  AS happened_at,
      g.start_at                                                    AS scheduled_for,
      90                                                            AS priority,
      jsonb_build_object('role', 'host')                            AS payload
    FROM public.games g
    JOIN me ON g.creator_user_id = me.user_id
    WHERE g.is_cancelled = false
  ),
  game_joined AS (
    SELECT
      g.id                                                          AS id,
      'game'::text                                                  AS subject_type,
      g.id                                                          AS subject_id,
      'joined'::text                                                AS verb,
      NULL::text                                                    AS status,
      CASE
        WHEN g.end_at < NOW()                              THEN 'past'
        WHEN g.start_at <= NOW() AND g.end_at >= NOW()    THEN 'present'
        WHEN g.start_at > NOW()                           THEN 'upcoming'
        ELSE 'past'
      END                                                           AS time_bucket,
      gr.joined_at                                                  AS happened_at,
      g.start_at                                                    AS scheduled_for,
      80                                                            AS priority,
      jsonb_build_object('role', 'player')                          AS payload
    FROM public.game_roster gr
    JOIN public.games g ON g.id = gr.game_id
    JOIN me ON gr.user_id = me.user_id
    WHERE gr.status = 'active'
      AND g.is_cancelled = false
      AND g.creator_user_id <> me.user_id
  ),
  game_events AS (
    SELECT * FROM game_created
    UNION ALL
    SELECT * FROM game_joined
  ),
  filtered AS (
    SELECT * FROM game_events e
    WHERE (_period = 'all' OR e.time_bucket = _period)
      AND (_cursor IS NULL OR e.happened_at < _cursor)
  )
  SELECT * FROM filtered
  ORDER BY
    CASE time_bucket WHEN 'upcoming' THEN 1 WHEN 'present' THEN 2 WHEN 'past' THEN 3 END,
    scheduled_for ASC,
    happened_at DESC,
    priority DESC
  LIMIT _limit;
END;
$$;


ALTER FUNCTION "public"."rpc_get_activity_feed"("_period" "text", "_limit" integer, "_cursor" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_friend_suggestions"("p_user_id" "uuid" DEFAULT "auth"."uid"(), "p_limit" integer DEFAULT 20) RETURNS TABLE("user_id" "uuid", "full_name" "text", "username" "text", "avatar_url" "text", "bio" "text", "mutual_friends_count" integer, "mutual_friend_ids" "uuid"[])
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH user_friends AS (
    SELECT
      CASE
        WHEN f.user_id = p_user_id THEN f.peer_user_id
        ELSE f.user_id
      END AS friend_id
    FROM friendships f
    WHERE (f.user_id = p_user_id OR f.peer_user_id = p_user_id)
      AND f.status = 'accepted'
  ),
  potential_friends AS (
    SELECT
      CASE
        WHEN f.user_id = uf.friend_id THEN f.peer_user_id
        ELSE f.user_id
      END AS suggested_user_id,
      uf.friend_id AS mutual_friend_id
    FROM friendships f
    INNER JOIN user_friends uf ON (f.user_id = uf.friend_id OR f.peer_user_id = uf.friend_id)
    WHERE f.status = 'accepted'
      AND CASE
        WHEN f.user_id = uf.friend_id THEN f.peer_user_id
        ELSE f.user_id
      END != p_user_id
      AND CASE
        WHEN f.user_id = uf.friend_id THEN f.peer_user_id
        ELSE f.user_id
      END NOT IN (SELECT friend_id FROM user_friends)
  ),
  suggestion_counts AS (
    SELECT
      pf.suggested_user_id,
      COUNT(DISTINCT pf.mutual_friend_id) AS mutual_count,
      ARRAY_AGG(DISTINCT pf.mutual_friend_id) AS mutual_ids
    FROM potential_friends pf
    WHERE NOT EXISTS (
      SELECT 1 FROM friendships f2
      WHERE ((f2.user_id = p_user_id AND f2.peer_user_id = pf.suggested_user_id)
         OR (f2.user_id = pf.suggested_user_id AND f2.peer_user_id = p_user_id))
        AND f2.status IN ('pending', 'blocked')
    )
    GROUP BY pf.suggested_user_id
  )
  SELECT
    p.id,
    -- Backward-compatible output column name.
    p.display_name,
    p.username,
    p.avatar_url,
    p.bio,
    sc.mutual_count::INTEGER,
    sc.mutual_ids
  FROM suggestion_counts sc
  INNER JOIN profiles p ON p.id = sc.suggested_user_id
  ORDER BY sc.mutual_count DESC, p.display_name ASC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."rpc_get_friend_suggestions"("p_user_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_friends"() RETURNS TABLE("profile_id" "uuid", "username" "text", "display_name" "text", "avatar_url" "text", "verified" boolean, "friendship_created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_my_profile_id UUID;
BEGIN
  -- Get current user's profile
  SELECT user_id INTO v_my_profile_id
  FROM profiles
  WHERE user_id = auth.uid()
  LIMIT 1;

  -- Return empty if no profile (instead of error)
  IF v_my_profile_id IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    CASE
      WHEN f.user_id = v_my_profile_id THEN f.peer_user_id
      ELSE f.user_id
    END AS profile_id,
    CASE
      WHEN f.user_id = v_my_profile_id THEN p2.username
      ELSE p1.username
    END AS username,
    CASE
      WHEN f.user_id = v_my_profile_id THEN p2.display_name
      ELSE p1.display_name
    END AS display_name,
    CASE
      WHEN f.user_id = v_my_profile_id THEN p2.avatar_url
      ELSE p1.avatar_url
    END AS avatar_url,
    CASE
      WHEN f.user_id = v_my_profile_id THEN p2.verified
      ELSE p1.verified
    END AS verified,
    f.created_at AS friendship_created_at
  FROM friendships f
  LEFT JOIN profiles p1 ON p1.user_id = f.user_id
  LEFT JOIN profiles p2 ON p2.user_id = f.peer_user_id
  WHERE (f.user_id = v_my_profile_id OR f.peer_user_id = v_my_profile_id)
    AND f.status = 'accepted'
  ORDER BY f.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."rpc_get_friends"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_friends"("p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("user_id" "uuid", "display_name" "text", "avatar_url" "text", "username" "text", "verified" boolean, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID;
BEGIN
  -- Use provided user_id or current authenticated user
  v_user_id := COALESCE(p_user_id, auth.uid());
  
  -- Check if user is authenticated
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'User not authenticated';
  END IF;

  -- Get all accepted friendships where the user is involved
  -- and join with profiles to get friend information
  RETURN QUERY
  SELECT 
    p.user_id,
    p.display_name,
    p.avatar_url,
    p.username,
    COALESCE(p.verified, false) as verified,
    f.created_at
  FROM friendships f
  INNER JOIN profiles p ON (
    CASE 
      WHEN f.user_id = v_user_id THEN p.user_id = f.peer_user_id
      WHEN f.peer_user_id = v_user_id THEN p.user_id = f.user_id
      ELSE FALSE
    END
  )
  WHERE 
    (f.user_id = v_user_id OR f.peer_user_id = v_user_id)
    AND f.status = 'accepted'
  ORDER BY f.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."rpc_get_friends"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_friendship_status"("p_peer_profile_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_my_profile_id UUID;
  v_user_id UUID;
  v_peer_user_id UUID;
  v_status TEXT;
  v_requested_by UUID;
BEGIN
  -- Get current user's profile
  SELECT user_id INTO v_my_profile_id
  FROM profiles
  WHERE user_id = auth.uid()
  LIMIT 1;

  IF v_my_profile_id IS NULL THEN
    RETURN 'error';
  END IF;

  -- Check if blocked
  IF EXISTS (
    SELECT 1 FROM blocks
    WHERE (blocker_id = v_my_profile_id AND blocked_id = p_peer_profile_id)
       OR (blocker_id = p_peer_profile_id AND blocked_id = v_my_profile_id)
  ) THEN
    RETURN 'blocked';
  END IF;

  -- Determine canonical ordering
  IF v_my_profile_id < p_peer_profile_id THEN
    v_user_id := v_my_profile_id;
    v_peer_user_id := p_peer_profile_id;
  ELSE
    v_user_id := p_peer_profile_id;
    v_peer_user_id := v_my_profile_id;
  END IF;

  -- Check friendship
  SELECT f.status, f.requested_by INTO v_status, v_requested_by
  FROM friendships f
  WHERE f.user_id = v_user_id AND f.peer_user_id = v_peer_user_id;

  IF v_status IS NULL THEN
    RETURN 'none';
  END IF;

  IF v_status = 'accepted' THEN
    RETURN 'friends';
  END IF;

  IF v_status = 'pending' THEN
    IF v_requested_by = v_my_profile_id THEN
      RETURN 'pending_sent';
    ELSE
      RETURN 'pending_received';
    END IF;
  END IF;

  RETURN v_status;
END;
$$;


ALTER FUNCTION "public"."rpc_get_friendship_status"("p_peer_profile_id" "uuid") OWNER TO "postgres";


