    "user_id" "uuid" NOT NULL,
    "is_benched" boolean DEFAULT false NOT NULL,
    "benched_at" timestamp with time zone,
    "reason" "text",
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "bench_until" timestamp with time zone,
    "hide_in_feed" boolean DEFAULT true NOT NULL,
    "hide_in_search" boolean DEFAULT true NOT NULL,
    "block_friend_requests" boolean DEFAULT true NOT NULL,
    "suppress_social_notifications" boolean DEFAULT false NOT NULL
);


