COMMENT ON TABLE "public"."user_status" IS 'Tracks bench mode. When benched, hide community features but keep sports features active.';



COMMENT ON COLUMN "public"."user_status"."bench_until" IS 'If set, bench automatically ends at/after this time.';



COMMENT ON COLUMN "public"."user_status"."hide_in_feed" IS 'When benched, hide authored social content from feeds.';



COMMENT ON COLUMN "public"."user_status"."hide_in_search" IS 'When benched, exclude from people search & suggestions.';



COMMENT ON COLUMN "public"."user_status"."block_friend_requests" IS 'When benched, do not allow new vibe requests (friend requests).';



COMMENT ON COLUMN "public"."user_status"."suppress_social_notifications" IS 'When benched, suppress social-only pings; sports notifications still allowed.';



CREATE OR REPLACE FUNCTION "public"."rpc_get_my_status"() RETURNS "public"."user_status"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_row public.user_status;
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode='P0001';
  end if;

  -- create a default row if it doesn't exist
  insert into public.user_status (user_id, is_benched, benched_at, reason)
  values (v_uid, false, null, null)
  on conflict (user_id) do nothing;

  select * into v_row
  from public.user_status
  where user_id = v_uid;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."rpc_get_my_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_nearby_games"("p_lat" double precision, "p_lng" double precision, "p_radius_meters" integer DEFAULT 10000, "p_sport_id" "uuid" DEFAULT NULL::"uuid", "p_sort" "text" DEFAULT 'distance'::"text") RETURNS TABLE("id" "uuid", "title" "text", "sport_name" "text", "scheduled_at" timestamp with time zone, "status" "text", "venue_name" "text", "latitude" double precision, "longitude" double precision, "distance_meters" double precision, "player_count" integer, "spots_remaining" integer, "is_public" boolean, "min_skill" integer, "max_skill" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select
    g.id,
    coalesce(g.title, 'Untitled Game')    as title,
    s.name_en                              as sport_name,
    g.start_at                             as scheduled_at,
    case
      when g.is_cancelled         then 'cancelled'
      when now() >= g.end_at      then 'ended'
      when now() >= g.start_at    then 'live'
      else                             'upcoming'
    end                                    as status,
    ven.name_en                            as venue_name,
    st_y(gl.location::geometry)            as latitude,
    st_x(gl.location::geometry)            as longitude,
    st_distance(
      gl.location,
      st_setsrid(st_makepoint(p_lng, p_lat), 4326)::geography
    )                                      as distance_meters,
    coalesce(roster.cnt, 0)::int           as player_count,
    (g.capacity - coalesce(roster.cnt, 0))::int as spots_remaining,
    (g.listing_visibility = 'public')      as is_public,
    g.min_skill,
    g.max_skill
  from   games g
  join   geo_locations gl on g.geo_location_id = gl.id
  join   sports s         on s.id = g.sport_id
  left   join venue_spaces vs on vs.id = g.venue_space_id
  left   join venues ven      on ven.id = vs.venue_id
  left   join lateral (
    select count(*) as cnt
    from   game_roster gr
    where  gr.game_id = g.id
      and  gr.status  = 'active'
      and  gr.role    = 'player'
  ) roster on true
  where  g.is_cancelled = false
    and  g.start_at > now()
    and  st_dwithin(
           gl.location,
           st_setsrid(st_makepoint(p_lng, p_lat), 4326)::geography,
           p_radius_meters
         )
    and  (p_sport_id is null or g.sport_id = p_sport_id)
    and  (
           g.listing_visibility = 'public'
           or g.creator_user_id = auth.uid()
           or public.can_view_with_scope(
                auth.uid(), g.creator_user_id, g.listing_visibility, g.squad_id
              )
         )
  order  by
    case when p_sort = 'distance'
         then st_distance(
                gl.location,
                st_setsrid(st_makepoint(p_lng, p_lat), 4326)::geography
              )
    end asc nulls last,
    g.start_at asc
  limit 50;
$$;


ALTER FUNCTION "public"."rpc_get_nearby_games"("p_lat" double precision, "p_lng" double precision, "p_radius_meters" integer, "p_sport_id" "uuid", "p_sort" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_get_nearby_venues"("p_lat" double precision, "p_lng" double precision, "p_radius_meters" integer DEFAULT 10000, "p_sport_id" "uuid" DEFAULT NULL::"uuid", "p_sort" "text" DEFAULT 'distance'::"text") RETURNS TABLE("id" "uuid", "name_en" "text", "name_ar" "text", "city" "text", "area" "text", "is_indoor" boolean, "price_per_hour" numeric, "latitude" double precision, "longitude" double precision, "distance_meters" double precision, "sport_names" "text"[])
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    v.id,
    v.name_en,
    v.name_ar,
    a.city                          AS city,
    a.name                          AS area,
    bool_or(vs.indoor)              AS is_indoor,
    min(vs.price_per_hour)          AS price_per_hour,
    ST_Y(gl.location::geometry)     AS latitude,
    ST_X(gl.location::geometry)     AS longitude,
    ST_Distance(
      gl.location,
      ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography
    )                               AS distance_meters,
    COALESCE(
      array_agg(DISTINCT s.name_en) FILTER (WHERE s.name_en IS NOT NULL),
      '{}'::text[]
    )                               AS sport_names
  FROM   venues v
  JOIN   geo_locations gl ON v.geo_location_id = gl.id
  LEFT   JOIN areas a          ON v.area_id = a.id
  LEFT   JOIN venue_spaces vs  ON vs.venue_id = v.id
  LEFT   JOIN sports s         ON s.id = vs.sport_id
  WHERE  v.is_active = true
    AND  ST_DWithin(
           gl.location,
           ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography,
           p_radius_meters
         )
    AND  (p_sport_id IS NULL OR EXISTS (
           SELECT 1 FROM venue_spaces vs2
           WHERE  vs2.venue_id = v.id AND vs2.sport_id = p_sport_id
         ))
  GROUP  BY v.id, v.name_en, v.name_ar, a.city, a.name, gl.location
  ORDER  BY
    CASE WHEN p_sort = 'distance'
         THEN ST_Distance(
                gl.location,
                ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography
              )
    END ASC NULLS LAST,
    v.name_en ASC
  LIMIT 50;
$$;


ALTER FUNCTION "public"."rpc_get_nearby_venues"("p_lat" double precision, "p_lng" double precision, "p_radius_meters" integer, "p_sport_id" "uuid", "p_sort" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_hide_post"("p_post_id" "uuid") RETURNS "text"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  insert into public.post_hides(post_id, owner_user_id) values (p_post_id, auth.uid())
  on conflict do nothing;
  select 'hidden';
$$;


ALTER FUNCTION "public"."rpc_hide_post"("p_post_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_hide_user"("target_user" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare me uuid := auth.uid();
begin
  if me is null then raise exception using errcode='P0001', message='not_authenticated'; end if;
  perform public._assert_not_self(me, target_user);

  insert into public.restrictions(user_id, target_user_id, type)
  values (me, target_user, 'hidden')
  on conflict do nothing;

  return true;
end;
$$;


ALTER FUNCTION "public"."rpc_hide_user"("target_user" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_hide_user"("p_peer" "uuid", "p_hide" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  me uuid := auth.uid();
begin
  if me is null then
    raise exception using errcode='P0001', message='not_authenticated';
  end if;

  if p_hide then
    insert into public.restrictions(user_id, target_user_id, type)
    values (me, p_peer, 'hidden')
    on conflict (user_id, target_user_id, type) do nothing;
  else
    delete from public.restrictions
    where user_id = me and target_user_id = p_peer and type='hidden';
  end if;
end;
$$;


ALTER FUNCTION "public"."rpc_hide_user"("p_peer" "uuid", "p_hide" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_invite_user"("p_game_id" "uuid", "p_to_user_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE gid uuid;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.games g
    WHERE g.id = p_game_id
      AND (g.creator_user_id = auth.uid() OR public.is_admin(auth.uid()))
  ) THEN
    RAISE EXCEPTION USING errcode='P0001', message='not_host';
  END IF;

  INSERT INTO public.game_invites(game_id, to_user_id, invited_by_profile_id, status)
  VALUES (
    p_game_id,
    p_to_user_id,
    (SELECT id FROM public.profiles WHERE user_id = auth.uid() AND profile_type = 'organiser' LIMIT 1),
    'pending'
  )
  RETURNING id INTO gid;

  RETURN gid;
END$$;


ALTER FUNCTION "public"."rpc_invite_user"("p_game_id" "uuid", "p_to_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_is_following_user"("p_target_profile_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.profile_follows pf
    join public.profiles fp on fp.id = pf.follower_profile_id
    join public.profiles op on op.id = pf.following_profile_id
    where fp.user_id = auth.uid()
      and op.user_id = (
        select user_id from public.profiles where id = p_target_profile_id
      )
  );
$$;


ALTER FUNCTION "public"."rpc_is_following_user"("p_target_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_join_game"("p_actor_type" "text", "p_game_id" "uuid", "p_link_token" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("result" "text", "roster_status" "text", "waitlist_position" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  decision jsonb;
  pid uuid;
  uid uuid := auth.uid();
  g record;
  slots int;
BEGIN
  decision := public.can_current_user_join_game(p_game_id, p_actor_type, p_link_token);

  IF COALESCE((decision->>'allowed')::boolean, false) = false THEN
    RAISE EXCEPTION USING
      errcode = 'P0001',
      message = COALESCE(decision->>'cta', 'not_allowed'),
      detail  = COALESCE(decision->>'reason', '');
  END IF;

  pid := public.choose_actor(p_actor_type);

  IF (decision->>'cta') = 'join_with_link' THEN
    PERFORM public._consume_link_token(p_game_id, p_link_token);
  END IF;

  IF (decision->>'cta') = 'request' THEN
    INSERT INTO public.game_join_requests(game_id, from_profile_id, status)
    VALUES (p_game_id, pid, 'pending')
    ON CONFLICT DO NOTHING;
    result := 'request_submitted'; roster_status := NULL; waitlist_position := NULL; RETURN NEXT; RETURN;
  END IF;

  SELECT * INTO g FROM public.games WHERE id = p_game_id FOR UPDATE;
  slots := public.game_slots_left(p_game_id);

  IF slots > 0 THEN
    INSERT INTO public.game_roster(game_id, profile_id, role, status)
    VALUES (p_game_id, pid, 'player', 'active')
    ON CONFLICT (game_id, profile_id) DO UPDATE SET status='active', left_at=NULL;
    result := 'joined'; roster_status := 'active'; waitlist_position := NULL; RETURN NEXT; RETURN;
  ELSE
    INSERT INTO public.game_waitlist(game_id, profile_id, user_id, position)
    SELECT p_game_id, pid, uid,
           COALESCE((SELECT max(position)+1 FROM public.game_waitlist WHERE game_id = p_game_id), 1)
    ON CONFLICT DO NOTHING;
    waitlist_position := (SELECT position FROM public.game_waitlist WHERE game_id=p_game_id AND profile_id=pid);
    result := 'waitlisted'; roster_status := NULL; RETURN NEXT; RETURN;
  END IF;
END;
$$;


ALTER FUNCTION "public"."rpc_join_game"("p_actor_type" "text", "p_game_id" "uuid", "p_link_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_leave_game"("p_actor_type" "text", "p_game_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  pid uuid := public.choose_actor(p_actor_type);
  was_active boolean;
  w_profile uuid;
  upsert_ct int := 0;
BEGIN
  UPDATE public.game_roster
     SET status = 'left', left_at = now()
   WHERE game_id = p_game_id AND profile_id = pid AND status = 'active'
  RETURNING true INTO was_active;
  IF NOT was_active THEN RETURN 'not_on_roster'; END IF;
  SELECT wl.profile_id INTO w_profile
  FROM public.game_waitlist wl WHERE wl.game_id = p_game_id
  ORDER BY wl.position ASC LIMIT 1;
  IF w_profile IS NULL THEN RETURN 'left'; END IF;
  INSERT INTO public.game_roster (game_id, profile_id, role, status)
  VALUES (p_game_id, w_profile, 'player', 'active')
  ON CONFLICT (game_id, profile_id) DO UPDATE SET status='active', left_at=NULL;
  GET DIAGNOSTICS upsert_ct = ROW_COUNT;
  DELETE FROM public.game_waitlist WHERE game_id = p_game_id AND profile_id = w_profile;
  IF upsert_ct > 0 THEN RETURN 'left_promoted_waitlist'; ELSE RETURN 'left'; END IF;
END;
$$;


ALTER FUNCTION "public"."rpc_leave_game"("p_actor_type" "text", "p_game_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_mark_all_read"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare n int;
begin
  update public.notifications
  set is_read = true, read_at = now()
  where user_id = auth.uid() and is_read = false;
  get diagnostics n = row_count;
  return n;
end;
$$;


