CREATE OR REPLACE FUNCTION "public"."rpc_meetup_attendees"("p_meetup_id" "uuid", "p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("actor_profile_id" "uuid", "display_name" "text", "username" "public"."citext", "status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  me    uuid := auth.uid();
  owner uuid;
  vis   text;
begin
  -- load owner + scope
  select m.owner_user_id, m.visibility
    into owner, vis
  from public.meetups m
  where m.id = p_meetup_id;

  if owner is null then
    raise exception using errcode='P0001', message='meetup_not_found';
  end if;

  -- visibility gate (anon allowed if scope permits)
  if not public.can_view_with_scope3(me, owner, vis) then
    raise exception using errcode='P0001', message='not_allowed';
  end if;

  -- return list (after gate)
  return query
  select
    a.actor_profile_id,
    p.display_name,
    p.username,
    a.status
  from public.meetup_attendees a
  join public.profiles p on p.id = a.actor_profile_id
  where a.meetup_id = p_meetup_id
    and (p_status is null or a.status = p_status)
  order by a.updated_at desc nulls last, a.created_at desc
  limit p_limit offset p_offset;
end;
$$;


ALTER FUNCTION "public"."rpc_meetup_attendees"("p_meetup_id" "uuid", "p_status" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_meetup_cancel"("p_meetup_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not exists (select 1 from public.meetups m where m.id=p_meetup_id and (m.owner_user_id=auth.uid() or public.is_admin(auth.uid()))) then
    raise exception using errcode='P0001', message='not_host';
  end if;
  update public.meetups set is_cancelled = true where id = p_meetup_id and is_cancelled = false;
  perform public.emit_event('meetup.cancelled','meetup', p_meetup_id, auth.uid(), '{}');
  return 'ok';
end;
$$;


ALTER FUNCTION "public"."rpc_meetup_cancel"("p_meetup_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_meetup_card"("p_meetup_id" "uuid", "p_profile_type" "text" DEFAULT 'player'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  me          uuid := auth.uid();
  owner       uuid;
  vis         text;
  my_actor    uuid;
  g int; i int; d int;
  my_status_  text;
  result      jsonb;
begin
  -- load owner + scope
  select m.owner_user_id, m.visibility
    into owner, vis
  from public.meetups m
  where m.id = p_meetup_id;

  if owner is null then
    raise exception using errcode='P0001', message='meetup_not_found';
  end if;

  -- visibility gate
  if not public.can_view_with_scope3(me, owner, vis) then
    raise exception using errcode='P0001', message='not_allowed';
  end if;

  -- prefer the actual actor I used to RSVP; otherwise fall back to requested type
  if me is not null then
    select a.actor_profile_id
      into my_actor
    from public.meetup_attendees a
    where a.meetup_id = p_meetup_id
      and a.user_id = me
    limit 1;

    if my_actor is null then
      begin
        my_actor := public.assert_profile_exists_for_user(me, p_profile_type);
      exception when others then
        my_actor := null;
      end;
    end if;
  end if;

  -- counts & my_status via definer helpers (bypass RLS after gate)
  select going, interested, declined into g, i, d
  from public.meetup_counts(p_meetup_id);

  if my_actor is not null then
    my_status_ := public.meetup_my_status(p_meetup_id, my_actor);
  end if;

  -- assemble
  select jsonb_build_object(
           'id',               m.id,
           'title',            m.title,
           'start_at',         m.start_at,
           'visibility',       m.visibility,
           'owner_user_id',    m.owner_user_id,
           'owner_profile_id', m.owner_profile_id,
           'host', jsonb_build_object(
             'actor_profile_id', m.host_actor_id,
             'display_name',     hp.display_name,
             'username',         hp.username
           ),
           'counts', jsonb_build_object(
             'going',      coalesce(g,0),
             'interested', coalesce(i,0),
             'declined',   coalesce(d,0)
           ),
           'my_status', my_status_
         )
    into result
  from public.meetups m
  left join public.profiles hp on hp.id = m.host_actor_id
  where m.id = p_meetup_id;

  return result;
end;
$$;


ALTER FUNCTION "public"."rpc_meetup_card"("p_meetup_id" "uuid", "p_profile_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_meetup_create"("p_profile_type" "text", "p_title" "text", "p_starts_at" timestamp with time zone, "p_visibility" "text") RETURNS TABLE("id" "uuid", "title" "text", "starts_at" timestamp with time zone, "visibility" "text", "host_actor_id" "uuid", "owner_user_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  me  uuid := auth.uid();
  pid uuid;

  has_owner_profile_id boolean;
  has_start_at         boolean;
  has_starts_at        boolean;

  sql text;
begin
  if me is null then
    raise exception using errcode='P0001', message='not_authenticated';
  end if;

  if p_visibility not in ('public','circle','hidden') then
    raise exception using errcode='P0001', message='visibility_invalid';
  end if;

  pid := public.choose_actor(p_profile_type);
  if not public.actor_is_organiser(pid) then
    raise exception using errcode='P0001', message='actor_must_be_organiser';
  end if;

  -- Detect live shape
  select exists (select 1 from information_schema.columns where table_schema='public' and table_name='meetups' and column_name='owner_profile_id'),
         exists (select 1 from information_schema.columns where table_schema='public' and table_name='meetups' and column_name='start_at'),
         exists (select 1 from information_schema.columns where table_schema='public' and table_name='meetups' and column_name='starts_at')
  into has_owner_profile_id, has_start_at, has_starts_at;

  if not has_start_at and not has_starts_at then
    raise exception using errcode='P0001', message='meetups_missing_start_column';
  end if;

  -- Build INSERT that satisfies NOT NULLs. When both start_at & starts_at exist, set both.
  if has_owner_profile_id and has_start_at and has_starts_at then
    sql := '
      insert into public.meetups as m
        (owner_user_id, owner_profile_id, host_actor_id, title, start_at, starts_at, visibility)
      values ($1, $2, $2, $3, $4, $4, $5)
      returning m.id, m.title, m.starts_at, m.visibility, m.host_actor_id, m.owner_user_id';

  elsif has_owner_profile_id and has_start_at then
    sql := '
      insert into public.meetups as m
        (owner_user_id, owner_profile_id, host_actor_id, title, start_at, visibility)
      values ($1, $2, $2, $3, $4, $5)
      returning m.id, m.title, m.start_at, m.visibility, m.host_actor_id, m.owner_user_id';

  elsif has_owner_profile_id and has_starts_at then
    sql := '
      insert into public.meetups as m
        (owner_user_id, owner_profile_id, host_actor_id, title, starts_at, visibility)
      values ($1, $2, $2, $3, $4, $5)
      returning m.id, m.title, m.starts_at, m.visibility, m.host_actor_id, m.owner_user_id';

  elsif (not has_owner_profile_id) and has_start_at and has_starts_at then
    sql := '
      insert into public.meetups as m
        (owner_user_id, host_actor_id, title, start_at, starts_at, visibility)
      values ($1, $2, $3, $4, $4, $5)
      returning m.id, m.title, m.starts_at, m.visibility, m.host_actor_id, m.owner_user_id';

  elsif (not has_owner_profile_id) and has_start_at then
    sql := '
      insert into public.meetups as m
        (owner_user_id, host_actor_id, title, start_at, visibility)
      values ($1, $2, $3, $4, $5)
      returning m.id, m.title, m.start_at, m.visibility, m.host_actor_id, m.owner_user_id';

  else  -- no owner_profile_id, has starts_at
    sql := '
      insert into public.meetups as m
        (owner_user_id, host_actor_id, title, starts_at, visibility)
      values ($1, $2, $3, $4, $5)
      returning m.id, m.title, m.starts_at, m.visibility, m.host_actor_id, m.owner_user_id';
  end if;

  execute sql
    using me, pid, p_title, p_starts_at, p_visibility
    into id, title, starts_at, visibility, host_actor_id, owner_user_id;

  return next;
end;
$_$;


ALTER FUNCTION "public"."rpc_meetup_create"("p_profile_type" "text", "p_title" "text", "p_starts_at" timestamp with time zone, "p_visibility" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_meetup_create"("p_owner_profile_id" "uuid", "p_title" "text", "p_description" "text", "p_start_at" timestamp with time zone, "p_end_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_location_name" "text" DEFAULT NULL::"text", "p_lat" double precision DEFAULT NULL::double precision, "p_lng" double precision DEFAULT NULL::double precision, "p_listing_visibility" "text" DEFAULT 'public'::"text", "p_rsvp_policy" "text" DEFAULT 'open'::"text", "p_capacity" integer DEFAULT NULL::integer, "p_vibe_key" "text" DEFAULT NULL::"text", "p_meta" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare u uuid; ok boolean; mid uuid;
begin
  if auth.uid() is null then raise exception using errcode='P0001', message='auth_required'; end if;
  select user_id, ok into u, ok from public._profile_guard_organiser(p_owner_profile_id);
  if not ok or u is distinct from auth.uid() then
    raise exception using errcode='P0001', message='organiser_required';
  end if;

  insert into public.meetups(owner_profile_id, owner_user_id, title, description, start_at, end_at,
                             location_name, lat, lng, listing_visibility, rsvp_policy, capacity, vibe_key, meta)
  values (p_owner_profile_id, u, p_title, p_description, p_start_at, p_end_at,
          p_location_name, p_lat, p_lng, p_listing_visibility, p_rsvp_policy, p_capacity, p_vibe_key, p_meta)
  returning id into mid;

  perform public.emit_event('meetup.created','meetup', mid, u, jsonb_build_object('title', p_title));
  return mid;
end;
$$;


