CREATE OR REPLACE FUNCTION "public"."rpc_meetup_rsvp"("p_meetup_id" "uuid", "p_profile_type" "text" DEFAULT 'player'::"text", "p_status" "text" DEFAULT 'going'::"text") RETURNS TABLE("meetup_id" "uuid", "actor_profile_id" "uuid", "status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  pid uuid;
  owner uuid;
  vis  text;
begin
  if me is null then
    raise exception using errcode='P0001', message='not_authenticated';
  end if;

  if p_status not in ('going','interested','declined') then
    raise exception using errcode='P0001', message='rsvp_status_invalid';
  end if;

  pid := public.choose_actor(p_profile_type);
  if not public.actor_is_player(pid) then
    raise exception using errcode='P0001', message='actor_must_be_player';
  end if;

  select m.owner_user_id, m.visibility
  into owner, vis
  from public.meetups m
  where m.id = p_meetup_id;

  if owner is null then
    raise exception using errcode='P0001', message='meetup_not_found';
  end if;

  if not public.can_view_with_scope3(me, owner, vis) then
    raise exception using errcode='P0001', message='not_allowed';
  end if;

  insert into public.meetup_attendees as a (meetup_id, actor_profile_id, user_id, status)
  values (p_meetup_id, pid, me, p_status)
  on conflict on constraint meetup_attendees_pkey
  do update set status = excluded.status, updated_at = now()
  returning a.meetup_id, a.actor_profile_id, a.status
  into meetup_id, actor_profile_id, status;

  return next;
end;
$$;


ALTER FUNCTION "public"."rpc_meetup_rsvp"("p_meetup_id" "uuid", "p_profile_type" "text", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_meetup_rsvp"("p_meetup_id" "uuid", "p_action" "text", "p_profile_id" "uuid" DEFAULT NULL::"uuid", "p_link_token" "uuid" DEFAULT NULL::"uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  d jsonb;
  u uuid := auth.uid();
  slots int;
begin
  if u is null then raise exception using errcode='P0001', message='auth_required'; end if;

  d := public.can_current_user_rsvp_meetup(p_meetup_id, p_link_token);

  if coalesce((d->>'allowed')::boolean, false) = false then
    raise exception using errcode='P0001', message=coalesce(d->>'cta','not_allowed');
  end if;

  -- Accept invite path
  if p_action = 'accept_invite' then
    update public.meetup_invites
       set status='accepted'
     where meetup_id = p_meetup_id and to_user_id = u and status='pending';
  end if;

  -- Link consumption if needed
  if (d->>'cta') = 'rsvp_going' and (select rsvp_policy from public.meetups where id=p_meetup_id) = 'link' then
    perform public._meetup_link_consume(p_meetup_id, p_link_token);
  end if;

  -- Capacity check for 'going' (interested doesn't consume)
  if p_action in ('going','accept_invite') then
    select public.meetup_slots_left(p_meetup_id) into slots;
    if slots = 0 then
      -- mark as interested instead of failing hard
      insert into public.meetup_rsvps(meetup_id, user_id, profile_id, status)
      values (p_meetup_id, u, p_profile_id, 'interested')
      on conflict (meetup_id, user_id) do update set status='interested', profile_id=excluded.profile_id, updated_at=now();
      perform public.emit_event('meetup.waitlisted','meetup', p_meetup_id, u, jsonb_build_object('reason','full'));
      return 'interested';
    end if;
  end if;

  -- Apply action
  if p_action = 'going' or p_action = 'accept_invite' then
    insert into public.meetup_rsvps(meetup_id, user_id, profile_id, status)
    values (p_meetup_id, u, p_profile_id, 'going')
    on conflict (meetup_id, user_id) do update set status='going', profile_id=excluded.profile_id, updated_at=now();
    perform public.emit_event('meetup.rsvp_going','meetup', p_meetup_id, u, jsonb_build_object('profile_id', p_profile_id));
    return 'going';

  elsif p_action = 'interested' then
    insert into public.meetup_rsvps(meetup_id, user_id, profile_id, status)
    values (p_meetup_id, u, p_profile_id, 'interested')
    on conflict (meetup_id, user_id) do update set status='interested', profile_id=excluded.profile_id, updated_at=now();
    perform public.emit_event('meetup.rsvp_interested','meetup', p_meetup_id, u, jsonb_build_object('profile_id', p_profile_id));
    return 'interested';

  elsif p_action = 'cancel' then
    update public.meetup_rsvps set status='cancelled', updated_at=now()
    where meetup_id = p_meetup_id and user_id = u and status in ('going','interested','pending');
    perform public.emit_event('meetup.rsvp_cancelled','meetup', p_meetup_id, u, jsonb_build_object('profile_id', p_profile_id));
    return 'cancelled';

  elsif p_action = 'request' then
    -- translate to pending; owner may approve later (future)
    insert into public.meetup_rsvps(meetup_id, user_id, profile_id, status)
    values (p_meetup_id, u, p_profile_id, 'pending')
    on conflict (meetup_id, user_id) do update set status='pending', profile_id=excluded.profile_id, updated_at=now();
    perform public.emit_event('meetup.rsvp_requested','meetup', p_meetup_id, u, jsonb_build_object('profile_id', p_profile_id));
    return 'pending';

  else
    raise exception using errcode='P0001', message='invalid_action';
  end if;
end;
$$;


ALTER FUNCTION "public"."rpc_meetup_rsvp"("p_meetup_id" "uuid", "p_action" "text", "p_profile_id" "uuid", "p_link_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_meetup_set_attendee"("p_meetup_id" "uuid", "p_target_actor" "uuid", "p_status" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  owner uuid;
begin
  if me is null then raise exception using errcode='P0001', message='not_authenticated'; end if;
  if p_status not in ('going','interested','declined') then
    raise exception using errcode='P0001', message='rsvp_status_invalid';
  end if;

  select m.owner_user_id into owner from public.meetups m where m.id = p_meetup_id;
  if owner is null then raise exception using errcode='P0001', message='meetup_not_found'; end if;
  if not public.can_write_row(owner) then
    raise exception using errcode='P0001', message='not_meetup_owner';
  end if;

  insert into public.meetup_attendees(meetup_id, actor_profile_id, user_id, status)
  select p_meetup_id, p_target_actor, p.user_id, p_status
  from public.profiles p
  where p.id = p_target_actor
  on conflict (meetup_id, actor_profile_id)
  do update set status = excluded.status, updated_at = now();
end;
$$;


ALTER FUNCTION "public"."rpc_meetup_set_attendee"("p_meetup_id" "uuid", "p_target_actor" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_meetup_unrsvp"("p_meetup_id" "uuid", "p_profile_type" "text" DEFAULT 'player'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  pid uuid;
begin
  if me is null then
    raise exception using errcode='P0001', message='not_authenticated';
  end if;
  pid := public.choose_actor(p_profile_type);
  if not public.actor_is_player(pid) then
    raise exception using errcode='P0001', message='actor_must_be_player';
  end if;

  delete from public.meetup_attendees
  where meetup_id = p_meetup_id
    and actor_profile_id = pid
    and user_id = me;
end;
$$;


ALTER FUNCTION "public"."rpc_meetup_unrsvp"("p_meetup_id" "uuid", "p_profile_type" "text") OWNER TO "postgres";


