CREATE OR REPLACE FUNCTION "public"."rpc_mint_join_link"("p_game_id" "uuid", "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_max_uses" integer DEFAULT NULL::integer) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE t uuid;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.games g
    WHERE g.id = p_game_id
      AND (g.creator_user_id = auth.uid() OR public.is_admin(auth.uid()))
  ) THEN
    RAISE EXCEPTION USING errcode='P0001', message='not_host';
  END IF;

  t := gen_random_uuid();

  INSERT INTO public.game_link_tokens(game_id, token, created_by, expires_at, max_uses)
  VALUES (p_game_id, t, auth.uid(), p_expires_at, p_max_uses);

  RETURN t;
END;
$$;


ALTER FUNCTION "public"."rpc_mint_join_link"("p_game_id" "uuid", "p_expires_at" timestamp with time zone, "p_max_uses" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_moderation_resolve_ticket"("p_ticket_id" "uuid", "p_action" "text", "p_notes" "text" DEFAULT NULL::"text", "p_freeze_scope" "text" DEFAULT NULL::"text", "p_freeze_days" integer DEFAULT NULL::integer) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare t public.moderation_tickets%rowtype;
        target_user uuid;
        until_ts timestamptz;
begin
  if not public.is_admin(auth.uid()) then raise exception using errcode='P0001', message='admin_only'; end if;
  select * into t from public.moderation_tickets where id=p_ticket_id;
  if not found then raise exception using errcode='P0001', message='ticket_not_found'; end if;

  if t.target_kind='post' then
    if p_action='hide' then update public.posts set is_hidden_admin=true where id=t.target_id;
    elsif p_action='unhide' then update public.posts set is_hidden_admin=false where id=t.target_id;
    elsif p_action='delete' then update public.posts set is_deleted=true where id=t.target_id;
    end if;
  elsif t.target_kind='comment' then
    if p_action='hide' then update public.post_comments set is_hidden_admin=true where id=t.target_id;
    elsif p_action='unhide' then update public.post_comments set is_hidden_admin=false where id=t.target_id;
    elsif p_action='delete' then update public.post_comments set is_deleted=true where id=t.target_id;
    end if;
  end if;

  if p_action='freeze' then
    if t.target_kind='post' then
      select author_user_id into target_user from public.posts where id=t.target_id;
    elsif t.target_kind='comment' then
      select author_user_id into target_user from public.post_comments where id=t.target_id;
    end if;
    until_ts := case when p_freeze_days is null then null else now() + (p_freeze_days||' days')::interval end;
    insert into public.user_freezes(user_id, scope, reason, created_by, until, is_active)
    values (target_user, coalesce(p_freeze_scope,'all'), left(coalesce(p_notes,'moderation freeze'),280), auth.uid(), until_ts, true);
  end if;

  update public.moderation_tickets set status =
    case when p_action='dismiss' then 'dismissed' else 'resolved' end,
    updated_at = now()
  where id = p_ticket_id;

  insert into public.moderation_actions(target_kind,target_id,action,actor_user_id,notes)
  values (t.target_kind, t.target_id, p_action, auth.uid(), left(p_notes, 500));

  return 'resolved';
end; $$;


ALTER FUNCTION "public"."rpc_moderation_resolve_ticket"("p_ticket_id" "uuid", "p_action" "text", "p_notes" "text", "p_freeze_scope" "text", "p_freeze_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_moderation_take_ticket"("p_ticket_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.is_admin(auth.uid()) then raise exception using errcode='P0001', message='admin_only'; end if;
  update public.moderation_tickets
     set status='reviewing', assigned_to=auth.uid()
   where id=p_ticket_id and status='open';
  if not found then return 'no_change'; end if;
  return 'taken';
end; $$;


ALTER FUNCTION "public"."rpc_moderation_take_ticket"("p_ticket_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_my_venue_permissions"("p_venue_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
declare
  v_user_id uuid;
  v_claims jsonb;
begin
  -- Extract JWT safely
  v_claims := nullif(current_setting('request.jwt.claims', true), '')::jsonb;
  v_user_id := (v_claims ->> 'sub')::uuid;

  if v_user_id is null then
    return jsonb_build_object(
      'can_manage', false,
      'can_edit_details', false,
      'can_view_bookings', false,
      'can_create_booking', false,
      'can_manage_members', false
    );
  end if;

  return jsonb_build_object(
    'can_manage',
      public.can_manage_venue(v_user_id, p_venue_id),

    'can_edit_details',
      public.can_edit_venue_details(v_user_id, p_venue_id),

    'can_view_bookings',
      public.can_view_venue_bookings(v_user_id, p_venue_id),

    'can_create_booking',
      public.can_create_venue_booking(v_user_id, p_venue_id),

    'can_manage_members',
      public.can_manage_venue_members(v_user_id, p_venue_id)
  );
end;
$$;


ALTER FUNCTION "public"."rpc_my_venue_permissions"("p_venue_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_nearby_users"("p_lat" double precision, "p_lng" double precision, "p_delta" double precision DEFAULT 0.05, "p_limit" integer DEFAULT 20) RETURNS TABLE("profile_id" "uuid", "username" "text", "display_name" "text", "avatar_url" "text", "latitude" double precision, "longitude" double precision)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
SELECT p.id, p.username, p.display_name, p.avatar_url, p.latitude, p.longitude
FROM public.profiles p
WHERE p.latitude IS NOT NULL AND p.longitude IS NOT NULL
AND p.latitude BETWEEN (p_lat - p_delta) AND (p_lat + p_delta)
AND p.longitude BETWEEN (p_lng - p_delta) AND (p_lng + p_delta)
ORDER BY p.last_location_updated_at DESC NULLS LAST
LIMIT p_limit;
$$;


ALTER FUNCTION "public"."rpc_nearby_users"("p_lat" double precision, "p_lng" double precision, "p_delta" double precision, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_notification_clicked"("p_notification_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_kind text;
    v_user uuid;
BEGIN

    -- Update notification
    UPDATE public.notifications
    SET clicked_at = now(),
        interaction_count = interaction_count + 1,
        is_read = true,
        read_at = now()
    WHERE id = p_notification_id
      AND to_user_id = auth.uid()
    RETURNING kind_key, to_user_id
    INTO v_kind, v_user;

    IF NOT FOUND THEN
        RETURN 'not_found';
    END IF;

    -- Adaptive engagement learning
    INSERT INTO public.notification_user_preferences
    (user_id, kind_key, engagement_score)
    VALUES
    (v_user, v_kind, 1.1)
    ON CONFLICT (user_id, kind_key)
    DO UPDATE
    SET engagement_score =
        notification_user_preferences.engagement_score + 0.1;

    RETURN 'ok';

END;
$$;


ALTER FUNCTION "public"."rpc_notification_clicked"("p_notification_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_onboard_profile"("p_user_id" "uuid", "p_display_name" "text", "p_username" "text", "p_age" integer, "p_gender" "text", "p_persona_type" "text", "p_preferred_sport" "uuid" DEFAULT NULL::"uuid", "p_interests" "uuid"[] DEFAULT NULL::"uuid"[], "p_country" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_profile_id uuid; v_profile_type text; v_persona_type text; v_tier_code text;
BEGIN
  IF auth.uid() IS NULL OR auth.uid() != p_user_id THEN
    RAISE EXCEPTION 'Access denied: can only onboard your own profile';
  END IF;

  v_persona_type := CASE p_persona_type WHEN 'hoster' THEN 'host' ELSE p_persona_type END;
  v_profile_type := CASE v_persona_type
    WHEN 'player' THEN 'personal' WHEN 'organiser' THEN 'business'
    WHEN 'host' THEN 'venue' WHEN 'socialiser' THEN 'personal' ELSE 'personal' END;
  SELECT id INTO v_profile_id FROM public.profiles WHERE user_id = p_user_id LIMIT 1;
  IF v_profile_id IS NOT NULL THEN
    UPDATE public.profiles SET
      display_name = p_display_name, username = p_username, age = p_age,
      gender = lower(p_gender), persona_type = v_persona_type,
      preferred_sport = p_preferred_sport, primary_sport = p_preferred_sport,
      interests = p_interests, country = p_country, city = p_city,
      skill_level = 1, onboard = true
    WHERE id = v_profile_id;
  ELSE
    INSERT INTO public.profiles (
      user_id, display_name, username, age, gender,
      profile_type, persona_type, intention,
      preferred_sport, primary_sport, interests,
      country, city, skill_level, onboard, is_player, is_active
    ) VALUES (
      p_user_id, p_display_name, p_username, p_age, lower(p_gender),
      v_profile_type, v_persona_type, v_persona_type,
      p_preferred_sport, p_preferred_sport, p_interests,
      p_country, p_city, 1, true, (v_persona_type = 'player'), true
    ) RETURNING id INTO v_profile_id;
  END IF;
  SELECT code INTO v_tier_code FROM public.tiers WHERE is_default = true LIMIT 1;
  IF v_tier_code IS NOT NULL THEN
    INSERT INTO public.profile_tiers (profile_id, tier_code, is_active)
    VALUES (v_profile_id, v_tier_code, true)
    ON CONFLICT DO NOTHING;
  END IF;
  RETURN v_profile_id;
END;
$$;


ALTER FUNCTION "public"."rpc_onboard_profile"("p_user_id" "uuid", "p_display_name" "text", "p_username" "text", "p_age" integer, "p_gender" "text", "p_persona_type" "text", "p_preferred_sport" "uuid", "p_interests" "uuid"[], "p_country" "text", "p_city" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_post_as"("p_profile_type" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  pid uuid;
  can_post boolean;
begin
  if me is null then
    raise exception 'not_authenticated' using errcode='P0001';
  end if;

  pid := public.choose_actor(p_profile_type);
  can_post := public.actor_can(pid, 'post');
  if not can_post then
    raise exception using errcode = 'P0001', message = 'actor_not_allowed';
  end if;

  return jsonb_build_object(
    'actor_profile_id', pid,
    'actor_type', (select profile_type from public.profiles where id = pid),
    'payload', p_payload
  );
end;
$$;


ALTER FUNCTION "public"."rpc_post_as"("p_profile_type" "text", "p_payload" "jsonb") OWNER TO "postgres";


