ALTER FUNCTION "public"."rpc_potential_vibes"("p_sport" "text", "p_as_role" "text", "p_lat" double precision, "p_lng" double precision, "p_radius_km" numeric, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_potential_vibes"("p_sport" "text", "p_as_role" "text", "p_lat" double precision, "p_lng" double precision, "p_radius_km" numeric, "p_limit" integer, "p_me" "uuid") RETURNS TABLE("user_id" "uuid", "role" "text", "sport_key" "text", "username" "text", "display_name" "text", "score" numeric, "reasons" "jsonb")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    spw.user_id,
    spw.profile_type         AS role,
    spw.sport_key,
    spw.profile_username     AS username,
    spw.profile_display_name AS display_name,
    1.0::numeric             AS score,   -- stub score for now
    jsonb_build_object(
      'source', 'stub',
      'reason', 'v_sport_profiles_with_user'
    )                         AS reasons
  FROM public.v_sport_profiles_with_user spw
  WHERE
    -- filter by sport if provided
    (p_sport IS NULL OR spw.sport_key = p_sport)
    -- don’t recommend yourself
    AND spw.user_id <> p_me
    -- later: role filter if you want it
    -- AND (p_as_role IS NULL OR spw.profile_type = p_as_role)
  ORDER BY score DESC
  LIMIT COALESCE(p_limit, 20);
$$;


ALTER FUNCTION "public"."rpc_potential_vibes"("p_sport" "text", "p_as_role" "text", "p_lat" double precision, "p_lng" double precision, "p_radius_km" numeric, "p_limit" integer, "p_me" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_potential_vibes_debug"("p_me" "uuid", "p_sport" "text" DEFAULT NULL::"text", "p_as_role" "text" DEFAULT 'player'::"text", "p_lat" double precision DEFAULT NULL::double precision, "p_lng" double precision DEFAULT NULL::double precision, "p_radius_km" numeric DEFAULT NULL::numeric, "p_limit" integer DEFAULT 20) RETURNS TABLE("user_id" "uuid", "role" "text", "sport_key" "text", "username" "text", "display_name" "text", "score" numeric, "reasons" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  me uuid := p_me;
  cfg_rec record;
  max_km numeric;
begin
  if me is null then
    raise exception using errcode='P0001', message='me_required';
  end if;

  select * into cfg_rec from public.vibes_reco_config where id = true;
  max_km := coalesce(p_radius_km, cfg_rec.max_km);

  return query
  with base as (
    select *
    from public.v_vibes_candidates c
    where (p_sport is null or c.sport_key = p_sport)
      and c.you_user_id = me
      and c.other_user_id <> me
  ),
  features as (
    select
      b.other_user_id as candidate_user_id,
      b.other_role    as role,
      b.sport_key,
      b.username,
      b.display_name,
      public._clamp01( ln(1 + public._mutuals_count(me, b.other_user_id)) / ln(1+10) )                                   as f_mutuals,
      case
        when p_lat is null or p_lng is null or b.geo_lat is null or b.geo_lng is null
          then 0.5
        else public._clamp01(1.0 - least(max_km, public._km_between(p_lat,p_lng,b.geo_lat,b.geo_lng)) / max_km)
      end                                                                                                                  as f_locality,
      case
        when b.sport_key is null then 0.5
        when to_regclass('public.sport_profiles') is null then 0.5
        else public._skill_proximity(
               (select spm.skill_level
                from public.sport_profiles spm
                where spm.user_id = me and spm.sport_key = b.sport_key
                limit 1),
               b.skill_level
             )
      end                                                                                                                  as f_skill,
      public._clamp01( coalesce((select composite_score from public.v_user_reputation v where v.user_id=b.other_user_id)/5.0, 0.7) )
                                                                                                                           as f_quality,
      public._recent_activity_score(b.other_user_id, cfg_rec.recent_days)                                                  as f_activity,
      case
        when lower(p_as_role)='player'    and b.other_role='organiser' then cfg_rec.boost_org
        when lower(p_as_role)='player'    and b.other_role='player'    then cfg_rec.boost_player
        when lower(p_as_role)='organiser' and b.other_role='player'    then cfg_rec.boost_player
        when lower(p_as_role)='organiser' and b.other_role='organiser' then 0.0
        else 0.0
      end                                                                                                                  as f_roleboost
    from base b
  )
  select
    f.candidate_user_id                as user_id,
    (f.role)::text                     as role,
    f.sport_key                        as sport_key,
    (f.username)::text                 as username,
    (f.display_name)::text             as display_name,
    round((
      vc.w_mutuals * f.f_mutuals
    + vc.w_locality* f.f_locality
    + vc.w_skill   * f.f_skill
    + vc.w_quality * f.f_quality
    + vc.w_activity* f.f_activity
    + f.f_roleboost
    )::numeric, 4)                     as score,
    jsonb_build_object(
      'mutuals',    f.f_mutuals,
      'locality',   f.f_locality,
      'skill',      f.f_skill,
      'quality',    f.f_quality,
      'activity',   f.f_activity,
      'role_boost', f.f_roleboost
    )                                   as reasons
  from features f
  cross join public.vibes_reco_config vc
  where vc.id = true
  order by score desc, f.username nulls last
  limit greatest(1, coalesce(p_limit,20));

end;
$$;


ALTER FUNCTION "public"."rpc_potential_vibes_debug"("p_me" "uuid", "p_sport" "text", "p_as_role" "text", "p_lat" double precision, "p_lng" double precision, "p_radius_km" numeric, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_profile_search"("p_q" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_language" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "username" "public"."citext", "display_name" "text", "profile_type" "text", "avatar_url" "text", "city" "text", "country" "text", "language" "text", "verified" boolean, "rank" numeric)
    LANGUAGE "sql"
    SET "search_path" TO 'public'
    AS $$
  with base as (
    select
      p.id, p.username, p.display_name, p.profile_type,
      p.avatar_url, p.city, p.country, p.language, p.verified,
      -- similarity score (works even if p_q is null; coalesce to '')
      greatest(
        similarity(p.display_name, coalesce(p_q,'')),
        similarity(coalesce(p.username::text,''), coalesce(p_q,''))
      ) as s
    from public.profiles p
    where
      p.is_active = true
      and not public.fn_is_benched(p.user_id)
      and (p_city is null or p.city ilike p_city)
      and (p_language is null or p.language = p_language)
      and (
        p_q is null
        or p.display_name ilike '%' || p_q || '%'
        or p.username::text ilike '%' || p_q || '%'
      )
  )
  select
    id, username, display_name, profile_type,
    avatar_url, city, country, language, verified,
    s as rank
  from base
  order by
    case when p_q is null then 0 else (s) end desc,
    display_name asc
  limit greatest(p_limit, 1)
  offset greatest(p_offset, 0)
$$;


ALTER FUNCTION "public"."rpc_profile_search"("p_q" "text", "p_city" "text", "p_language" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_profile_update_basic"("p_profile_type" "text", "p_display_name" "text" DEFAULT NULL::"text", "p_avatar_url" "text" DEFAULT NULL::"text", "p_bio" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_language" "text" DEFAULT NULL::"text") RETURNS TABLE("profile_id" "uuid", "profile_type" "text", "username" "public"."citext", "display_name" "text", "avatar_url" "text", "bio" "text", "city" "text", "country" "text", "language" "text", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  pid uuid;
  new_display_name_norm text;
begin
  if p_profile_type not in ('player','organiser') then
    raise exception using errcode = 'P0001', message = 'profile_type_invalid';
  end if;

  select id into pid
  from public.profiles
  where user_id = me and profile_type = p_profile_type
  limit 1;

  if pid is null then
    raise exception using errcode = 'P0001', message = 'profile_missing';
  end if;

  if p_display_name is not null then
    if public.is_display_name_banned(p_display_name) then
      raise exception using errcode = 'P0001', message = 'display_name_banned';
    end if;

    new_display_name_norm := public.normalize_display_name(p_display_name);

    if public.display_name_conflicts_username(p_display_name, (select username from public.profiles where id = pid)) then
      raise exception using errcode = 'P0001', message = 'display_name_conflicts_username';
    end if;

    if exists (
      select 1 from public.profiles
      where display_name_norm = new_display_name_norm
        and id <> pid
    ) then
      raise exception using errcode = 'P0001', message = 'display_name_taken';
    end if;
  end if;

  update public.profiles
  set display_name = coalesce(p_display_name, display_name),
      avatar_url   = coalesce(p_avatar_url, avatar_url),
      bio          = coalesce(p_bio, bio),
      city         = coalesce(p_city, city),
      language     = coalesce(p_language, language)
  where id = pid
  returning id, profile_type, username, display_name, avatar_url, bio, city, country, language, updated_at
  into profile_id, profile_type, username, display_name, avatar_url, bio, city, country, language, updated_at;

  return next;
end;
$$;


ALTER FUNCTION "public"."rpc_profile_update_basic"("p_profile_type" "text", "p_display_name" "text", "p_avatar_url" "text", "p_bio" "text", "p_city" "text", "p_language" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rpc_profile_update_basic"("p_profile_type" "text", "p_display_name" "text", "p_avatar_url" "text", "p_bio" "text", "p_city" "text", "p_language" "text") IS 'Owner-only update of profile fields; validates display_name (global unique) and non-equality with username.';



CREATE OR REPLACE FUNCTION "public"."rpc_rate_game"("p_game_id" "uuid", "p_rater_profile_id" "uuid", "p_scores" "jsonb", "p_comment" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  g record;
  prof record;
  r_user uuid;
  d record; v numeric;
begin
  if auth.uid() is null then raise exception using errcode='P0001', message='auth_required'; end if;

  select id, end_at, is_cancelled into g from public.games where id=p_game_id;
  if not found or g.is_cancelled then raise exception using errcode='P0001', message='game_not_ratable'; end if;
  if now() > g.end_at + interval '7 days' then raise exception using errcode='P0001', message='rating_window_closed'; end if;

  select id, user_id, profile_type into prof from public.profiles where id=p_rater_profile_id;
  if not found or prof.user_id <> auth.uid() then raise exception using errcode='P0001', message='not_profile_owner'; end if;
  if prof.profile_type <> 'player' then raise exception using errcode='P0001', message='organiser_cannot_rate_game'; end if;
  r_user := prof.user_id;

  if not public._user_played_in_game(r_user, p_game_id) then
    raise exception using errcode='P0001', message='rater_not_in_game';
  end if;

  if exists (select 1 from public.game_rating_events where game_id=p_game_id and rater_user_id=r_user) then
    raise exception using errcode='P0001', message='already_rated';
  end if;

  if p_scores is null or jsonb_typeof(p_scores) <> 'object' then
    raise exception using errcode='P0001', message='invalid_scores';
  end if;

  for d in select key from public.game_rating_dimensions where is_active loop
    if p_scores ? d.key then
      v := (p_scores ->> d.key)::numeric;
      if v is null then raise exception using errcode='P0001', message='score_not_numeric'; end if;
      if v < 0 or v > 5 then raise exception using errcode='P0001', message='score_out_of_range'; end if;
    end if;
  end loop;

  insert into public.game_rating_events(game_id, rater_user_id, rater_profile_id, scores, comment)
  values (p_game_id, r_user, p_rater_profile_id, p_scores, left(p_comment, 280));

  perform public.game_rating_recompute(p_game_id);

  return 'ok';
end;
$$;


ALTER FUNCTION "public"."rpc_rate_game"("p_game_id" "uuid", "p_rater_profile_id" "uuid", "p_scores" "jsonb", "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_rate_user"("p_game_id" "uuid", "p_rater_profile_id" "uuid", "p_ratee_user_id" "uuid", "p_scores" "jsonb", "p_comment" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  g              record;
  rater_user     uuid;
  rprof          record;
  ratee_is_host  boolean;
  window_ok      boolean;
  d              record;
  k text; v numeric;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION USING errcode='P0001', message='auth_required'; END IF;

  SELECT id, creator_user_id, start_at, end_at, is_cancelled INTO g FROM public.games WHERE id = p_game_id;
  IF NOT FOUND OR g.is_cancelled THEN RAISE EXCEPTION USING errcode='P0001', message='game_not_ratable'; END IF;

  window_ok := (now() <= g.end_at + interval '7 days');
  IF NOT window_ok THEN RAISE EXCEPTION USING errcode='P0001', message='rating_window_closed'; END IF;

  SELECT id, user_id, profile_type INTO rprof FROM public.profiles WHERE id = p_rater_profile_id;
  IF NOT FOUND OR rprof.user_id <> auth.uid() THEN
    RAISE EXCEPTION USING errcode='P0001', message='not_profile_owner';
  END IF;
  IF rprof.profile_type <> 'player' THEN
    RAISE EXCEPTION USING errcode='P0001', message='organiser_cannot_rate_user';
  END IF;

  rater_user := rprof.user_id;

  IF NOT EXISTS (SELECT 1 FROM public.game_roster WHERE game_id = p_game_id AND user_id = rater_user AND status = 'active') THEN
    RAISE EXCEPTION USING errcode='P0001', message='rater_not_in_game';
  END IF;

  ratee_is_host := (p_ratee_user_id = g.creator_user_id);
  IF NOT ratee_is_host AND NOT EXISTS (
    SELECT 1 FROM public.game_roster WHERE game_id = p_game_id AND user_id = p_ratee_user_id AND status = 'active'
  ) THEN RAISE EXCEPTION USING errcode='P0001', message='ratee_not_in_game'; END IF;

  IF p_ratee_user_id = rater_user THEN
    RAISE EXCEPTION USING errcode='P0001', message='cannot_rate_self';
  END IF;

  IF EXISTS (SELECT 1 FROM public.user_reputation_events WHERE game_id = p_game_id AND rater_user_id = rater_user AND ratee_user_id = p_ratee_user_id) THEN
    RAISE EXCEPTION USING errcode='P0001', message='already_rated';
  END IF;

  IF p_scores IS NULL OR jsonb_typeof(p_scores) <> 'object' THEN
    RAISE EXCEPTION USING errcode='P0001', message='invalid_scores';
  END IF;

  FOR d IN
    SELECT key FROM public.reputation_dimensions
    WHERE is_active = true
      AND (
        (ratee_is_host     AND 'rate_organiser' = ANY(applicable_to)) OR
        (NOT ratee_is_host AND 'rate_player'    = ANY(applicable_to))
      )
  LOOP
    k := d.key;
    IF p_scores ? k THEN
      v := (p_scores ->> k)::numeric;
      IF v IS NULL THEN RAISE EXCEPTION USING errcode='P0001', message='score_not_numeric'; END IF;
      IF v < 0 OR v > 5 THEN RAISE EXCEPTION USING errcode='P0001', message='score_out_of_range'; END IF;
    END IF;
  END LOOP;

  INSERT INTO public.user_reputation_events(game_id, rater_user_id, rater_profile_id, ratee_user_id, scores, comment)
  VALUES (p_game_id, rater_user, p_rater_profile_id, p_ratee_user_id, p_scores, LEFT(p_comment, 280));

  PERFORM public.reputation_recompute(p_ratee_user_id);
  RETURN 'ok';
END;
$$;


ALTER FUNCTION "public"."rpc_rate_user"("p_game_id" "uuid", "p_rater_profile_id" "uuid", "p_ratee_user_id" "uuid", "p_scores" "jsonb", "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_rate_venue"("p_game_id" "uuid", "p_venue_id" "uuid", "p_rater_profile_id" "uuid", "p_scores" "jsonb", "p_comment" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  g      record;
  prof   record;
  r_user uuid;
  d record; v numeric;
  tied boolean;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION USING errcode='P0001', message='auth_required'; END IF;

  SELECT id, creator_user_id, end_at, is_cancelled INTO g FROM public.games WHERE id = p_game_id;
  IF NOT FOUND OR g.is_cancelled THEN RAISE EXCEPTION USING errcode='P0001', message='game_not_ratable'; END IF;

  IF NOT public._game_belongs_to_venue(p_game_id, p_venue_id) THEN
    RAISE EXCEPTION USING errcode='P0001', message='venue_mismatch';
  END IF;
  IF now() > g.end_at + interval '7 days' THEN
    RAISE EXCEPTION USING errcode='P0001', message='rating_window_closed';
  END IF;

  SELECT id, user_id, profile_type INTO prof FROM public.profiles WHERE id = p_rater_profile_id;
  IF NOT FOUND OR prof.user_id <> auth.uid() THEN
    RAISE EXCEPTION USING errcode='P0001', message='not_profile_owner';
  END IF;
  r_user := prof.user_id;

  IF prof.profile_type = 'player' THEN
    tied := public._user_played_in_game(r_user, p_game_id);
  ELSE
    tied := public._user_hosted_game(r_user, p_game_id);
  END IF;
  IF NOT tied THEN RAISE EXCEPTION USING errcode='P0001', message='rater_not_tied_to_game'; END IF;

  IF EXISTS (SELECT 1 FROM public.venue_rating_events WHERE game_id = p_game_id AND venue_id = p_venue_id AND rater_user_id = r_user) THEN
    RAISE EXCEPTION USING errcode='P0001', message='already_rated';
  END IF;

  IF p_scores IS NULL OR jsonb_typeof(p_scores) <> 'object' THEN
    RAISE EXCEPTION USING errcode='P0001', message='invalid_scores';
  END IF;

  FOR d IN SELECT key FROM public.venue_rating_dimensions WHERE is_active LOOP
    IF p_scores ? d.key THEN
      v := (p_scores ->> d.key)::numeric;
      IF v IS NULL THEN RAISE EXCEPTION USING errcode='P0001', message='score_not_numeric'; END IF;
      IF v < 0 OR v > 5 THEN RAISE EXCEPTION USING errcode='P0001', message='score_out_of_range'; END IF;
    END IF;
  END LOOP;

  INSERT INTO public.venue_rating_events(game_id, venue_id, rater_user_id, rater_profile_id, scores, comment)
  VALUES (p_game_id, p_venue_id, r_user, p_rater_profile_id, p_scores, LEFT(p_comment, 280));

  PERFORM public.venue_rating_recompute(p_venue_id);
  RETURN 'ok';
END;
$$;


ALTER FUNCTION "public"."rpc_rate_venue"("p_game_id" "uuid", "p_venue_id" "uuid", "p_rater_profile_id" "uuid", "p_scores" "jsonb", "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_recreate_from_game"("p_game_id" "uuid", "p_shift_week" boolean DEFAULT true) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE g record; payload jsonb; did uuid;
BEGIN
  SELECT id, sport_id, venue_space_id, start_at, end_at, capacity, listing_visibility, join_policy, title
  INTO g FROM public.games WHERE id = p_game_id;

  IF NOT FOUND THEN RAISE EXCEPTION USING errcode='P0001', message='game_not_found'; END IF;

  IF NOT EXISTS(
    SELECT 1 FROM public.games gg
    WHERE gg.id = p_game_id
      AND (gg.creator_user_id = auth.uid() OR public.is_admin(auth.uid()))
  ) THEN
    RAISE EXCEPTION USING errcode='P0001', message='not_authorized';
  END IF;

  payload := jsonb_build_object(
    'sport_id',           g.sport_id,
    'venue_space_id',     g.venue_space_id,
    'start_at',           CASE WHEN p_shift_week THEN public._next_week_same_time(g.start_at) ELSE g.start_at END,
    'end_at',             CASE WHEN p_shift_week THEN public._next_week_same_time(g.end_at)   ELSE g.end_at   END,
    'capacity',           g.capacity,
    'listing_visibility', g.listing_visibility,
    'join_policy',        g.join_policy,
    'title',              g.title
  );

  did := public.rpc_draft_create('game', payload);
  RETURN did;
END;
$$;


ALTER FUNCTION "public"."rpc_recreate_from_game"("p_game_id" "uuid", "p_shift_week" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_recreate_suggestions"("p_context" "text", "p_sport" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 5) RETURNS TABLE("suggested_payload" "jsonb", "score" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select
    c.suggested_payload,
    c.score
  from public.v_recreate_candidates c
  where c.context = p_context
    and (p_sport is null or lower(c.suggested_payload->>'sport') = lower(p_sport))
  limit greatest(1, least(p_limit, 10))
$$;


ALTER FUNCTION "public"."rpc_recreate_suggestions"("p_context" "text", "p_sport" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_remove_player"("p_game_id" "uuid", "p_profile_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_creator uuid;
  v_target record;
  w_profile uuid;
  upsert_ct int := 0;
begin
  select creator_user_id into v_creator
  from public.games
  where id = p_game_id and is_cancelled = false;
  if v_creator is null then
    raise exception using errcode='P0001', message='game_not_found';
  end if;
  if v_creator <> auth.uid() and not public.is_admin(auth.uid()) then
    raise exception using errcode='P0001', message='not_host';
  end if;

  select * into v_target
  from public.game_roster
  where game_id = p_game_id and profile_id = p_profile_id and status = 'active'
  for update;
  if not found then
    raise exception using errcode='P0001', message='player_not_on_roster';
  end if;
  if v_target.role = 'host' then
    raise exception using errcode='P0001', message='cannot_remove_host';
  end if;

  update public.game_roster
     set status = 'kicked', left_at = now()
   where game_id = p_game_id and profile_id = p_profile_id;

  if v_target.user_id is not null then
    perform public.process_notification_event(
      v_target.user_id,
      'game.removed',
      'game',
      p_game_id,
      auth.uid(),
      'You''ve been removed from a game'
    );
  end if;

  select wl.profile_id into w_profile
  from public.game_waitlist wl
  where wl.game_id = p_game_id
  order by wl.position asc
  limit 1;
  if w_profile is null then return 'removed'; end if;

  insert into public.game_roster (game_id, profile_id, role, status)
  values (p_game_id, w_profile, 'player', 'active')
  on conflict (game_id, profile_id) do update set status='active', left_at=null;
  get diagnostics upsert_ct = row_count;
  delete from public.game_waitlist
  where game_id = p_game_id and profile_id = w_profile;

  if upsert_ct > 0 then return 'removed_promoted_waitlist'; end if;
  return 'removed';
end$$;


ALTER FUNCTION "public"."rpc_remove_player"("p_game_id" "uuid", "p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_report_post"("p_post_id" "uuid", "p_reason" "text", "p_details" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  insert into public.post_reports(post_id, reporter_user_id, reason, details)
  values (p_post_id, auth.uid(), left(p_reason,140), left(p_details,500))
  on conflict (post_id, reporter_user_id) do update
    set reason = excluded.reason, details = excluded.details, status='open', updated_at=now();
  select 'reported';
$$;


ALTER FUNCTION "public"."rpc_report_post"("p_post_id" "uuid", "p_reason" "text", "p_details" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_report_rating"("p_rating_id" "uuid", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare rid uuid;
begin
  if auth.uid() is null then
    raise exception using errcode='P0001', message='auth_required';
  end if;

  if exists(select 1 from public.ratings where id = p_rating_id and rater_user_id = auth.uid()) then
    raise exception using errcode='P0001', message='cannot_report_own';
  end if;

  insert into public.rating_reports(rating_id, reporter_user_id, reason)
  values (p_rating_id, auth.uid(), left(coalesce(p_reason, 'inappropriate'), 500))
  returning id into rid;

  update public.ratings set is_flagged = true where id = p_rating_id;

  perform public.emit_event(
    'rating.reported', 'rating', p_rating_id, auth.uid(),
    jsonb_build_object('reason', p_reason)
  );

  return rid;
end;
$$;


ALTER FUNCTION "public"."rpc_report_rating"("p_rating_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_repost_post"("p_original_post_id" "uuid", "p_quote_text" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_profile_id uuid; v_new_post_id uuid;
  v_original_kind public.post_kind; v_original_visibility text;
  v_original_origin_type public.origin_type_enum; v_repost_row_id uuid;
BEGIN
  SELECT id INTO v_profile_id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1;
  IF v_profile_id IS NULL THEN RAISE EXCEPTION 'profile_not_found'; END IF;
  SELECT kind, visibility, origin_type INTO v_original_kind, v_original_visibility, v_original_origin_type
  FROM public.posts WHERE id = p_original_post_id AND is_deleted = false AND is_hidden_admin = false FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'original_post_not_found'; END IF;
  IF v_original_origin_type = 'repost' THEN RAISE EXCEPTION 'cannot_repost_a_repost'; END IF;
  INSERT INTO public.post_reposts (parent_activity_id, reposter_profile_id, reposter_user_id, commentary)
  VALUES (p_original_post_id, v_profile_id, auth.uid(), p_quote_text)
  ON CONFLICT (parent_activity_id, reposter_user_id) DO NOTHING
  RETURNING id INTO v_repost_row_id;
  IF v_repost_row_id IS NULL THEN RAISE EXCEPTION 'already_reposted'; END IF;
  INSERT INTO public.posts (author_profile_id, author_user_id, kind, visibility, origin_type, origin_id, body)
  VALUES (v_profile_id, auth.uid(), v_original_kind, v_original_visibility, 'repost', p_original_post_id, p_quote_text)
  RETURNING id INTO v_new_post_id;
  RETURN v_new_post_id;
END;
$$;


ALTER FUNCTION "public"."rpc_repost_post"("p_original_post_id" "uuid", "p_quote_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_reschedule_game"("p_game_id" "uuid", "p_start_at" timestamp with time zone, "p_end_at" timestamp with time zone) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_end_at <= p_start_at THEN
    RAISE EXCEPTION USING errcode='P0001', message='invalid_time_range';
  END IF;
  UPDATE public.games
  SET start_at = p_start_at, end_at = p_end_at
  WHERE id = p_game_id
    AND (creator_user_id = auth.uid() OR public.is_admin(auth.uid()));
  IF NOT FOUND THEN
    RAISE EXCEPTION USING errcode='P0001', message='not_host_or_not_found';
  END IF;
  RETURN 'rescheduled';
END$$;


ALTER FUNCTION "public"."rpc_reschedule_game"("p_game_id" "uuid", "p_start_at" timestamp with time zone, "p_end_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_restrict_clear"("p_target" "uuid", "p_type" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare me uuid := auth.uid();
begin
  if me is null then raise exception using errcode='P0001', message='not_authenticated'; end if;
  if p_type not in ('hidden','blocked') then raise exception using errcode='P0001', message='invalid_type'; end if;
  delete from public.restrictions
  where user_id = me and target_user_id = p_target and type = p_type;
end; $$;


ALTER FUNCTION "public"."rpc_restrict_clear"("p_target" "uuid", "p_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_restrict_set"("p_target" "uuid", "p_type" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare me uuid := auth.uid();
begin
  if me is null then raise exception using errcode='P0001', message='not_authenticated'; end if;
  if p_target is null or p_target = me then raise exception using errcode='P0001', message='invalid_target'; end if;
  if p_type not in ('hidden','blocked') then raise exception using errcode='P0001', message='invalid_type'; end if;

  insert into public.restrictions(user_id, target_user_id, type)
  values (me, p_target, p_type)
  on conflict (user_id, target_user_id, type) do nothing;

  -- Optional: auto-downgrade friendship to removed if blocking
  if p_type = 'blocked' then
    update public.friendships
    set status='removed', updated_at=now()
    where (user_id, peer_user_id) in ( (least(me,p_target), greatest(me,p_target)) );
  end if;
end; $$;


ALTER FUNCTION "public"."rpc_restrict_set"("p_target" "uuid", "p_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_review_report"("p_report_id" "uuid", "p_new_status" "text", "p_resolution_notes" "text" DEFAULT NULL::"text", "p_action" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor uuid := public.admin_actor();
  r       record;
begin
  if v_actor is null then raise exception using errcode='P0001', message='not_authenticated'; end if;
  if not public.is_admin(v_actor) then raise exception using errcode='P0001', message='not_admin'; end if;
  if p_new_status not in ('reviewing','resolved','dismissed') then
    raise exception using errcode='P0001', message='invalid_status';
  end if;

  select * into r from public.content_reports where id = p_report_id for update;
  if not found then raise exception using errcode='P0001', message='report_not_found'; end if;

  update public.content_reports
     set status         = p_new_status,
         resolved_by    = case when p_new_status in ('resolved','dismissed') then v_actor else resolved_by end,
         resolution_notes = p_resolution_notes
   where id = p_report_id;

  if p_new_status = 'resolved' and p_action is not null then
    if p_action = 'shadow_hide' then
      perform public.rpc_shadow_hide(r.target_table, r.target_id, coalesce(p_resolution_notes,'report_resolved'), null);
    elsif p_action = 'takedown' then
      perform public.rpc_takedown(r.target_table, r.target_id, coalesce(p_resolution_notes,'report_resolved'));
    end if;
  end if;

  insert into public.moderation_actions(actor_admin_id, action_type, target_table, target_id, reason, metadata)
  values (
    v_actor,
    case when p_new_status='dismissed' then 'report_dismissed' else 'report_resolved' end,
    r.target_table, r.target_id,
    p_resolution_notes,
    jsonb_build_object('report_id', p_report_id, 'final_status', p_new_status, 'action', p_action)
  );

  return 'ok';
end;
$$;


ALTER FUNCTION "public"."rpc_review_report"("p_report_id" "uuid", "p_new_status" "text", "p_resolution_notes" "text", "p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_rewards_apply_event"("p_event_id" "uuid", "p_user_id" "uuid", "p_event_key" "text", "p_sport" "text" DEFAULT NULL::"text", "p_context" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  r record;
  awarded_points int := 0;
  badges jsonb := '[]'::jsonb;
  did_badge boolean;
  ins_id uuid;
begin
  -- Frozen users shouldn’t gain rewards for new activity
  if public.is_frozen(p_user_id) then
    return jsonb_build_object('awarded_points', 0, 'badges', badges, 'reason','frozen');
  end if;

  for r in
    select * from public.reward_rules
    where is_active = true
      and rule_type = 'event'
      and (event_keys @> array[p_event_key]::text[])
    order by sort_order, created_at
  loop
    -- Cooldown per user
    if r.cooldown_per_user_sec > 0
       and public.rule_on_cooldown(r.key, p_user_id, r.cooldown_per_user_sec) then
      continue;
    end if;

    -- Conditions
    if not public._conditions_match(r.conditions, p_sport, p_context) then
      continue;
    end if;

    -- Points
    ins_id := public._award_points(p_user_id, r.points, p_event_key, r.key, p_sport, p_event_id);
    if ins_id is not null then
      awarded_points := awarded_points + r.points;
    end if;

    -- Badge
    if r.badge_key is not null then
      did_badge := public._award_badge_if_absent(p_user_id, r.badge_key, r.key, p_sport, p_context);
      if did_badge then
        badges := badges || to_jsonb(r.badge_key);
      end if;
    end if;
  end loop;

  return jsonb_build_object('awarded_points', awarded_points, 'badges', badges);
end;
$$;


ALTER FUNCTION "public"."rpc_rewards_apply_event"("p_event_id" "uuid", "p_user_id" "uuid", "p_event_key" "text", "p_sport" "text", "p_context" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_search_entities"("p_q" "text", "p_scope" "text"[] DEFAULT ARRAY['people'::"text", 'venues'::"text", 'squads'::"text", 'games'::"text", 'arenas'::"text"], "p_sport" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 40) RETURNS TABLE("entity_type" "text", "entity_id" "uuid", "title" "text", "subtitle" "text", "extra" "jsonb", "rank_score" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  ts tsquery;
  qnorm text;
begin
  if me is null then
    raise exception using errcode='P0001', message='auth_required';
  end if;

  select t.ts, t.qnorm into ts, qnorm
  from public._normalize_query(p_q) as t;

  -- PEOPLE
  return query
  with src as (
    select pc.profile_id as id, pc.user_id, pc.profile_type, pc.username, pc.display_name,
           pc.sport_key, pc.avatar_url,
           p.search_tsv,
           greatest(coalesce(ts_rank(p.search_tsv, ts),0)::numeric,
                    case when qnorm is not null then
                      greatest(similarity(lower(pc.username), qnorm),
                               similarity(lower(pc.display_name), qnorm))::numeric
                    else 0 end) as text_score,
           case when pc.profile_type='organiser' then 0.10 else 0 end as role_boost,
           case when p_sport is not null and pc.sport_key = p_sport then 0.15 else 0 end as sport_boost,
           public._clamp01(public.potential_vibe_score(me, pc.user_id))*0.25 as vibe_boost
    from public.v_person_card pc
    join public.profiles p on p.id = pc.profile_id
    where ('people' = any(p_scope))
      and (p_sport is null or pc.sport_key = p_sport or pc.profile_type='organiser')
      and (ts is null or p.search_tsv @@ ts
           or (qnorm is not null and (similarity(lower(pc.username), qnorm) > 0.3
                                   or similarity(lower(pc.display_name), qnorm) > 0.3)))
  ),
  vis as (
    select * from src where public.can_view_profile(me, id)
  )
  select
    'person'::text, id,
    coalesce(display_name, username) as title,
    case when profile_type='organiser' then '@'||username||' · organiser'
         else '@'||username||coalesce(' · '||sport_key,'') end as subtitle,
    jsonb_build_object('profile_type',profile_type,'username',username,'sport_key',sport_key,'avatar_url',avatar_url) as extra,
    round(least(1.0, (text_score + role_boost + sport_boost + vibe_boost))::numeric, 6) as rank_score
  from vis
  limit greatest(0, coalesce(p_limit,40));

  -- VENUES (use the view's sports::text[] directly)
  return query
  with src as (
    select v.id, v.name, v.district, v.city, vn.search_tsv, v.sports,
           (coalesce(ts_rank(vn.search_tsv, ts),0))::numeric as text_score
    from public.v_venue_card v
    join public.venues vn on vn.id = v.id
    where ('venues' = any(p_scope))
      and (ts is null or vn.search_tsv @@ ts
           or (qnorm is not null and similarity(lower(v.name), qnorm) > 0.3))
      and (p_sport is null or (v.sports is not null and p_sport = any(v.sports)))
  )
  select
    'venue', id,
    name as title,
    coalesce(district,'') ||
    case when city is not null and district is not null then ', ' else '' end ||
    coalesce(city,'') as subtitle,
    jsonb_build_object('district',district,'city',city) as extra,
    round(least(1.0, text_score)::numeric,6) as rank_score
  from src
  limit greatest(0, coalesce(p_limit,40));

  -- SQUADS
  return query
  with src as (
    select s.id, s.display_name, s.handle, s.sport_key, sq.search_tsv,
           (coalesce(ts_rank(sq.search_tsv, ts),0))::numeric as text_score,
           case when p_sport is not null and s.sport_key = p_sport then 0.15 else 0 end as sport_boost
    from public.v_squad_card s
    join public.squads sq on sq.id = s.id
    where ('squads' = any(p_scope))
      and (ts is null or sq.search_tsv @@ ts
           or (qnorm is not null and (similarity(lower(s.handle), qnorm) > 0.3
                                   or similarity(lower(s.display_name), qnorm) > 0.3)))
      and (p_sport is null or s.sport_key = p_sport)
  )
  select
    'squad', id,
    coalesce(display_name, handle) as title,
    '@'||handle||' · '||coalesce(sport_key,'') as subtitle,
    jsonb_build_object('sport_key',sport_key,'handle',handle) as extra,
    round(least(1.0, (text_score + sport_boost))::numeric,6) as rank_score
  from src
  limit greatest(0, coalesce(p_limit,40));

  -- GAMES
  return query
  with src as (
    select g.id, g.title, g.sport, g.start_at, gm.search_tsv,
           (coalesce(ts_rank(gm.search_tsv, ts),0))::numeric as text_score
    from public.v_game_card g
    join public.games gm on gm.id = g.id
    where ('games' = any(p_scope))
      and (p_sport is null or g.sport = p_sport)
      and (ts is null or gm.search_tsv @@ ts
           or (qnorm is not null and similarity(lower(coalesce(g.title,'')), qnorm) > 0.3))
      and public.can_view_game(me, g.id)
  )
  select
    'game', id,
    coalesce(title, initcap(sport)||' game') as title,
    to_char(start_at at time zone 'UTC','YYYY-MM-DD HH24:MI UTC') as subtitle,
    jsonb_build_object('sport',sport,'start_at',start_at) as extra,
    round(least(1.0, text_score)::numeric,6) as rank_score
  from src
  limit greatest(0, coalesce(p_limit,40));

  -- ARENAS (optional)
  if 'arenas' = any(p_scope) and exists (
       select 1 from information_schema.tables where table_schema='public' and table_name='arenas'
     ) then
    return query
    with src as (
      select a.id, a.title, a.key, a.sport_key, a.search_tsv,
             (coalesce(ts_rank(a.search_tsv, ts),0))::numeric as text_score,
             case when p_sport is not null and a.sport_key = p_sport then 0.15 else 0 end as sport_boost
      from public.arenas a
      where (ts is null or a.search_tsv @@ ts
             or (qnorm is not null and (similarity(lower(a.title), qnorm) > 0.3
                                     or similarity(lower(a.key), qnorm) > 0.3)))
        and (p_sport is null or a.sport_key = p_sport)
    )
    select
      'arena', id,
      title as title,
      key||coalesce(' · '||sport_key,'') as subtitle,
      jsonb_build_object('sport_key',sport_key,'key',key) as extra,
      round(least(1.0, (text_score + sport_boost))::numeric,6) as rank_score
    from src
    limit greatest(0, coalesce(p_limit,40));
  end if;
end;
$$;


ALTER FUNCTION "public"."rpc_search_entities"("p_q" "text", "p_scope" "text"[], "p_sport" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_search_posts"("p_vibe_keys" "text"[] DEFAULT NULL::"text"[], "p_sport" "text" DEFAULT NULL::"text", "p_venue" "uuid" DEFAULT NULL::"uuid", "p_text" "text" DEFAULT NULL::"text", "p_since" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_limit" integer DEFAULT 30) RETURNS TABLE("id" "uuid", "kind" "text", "visibility" "text", "body" "text", "lang" "text", "sport_key" "text", "venue_id" "uuid", "media" "jsonb", "like_count" integer, "comment_count" integer, "created_at" timestamp with time zone, "author_username" "text", "author_display_name" "text", "author_role" "text", "vibe_keys" "text"[], "match_rank" real)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  q tsquery := null;
begin
  if me is null then raise exception using errcode='P0001', message='auth_required'; end if;

  if p_text is not null and length(trim(p_text)) > 0 then
    q := websearch_to_tsquery('simple', unaccent(p_text));
  end if;

  return query
  with base as (
    select d.*, p.search_tsv
    from public.v_post_discovery d
    join public.posts p on p.id = d.id
    where (p_sport is null or d.sport_key = p_sport)
      and (p_venue is null or d.venue_id = p_venue)
      and (p_since is null or d.created_at < p_since)
      and (q is null or p.search_tsv @@ q)
      and (
        p_vibe_keys is null
        or exists (
            select 1
            from public.post_vibes pv
            join public.vibes v on v.id = pv.vibe_id
            where pv.post_id = d.id
              and v.key = any(p_vibe_keys)
        )
      )
  ),
  visible as (
    select b.*
    from base b
    join public.posts p on p.id=b.id
    where public.can_view_post(auth.uid(), p)
  )
  select
    id, kind, visibility, body, lang, sport_key, venue_id, media,
    like_count, comment_count, created_at, author_username, author_display_name, author_role,
    vibe_keys,
    coalesce(ts_rank(search_tsv, q), 0)::real as match_rank
  from visible
  order by (case when q is null then 0 else ts_rank(search_tsv,q) end) desc,
           created_at desc, id
  limit greatest(1, coalesce(p_limit,30));
end;
$$;


ALTER FUNCTION "public"."rpc_search_posts"("p_vibe_keys" "text"[], "p_sport" "text", "p_venue" "uuid", "p_text" "text", "p_since" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_search_users"("p_query" "text", "p_limit" integer DEFAULT 20) RETURNS TABLE("user_id" "uuid", "full_name" "text", "username" "text", "avatar_url" "text", "bio" "text", "is_friend" boolean, "has_pending_request" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_current_user_id UUID := auth.uid();
BEGIN
  RETURN QUERY
  SELECT
    p.id,
    -- Backward-compatible output column name.
    p.display_name,
    p.username,
    p.avatar_url,
    p.bio,
    EXISTS (
      SELECT 1 FROM friendships f
      WHERE ((f.user_id = v_current_user_id AND f.peer_user_id = p.id)
         OR (f.user_id = p.id AND f.peer_user_id = v_current_user_id))
        AND f.status = 'accepted'
    ) AS is_friend,
    EXISTS (
      SELECT 1 FROM friendships f
      WHERE ((f.user_id = v_current_user_id AND f.peer_user_id = p.id)
         OR (f.user_id = p.id AND f.peer_user_id = v_current_user_id))
        AND f.status = 'pending'
    ) AS has_pending_request
  FROM profiles p
  WHERE p.id != v_current_user_id
    AND (
      p.display_name ILIKE '%' || p_query || '%'
      OR p.username ILIKE '%' || p_query || '%'
    )
  ORDER BY
    CASE WHEN p.username ILIKE p_query THEN 0 ELSE 1 END,
    p.display_name ASC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."rpc_search_users"("p_query" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_set_actor"("preferred" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  me uuid := auth.uid();
begin
  if me is null then
    raise exception 'not_authenticated' using errcode='P0001';
  end if;

  if preferred not in ('player','organiser') then
    raise exception using errcode = 'P0001', message = 'actor_type_invalid';
  end if;

  insert into public.user_actor_pref(user_id, preferred_actor_type)
  values (me, preferred)
  on conflict (user_id) do update
    set preferred_actor_type = excluded.preferred_actor_type,
        updated_at = now();
end;
$$;


ALTER FUNCTION "public"."rpc_set_actor"("preferred" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_set_post_primary_vibe"("p_post_id" "uuid", "p_vibe_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  p public.posts%rowtype;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION USING errcode='P0001', message='auth_required';
  END IF;

  SELECT * INTO p FROM public.posts WHERE id = p_post_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING errcode='P0001', message='not_found';
  END IF;

  IF p.author_user_id <> auth.uid() THEN
    RAISE EXCEPTION USING errcode='P0001', message='forbidden';
  END IF;

  UPDATE public.posts SET vibe_id = p_vibe_id WHERE id = p_post_id;
  RETURN 'ok';
END;
$$;


ALTER FUNCTION "public"."rpc_set_post_primary_vibe"("p_post_id" "uuid", "p_vibe_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_shadow_hide"("p_table" "text", "p_id" "uuid", "p_reason" "text" DEFAULT NULL::"text", "p_expires" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor uuid := public.admin_actor();
begin
  if v_actor is null then raise exception using errcode='P0001', message='not_authenticated'; end if;
  if not public.is_admin(v_actor) then raise exception using errcode='P0001', message='not_admin'; end if;

  insert into public.content_enforcement(target_table, target_id, action, active, reason, created_by, expires_at)
  values (p_table, p_id, 'shadow_hide', true, p_reason, v_actor, p_expires)
  on conflict do nothing;

  insert into public.moderation_actions(actor_admin_id, action_type, target_table, target_id, reason)
  values (v_actor, 'shadow_hide', p_table, p_id, p_reason);
end;
$$;


ALTER FUNCTION "public"."rpc_shadow_hide"("p_table" "text", "p_id" "uuid", "p_reason" "text", "p_expires" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_shadow_unhide"("p_table" "text", "p_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor uuid := public.admin_actor();
begin
  if v_actor is null then raise exception using errcode='P0001', message='not_authenticated'; end if;
  if not public.is_admin(v_actor) then raise exception using errcode='P0001', message='not_admin'; end if;

  update public.content_enforcement
     set active = false,
         expires_at = now()
   where target_table = p_table
     and target_id    = p_id
     and action       = 'shadow_hide'
     and active       = true;

  insert into public.moderation_actions(actor_admin_id, action_type, target_table, target_id, reason)
  values (v_actor, 'shadow_unhide', p_table, p_id, p_reason);
end;
$$;


ALTER FUNCTION "public"."rpc_shadow_unhide"("p_table" "text", "p_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_squad_add_member"("p_squad_id" "uuid", "p_profile_id" "uuid", "p_as_captain" boolean DEFAULT false) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  caller uuid := auth.uid();
  prof record;
  role_text text := case when p_as_captain then 'captain' else 'member' end;
begin
  if caller is null then raise exception using errcode='P0001', message='auth_required'; end if;
  if not public.is_squad_owner_or_captain(p_squad_id, caller) and not public.is_admin(caller) then
    raise exception using errcode='P0001', message='not_authorized';
  end if;

  select id, user_id, profile_type into prof from public.profiles where id = p_profile_id;
  if prof.id is null then raise exception using errcode='P0001', message='profile_not_found'; end if;
  if prof.profile_type <> 'player' then
    raise exception using errcode='P0001', message='only_player_profiles_can_join';
  end if;

  insert into public.squad_members(squad_id, profile_id, user_id, role, status)
  values (p_squad_id, p_profile_id, prof.user_id, role_text, 'active')
  on conflict (squad_id, profile_id) do update
    set status='active', left_at=null, role = excluded.role;

  perform public.emit_event('squad.member_added','squad', p_squad_id, caller, jsonb_build_object('profile_id', p_profile_id, 'role', role_text));

  return 'ok';
end;
$$;


ALTER FUNCTION "public"."rpc_squad_add_member"("p_squad_id" "uuid", "p_profile_id" "uuid", "p_as_captain" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_squad_create"("p_created_by_profile_id" "uuid", "p_sport" "text", "p_name" "text", "p_bio" "text" DEFAULT NULL::"text", "p_listing_visibility" "text" DEFAULT 'public'::"text", "p_join_policy" "text" DEFAULT 'request'::"text", "p_max_members" integer DEFAULT NULL::integer, "p_captain_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE pr record; sid uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION USING errcode='P0001', message='auth_required'; END IF;

  SELECT id, user_id, profile_type INTO pr
  FROM public.profiles WHERE id = p_created_by_profile_id;

  IF NOT FOUND THEN RAISE EXCEPTION USING errcode='P0001', message='profile_not_found'; END IF;
  IF pr.user_id <> auth.uid() THEN RAISE EXCEPTION USING errcode='P0001', message='not_profile_owner'; END IF;

  IF pr.profile_type = 'player' THEN
    IF EXISTS (SELECT 1 FROM public.squads WHERE founder_user_id = auth.uid()) THEN
      RAISE EXCEPTION USING errcode='P0001', message='founder_limit_reached';
    END IF;

    INSERT INTO public.squads(
      sport,name,bio,created_by_user_id,created_by_profile_id,created_by_role,founder_user_id,
      listing_visibility,join_policy,max_members,city
    ) VALUES (
      p_sport, p_name, p_bio, auth.uid(), p_created_by_profile_id, 'player', auth.uid(),
      p_listing_visibility, p_join_policy, p_max_members, 'Dubai'
    ) RETURNING id INTO sid;

    INSERT INTO public.squad_members(squad_id,user_id,profile_id,role,status)
    VALUES (sid, auth.uid(), p_created_by_profile_id, 'captain','active');

  ELSIF pr.profile_type = 'organiser' THEN
    IF p_captain_user_id IS NULL THEN
      RAISE EXCEPTION USING errcode='P0001', message='captain_required';
    END IF;

    INSERT INTO public.squads(
      sport,name,bio,created_by_user_id,created_by_profile_id,created_by_role,founder_user_id,
      listing_visibility,join_policy,max_members,city
    ) VALUES (
      p_sport, p_name, p_bio, auth.uid(), p_created_by_profile_id, 'organiser', NULL,
      p_listing_visibility, p_join_policy, p_max_members, 'Dubai'
    ) RETURNING id INTO sid;

    IF NOT EXISTS (
      SELECT 1 FROM public.profiles px
      WHERE px.user_id = p_captain_user_id
        AND px.profile_type = 'player'
        AND public._profile_matches_sport(px.id, p_sport)
    ) THEN
      RAISE EXCEPTION USING errcode='P0001', message='captain_must_be_player';
    END IF;

    INSERT INTO public.squad_members(squad_id,user_id,profile_id,role,status)
    SELECT sid, px.user_id, px.id, 'captain','active'
    FROM public.profiles px
    WHERE px.user_id = p_captain_user_id
      AND px.profile_type='player'
      AND public._profile_matches_sport(px.id, p_sport)
    LIMIT 1;

  ELSE
    RAISE EXCEPTION USING errcode='P0001', message='invalid_creator_role';
  END IF;

  PERFORM public.emit_event('squad.created','squad', sid, auth.uid(),
    jsonb_build_object('sport',p_sport,'name',p_name));
  RETURN sid;
END;
$$;


ALTER FUNCTION "public"."rpc_squad_create"("p_created_by_profile_id" "uuid", "p_sport" "text", "p_name" "text", "p_bio" "text", "p_listing_visibility" "text", "p_join_policy" "text", "p_max_members" integer, "p_captain_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_squad_invite"("p_squad_id" "uuid", "p_to_profile_id" "uuid", "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  caller_profile uuid;
  caller_user uuid := auth.uid();
  rid uuid;
  tu record;
begin
  if caller_user is null then raise exception using errcode='P0001', message='auth_required'; end if;
  if not public.is_squad_owner_or_captain(p_squad_id, caller_user) and not public.is_admin(caller_user) then
    raise exception using errcode='P0001', message='not_authorized';
  end if;

  select id, user_id, profile_type into tu from public.profiles where id = p_to_profile_id;
  if tu.id is null then raise exception using errcode='P0001', message='profile_not_found'; end if;
  if tu.profile_type <> 'player' then raise exception using errcode='P0001', message='only_player_profiles_can_join'; end if;

  -- find a caller profile (any player or organiser linked to caller; prefer organiser/owner or first captain)
  select p.id into caller_profile
  from public.profiles p
  where p.user_id = caller_user
  order by case when p.id in (select owner_profile_id from public.squads where id=p_squad_id) then 0 else 1 end, p.created_at
  limit 1;

  insert into public.squad_invites(squad_id, to_profile_id, to_user_id, created_by_profile_id, expires_at)
  values (p_squad_id, p_to_profile_id, tu.user_id, caller_profile, p_expires_at)
  returning id into rid;

  perform public.emit_event('squad.invite_sent','squad', p_squad_id, caller_user, jsonb_build_object('invite_id', rid, 'to_profile_id', p_to_profile_id));

  return rid;
end;
$$;


ALTER FUNCTION "public"."rpc_squad_invite"("p_squad_id" "uuid", "p_to_profile_id" "uuid", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_squad_remove_member"("p_squad_id" "uuid", "p_profile_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  caller uuid := auth.uid();
begin
  if caller is null then raise exception using errcode='P0001', message='auth_required'; end if;
  if not public.is_squad_owner_or_captain(p_squad_id, caller) and not public.is_admin(caller) then
    raise exception using errcode='P0001', message='not_authorized';
  end if;

  update public.squad_members
  set status='left', left_at=now()
  where squad_id = p_squad_id and profile_id = p_profile_id and status='active';

  if not found then
    raise exception using errcode='P0001', message='not_member';
  end if;

  perform public.emit_event('squad.member_removed','squad', p_squad_id, caller, jsonb_build_object('profile_id', p_profile_id));

  return 'ok';
end;
$$;


ALTER FUNCTION "public"."rpc_squad_remove_member"("p_squad_id" "uuid", "p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_squad_request_join"("p_squad_id" "uuid", "p_profile_id" "uuid", "p_message" "text" DEFAULT NULL::"text", "p_link_token" "uuid" DEFAULT NULL::"uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE s record; members int;
BEGIN
  SELECT id, sport, join_policy, max_members INTO s
  FROM public.squads WHERE id=p_squad_id AND is_active=true;
  IF NOT FOUND THEN RAISE EXCEPTION USING errcode='P0001', message='squad_not_found'; END IF;

  IF NOT public._profile_is_player_for_sport(p_profile_id, s.sport) THEN
    RAISE EXCEPTION USING errcode='P0001', message='profile_not_player_for_sport';
  END IF;
  IF NOT public._can_participate(auth.uid()) THEN
    RAISE EXCEPTION USING errcode='P0001', message='benched_or_frozen';
  END IF;

  IF s.max_members IS NOT NULL THEN
    SELECT COUNT(*) INTO members FROM public.squad_members WHERE squad_id=s.id AND status='active';
    IF members >= s.max_members THEN RAISE EXCEPTION USING errcode='P0001', message='squad_full'; END IF;
  END IF;

  CASE s.join_policy
    WHEN 'open' THEN
      INSERT INTO public.squad_members(squad_id,user_id,profile_id,role,status)
      VALUES (s.id, auth.uid(), p_profile_id, 'member','active')
      ON CONFLICT (squad_id, user_id) DO UPDATE
        SET status='active', profile_id=EXCLUDED.profile_id, left_at=NULL;

      PERFORM public.emit_event('squad.member_joined','squad', s.id, auth.uid(), jsonb_build_object('via','open'));
      RETURN 'joined';

    WHEN 'request' THEN
      INSERT INTO public.squad_join_requests(squad_id,user_id,profile_id,status,message)
      VALUES (s.id, auth.uid(), p_profile_id, 'pending', LEFT(p_message,300))
      ON CONFLICT DO NOTHING;

      PERFORM public.emit_event('squad.join_requested','squad', s.id, auth.uid(), '{}');
      RETURN 'pending';

    WHEN 'invite' THEN
      RAISE EXCEPTION USING errcode='P0001', message='invite_only';

    WHEN 'closed' THEN
      RAISE EXCEPTION USING errcode='P0001', message='closed';

    WHEN 'link' THEN
      IF p_link_token IS NULL OR NOT public._squad_link_valid(s.id, p_link_token) THEN
        RAISE EXCEPTION USING errcode='P0001', message='link_required';
      END IF;
      PERFORM public._squad_link_consume(s.id, p_link_token);

      INSERT INTO public.squad_members(squad_id,user_id,profile_id,role,status)
      VALUES (s.id, auth.uid(), p_profile_id, 'member','active')
      ON CONFLICT (squad_id, user_id) DO UPDATE
        SET status='active', profile_id=EXCLUDED.profile_id, left_at=NULL;

      PERFORM public.emit_event('squad.member_joined','squad', s.id, auth.uid(), jsonb_build_object('via','link'));
      RETURN 'joined';

    ELSE
      RAISE EXCEPTION USING errcode='P0001', message='unknown_policy';
  END CASE;
END;
$$;


ALTER FUNCTION "public"."rpc_squad_request_join"("p_squad_id" "uuid", "p_profile_id" "uuid", "p_message" "text", "p_link_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_squad_respond_invite"("p_invite_id" "uuid", "p_decision" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare inv record;
begin
  if auth.uid() is null then raise exception using errcode='P0001', message='auth_required'; end if;

  select * into inv from public.squad_invites where id = p_invite_id for update;
  if not found then raise exception using errcode='P0001', message='invite_not_found'; end if;
  if inv.to_user_id <> auth.uid() then raise exception using errcode='P0001', message='not_invitee'; end if;
  if inv.status <> 'pending' then raise exception using errcode='P0001', message='invite_not_pending'; end if;
  if inv.expires_at is not null and now() >= inv.expires_at then
    update public.squad_invites set status='expired' where id = p_invite_id;
    raise exception using errcode='P0001', message='invite_expired';
  end if;

  if p_decision = 'accepted' then
    -- add as member
    perform public.rpc_squad_add_member(inv.squad_id, inv.to_profile_id, false);
    update public.squad_invites set status='accepted' where id = p_invite_id;
    return 'accepted';
  elsif p_decision = 'declined' then
    update public.squad_invites set status='declined' where id = p_invite_id;
    return 'declined';
  else
    raise exception using errcode='P0001', message='invalid_decision';
  end if;
end;
$$;


ALTER FUNCTION "public"."rpc_squad_respond_invite"("p_invite_id" "uuid", "p_decision" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_squad_respond_invite"("p_invite_id" "uuid", "p_action" "text", "p_profile_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE inv record; sp text; members int; maxm int;
BEGIN
  SELECT * INTO inv FROM public.squad_invites WHERE id=p_invite_id AND to_user_id=auth.uid();
  IF NOT FOUND THEN RAISE EXCEPTION USING errcode='P0001', message='invite_not_found'; END IF;

  SELECT sport, max_members INTO sp, maxm FROM public.squads WHERE id=inv.squad_id;

  IF p_action = 'decline' THEN
    UPDATE public.squad_invites SET status='declined' WHERE id=p_invite_id AND status='pending';
    RETURN 'declined';

  ELSIF p_action = 'accept' THEN
    IF NOT public._profile_is_player_for_sport(p_profile_id, sp) THEN
      RAISE EXCEPTION USING errcode='P0001', message='profile_not_player_for_sport';
    END IF;

    IF NOT public._can_participate(auth.uid()) THEN
      RAISE EXCEPTION USING errcode='P0001', message='benched_or_frozen';
    END IF;

    IF maxm IS NOT NULL THEN
      SELECT COUNT(*) INTO members FROM public.squad_members WHERE squad_id=inv.squad_id AND status='active';
      IF members >= maxm THEN RAISE EXCEPTION USING errcode='P0001', message='squad_full'; END IF;
    END IF;

    INSERT INTO public.squad_members(squad_id,user_id,profile_id,role,status)
    VALUES (inv.squad_id, auth.uid(), p_profile_id, 'member','active')
    ON CONFLICT (squad_id, user_id) DO UPDATE
      SET status='active', profile_id=EXCLUDED.profile_id, left_at=NULL;

    UPDATE public.squad_invites SET status='accepted' WHERE id=p_invite_id AND status='pending';

    PERFORM public.emit_event('squad.member_joined','squad', inv.squad_id, auth.uid(), jsonb_build_object('via','invite'));
    RETURN 'accepted';

  ELSE
    RAISE EXCEPTION USING errcode='P0001', message='invalid_action';
  END IF;
END;
$$;


ALTER FUNCTION "public"."rpc_squad_respond_invite"("p_invite_id" "uuid", "p_action" "text", "p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_squad_set_captain"("p_squad_id" "uuid", "p_profile_id" "uuid", "p_is_captain" boolean) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  caller uuid := auth.uid();
begin
  if caller is null then raise exception using errcode='P0001', message='auth_required'; end if;
  -- Owner or admin only
  if not exists (select 1 from public.squads s where s.id=p_squad_id and (s.owner_user_id=caller or public.is_admin(caller))) then
    raise exception using errcode='P0001', message='not_owner';
  end if;

  update public.squad_members
  set role = case when p_is_captain then 'captain' else 'member' end
  where squad_id = p_squad_id and profile_id = p_profile_id and status='active';

  if not found then raise exception using errcode='P0001', message='not_member'; end if;

  perform public.emit_event(
    case when p_is_captain then 'squad.promoted_captain' else 'squad.demoted_captain' end,
    'squad', p_squad_id, caller, jsonb_build_object('profile_id', p_profile_id)
  );

  return 'ok';
end;
$$;


ALTER FUNCTION "public"."rpc_squad_set_captain"("p_squad_id" "uuid", "p_profile_id" "uuid", "p_is_captain" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_submission_approval_state"("p_submission_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select jsonb_build_object(
    'submission', jsonb_build_object(
      'id', vs.id,
      'status', vs.status,
      'approved_venue_id', vs.approved_venue_id,
      'approved_at', vs.approved_at,
      'approved_by', vs.approved_by
    ),
    'venue', case
      when v.id is null then null
      else jsonb_build_object(
        'id', v.id,
        'name_en', v.name_en,
        'is_active', v.is_active,
        'is_verified', v.is_verified
      )
    end
  )
  from public.venue_submissions vs
  left join public.venues v
    on v.id = vs.approved_venue_id
  where vs.id = p_submission_id;
$$;


ALTER FUNCTION "public"."rpc_submission_approval_state"("p_submission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_submission_audit_timeline"("p_submission_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'action', ae.action,
        'actor_user_id', ae.actor_user_id,
        'meta', ae.meta,
        'created_at', ae.created_at
      )
      order by ae.created_at asc
    ),
    '[]'::jsonb
  )
  from public.audit_events ae
  where ae.target_id = p_submission_id;
$$;


ALTER FUNCTION "public"."rpc_submission_audit_timeline"("p_submission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_submit_venue_submission"("p_submission_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
DECLARE
  v_user_id uuid;
BEGIN
  v_user_id := auth.uid();

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  UPDATE public.venue_submissions
  SET
    status = 'pending',
    submitted_at = now(),
    updated_at = now()
  WHERE id = p_submission_id
    AND submitted_by_user_id = v_user_id
    AND status = 'draft';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Submission not in draft or not owned by user';
  END IF;
END;
$$;


ALTER FUNCTION "public"."rpc_submit_venue_submission"("p_submission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_takedown"("p_table" "text", "p_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor uuid := public.admin_actor();
begin
  if v_actor is null then raise exception using errcode='P0001', message='not_authenticated'; end if;
  if not public.is_admin(v_actor) then raise exception using errcode='P0001', message='not_admin'; end if;

  insert into public.content_enforcement(target_table, target_id, action, active, reason, created_by)
  values (p_table, p_id, 'takedown', true, p_reason, v_actor)
  on conflict do nothing;

  insert into public.moderation_actions(actor_admin_id, action_type, target_table, target_id, reason)
  values (v_actor, 'takedown', p_table, p_id, p_reason);
end;
$$;


ALTER FUNCTION "public"."rpc_takedown"("p_table" "text", "p_id" "uuid", "p_reason" "text") OWNER TO "postgres";


