CREATE OR REPLACE FUNCTION "public"."rpc_toggle_bench"("p_is_benched" boolean, "p_reason" "text" DEFAULT NULL::"text", "p_bench_until" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_hide_in_feed" boolean DEFAULT true, "p_hide_in_search" boolean DEFAULT true, "p_block_friend_requests" boolean DEFAULT true, "p_suppress_social_notifications" boolean DEFAULT false) RETURNS TABLE("out_user_id" "uuid", "out_is_benched" boolean, "out_bench_until" timestamp with time zone, "out_hide_in_feed" boolean, "out_hide_in_search" boolean, "out_block_friend_requests" boolean, "out_suppress_social_notifications" boolean, "out_updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  me uuid := auth.uid();
begin
  if me is null then
    raise exception 'not_authenticated' using errcode='P0001';
  end if;

  insert into public.user_status as s (
    user_id, is_benched, benched_at, reason, bench_until,
    hide_in_feed, hide_in_search, block_friend_requests, suppress_social_notifications
  )
  values (
    me, p_is_benched,
    case when p_is_benched then now() else null end,
    p_reason, p_bench_until,
    p_hide_in_feed, p_hide_in_search, p_block_friend_requests, p_suppress_social_notifications
  )
  on conflict (user_id)
  do update set
    is_benched = excluded.is_benched,
    benched_at = case when excluded.is_benched then coalesce(s.benched_at, now()) else null end,
    reason = excluded.reason,
    bench_until = excluded.bench_until,
    hide_in_feed = excluded.hide_in_feed,
    hide_in_search = excluded.hide_in_search,
    block_friend_requests = excluded.block_friend_requests,
    suppress_social_notifications = excluded.suppress_social_notifications,
    updated_at = now()
  returning
    s.user_id, s.is_benched, s.bench_until, s.hide_in_feed, s.hide_in_search,
    s.block_friend_requests, s.suppress_social_notifications, s.updated_at
  into
    out_user_id, out_is_benched, out_bench_until, out_hide_in_feed, out_hide_in_search,
    out_block_friend_requests, out_suppress_social_notifications, out_updated_at;

  return next;
end;
$$;


ALTER FUNCTION "public"."rpc_toggle_bench"("p_is_benched" boolean, "p_reason" "text", "p_bench_until" timestamp with time zone, "p_hide_in_feed" boolean, "p_hide_in_search" boolean, "p_block_friend_requests" boolean, "p_suppress_social_notifications" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_toggle_like"("p_post_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null then raise exception using errcode='P0001', message='auth_required'; end if;

  if exists (select 1 from public.post_likes where post_id=p_post_id and user_id=auth.uid()) then
    delete from public.post_likes where post_id=p_post_id and user_id=auth.uid();
    return 'unliked';
  else
    insert into public.post_likes(post_id, user_id) values (p_post_id, auth.uid());
    return 'liked';
  end if;
end;
$$;


ALTER FUNCTION "public"."rpc_toggle_like"("p_post_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_toggle_post_vibe"("p_post_id" "uuid", "p_vibe_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.post_vibes WHERE post_id = p_post_id AND vibe_id = p_vibe_id) THEN
    DELETE FROM public.post_vibes WHERE post_id = p_post_id AND vibe_id = p_vibe_id;
    RETURN 'removed';
  ELSE
    INSERT INTO public.post_vibes(post_id, vibe_id) VALUES (p_post_id, p_vibe_id);
    RETURN 'added';
  END IF;
END;
$$;


