$$;


ALTER FUNCTION "public"."rpc_track_event"("_event_name" "text", "_properties" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_trending_posts"("p_window_hours" integer DEFAULT 48, "p_sport" "text" DEFAULT NULL::"text", "p_venue" "uuid" DEFAULT NULL::"uuid", "p_vibe_keys" "text"[] DEFAULT NULL::"text"[], "p_limit" integer DEFAULT 20) RETURNS TABLE("id" "uuid", "kind" "text", "visibility" "text", "body" "text", "sport_key" "text", "venue_id" "uuid", "media" "jsonb", "like_count" integer, "comment_count" integer, "created_at" timestamp with time zone, "author_username" "text", "author_display_name" "text", "author_role" "text", "trend_score" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  me     uuid        := auth.uid();
  cutoff timestamptz := now() - make_interval(hours => greatest(1, coalesce(p_window_hours, 48)));
BEGIN
  IF me IS NULL THEN RAISE EXCEPTION USING errcode='P0001', message='auth_required'; END IF;
  RETURN QUERY
  WITH c AS (
    SELECT d.*, p.author_user_id
    FROM public.v_post_discovery d
    JOIN public.posts p ON p.id = d.id
    WHERE d.created_at >= cutoff
      AND (p_sport IS NULL OR d.sport_key = p_sport)
      AND (p_venue IS NULL OR d.venue_id = p_venue)
      AND (p_vibe_keys IS NULL OR EXISTS (
          SELECT 1 FROM public.post_vibes pv JOIN public.vibes v ON v.id = pv.vibe_id
          WHERE pv.post_id = d.id AND v.key = ANY(p_vibe_keys)))
  ),
  vis AS (
    SELECT c.* FROM c JOIN public.posts p ON p.id = c.id WHERE public.can_view_post(me, p)
  ),
  e AS (
    SELECT v.*,
      COALESCE((
        SELECT SUM(public._time_decay(pc.created_at, 48))
        FROM public.comments pc
        WHERE pc.parent_activity_id = v.id AND pc.created_at >= cutoff
          AND NOT pc.is_hidden_admin AND NOT pc.is_deleted
      ), 0) AS dcom,
      COALESCE((SELECT pa.like_count FROM public.public_activities pa WHERE pa.id = v.id), 0)::numeric AS dlikes
    FROM vis v
  ),
  scored AS (
    SELECT e.*,
      0.4 * public._time_decay(e.created_at, 24)
    + 0.6 * public._clamp01((e.dlikes + 2*e.dcom) / 50.0) AS trend_score
    FROM e
  )
  SELECT s.id, s.kind, s.visibility, s.body, s.sport_key, s.venue_id, s.media,
    s.like_count, s.comment_count, s.created_at,
    s.author_username, s.author_display_name, s.author_role,
    round(s.trend_score, 6)
  FROM scored s ORDER BY trend_score DESC, created_at DESC
  LIMIT greatest(1, coalesce(p_limit, 20));
END;
$$;


ALTER FUNCTION "public"."rpc_trending_posts"("p_window_hours" integer, "p_sport" "text", "p_venue" "uuid", "p_vibe_keys" "text"[], "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_unblock_user"("p_peer" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_caller UUID := auth.uid();
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  DELETE FROM public.user_blocks
  WHERE blocker_user_id = v_caller AND blocked_user_id = p_peer;
END;
$$;


ALTER FUNCTION "public"."rpc_unblock_user"("p_peer" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_unfollow_user"("p_target_profile_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_target_user uuid;
  v_count integer;
begin
  select user_id into v_target_user
  from public.profiles where id = p_target_profile_id;
  if v_target_user is null then
    raise exception using errcode='P0001', message='profile_not_found';
  end if;

  delete from public.profile_follows pf
  using public.profiles fp, public.profiles op
  where fp.id = pf.follower_profile_id
    and op.id = pf.following_profile_id
    and fp.user_id = auth.uid()
    and op.user_id = v_target_user;

  get diagnostics v_count = row_count;
  return v_count;
end$$;


ALTER FUNCTION "public"."rpc_unfollow_user"("p_target_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_unfreeze_user"("p_user_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor uuid := public.admin_actor();
begin
  if v_actor is null then
    raise exception using errcode='P0001', message='not_authenticated';
  end if;
  if not public.is_admin(v_actor) then
    raise exception using errcode='P0001', message='not_admin';
  end if;

  update public.user_freezes
     set is_frozen = false,
         lifted_at = now(),
         reason    = coalesce(p_reason, reason)
   where user_id = p_user_id;

  insert into public.moderation_actions(actor_admin_id, action_type, target_table, target_id, target_user_id, reason)
  values (v_actor, 'unfreeze_user', 'auth.users', p_user_id, p_user_id, p_reason);
end;
$$;


ALTER FUNCTION "public"."rpc_unfreeze_user"("p_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_unhide_user"("target_user" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare me uuid := auth.uid();
begin
  if me is null then raise exception using errcode='P0001', message='not_authenticated'; end if;
  perform public._assert_not_self(me, target_user);

  delete from public.restrictions
  where user_id = me and target_user_id = target_user and type='hidden';

  return true;
end;
$$;


ALTER FUNCTION "public"."rpc_unhide_user"("target_user" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_unified_search_sectioned"("p_query" "text", "p_sport_id" "uuid" DEFAULT NULL::"uuid", "p_lat" double precision DEFAULT NULL::double precision, "p_lng" double precision DEFAULT NULL::double precision, "p_radius_km" double precision DEFAULT NULL::double precision, "p_limit_per_section" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tsquery tsquery;
  v_q       text;
BEGIN
  IF p_query IS NULL OR length(trim(p_query)) < 2 THEN
    RETURN jsonb_build_object(
      'profiles','[]'::jsonb,'games','[]'::jsonb,'venues','[]'::jsonb,
      'squads','[]'::jsonb,'posts','[]'::jsonb,'meetups','[]'::jsonb,
      'challenges','[]'::jsonb,'hashtags','[]'::jsonb);
  END IF;
  v_tsquery := plainto_tsquery('simple', unaccent(p_query));
  v_q       := '%' || lower(trim(p_query)) || '%';
  RETURN jsonb_build_object(
    'hashtags', (
      SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) FROM (
        SELECT h.id, h.tag AS slug, h.display_tag, h.usage_count
        FROM public.hashtags h
        WHERE lower(h.tag) LIKE v_q
          AND (h.is_banned IS NULL OR h.is_banned = false)
          AND (h.is_searchable IS NULL OR h.is_searchable = true)
          AND (h.is_approved IS NULL OR h.is_approved = true)
        ORDER BY h.usage_count DESC NULLS LAST LIMIT p_limit_per_section) t),
    'posts', (
      SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) FROM (
        SELECT 'post' AS entity_type, p.id AS entity_id, left(p.body,80) AS title,
          p.author_display_name AS subtitle, NULL::text AS image_url,
          '/post/' || p.id AS route,
          ts_rank(p.search_tsv, v_tsquery)
          + (COALESCE(p.priority_score,0) * 0.01)
          + (SELECT COUNT(*) * 0.05 FROM public.comments pc
             WHERE pc.parent_activity_id = p.id
               AND pc.search_tsv @@ v_tsquery
               AND pc.is_deleted = FALSE AND pc.is_hidden_admin = FALSE) AS score
        FROM public.posts p
        WHERE p.search_tsv @@ v_tsquery AND p.visibility = 'public'
          AND p.is_deleted = FALSE AND p.is_hidden_admin = FALSE AND p.is_active = TRUE
        ORDER BY score DESC LIMIT p_limit_per_section) t),
    'profiles', (
      SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) FROM (
        SELECT 'profile' AS entity_type, p.user_id AS entity_id, p.id AS profile_id,
          p.display_name AS title, p.username AS subtitle, p.avatar_url AS image_url,
          p.persona_type AS profile_type, p.is_active, '/profile/' || p.username AS route,
          ts_rank(p.search_tsv, v_tsquery) AS score
        FROM public.profiles p WHERE p.search_tsv @@ v_tsquery
        ORDER BY score DESC LIMIT p_limit_per_section) t),
    'games', (
      SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) FROM (
        SELECT 'game' AS entity_type, g.id AS entity_id, g.title AS title,
          NULL::text AS subtitle, NULL::text AS image_url, '/game/' || g.id AS route,
          ts_rank(g.search_tsv, v_tsquery) + CASE WHEN g.start_at > NOW() THEN 0.2 ELSE 0 END AS score
        FROM public.games g
        WHERE g.search_tsv @@ v_tsquery AND g.listing_visibility = 'public' AND g.is_cancelled = FALSE
        ORDER BY score DESC LIMIT p_limit_per_section) t),
    'venues', (
      SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) FROM (
        SELECT 'venue' AS entity_type, v.id AS entity_id, v.name_en AS title,
          v.area AS subtitle, NULL::text AS image_url, '/venue/' || v.id AS route,
          ts_rank(v.search_tsv, v_tsquery) + (COALESCE(v.rating,0) * 0.05) AS score
        FROM public.venues v WHERE v.search_tsv @@ v_tsquery AND v.is_active = TRUE
        ORDER BY score DESC LIMIT p_limit_per_section) t),
    'squads', (
      SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) FROM (
        SELECT 'squad' AS entity_type, s.id AS entity_id, s.name AS title,
          s.city AS subtitle, s.logo_url AS image_url, '/squad/' || s.id AS route,
          ts_rank(s.search_tsv, v_tsquery) AS score
        FROM public.squads s WHERE s.search_tsv @@ v_tsquery AND s.is_active = TRUE
        ORDER BY score DESC LIMIT p_limit_per_section) t),
    'meetups', (
      SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) FROM (
        SELECT 'meetup' AS entity_type, m.id AS entity_id, m.title AS title,
          m.location_name AS subtitle, NULL::text AS image_url, '/meetup/' || m.id AS route,
          ts_rank(m.search_tsv, v_tsquery) AS score
        FROM public.meetups m WHERE m.search_tsv @@ v_tsquery
          AND m.listing_visibility = 'public' AND m.is_cancelled = FALSE
        ORDER BY score DESC LIMIT p_limit_per_section) t),
    'challenges', (
      SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) FROM (
        SELECT 'challenge' AS entity_type, c.id AS entity_id, c.title AS title,
          c.status AS subtitle, NULL::text AS image_url, '/challenge/' || c.id AS route,
          ts_rank(c.search_tsv, v_tsquery) AS score
        FROM public.challenges c WHERE c.search_tsv @@ v_tsquery AND c.is_active = TRUE
        ORDER BY score DESC LIMIT p_limit_per_section) t)
  );
END;
$$;


ALTER FUNCTION "public"."rpc_unified_search_sectioned"("p_query" "text", "p_sport_id" "uuid", "p_lat" double precision, "p_lng" double precision, "p_radius_km" double precision, "p_limit_per_section" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_unverify_profile"("p_profile_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor uuid := public.admin_actor();
  uid     uuid;
begin
  if v_actor is null then raise exception using errcode='P0001', message='not_authenticated'; end if;
  if not public.is_admin(v_actor) then raise exception using errcode='P0001', message='not_admin'; end if;

  insert into public.profile_verifications(profile_id, verified, verified_at, verified_by, reason)
  values (p_profile_id, false, now(), v_actor, p_reason)
  on conflict (profile_id) do update
    set verified    = false,
        verified_at = now(),
        verified_by = v_actor,
        reason      = coalesce(p_reason, public.profile_verifications.reason);

  select user_id into uid from public.profiles where id = p_profile_id;

  insert into public.moderation_actions(actor_admin_id, action_type, target_table, target_id, target_user_id, reason)
  values (v_actor, 'unverify_profile', 'profiles', p_profile_id, uid, p_reason);
end;
$$;


ALTER FUNCTION "public"."rpc_unverify_profile"("p_profile_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_update_game"("p_game_id" "uuid", "p_start_at" timestamp with time zone, "p_end_at" timestamp with time zone, "p_title" "text" DEFAULT NULL::"text", "p_venue_space_id" "uuid" DEFAULT NULL::"uuid", "p_clear_venue" boolean DEFAULT false, "p_listing_visibility" "text" DEFAULT NULL::"text", "p_join_policy" "text" DEFAULT NULL::"text", "p_allow_spectators" boolean DEFAULT NULL::boolean, "p_allows_waitlist" boolean DEFAULT NULL::boolean, "p_min_skill" integer DEFAULT NULL::integer, "p_max_skill" integer DEFAULT NULL::integer, "p_clear_skill" boolean DEFAULT false, "p_rules" "jsonb" DEFAULT NULL::"jsonb", "p_min_players" integer DEFAULT NULL::integer, "p_max_players" integer DEFAULT NULL::integer) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_roster_count integer;
begin
  if p_end_at <= p_start_at then
    raise exception using errcode='P0001', message='invalid_time_range';
  end if;
  if p_max_players is not null and p_max_players < 1 then
    raise exception using errcode='P0001', message='invalid_max_players';
  end if;
  if p_min_players is not null and p_min_players < 1 then
    raise exception using errcode='P0001', message='invalid_min_players';
  end if;
  if p_min_players is not null and p_max_players is not null
     and p_min_players > p_max_players then
    raise exception using errcode='P0001', message='invalid_player_range';
  end if;

  select count(*) into v_roster_count
  from public.game_roster
  where game_id = p_game_id and status = 'active';

  update public.games g
  set start_at           = p_start_at,
      end_at             = p_end_at,
      title              = coalesce(nullif(p_title, ''), g.title),
      venue_space_id     = case
                             when p_clear_venue then null
                             else coalesce(p_venue_space_id, g.venue_space_id)
                           end,
      listing_visibility = coalesce(p_listing_visibility, g.listing_visibility),
      join_policy        = coalesce(p_join_policy, g.join_policy),
      allow_spectators   = coalesce(p_allow_spectators, g.allow_spectators),
      allows_waitlist    = coalesce(p_allows_waitlist, g.allows_waitlist),
      min_skill          = case when p_clear_skill then null
                                else coalesce(p_min_skill, g.min_skill) end,
      max_skill          = case when p_clear_skill then null
                                else coalesce(p_max_skill, g.max_skill) end,
      capacity           = greatest(
                             coalesce(p_max_players, g.capacity),
                             v_roster_count
                           ),
      rules              = coalesce(p_rules, g.rules, '{}'::jsonb)
                           || case when p_min_players is not null
                                then jsonb_build_object('min_players', p_min_players)
                                else '{}'::jsonb end
                           || case when p_max_players is not null
                                then jsonb_build_object('max_players', p_max_players)
                                else '{}'::jsonb end
  where g.id = p_game_id
    and g.is_cancelled = false
    and g.end_at > now()
    and (g.creator_user_id = auth.uid() or public.is_admin(auth.uid()));

  if not found then
    raise exception using errcode='P0001', message='not_host_or_not_found';
  end if;

  return 'updated';
end$$;


ALTER FUNCTION "public"."rpc_update_game"("p_game_id" "uuid", "p_start_at" timestamp with time zone, "p_end_at" timestamp with time zone, "p_title" "text", "p_venue_space_id" "uuid", "p_clear_venue" boolean, "p_listing_visibility" "text", "p_join_policy" "text", "p_allow_spectators" boolean, "p_allows_waitlist" boolean, "p_min_skill" integer, "p_max_skill" integer, "p_clear_skill" boolean, "p_rules" "jsonb", "p_min_players" integer, "p_max_players" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_username_availability"("p_username" "text") RETURNS TABLE("username_norm" "text", "available" boolean, "reason" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  u text;
  avail boolean;
begin
  u := public.normalize_username(p_username);

  if exists (select 1 from public.username_banned b where b.username = u) then
    available := false; reason := 'banned'; username_norm := u;
    return next;
    return;
  end if;

  if exists (
    select 1 from public.username_reserved r
    where r.username = u and (r."until" is null or r."until" > now())
  ) then
    available := false; reason := 'reserved'; username_norm := u;
    return next;
    return;
  end if;

  if exists (
    select 1 from public.username_registry reg
    where reg.username = u and reg.released_at is null
  ) then
    available := false; reason := 'taken'; username_norm := u;
    return next;
    return;
  end if;

  available := true; reason := 'available'; username_norm := u;
  return next;
end;
$$;


ALTER FUNCTION "public"."rpc_username_availability"("p_username" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rpc_username_availability"("p_username" "text") IS 'Check availability without leaking owners; returns normalized value and reason.';



CREATE OR REPLACE FUNCTION "public"."rpc_username_claim"("p_profile_type" "text", "p_username" "text") RETURNS TABLE("claimed_username" "text", "profile_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  u   text := public.normalize_username(p_username);
  me  uuid := auth.uid();
  pid uuid;
  my_other_username text;
begin
  if p_profile_type not in ('player','organiser') then
    raise exception using errcode = 'P0001', message = 'profile_type_invalid';
  end if;

  -- ensure profile exists and is active
  pid := public.assert_profile_exists(me, p_profile_type);
  if pid is null then
    raise exception using errcode = 'P0001', message = 'profile_missing';
  end if;

  -- bans
  if exists (select 1 from public.username_banned  b where b.username = u) then
    insert into public.username_attempts(user_id, attempted_username, ok, reason)
    values (me, u, false, 'banned');
    raise exception using errcode = 'P0001', message = 'username_banned';
  end if;

  -- reservations
  if exists (
    select 1
    from public.username_reserved r
    where r.username = u
      and (r."until" is null or r."until" > now())
  ) then
    insert into public.username_attempts(user_id, attempted_username, ok, reason)
    values (me, u, false, 'reserved');
    raise exception using errcode = 'P0001', message = 'username_reserved';
  end if;

  -- rate limit
  if not public.can_user_rename(me) then
    insert into public.username_attempts(user_id, attempted_username, ok, reason)
    values (me, u, false, 'rate_limited');
    raise exception using errcode = 'P0001', message = 'rename_rate_limited';
  end if;

  -- must differ from my other profile's username
  select p.username::text
    into my_other_username
  from public.profiles p
  where p.user_id = me
    and p.profile_type <> p_profile_type
    and p.username is not null
  limit 1;

  if my_other_username is not null and lower(my_other_username) = u then
    insert into public.username_attempts(user_id, attempted_username, ok, reason)
    values (me, u, false, 'same_as_other_profile');
    raise exception using errcode = 'P0001', message = 'username_must_differ_across_profiles';
  end if;

  -- try to claim (global uniqueness via partial unique index)
  insert into public.username_registry(username, owner_user_id, source)
  values (u, me, 'manual')
  on conflict (username) where released_at is null
  do nothing;

  -- confirm I own it
  if not exists (
    select 1 from public.username_registry reg
    where reg.username = u
      and reg.released_at is null
      and reg.owner_user_id = me
  ) then
    insert into public.username_attempts(user_id, attempted_username, ok, reason)
    values (me, u, false, 'taken');
    raise exception using errcode = 'P0001', message = 'username_taken';
  end if;

  -- update profile (history captured by trigger)
  update public.profiles
     set username = u
   where id = pid;

  -- success telemetry
  insert into public.username_attempts(user_id, attempted_username, ok, reason)
  values (me, u, true, 'claimed');

  claimed_username := u;
  profile_id       := pid;
  return next;
end;
$$;


ALTER FUNCTION "public"."rpc_username_claim"("p_profile_type" "text", "p_username" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_username_release"("p_profile_type" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  pid uuid;
  uname text;
begin
  if p_profile_type not in ('player','organiser') then
    raise exception using errcode = 'P0001', message = 'profile_type_invalid';
  end if;

  pid := public.assert_profile_exists(me, p_profile_type);
  if pid is null then
    raise exception using errcode = 'P0001', message = 'profile_missing';
  end if;

  select username::text into uname from public.profiles where id = pid;
  if uname is null then
    return; -- nothing to release
  end if;

  -- clear profile handle
  update public.profiles set username = null where id = pid;

  -- mark registry as released (historical row)
  update public.username_registry
  set released_at = now()
  where username = uname and owner_user_id = me and released_at is null;

  -- history row is auto-written by username trigger (old=new? handled above for update)
  insert into public.username_changes(user_id, old_username, new_username, profile_type)
  values (me, uname, null, p_profile_type);

  -- attempt log
  insert into public.username_attempts(user_id, attempted_username, ok, reason)
  values (me, uname, true, 'released');
end;
$$;


ALTER FUNCTION "public"."rpc_username_release"("p_profile_type" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rpc_username_release"("p_profile_type" "text") IS 'Releases current username for the given profile; discouraged for squatting—enable only if product allows.';



CREATE OR REPLACE FUNCTION "public"."rpc_username_suggest"("p_base" "text", "p_profile_type" "text" DEFAULT 'player'::"text", "p_city" "text" DEFAULT NULL::"text", "p_sport" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 3) RETURNS SETOF "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  base text := regexp_replace(lower(coalesce(p_base,'')), '[^a-z0-9_]', '_', 'g');
  sfx  text[];
  candidate text;
  norm text;
  out_count int := 0;

  -- CHANGE THIS ONE LINE depending on where pgcrypto is installed:
  -- If pg_extension shows schema = 'public', keep public.digest below.
  -- If it shows 'extensions', replace public.digest with extensions.digest.
seed int := (
  'x' || substr(pg_catalog.encode(extensions.digest(auth.uid()::text, 'sha256'), 'hex'), 1, 8)
)::bit(32)::int;

  i int := 0;
begin
  -- ... your original body stays the same ...
  return;
end;
$$;


ALTER FUNCTION "public"."rpc_username_suggest"("p_base" "text", "p_profile_type" "text", "p_city" "text", "p_sport" "text", "p_limit" integer) OWNER TO "postgres";


