CREATE OR REPLACE FUNCTION "public"."rpc_verify_profile"("p_profile_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor uuid := public.admin_actor();
  uid     uuid;
begin
  if v_actor is null then raise exception using errcode='P0001', message='not_authenticated'; end if;
  if not public.is_admin(v_actor) then raise exception using errcode='P0001', message='not_admin'; end if;

  insert into public.profile_verifications(profile_id, verified, verified_at, verified_by, reason)
  values (p_profile_id, true, now(), v_actor, p_reason)
  on conflict (profile_id) do update
    set verified    = true,
        verified_at = now(),
        verified_by = v_actor,
        reason      = coalesce(p_reason, public.profile_verifications.reason);

  select user_id into uid from public.profiles where id = p_profile_id;

  insert into public.moderation_actions(actor_admin_id, action_type, target_table, target_id, target_user_id, reason)
  values (v_actor, 'verify_profile', 'profiles', p_profile_id, uid, p_reason);
end;
$$;


ALTER FUNCTION "public"."rpc_verify_profile"("p_profile_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rule_on_cooldown"("p_rule_key" "text", "p_user" "uuid", "p_window_seconds" integer) RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists(
    select 1
    from public.point_ledger
    where user_id = p_user
      and rule_key = p_rule_key
      and created_at >= (now() - make_interval(secs => greatest(p_window_seconds,0)))
  )
$$;


ALTER FUNCTION "public"."rule_on_cooldown"("p_rule_key" "text", "p_user" "uuid", "p_window_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_badge_engine"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  r record;
  awarded int;
  results jsonb := '{}'::jsonb;
begin
  for r in select badge_key, rule_type, params from public.badge_rules where is_active loop
    if r.rule_type = 'user_metric' then
      awarded := public.award_user_metric_badge(r.badge_key, r.params);
    elsif r.rule_type = 'host_weekly' then
      awarded := public.award_top_host_weekly(r.badge_key, r.params);
    elsif r.rule_type = 'venue_dim_top' then
      awarded := public.award_venue_dim_top(r.badge_key, r.params);
    else
      awarded := 0;
    end if;

    results := results || jsonb_build_object(r.badge_key, awarded);
  end loop;
  return results;
end;
$$;


ALTER FUNCTION "public"."run_badge_engine"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."schedule_game_reminders_for_user"("p_user" "uuid", "p_game_id" "uuid", "p_start_at" timestamp with time zone, "p_payload" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  cnt int := 0;
  t timestamptz;
  due timestamptz;
  offs interval[];
  off interval;
begin
  offs := ARRAY['24 hours'::interval, '2 hours'::interval, '30 minutes'::interval];

  foreach off in array offs loop
    t := p_start_at - off;

    -- If within quiet hours, nudge to end of quiet window (simple heuristic)
    if public.is_quiet_hour(p_user, t) then
      -- compute user local tz from settings
      declare tz text := coalesce((select timezone from public.user_settings where user_id=p_user),'Asia/Dubai');
              qend time := (select quiet_end from public.user_settings where user_id=p_user);
              local_date date := (t at time zone tz)::date;
      begin
        if qend is not null then
          due := (local_date::timestamptz + qend) at time zone tz;
        else
          due := t;
        end if;
      end;
    else
      due := t;
    end if;

    insert into public.notification_jobs(user_id, type_key, payload, due_at)
    values (p_user, 'game.reminder', jsonb_build_object('game_id', p_game_id)::jsonb || p_payload, due)
    on conflict do nothing;
    cnt := cnt + 1;
  end loop;

  return cnt;
end;
$$;


ALTER FUNCTION "public"."schedule_game_reminders_for_user"("p_user" "uuid", "p_game_id" "uuid", "p_start_at" timestamp with time zone, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_areas"("p_query" "text", "p_limit" integer DEFAULT 10) RETURNS TABLE("id" "uuid", "name" "text", "district" "text", "city" "text", "country" "text", "center_lat" double precision, "center_lng" double precision, "is_verified" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT id, name, district, city, country, center_lat, center_lng, is_verified
  FROM public.areas
  WHERE is_active = true
    AND (
      name     ILIKE '%' || p_query || '%' OR
      district ILIKE '%' || p_query || '%' OR
      city     ILIKE '%' || p_query || '%'
    )
  ORDER BY
    is_verified DESC,
    CASE
      WHEN lower(name) = lower(p_query)            THEN 0
      WHEN lower(name) LIKE lower(p_query) || '%'  THEN 1
      ELSE 2
    END,
    name ASC
  LIMIT p_limit;
$$;


ALTER FUNCTION "public"."search_areas"("p_query" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_venues_with_filters"("p_lat" double precision DEFAULT NULL::double precision, "p_lng" double precision DEFAULT NULL::double precision, "p_radius_km" double precision DEFAULT 10, "p_sport" "text" DEFAULT NULL::"text", "p_price_min" numeric DEFAULT NULL::numeric, "p_price_max" numeric DEFAULT NULL::numeric, "p_is_indoor" boolean DEFAULT NULL::boolean, "p_surface_type" "text" DEFAULT NULL::"text", "p_min_rating" numeric DEFAULT NULL::numeric, "p_amenities" "text"[] DEFAULT NULL::"text"[], "p_city" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "name_en" "text", "address_line1" "text", "city" "text", "lat" double precision, "lng" double precision, "is_indoor" boolean, "surface_type" "text", "min_price_per_hour" numeric, "max_price_per_hour" numeric, "rating" numeric, "rating_count" integer, "amenities" "text"[], "distance_km" double precision)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    v.id,
    v.name_en,
    v.address_line1,
    v.city,
    v.lat,
    v.lng,
    v.is_indoor,
    v.surface_type,
    v.min_price_per_hour,
    v.max_price_per_hour,
    v.rating,
    v.rating_count,
    v.amenities,
    CASE 
      WHEN p_lat IS NOT NULL AND p_lng IS NOT NULL THEN
        -- Haversine distance calculation (approximate)
        6371 * acos(
          cos(radians(p_lat)) * 
          cos(radians(v.lat)) * 
          cos(radians(v.lng) - radians(p_lng)) + 
          sin(radians(p_lat)) * 
          sin(radians(v.lat))
        )
      ELSE NULL
    END AS distance_km
  FROM venues v
  LEFT JOIN venue_spaces vs ON vs.venue_id = v.id
  WHERE 
    v.is_active = true
    AND (p_sport IS NULL OR vs.sport = p_sport)
    AND (p_city IS NULL OR v.city = p_city)
    AND (p_price_min IS NULL OR v.max_price_per_hour >= p_price_min)
    AND (p_price_max IS NULL OR v.min_price_per_hour <= p_price_max)
    AND (p_is_indoor IS NULL OR v.is_indoor = p_is_indoor)
    AND (p_surface_type IS NULL OR v.surface_type = p_surface_type)
    AND (p_min_rating IS NULL OR v.rating >= p_min_rating)
    AND (p_amenities IS NULL OR v.amenities && p_amenities)
    AND (
      p_lat IS NULL OR 
      p_lng IS NULL OR
      -- Distance filter (using bounding box approximation)
      v.lat BETWEEN p_lat - (p_radius_km / 111.0) AND p_lat + (p_radius_km / 111.0)
      AND v.lng BETWEEN p_lng - (p_radius_km / (111.0 * cos(radians(p_lat)))) 
                     AND p_lng + (p_radius_km / (111.0 * cos(radians(p_lat))))
    )
  GROUP BY v.id, v.name_en, v.address_line1, v.city, v.lat, v.lng, 
           v.is_indoor, v.surface_type, v.min_price_per_hour, v.max_price_per_hour,
           v.rating, v.rating_count, v.amenities
  ORDER BY distance_km NULLS LAST, v.rating DESC;
END;
$$;


ALTER FUNCTION "public"."search_venues_with_filters"("p_lat" double precision, "p_lng" double precision, "p_radius_km" double precision, "p_sport" "text", "p_price_min" numeric, "p_price_max" numeric, "p_is_indoor" boolean, "p_surface_type" "text", "p_min_rating" numeric, "p_amenities" "text"[], "p_city" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_vibe_request"("p_to_user" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  a uuid; b uuid; existing record;
begin
  if me is null then raise exception using errcode='P0001', message='auth_required'; end if;
  if p_to_user = me then raise exception using errcode='P0001', message='cannot_vibe_self'; end if;

  select a,b into a,b from public._pair(me, p_to_user);

  -- Upsert edge
  select * into existing from public.friend_edges
   where least(user_a,user_b)=a and greatest(user_a,user_b)=b;

  if existing is null then
    insert into public.friend_edges(user_a,user_b,status,requested_by,responded_by)
    values (a,b,'pending',me,null);
  else
    -- If already accepted → noop; if pending and I am not the requester → noop (await response)
    if existing.status = 'accepted' then
      return 'already_synced';
    elsif existing.status = 'pending' then
      return case when existing.requested_by = me then 'already_requested' else 'awaiting_response' end;
    else
      -- rejected/removed → reopen as pending
      update public.friend_edges
      set status='pending', requested_by=me, responded_by=null, updated_at=now()
      where id=existing.id;
    end if;
  end if;

  insert into public.friend_requests_audit(from_user,to_user,action,edge_id)
  values (me, p_to_user, 'requested',
          (select id from public.friend_edges where least(user_a,user_b)=a and greatest(user_a,user_b)=b));

  -- TODO: enqueue notification: friend.requested
  return 'ok';
end;
$$;


ALTER FUNCTION "public"."send_vibe_request"("p_to_user" "uuid") OWNER TO "postgres";


