CREATE OR REPLACE FUNCTION "public"."set_hidden_mode"("p_target_user" "uuid", "p_enable" boolean, "p_reason" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare me uuid := auth.uid();
begin
  if me is null then raise exception using errcode='P0001', message='auth_required'; end if;
  if p_target_user = me then raise exception using errcode='P0001', message='cannot_hide_self'; end if;

  if p_enable then
    insert into public.user_hidden_modes(owner_user_id, target_user_id, mode, reason)
    values (me, p_target_user, 'hidden', left(p_reason, 200))
    on conflict (owner_user_id, target_user_id)
      do update set mode='hidden', reason=excluded.reason;
    -- TODO: downstream effects: filter in feeds, DM, invites
    return 'hidden_enabled';
  else
    delete from public.user_hidden_modes where owner_user_id=me and target_user_id=p_target_user;
    return 'hidden_disabled';
  end if;
end;
$$;


