CREATE TABLE IF NOT EXISTS "public"."game_settlements" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "game_id" "uuid" NOT NULL,
    "organiser_user_id" "uuid" NOT NULL,
    "sport" "text" NOT NULL,
    "gross_collected_aed" numeric(12,2) NOT NULL,
    "app_fee_rate" numeric(5,2) NOT NULL,
    "app_fee_aed" numeric(12,2) NOT NULL,
    "organiser_earnings_aed" numeric(12,2) NOT NULL,
    "status" "public"."settlement_status" DEFAULT 'pending'::"public"."settlement_status" NOT NULL,
    "notes" "text",
    "meta" "jsonb",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "settled_at" timestamp with time zone,
    CONSTRAINT "game_settlements_gross_collected_aed_check" CHECK (("gross_collected_aed" >= (0)::numeric))
);


ALTER TABLE "public"."game_settlements" OWNER TO "postgres";


COMMENT ON TABLE "public"."game_settlements" IS 'One settlement snapshot per game. When settled, credits organiser wallet and posts app fee (optional internal account).';



CREATE OR REPLACE FUNCTION "public"."settle_game"("p_game_id" "uuid", "p_organiser_user_id" "uuid", "p_sport" "text", "p_gross_collected" numeric, "p_finalize" boolean DEFAULT true) RETURNS "public"."game_settlements"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  me uuid := auth.uid();
  r record;
  fee_rate numeric(5,2);
  min_fee numeric(12,2);
  max_fee numeric(12,2);
  fee numeric(12,2);
  earnings numeric(12,2);
  gs public.game_settlements;
begin
  if me is null then
    raise exception using errcode='P0001', message='auth_required';
  end if;

  -- Only admin or organiser can settle
  if not (public.is_admin(me) or me = p_organiser_user_id) then
    raise exception using errcode='P0001', message='forbidden';
  end if;

  if p_gross_collected is null or p_gross_collected < 0 then
    raise exception using errcode='P0001', message='invalid_gross';
  end if;

  -- fetch correct commission rule
  select * into r
  from public.resolve_commission(p_organiser_user_id, p_sport, now());

  fee_rate := coalesce(r.rate, 10.00);
  min_fee  := coalesce(r.min_fee, 0);
  max_fee  := coalesce(r.max_fee, null);

  fee := round(p_gross_collected * (fee_rate/100.0), 2);
  if fee < min_fee then fee := min_fee; end if;
  if max_fee is not null and fee > max_fee then fee := max_fee; end if;

  earnings := round(p_gross_collected - fee, 2);

  insert into public.game_settlements(
      game_id,
      organiser_user_id,
      sport,
      gross_collected_aed,
      app_fee_rate,
      app_fee_aed,
      organiser_earnings_aed,
      status,
      meta
  )
  values (
      p_game_id,
      p_organiser_user_id,
      p_sport,
      p_gross_collected,
      fee_rate,
      fee,
      earnings,
      case when p_finalize then 'settled' else 'pending' end,
      jsonb_build_object('resolved_at', now())
  )
  on conflict (game_id) do update
    set gross_collected_aed   = excluded.gross_collected_aed,
        app_fee_rate          = excluded.app_fee_rate,
        app_fee_aed           = excluded.app_fee_aed,
        organiser_earnings_aed = excluded.organiser_earnings_aed,
        status                 = excluded.status,
        meta                   = excluded.meta,
        settled_at             = case when excluded.status='settled' then now() else null end
  returning * into gs;

  -- finalize → post wallet credit
  if p_finalize then
    insert into public.wallet_ledger(
      user_id,
      direction,
      amount_aed,
      status,
      ref_type,
      ref_id,
      memo,
      meta
    )
    values (
      p_organiser_user_id,
      'credit',
      gs.organiser_earnings_aed,
      'posted',
      'game_settlement',
      gs.id,
      'Game settlement earnings',
      jsonb_build_object(
        'game_id', gs.game_id,
        'sport', gs.sport
      )
    );
  end if;

  return gs;
end;
$$;


ALTER FUNCTION "public"."settle_game"("p_game_id" "uuid", "p_organiser_user_id" "uuid", "p_sport" "text", "p_gross_collected" numeric, "p_finalize" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."should_bypass_quiet_hours"("p_user_id" "uuid", "p_priority" "public"."notify_priority") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_plan text;
BEGIN

    SELECT plan_key
    INTO v_plan
    FROM public.user_subscriptions
    WHERE user_id = p_user_id
      AND is_active = true
    LIMIT 1;

    -- Only Prime can bypass
    IF v_plan = 'prime'
       AND p_priority = 'high'
    THEN
        RETURN true;
    END IF;

    RETURN false;

END;
$$;


