CREATE OR REPLACE FUNCTION "public"."switch_active_profile"("p_profile_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
    -- Deactivate all profiles for this user
    UPDATE public.profiles
    SET is_active = false
    WHERE user_id = auth.uid();

    -- Activate selected profile
    UPDATE public.profiles
    SET is_active = true
    WHERE id = p_profile_id
      AND user_id = auth.uid();

    -- Optional safety check
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Invalid profile for this user';
    END IF;
END;
$$;


ALTER FUNCTION "public"."switch_active_profile"("p_profile_id" "uuid") OWNER TO "postgres";


