    SELECT
      ST_Y(location::geometry),
      ST_X(location::geometry)
    INTO NEW.lat, NEW.lng
    FROM geo_locations
    WHERE id = NEW.geo_location_id;
  END IF;

  RETURN NEW;
END;
$$;


