CREATE OR REPLACE FUNCTION "public"."sync_reaction_breakdown"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    target_post    uuid;
    total_count    integer;
    breakdown_json jsonb;
BEGIN
    target_post := COALESCE(NEW.parent_activity_id, OLD.parent_activity_id);

    SELECT COUNT(*) INTO total_count
    FROM public.reactions WHERE parent_activity_id = target_post;

    SELECT jsonb_object_agg(v.key, cnt) INTO breakdown_json
    FROM (
        SELECT vibe_id, COUNT(*) AS cnt
        FROM public.reactions WHERE parent_activity_id = target_post
        GROUP BY vibe_id
    ) r
    JOIN public.vibes v ON v.id = r.vibe_id;

    UPDATE public.posts
    SET reaction_breakdown = jsonb_build_object(
        'total', COALESCE(total_count, 0),
        'breakdown', COALESCE(breakdown_json, '{}'::jsonb)
    )
    WHERE id = target_post;

    RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."sync_reaction_breakdown"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."time_decay_score"("p_ts" timestamp with time zone) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select case 
    when p_ts is null then 0
    else exp(-extract(epoch from (now() - p_ts)) / 86400.0)
  end;
$$;


ALTER FUNCTION "public"."time_decay_score"("p_ts" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toggle_venue_favorite"("venue_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  perform public.toggle_venue_favorite($1, auth.uid());
end;
$_$;


ALTER FUNCTION "public"."toggle_venue_favorite"("venue_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toggle_venue_favorite"("venue_id" "uuid", "user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if $2 <> auth.uid() then
    raise exception 'Unauthorized';
  end if;

  if exists (
    select 1
    from public.venue_favorites vf
    where vf.venue_id = $1
      and vf.user_id = $2
  ) then
    delete from public.venue_favorites vf
    where vf.venue_id = $1
      and vf.user_id = $2;
  else
    -- Insert without ON CONFLICT targets (avoids user_id ambiguity)
    insert into public.venue_favorites
    select gen_random_uuid(), $2, $1, now()
    where not exists (
      select 1
      from public.venue_favorites vf
      where vf.venue_id = $1
        and vf.user_id = $2
    );
  end if;
end;
$_$;


ALTER FUNCTION "public"."toggle_venue_favorite"("venue_id" "uuid", "user_id" "uuid") OWNER TO "postgres";


