CREATE OR REPLACE FUNCTION "public"."trg_fn_venues_set_geo"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_geo_id uuid;
BEGIN
  -- Only run when lat/lng are provided and geo_location_id is not already set
  IF NEW.lat IS NOT NULL AND NEW.lng IS NOT NULL AND NEW.geo_location_id IS NULL THEN
    INSERT INTO geo_locations (location, area_id, geohash)
    VALUES (
      ST_SetSRID(ST_MakePoint(NEW.lng, NEW.lat), 4326)::geography,
      NEW.area_id,
      encode(sha256((NEW.lat::text || ',' || NEW.lng::text)::bytea), 'hex')
    )
    RETURNING id INTO v_geo_id;

    NEW.geo_location_id := v_geo_id;
  END IF;
  RETURN NEW;
END;
$$;


