CREATE OR REPLACE FUNCTION "public"."trg_news_comment_count"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE public.news SET comment_count = comment_count + 1 WHERE id = NEW.news_id;
  ELSIF TG_OP = 'DELETE'
     OR (TG_OP = 'UPDATE' AND NEW.is_deleted AND NOT OLD.is_deleted) THEN
    UPDATE public.news
    SET comment_count = GREATEST(comment_count - 1, 0)
    WHERE id = COALESCE(NEW.news_id, OLD.news_id);
  END IF;
  RETURN NULL;
END;
$$;


