CREATE OR REPLACE FUNCTION "public"."trg_post_reaction_breakdown"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_vibe_id  text;
  v_post_id  uuid;
  v_current  jsonb;
  v_bd       jsonb;
  v_new_val  int;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_vibe_id := NEW.vibe_id::text;
    v_post_id := NEW.parent_activity_id;
    SELECT COALESCE(reaction_breakdown, '{"breakdown":{}}'::jsonb)
      INTO v_current FROM public.posts WHERE id = v_post_id;
    IF v_current IS NULL THEN RETURN NULL; END IF;  -- parent is news, not a post
    v_bd := COALESCE(v_current->'breakdown', '{}'::jsonb);
    v_new_val := COALESCE((v_bd->>v_vibe_id)::int, 0) + 1;
    v_bd := jsonb_set(v_bd, ARRAY[v_vibe_id], to_jsonb(v_new_val));
    UPDATE public.posts SET reaction_breakdown = jsonb_set(v_current, '{breakdown}', v_bd) WHERE id = v_post_id;
  ELSIF TG_OP = 'DELETE' THEN
    v_vibe_id := OLD.vibe_id::text;
    v_post_id := OLD.parent_activity_id;
    SELECT COALESCE(reaction_breakdown, '{"breakdown":{}}'::jsonb)
      INTO v_current FROM public.posts WHERE id = v_post_id;
    IF v_current IS NULL THEN RETURN NULL; END IF;
    v_bd := COALESCE(v_current->'breakdown', '{}'::jsonb);
    v_new_val := GREATEST(COALESCE((v_bd->>v_vibe_id)::int, 0) - 1, 0);
    IF v_new_val = 0 THEN v_bd := v_bd - v_vibe_id;
    ELSE v_bd := jsonb_set(v_bd, ARRAY[v_vibe_id], to_jsonb(v_new_val));
    END IF;
    UPDATE public.posts SET reaction_breakdown = jsonb_set(v_current, '{breakdown}', v_bd) WHERE id = v_post_id;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."trg_post_reaction_breakdown"() OWNER TO "postgres";


