CREATE OR REPLACE FUNCTION "public"."trg_post_search_refresh_from_vibes"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  perform 1;
  if tg_op = 'INSERT' then
    update public.posts set search_tsv = public._post_search_vector(new.post_id) where id = new.post_id;
    return new;
  else
    update public.posts set search_tsv = public._post_search_vector(old.post_id) where id = old.post_id;
    return old;
  end if;
end $$;


ALTER FUNCTION "public"."trg_post_search_refresh_from_vibes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_post_vibes_check"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  k text;
BEGIN
  SELECT kind INTO k FROM public.posts
  WHERE id = (CASE WHEN TG_OP='INSERT' THEN NEW.post_id ELSE OLD.post_id END);

  IF TG_OP = 'INSERT' THEN
    IF NOT public._post_vibe_kind_ok(k, NEW.vibe_id) THEN
      RAISE EXCEPTION USING errcode='P0001', message='vibe_not_compatible_with_post_kind';
    END IF;
    RETURN NEW;
  ELSE
    RETURN OLD;
  END IF;
END
$$;


