CREATE OR REPLACE FUNCTION "public"."trg_squads_owner_default"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Try created_by_profile_id first; otherwise pick the user's best profile (prefer player).
  NEW.owner_profile_id := COALESCE(
    NEW.owner_profile_id,
    NEW.created_by_profile_id,
    (SELECT pr.id
     FROM public.profiles pr
     WHERE pr.user_id = NEW.created_by_user_id
     ORDER BY (pr.profile_type='player') DESC
     LIMIT 1)
  );

  RETURN NEW;
END$$;


ALTER FUNCTION "public"."trg_squads_owner_default"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_squads_owner_defaults"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Owner user defaults to the creator
  NEW.owner_user_id := COALESCE(NEW.owner_user_id, NEW.created_by_user_id);

  -- Owner profile: explicit > created_by_profile > best profile for owner_user
  NEW.owner_profile_id := COALESCE(
    NEW.owner_profile_id,
    NEW.created_by_profile_id,
    (
      SELECT pr.id
      FROM public.profiles pr
      WHERE pr.user_id = NEW.owner_user_id
      ORDER BY (pr.profile_type = 'player') DESC
      LIMIT 1
    )
  );

  RETURN NEW;
END$$;


ALTER FUNCTION "public"."trg_squads_owner_defaults"() OWNER TO "postgres";


