CREATE OR REPLACE FUNCTION "public"."trg_validate_circle_member"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_owner_profile_id uuid;
BEGIN
    -- Get the circle owner
    SELECT owner_profile_id INTO v_owner_profile_id
    FROM public.circles
    WHERE id = NEW.circle_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Circle not found';
    END IF;

    -- If adding the owner themselves, always allow
    IF NEW.member_profile_id = v_owner_profile_id THEN
        RETURN NEW;
    END IF;

    -- Otherwise, the member profile must follow the circle owner
    IF NOT EXISTS (
        SELECT 1
        FROM public.profile_follows pf
        WHERE pf.follower_profile_id = NEW.member_profile_id
          AND pf.following_profile_id = v_owner_profile_id
    ) THEN
        RAISE EXCEPTION 'Only followers of the circle owner can be added to a circle'
            USING ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trg_validate_circle_member"() OWNER TO "postgres";


