CREATE OR REPLACE FUNCTION "public"."trg_welcome_notify"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Once per user: a user may have multiple profiles, and we never re-welcome.
  IF NOT EXISTS (
    SELECT 1 FROM public.notifications
    WHERE to_user_id = NEW.user_id AND kind_key = 'auth.welcome'
  ) THEN
    BEGIN
      INSERT INTO public.notifications (
        to_user_id, kind_key, title, body, action_route, context, created_at
      )
      VALUES (
        NEW.user_id,
        'auth.welcome',
        'Welcome to Dabbler! 🎉',
        'Find games, join events, and connect with players near you.',
        '/home',
        '{}'::jsonb,
        now()
      );
    EXCEPTION WHEN OTHERS THEN
      -- Never let a welcome failure break user creation.
      RAISE WARNING 'trg_welcome_notify failed for user %: %', NEW.user_id, SQLERRM;
    END;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trg_welcome_notify"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trgfn_block_follow_if_blocked"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM public.user_blocks b
    JOIN public.profiles p_follower ON p_follower.id = NEW.follower_profile_id
    JOIN public.profiles p_following ON p_following.id = NEW.following_profile_id
    WHERE
      (b.blocker_user_id = p_follower.user_id AND b.blocked_user_id = p_following.user_id)
      OR
      (b.blocker_user_id = p_following.user_id AND b.blocked_user_id = p_follower.user_id)
  ) THEN
    RAISE EXCEPTION 'Follow not allowed due to blocking';
  END IF;

  RETURN NEW;
END;
$$;


