CREATE OR REPLACE FUNCTION "public"."trgfn_block_variant_as_sport"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Only enforce variant rules if column exists
  IF EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_schema = TG_TABLE_SCHEMA
      AND table_name = TG_TABLE_NAME
      AND column_name = 'variant'
  ) THEN
    IF NEW.variant IS NOT NULL
       AND NEW.variant <> NEW.sport_key THEN
      RAISE EXCEPTION
        USING
          errcode = 'P0001',
          message = 'variant_cannot_be_registered_as_sport';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


