    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op='INSERT' then
    perform public.emit_event('challenge.created','challenge', new.id, new.owner_user_id,
                              jsonb_build_object('type', new.type));
  elsif tg_op='UPDATE' then
    if new.status<>old.status then
      perform public.emit_event('challenge.status_changed','challenge', new.id, auth.uid(),
                                jsonb_build_object('status', new.status));
    end if;
  end if;
  return null; -- AFTER ROW: return value ignored
end;
$$;


