CREATE OR REPLACE FUNCTION "public"."trgfn_posts_enforce_author_refs"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
DECLARE
  v_profile_user uuid;
  v_profile_id   uuid;
  v_display      text;
  v_persona      text;
BEGIN
  -- If no author_user_id, nothing we can enforce.
  IF NEW.author_user_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- If a profile is provided, verify it belongs to the same user_id; otherwise clear it.
  IF NEW.author_profile_id IS NOT NULL THEN
    SELECT pr.user_id INTO v_profile_user
    FROM public.profiles pr
    WHERE pr.id = NEW.author_profile_id;

    IF NOT FOUND OR v_profile_user IS DISTINCT FROM NEW.author_user_id THEN
      NEW.author_profile_id := NULL;
    END IF;
  END IF;

  -- If no valid profile yet, pick the user's active profile.
  IF NEW.author_profile_id IS NULL THEN
    SELECT pr.id INTO v_profile_id
    FROM public.profiles pr
    WHERE pr.user_id = NEW.author_user_id
      AND pr.is_active = true
    ORDER BY pr.created_at ASC NULLS LAST
    LIMIT 1;

    IF FOUND THEN
      NEW.author_profile_id := v_profile_id;
    END IF;
  END IF;

  -- Always source display name + persona_type from the profile we ended up with.
  IF NEW.author_profile_id IS NOT NULL THEN
    SELECT pr.display_name, pr.persona_type
      INTO v_display, v_persona
    FROM public.profiles pr
    WHERE pr.id = NEW.author_profile_id;

    NEW.author_display_name   := v_display;
    NEW.persona_type_snapshot := v_persona;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trgfn_posts_enforce_author_refs"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trgfn_posts_fill_author_display_name"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_profile uuid;
  v_display text;
BEGIN
  -- If caller supplied a valid profile for this user, use it directly.
  IF NEW.author_profile_id IS NOT NULL THEN
    SELECT id, display_name
      INTO v_profile, v_display
    FROM public.profiles
    WHERE id = NEW.author_profile_id
      AND user_id = NEW.author_user_id;

    IF v_profile IS NULL THEN
      RAISE EXCEPTION 'author_profile_id does not belong to the calling user';
    END IF;
  ELSE
    -- No profile provided: resolve the active profile for this user.
    SELECT id, display_name
      INTO v_profile, v_display
    FROM public.profiles
    WHERE user_id = NEW.author_user_id
      AND is_active = true
    ORDER BY created_at
    LIMIT 1;

    IF v_profile IS NULL THEN
      RAISE EXCEPTION 'No active profile found for user %', NEW.author_user_id;
    END IF;
  END IF;

  -- Fill / overwrite
  NEW.author_profile_id   := v_profile;
  NEW.author_display_name := COALESCE(NEW.author_display_name, v_display);

  RETURN NEW;
END
$$;


ALTER FUNCTION "public"."trgfn_posts_fill_author_display_name"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trgfn_posts_set_geo"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_geo_id  uuid;
  v_area_id uuid;
  v_lat     double precision;
  v_lng     double precision;
BEGIN
  -- PATH 1: Inherit from venue
  IF NEW.venue_id IS NOT NULL THEN
    SELECT v.geo_location_id, v.area_id,
           ST_Y(gl.location::geometry), ST_X(gl.location::geometry)
    INTO NEW.geo_location_id, NEW.area_id, NEW.geo_lat, NEW.geo_lng
    FROM venues v
    JOIN geo_locations gl ON gl.id = v.geo_location_id
    WHERE v.id = NEW.venue_id;

  -- PATH 2: Inherit from game
  ELSIF NEW.game_id IS NOT NULL THEN
    SELECT g.geo_location_id, g.area_id,
           ST_Y(gl.location::geometry), ST_X(gl.location::geometry)
    INTO NEW.geo_location_id, NEW.area_id, NEW.geo_lat, NEW.geo_lng
    FROM games g
    JOIN geo_locations gl ON gl.id = g.geo_location_id
    WHERE g.id = NEW.game_id;

  -- PATH 3: Manual lat/lng supplied
  ELSIF NEW.geo_lat IS NOT NULL AND NEW.geo_lng IS NOT NULL THEN
    v_lat := NEW.geo_lat;
    v_lng := NEW.geo_lng;

    SELECT id INTO v_area_id
    FROM areas
    ORDER BY ST_Distance(
      ST_SetSRID(ST_MakePoint(v_lng, v_lat), 4326)::geography,
      ST_SetSRID(ST_MakePoint(
        (SELECT ST_X(location::geometry) FROM geo_locations WHERE area_id = areas.id LIMIT 1),
        (SELECT ST_Y(location::geometry) FROM geo_locations WHERE area_id = areas.id LIMIT 1)
      ), 4326)::geography
    )
    LIMIT 1;

    INSERT INTO geo_locations (location, area_id, geohash)
    VALUES (
      ST_SetSRID(ST_MakePoint(v_lng, v_lat), 4326)::geography,
      v_area_id,
      encode(sha256((v_lat::text || ',' || v_lng::text)::bytea), 'hex')
    )
    RETURNING id INTO v_geo_id;

    NEW.geo_location_id := v_geo_id;
    NEW.area_id         := v_area_id;

  -- PATH 4: Fallback to author profile's last known location
  ELSE
    SELECT p.latitude, p.longitude
    INTO v_lat, v_lng
    FROM profiles p
    WHERE p.id = NEW.author_profile_id
      AND p.latitude IS NOT NULL AND p.longitude IS NOT NULL;

    -- PATH 5: Last resort — use the most active area's center
    IF v_lat IS NULL THEN
      SELECT a.center_lat, a.center_lng
      INTO v_lat, v_lng
      FROM areas a
      WHERE a.is_active = true
      ORDER BY a.is_verified DESC, a.id
      LIMIT 1;
    END IF;

    -- Resolve nearest area
    SELECT id INTO v_area_id
    FROM areas
    ORDER BY ST_Distance(
      ST_SetSRID(ST_MakePoint(v_lng, v_lat), 4326)::geography,
      ST_SetSRID(ST_MakePoint(
        (SELECT ST_X(location::geometry) FROM geo_locations WHERE area_id = areas.id LIMIT 1),
        (SELECT ST_Y(location::geometry) FROM geo_locations WHERE area_id = areas.id LIMIT 1)
      ), 4326)::geography
    )
    LIMIT 1;

    INSERT INTO geo_locations (location, area_id, geohash)
    VALUES (
      ST_SetSRID(ST_MakePoint(v_lng, v_lat), 4326)::geography,
      v_area_id,
      encode(sha256((v_lat::text || ',' || v_lng::text)::bytea), 'hex')
    )
    RETURNING id INTO v_geo_id;

    NEW.geo_location_id := v_geo_id;
    NEW.area_id         := v_area_id;
    NEW.geo_lat         := v_lat;
    NEW.geo_lng         := v_lng;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trgfn_posts_set_geo"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trgfn_posts_sync_author_display_name"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "row_security" TO 'off'
    AS $$
DECLARE
  v_name text;
BEGIN
  -- Load the authoritative display_name for this author_profile_id
  SELECT pr.display_name
    INTO v_name
  FROM public.profiles pr
  WHERE pr.id = NEW.author_profile_id;

  IF v_name IS NULL THEN
    RAISE EXCEPTION 'profiles(%): display_name not found for post %', NEW.author_profile_id, NEW.id;
  END IF;

  -- Overwrite any client-provided value to keep it consistent
  IF NEW.author_display_name IS DISTINCT FROM v_name THEN
    NEW.author_display_name := v_name;
  END IF;

  RETURN NEW;
END
$$;


