  -- Only act when the name actually changed
  if tg_op = 'UPDATE' and (new.display_name is distinct from old.display_name) then
    update public.posts
       set author_display_name = new.display_name
     where author_profile_id = new.id
       and (author_display_name is distinct from new.display_name);
  end if;
  return new;
end;
