CREATE OR REPLACE FUNCTION "public"."trgfn_rewards_from_outbox"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  uid   uuid;
  sport text;
begin
  -- Only react to topics we care about right now
  if NEW.topic not in ('game.joined','game.created') then
    return null; -- AFTER trigger: return value is ignored
  end if;

  -- Beneficiary is the actor who joined/created
  uid := NEW.actor_user_id;
  if uid is null then
    return null;
  end if;

  -- Try to infer sport from payload if present
  sport := NEW.payload->>'sport';

  -- Idempotent inside RPC via (user,rule,event) unique index
  perform public.rpc_rewards_apply_event(NEW.id, uid, NEW.topic, sport, NEW.payload);
  return null;
end;
$$;


