CREATE OR REPLACE FUNCTION "public"."trgfn_roster_block_frozen"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  uid uuid;
begin
  -- If user_id isn't set yet, derive it from the profile
  uid := coalesce(
    NEW.user_id,
    (select p.user_id from public.profiles p where p.id = NEW.profile_id)
  );

  -- Guard (raises user_frozen if active freeze)
  perform public.guard_user_not_frozen(uid);
  return NEW;
end;
$$;


