CREATE OR REPLACE FUNCTION "public"."trgfn_roster_set_user_and_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  uid uuid;
begin
  -- Always resolve user_id from profile_id first
  if new.profile_id is not null then
    select user_id into uid from public.profiles where id = new.profile_id;
    if uid is null then
      raise exception using errcode='P0001', message='profile_not_found';
    end if;
    new.user_id := uid;
  else
    uid := new.user_id;
  end if;

  -- Then enforce freeze
  perform public.guard_user_not_frozen(uid);
  return new;
end;
$$;


