CREATE OR REPLACE FUNCTION "public"."trgfn_set_badge_sport_id"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  -- Global badge: no sport
  if new.sport is null then
    new.sport_id := null;
    return new;
  end if;

  -- Resolve sport_id if missing or changed
  if new.sport_id is null
     or new.sport is distinct from old.sport then

    select s.id
    into new.sport_id
    from public.sports s
    where s.sport_key = case
      when lower(trim(new.sport)) = 'paddle' then 'padel'
      else lower(trim(new.sport))
    end
      and s.is_active = true;

    if new.sport_id is null then
      raise exception using
        errcode = 'P0001',
        message = 'invalid_sport';
    end if;
  end if;

  return new;
end;
$$;


