CREATE OR REPLACE FUNCTION "public"."trgfn_set_post_sport_id"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Case 1: sport_id provided but no sport text → fill sport from sports table
  IF NEW.sport IS NULL AND NEW.sport_id IS NOT NULL THEN
    SELECT COALESCE(emoji || ' ', '') || name_en
    INTO NEW.sport
    FROM public.sports
    WHERE id = NEW.sport_id AND is_active = true
    LIMIT 1;

    -- If sport_id doesn't resolve to a valid active sport, clear it
    IF NEW.sport IS NULL THEN
      NEW.sport_id := NULL;
    END IF;

    RETURN NEW;
  END IF;

  -- Case 2: sport text is NULL and no sport_id → clear both
  IF NEW.sport IS NULL THEN
    NEW.sport_id := NULL;
    RETURN NEW;
  END IF;

  -- Case 3: sport text provided → resolve/validate sport_id from sport_key
  IF NEW.sport_id IS NULL OR NEW.sport IS DISTINCT FROM OLD.sport THEN
    SELECT s.id
    INTO NEW.sport_id
    FROM public.sports s
    WHERE s.sport_key = CASE
      WHEN lower(trim(NEW.sport)) = 'paddle' THEN 'padel'
      ELSE lower(trim(NEW.sport))
    END
    AND s.is_active = true;

    IF NEW.sport_id IS NULL THEN
      RAISE EXCEPTION USING
        errcode = 'P0001',
        message = 'invalid_sport';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trgfn_set_post_sport_id"() OWNER TO "postgres";


