    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'INSERT' and new.status='active' then
    perform public.emit_event('squad.member_added','squad', new.squad_id, new.user_id,
      jsonb_build_object('profile_id', new.profile_id, 'role', new.role));
  elsif tg_op = 'UPDATE' and old.status='active' and new.status in ('left','kicked') then
    perform public.emit_event('squad.member_removed','squad', new.squad_id, auth.uid(),
      jsonb_build_object('profile_id', new.profile_id, 'reason', new.status));
  end if;
  return null;
end;
$$;


