  IF NEW.age IS DISTINCT FROM OLD.age
     OR NEW.gender IS DISTINCT FROM OLD.gender THEN

    UPDATE public.profiles
    SET
      age = NEW.age,
      gender = NEW.gender,
      updated_at = now()
    WHERE user_id = NEW.user_id
      AND id <> NEW.id;
  END IF;

  RETURN NEW;
END;
