CREATE OR REPLACE FUNCTION "public"."trgfn_validate_persona_compatibility"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  existing_personas text[];
BEGIN
  SELECT array_agg(profile_type)
  INTO existing_personas
  FROM public.profiles
  WHERE user_id = NEW.user_id
    AND is_active = true;

  -- Player world conflicts
  IF NEW.profile_type = 'player' AND existing_personas && ARRAY['socialiser','hoster'] THEN
    RAISE EXCEPTION 'Cannot add player with socialiser or hoster profile';
  END IF;

  IF NEW.profile_type = 'organiser' AND existing_personas && ARRAY['socialiser','hoster'] THEN
    RAISE EXCEPTION 'Cannot add organiser with socialiser or hoster profile';
  END IF;

  -- Presence world conflicts
  IF NEW.profile_type = 'hoster' AND existing_personas && ARRAY['player','organiser'] THEN
    RAISE EXCEPTION 'Cannot add hoster with player or organiser profile';
  END IF;

  IF NEW.profile_type = 'socialiser' AND existing_personas && ARRAY['player','organiser'] THEN
    RAISE EXCEPTION 'Cannot add socialiser with player or organiser profile';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trgfn_validate_persona_compatibility"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trgfn_validate_setup_variant"() RETURNS "trigger"
    LANGUAGE "plpgsql"
