CREATE OR REPLACE FUNCTION "public"."trgfn_validate_sports_ref_arrays_v2"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  invalid_country text;
  invalid_region text;
begin
  if new.popularity_country_codes is not null then
    select x
    into invalid_country
    from unnest(new.popularity_country_codes) as x
    where not exists (
      select 1
      from public.ref_countries c
      where c.code = x
    )
    limit 1;

    if invalid_country is not null then
      raise exception
        'Invalid value in sports.popularity_country_codes: "%" for sport_key=%',
        invalid_country,
        new.sport_key;
    end if;
  end if;

  if new.primary_sport_country_codes is not null then
    select x
    into invalid_country
    from unnest(new.primary_sport_country_codes) as x
    where not exists (
      select 1
      from public.ref_countries c
      where c.code = x
    )
    limit 1;

    if invalid_country is not null then
      raise exception
        'Invalid value in sports.primary_sport_country_codes: "%" for sport_key=%',
        invalid_country,
        new.sport_key;
    end if;
  end if;

  if new.popularity_region_keys is not null then
    select x
    into invalid_region
    from unnest(new.popularity_region_keys) as x
    where not exists (
      select 1
      from public.ref_regions r
      where r.key_text = x
    )
    limit 1;

    if invalid_region is not null then
      raise exception
        'Invalid value in sports.popularity_region_keys: "%" for sport_key=%',
        invalid_region,
        new.sport_key;
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."trgfn_validate_sports_ref_arrays_v2"() OWNER TO "postgres";


