CREATE OR REPLACE FUNCTION "public"."try_parse_post_time"("p_body" "text") RETURNS timestamp with time zone
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
  with y as (
    select extract(year from now())::int as yr
  ),
  m as (
    -- capture trailing pattern like "Thu Oct 23 12:00"
    select (regexp_match(p_body, '([A-Za-z]{3}\s+[A-Za-z]{3}\s+\d{1,2}\s+\d{2}:\d{2})$'))[1] as tail
  )
  select case
           when m.tail is null then null
           else to_timestamp(m.tail || ' ' || y.yr::text, 'Dy Mon DD HH24:MI YYYY')
                  at time zone 'Asia/Dubai'
         end
  from m, y;
$_$;


ALTER FUNCTION "public"."try_parse_post_time"("p_body" "text") OWNER TO "postgres";


