CREATE OR REPLACE FUNCTION "public"."update_post_comment_count"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE public.posts          SET comment_count = comment_count + 1                WHERE id = NEW.parent_activity_id;
    UPDATE public.published_news SET comment_count = comment_count + 1                WHERE id = NEW.parent_activity_id;
  ELSIF TG_OP = 'DELETE' THEN
    UPDATE public.posts          SET comment_count = GREATEST(comment_count - 1, 0)   WHERE id = OLD.parent_activity_id;
    UPDATE public.published_news SET comment_count = GREATEST(comment_count - 1, 0)   WHERE id = OLD.parent_activity_id;
  END IF;
  RETURN NULL;
END;
$$;


