CREATE OR REPLACE FUNCTION "public"."update_post_visibility"("p_post_id" "uuid", "p_new_visibility" "text", "p_circle_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_post record;
    v_user_id uuid := auth.uid();
BEGIN
    -- 1. Fetch the post and verify ownership
    SELECT id, author_user_id, author_profile_id, visibility
    INTO v_post
    FROM public.posts
    WHERE id = p_post_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Post not found' USING ERRCODE = 'P0002';
    END IF;

    IF v_post.author_user_id != v_user_id THEN
        RAISE EXCEPTION 'Only the post author can change visibility'
            USING ERRCODE = '42501';
    END IF;

    -- 2. Validate new visibility
    IF p_new_visibility NOT IN ('public', 'followers', 'circle') THEN
        RAISE EXCEPTION 'Invalid visibility: %', p_new_visibility
            USING ERRCODE = '22023';
    END IF;

    -- 3. If changing to circle, require a circle_id
    IF p_new_visibility = 'circle' AND p_circle_id IS NULL THEN
        RAISE EXCEPTION 'Circle visibility requires a circle_id'
            USING ERRCODE = '23514';
    END IF;

    -- 4. If changing to circle, verify the circle exists and the author owns it
    IF p_new_visibility = 'circle' THEN
        IF NOT EXISTS (
            SELECT 1 FROM public.circles
            WHERE id = p_circle_id
              AND owner_profile_id = v_post.author_profile_id
        ) THEN
            RAISE EXCEPTION 'Circle not found or not owned by author'
                USING ERRCODE = '42501';
        END IF;
    END IF;

    -- 5. Remove old post_circles rows if changing FROM circle
    IF v_post.visibility = 'circle' THEN
        DELETE FROM public.post_circles WHERE post_id = p_post_id;
    END IF;

    -- 6. Update the visibility
    UPDATE public.posts
    SET visibility = p_new_visibility,
        is_edited = true,
        edited_at = now()
    WHERE id = p_post_id;

    -- 7. If changing TO circle, insert the junction row
    IF p_new_visibility = 'circle' THEN
        INSERT INTO public.post_circles (post_id, circle_id)
        VALUES (p_post_id, p_circle_id)
        ON CONFLICT DO NOTHING;

        -- Ensure author is a member of the circle
        INSERT INTO public.circle_members (circle_id, member_profile_id)
        VALUES (p_circle_id, v_post.author_profile_id)
        ON CONFLICT DO NOTHING;
    END IF;

    -- 8. Return the updated post
    RETURN (
        SELECT to_jsonb(p) FROM public.posts p WHERE p.id = p_post_id
    );
END;
$$;


ALTER FUNCTION "public"."update_post_visibility"("p_post_id" "uuid", "p_new_visibility" "text", "p_circle_id" "uuid") OWNER TO "postgres";


