CREATE OR REPLACE FUNCTION "public"."upsert_area_from_mapbox"("p_name" "text", "p_city" "text", "p_country" "text", "p_lat" double precision, "p_lng" double precision) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_existing_id uuid;
  v_new_id      uuid;
BEGIN
  SELECT id INTO v_existing_id
  FROM public.areas
  WHERE is_active = true
    AND ST_Distance(
      ST_MakePoint(p_lng, p_lat)::geography,
      ST_MakePoint(center_lng, center_lat)::geography
    ) < 500
  ORDER BY ST_Distance(
    ST_MakePoint(p_lng, p_lat)::geography,
    ST_MakePoint(center_lng, center_lat)::geography
  )
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RETURN v_existing_id;
  END IF;

  INSERT INTO public.areas (
    name, city, country, district,
    center_lat, center_lng,
    is_active, is_verified
  ) VALUES (
    p_name, p_city, p_country,
    p_city,  -- district defaults to city until manually curated
    p_lat, p_lng,
    true, false
  )
  RETURNING id INTO v_new_id;

  RETURN v_new_id;
END;
$$;


