CREATE TABLE IF NOT EXISTS "public"."location_tags" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "label" "text" NOT NULL,
    "slug" "text" NOT NULL,
    "country_code" "text",
    "city" "text",
    "neighbourhood" "text",
    "venue_id" "uuid",
    "use_count" integer DEFAULT 0 NOT NULL,
    "last_used_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."location_tags" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_location_tag"("_label" "text", "_venue_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."location_tags"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  _slug text;
  _row public.location_tags;
begin
  _slug := regexp_replace(lower(trim(_label)), '\s+', '-', 'g');

  -- Try update existing
  update public.location_tags
  set use_count   = use_count + 1,
      last_used_at = now()
  where slug = _slug
    and coalesce(venue_id, '00000000-0000-0000-0000-000000000000'::uuid)
      = coalesce(_venue_id, '00000000-0000-0000-0000-000000000000'::uuid)
  returning * into _row;

  if _row.id is not null then
    return _row;
  end if;

  -- Insert new
  insert into public.location_tags (label, slug, venue_id, use_count)
  values (_label, _slug, _venue_id, 1)
  returning * into _row;

  return _row;
end;
$$;


