CREATE OR REPLACE FUNCTION "public"."user_has_feature"("p_user_id" "uuid", "p_feature_key" "text") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM public.user_subscriptions us
        JOIN public.subscription_features sf
            ON sf.plan_key = us.plan_key
        WHERE us.user_id = p_user_id
          AND us.is_active = true
          AND (us.expires_at IS NULL OR us.expires_at > now())
          AND sf.feature_key = p_feature_key
          AND sf.is_enabled = true
    );
$$;


