CREATE OR REPLACE FUNCTION "public"."v_activity_inbox"() RETURNS TABLE("item_type" "text", "title" "text", "action_route" "text", "created_at" timestamp with time zone, "context" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  rec record;
  tbl_reg regclass;
begin
  -- 1) Unread notifications first
  for rec in
    select 'notification'::text as item_type,
           n.title,
           coalesce(n.action_route, '/inbox') as action_route,
           n.created_at,
           n.context
    from public.notifications n
    where n.user_id = auth.uid() and n.is_read = false
    order by n.created_at desc
  loop
    item_type := rec.item_type;
    title := rec.title;
    action_route := rec.action_route;
    created_at := rec.created_at;
    context := rec.context;
    return next;
  end loop;

  -- 2) Friend requests (only if friendships table present)
  tbl_reg := to_regclass('public.friendships');
  if tbl_reg is not null then
    for rec in
      select 'friend.request'::text, 'Vibe Request Sent'::text, '/friends/requests'::text, f.created_at, jsonb_build_object('from_user_id', f.requester_id)
      from public.friendships f
      where f.addressee_id = auth.uid() and f.status = 'pending'
      order by f.created_at desc
    loop
      item_type := rec.column1; title := rec.column2; action_route := rec.column3;
      created_at := rec.column4; context := rec.column5;
      return next;
    end loop;
  end if;

  -- 3) Game invites (if present)
  tbl_reg := to_regclass('public.game_invites');
  if tbl_reg is not null then
    for rec in
      select 'game.invite'::text, 'Game invite'::text, '/game/'||gi.game_id::text, gi.created_at, jsonb_build_object('game_id', gi.game_id, 'from_user_id', gi.from_user_id)
      from public.game_invites gi
      where gi.to_user_id = auth.uid() and gi.status = 'pending'
      order by gi.created_at desc
    loop
      item_type := rec.column1; title := rec.column2; action_route := rec.column3;
      created_at := rec.column4; context := rec.column5;
      return next;
    end loop;
  end if;

  -- 4) Payouts (if present)
  tbl_reg := to_regclass('public.payouts');
  if tbl_reg is not null then
    for rec in
      select 'payout.status'::text, ('Payout '||p.status)::text, '/wallet'::text, p.requested_at, jsonb_build_object('payout_id', p.id, 'status', p.status)
      from public.payouts p
      where p.user_id = auth.uid() and p.status in ('approved','processing','failed')
      order by p.requested_at desc
    loop
      item_type := rec.column1; title := rec.column2; action_route := rec.column3;
      created_at := rec.column4; context := rec.column5;
      return next;
    end loop;
  end if;

  return;
end;
$$;


ALTER FUNCTION "public"."v_activity_inbox"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."v_rewards_leaderboard"("p_sport" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 20) RETURNS TABLE("user_id" "uuid", "points" integer, "level" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select pl.user_id,
         sum(pl.delta)::int as points,
         public.level_for_points(sum(pl.delta)::int) as level
  from public.point_ledger pl
  where (p_sport is null or pl.sport is not distinct from p_sport)
  group by pl.user_id
  order by points desc
  limit greatest(p_limit, 1)
$$;


