CREATE OR REPLACE FUNCTION "public"."validate_venue_submission_status"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Status cannot be NULL
  IF NEW.status IS NULL THEN
    RAISE EXCEPTION 'status cannot be null';
  END IF;

  -- Prevent changing after terminal states
  IF OLD.status IN ('approved', 'rejected', 'revoked')
     AND NEW.status <> OLD.status THEN
    RAISE EXCEPTION 'Cannot change status after %', OLD.status;
  END IF;

  -- Allowed transitions
  IF OLD.status = 'draft' AND NEW.status NOT IN ('draft', 'pending') THEN
    RAISE EXCEPTION 'Invalid transition from draft to %', NEW.status;
  END IF;

  IF OLD.status = 'pending' AND NEW.status NOT IN ('approved', 'returned', 'rejected') THEN
    RAISE EXCEPTION 'Invalid transition from pending to %', NEW.status;
  END IF;

  IF OLD.status = 'approved' AND NEW.status <> 'revoked' THEN
    RAISE EXCEPTION 'Approved submissions can only be revoked';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_venue_submission_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."venue_rating_rebuild_all"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare vid uuid; n int := 0;
begin
  for vid in select id from public.venues loop
    perform public.venue_rating_recompute(vid); n := n + 1;
  end loop;
  return n;
end $$;


