CREATE OR REPLACE FUNCTION "public"."venue_rating_recompute"("p_venue_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  cfg record;
  dim record;
  dim_sum numeric; dim_cnt numeric; dim_mean numeric;
  sum_map jsonb := '{}'::jsonb;
  cnt_map jsonb := '{}'::jsonb;
  comp numeric := 0.0; total_w numeric := 0.0;
  evt_count int;
begin
  select * into cfg from public._get_context_config('venue');

  for dim in select key, weight from public.venue_rating_dimensions where is_active loop
    select
      coalesce(sum( public._clamp_star((e.scores ->> dim.key)::numeric) *
                    public._decay_factor(e.created_at, cfg.half_life_days) ), 0.0),
      coalesce(sum( case when e.scores ? dim.key then public._decay_factor(e.created_at, cfg.half_life_days) else 0 end ), 0.0)
    into dim_sum, dim_cnt
    from public.venue_rating_events e
    where e.venue_id = p_venue_id;

    sum_map := sum_map || jsonb_build_object(dim.key, round(dim_sum::numeric,3));
    cnt_map := cnt_map || jsonb_build_object(dim.key, round(dim_cnt::numeric,3));

    dim_mean := case when (cfg.prior_weight + dim_cnt) > 0
                     then (cfg.prior_mean * cfg.prior_weight + dim_sum) / (cfg.prior_weight + dim_cnt)
                     else cfg.prior_mean
                end;

    comp := comp + coalesce(dim.weight,0.0) * dim_mean;
    total_w := total_w + coalesce(dim.weight,0.0);
  end loop;

  if total_w > 0 then comp := comp / total_w; else comp := coalesce(cfg.prior_mean,4.5); end if;

  select count(*) into evt_count from public.venue_rating_events where venue_id=p_venue_id;

  insert into public.venue_rating_aggregate(venue_id,event_count,dim_sums,dim_counts,composite_score,last_event_at,updated_at)
  values (
    p_venue_id, evt_count, sum_map, cnt_map, round(comp::numeric,2),
    (select max(created_at) from public.venue_rating_events where venue_id=p_venue_id),
    now()
  )
  on conflict (venue_id) do update set
    event_count     = excluded.event_count,
    dim_sums        = excluded.dim_sums,
    dim_counts      = excluded.dim_counts,
    composite_score = excluded.composite_score,
    last_event_at   = excluded.last_event_at,
    updated_at      = excluded.updated_at;
end;
$$;


ALTER FUNCTION "public"."venue_rating_recompute"("p_venue_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vibes_base_candidates"("p_me" "uuid") RETURNS TABLE("other_user_id" "uuid", "other_role" "text", "username" "text", "display_name" "text", "geo_lat" double precision, "geo_lng" double precision, "sport_key" "text", "skill_level" integer)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $_$
declare
  has_sp  boolean;
  has_lat boolean;
  has_lng boolean;
  sql     text;
begin
  if p_me is null then
    raise exception using errcode='P0001', message='me_required';
  end if;

  select to_regclass('public.sport_profiles') is not null into has_sp;
  select exists (select 1 from information_schema.columns where table_schema='public' and table_name='profiles' and column_name='geo_lat') into has_lat;
  select exists (select 1 from information_schema.columns where table_schema='public' and table_name='profiles' and column_name='geo_lng') into has_lng;

  sql := format($q$
    select
      p.user_id                               as other_user_id,
      p.profile_type                          as other_role,
      p.username::text                        as username,
      p.display_name::text                    as display_name,
      %s as geo_lat,
      %s as geo_lng,
      %s as sport_key,
      %s as skill_level
    from public.profiles p
    %s
    where p.user_id <> %L
      and not public._is_hidden(%L, p.user_id)
      and not public.is_benched(p.user_id)
      and not public.is_frozen(p.user_id)
  $q$,
    case when has_lat then 'p.geo_lat' else 'NULL::double precision' end,
    case when has_lng then 'p.geo_lng' else 'NULL::double precision' end,
    case when has_sp  then 'sp.sport_key' else 'NULL::text' end,
    case when has_sp  then 'sp.skill_level' else 'NULL::int' end,
    case when has_sp  then 'left join public.sport_profiles sp on sp.user_id = p.user_id' else '' end,
    p_me, p_me
  );

  return query execute sql;
end
$_$;


