    "profile_type" "text" NOT NULL,
    "username" "public"."citext" NOT NULL,
    "display_name" "text" NOT NULL,
    "bio" "text",
    "avatar_url" "text" DEFAULT ''::"text",
    "city" "text",
    "country" "text" DEFAULT 'UAE'::"text",
    "language" "text" DEFAULT 'en'::"text",
    "verified" boolean DEFAULT false,
    "is_active" boolean DEFAULT true,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "intention" "text" DEFAULT 'Social'::"text" NOT NULL,
    "gender" "text",
    "age" integer NOT NULL,
    "search_tsv" "tsvector",
    "is_player" boolean DEFAULT true,
    "skill_level" integer,
    "onboard" boolean DEFAULT true NOT NULL,
    "last_location_updated_at" timestamp with time zone,
    "latitude" double precision,
    "longitude" double precision,
    "persona_type" "text" NOT NULL,
    "profile_completion" "text",
    "last_seen" timestamp with time zone,
    "hashtag_reputation_score" numeric DEFAULT 0 NOT NULL,
    "preferred_sport" "uuid",
    "primary_sport" "uuid",
    "interests" "uuid"[],
    "is_original" boolean DEFAULT true NOT NULL,
    "news" boolean DEFAULT true NOT NULL,
    CONSTRAINT "profiles_display_name_check" CHECK ((("char_length"("display_name") >= 2) AND ("char_length"("display_name") <= 50))),
    CONSTRAINT "profiles_persona_type_check" CHECK (("persona_type" = ANY (ARRAY['player'::"text", 'organiser'::"text", 'host'::"text", 'socialiser'::"text"]))),
    CONSTRAINT "profiles_primary_sport_required_for_sport_personas" CHECK ((("persona_type" = 'socialiser'::"text") OR ("primary_sport" IS NOT NULL))),
    CONSTRAINT "profiles_profile_type_check" CHECK (("profile_type" = ANY (ARRAY['personal'::"text", 'business'::"text", 'venue'::"text", 'team'::"text", 'organisation'::"text"])))
);


ALTER TABLE "public"."profiles" OWNER TO "postgres";


COMMENT ON TABLE "public"."profiles" IS 'Represents a Player or Organiser profile. Each user may have one of each type.';



COMMENT ON COLUMN "public"."profiles"."user_id" IS 'FK to auth.users; immutable anchor for all user activity.';



COMMENT ON COLUMN "public"."profiles"."profile_type" IS 'Defines the role context: player or organiser.';



COMMENT ON COLUMN "public"."profiles"."is_active" IS 'False when profile is benched (hidden from community but still usable for sports features).';



