CREATE OR REPLACE VIEW "public"."published_news" WITH ("security_invoker"='true') AS
 SELECT "id",
    "title",
    "body",
    "cover_image_url",
    "media",
    "source_url",
    "source_label",
    "kind",
    "origin",
    "status",
    "sport_id",
    "area_id",
    "tags",
    "show_in_feed",
    "feed_label",
    "is_pinned",
    "priority_score",
    "published_at",
    "expires_at",
    "like_count",
    "view_count",
    "comment_count",
    "created_by",
    "created_at",
    "updated_at"
   FROM "public"."news"
  WHERE (("status" = 'published'::"public"."news_status_enum") AND ("published_at" <= "now"()) AND (("expires_at" IS NULL) OR ("expires_at" > "now"())));


ALTER VIEW "public"."published_news" OWNER TO "postgres";


