CREATE OR REPLACE VIEW "public"."v_autocomplete_internal_checks" AS
 WITH "p" AS (
         SELECT "profiles"."id",
            "profiles"."username",
            "profiles"."display_name",
            "lower"("public"."unaccent_immutable"(("profiles"."username")::"text")) AS "norm_username",
            "lower"("public"."unaccent_immutable"("profiles"."display_name")) AS "norm_display"
           FROM "public"."profiles"
         LIMIT 20
        ), "v" AS (
         SELECT "venues"."id",
            "venues"."name_en",
            "venues"."name_ar",
            "lower"("public"."unaccent_immutable"("venues"."name_en")) AS "norm_en",
            "lower"("public"."unaccent_immutable"("venues"."name_ar")) AS "norm_ar"
           FROM "public"."venues"
         LIMIT 20
        ), "s" AS (
         SELECT "squads"."id",
            "squads"."name",
            "lower"("public"."unaccent_immutable"("squads"."name")) AS "norm_name"
           FROM "public"."squads"
         LIMIT 20
        )
 SELECT 'profiles'::"text" AS "source",
    "p"."id",
    "p"."norm_username" AS "normalized",
    "p"."username" AS "raw"
   FROM "p"
UNION ALL
 SELECT 'profiles'::"text" AS "source",
    "p"."id",
    "p"."norm_display" AS "normalized",
    "p"."display_name" AS "raw"
   FROM "p"
UNION ALL
 SELECT 'venues'::"text" AS "source",
    "v"."id",
    "v"."norm_en" AS "normalized",
    "v"."name_en" AS "raw"
   FROM "v"
UNION ALL
 SELECT 'venues'::"text" AS "source",
    "v"."id",
    "v"."norm_ar" AS "normalized",
    "v"."name_ar" AS "raw"
   FROM "v"
UNION ALL
 SELECT 'squads'::"text" AS "source",
    "s"."id",
    "s"."norm_name" AS "normalized",
    "s"."name" AS "raw"
   FROM "s";


ALTER VIEW "public"."v_autocomplete_internal_checks" OWNER TO "postgres";


