    ( SELECT "count"(*) AS "count"
           FROM "public"."challenge_squads" "cs"
          WHERE (("cs"."challenge_id" = "c"."id") AND ("cs"."status" = 'active'::"text"))) AS "squads_count",
    "public"."can_view_with_scope"("auth"."uid"(), "c"."owner_user_id", "c"."listing_visibility", NULL::"uuid") AS "is_visible_to_you"
