  WHERE ("c"."is_active" = true);


ALTER VIEW "public"."v_challenge_card" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_challenge_standings" AS
 WITH "rr" AS (
         SELECT "f"."challenge_id",
            "s"."id" AS "squad_id",
            "s"."name" AS "squad_name",
            "sum"((
                CASE
                    WHEN (("f"."status" = 'completed'::"text") AND ("f"."home_squad_id" = "s"."id")) THEN COALESCE("f"."home_score", 0)
                    ELSE 0
                END +
                CASE
                    WHEN (("f"."status" = 'completed'::"text") AND ("f"."away_squad_id" = "s"."id")) THEN COALESCE("f"."away_score", 0)
                    ELSE 0
                END)) AS "goals_for",
            "sum"((
                CASE
                    WHEN (("f"."status" = 'completed'::"text") AND ("f"."home_squad_id" = "s"."id")) THEN COALESCE("f"."away_score", 0)
                    ELSE 0
                END +
                CASE
                    WHEN (("f"."status" = 'completed'::"text") AND ("f"."away_squad_id" = "s"."id")) THEN COALESCE("f"."home_score", 0)
                    ELSE 0
                END)) AS "goals_against",
            "sum"(
                CASE
                    WHEN (("f"."status" = 'completed'::"text") AND ("f"."winner_squad_id" = "s"."id")) THEN 1
                    ELSE 0
                END) AS "wins",
            "sum"(
                CASE
                    WHEN (("f"."status" = 'completed'::"text") AND ("f"."winner_squad_id" IS NULL) AND (("f"."home_squad_id" = "s"."id") OR ("f"."away_squad_id" = "s"."id"))) THEN 1
                    ELSE 0
                END) AS "draws",
            "sum"(
                CASE
                    WHEN (("f"."status" = 'completed'::"text") AND ("f"."winner_squad_id" IS NOT NULL) AND ("f"."winner_squad_id" <> "s"."id") AND (("f"."home_squad_id" = "s"."id") OR ("f"."away_squad_id" = "s"."id"))) THEN 1
                    ELSE 0
                END) AS "losses"
           FROM ("public"."challenge_fixtures" "f"
             JOIN "public"."squads" "s" ON ((("s"."id" = "f"."home_squad_id") OR ("s"."id" = "f"."away_squad_id"))))
          GROUP BY "f"."challenge_id", "s"."id", "s"."name"
        ), "pts" AS (
         SELECT "rr"."challenge_id",
            "rr"."squad_id",
            "rr"."squad_name",
            "rr"."goals_for",
            "rr"."goals_against",
            "rr"."wins",
            "rr"."draws",
            "rr"."losses",
            ( SELECT (("c"."rules" ->> 'points_win'::"text"))::integer AS "int4"
                   FROM "public"."challenges" "c"
                  WHERE ("c"."id" = "rr"."challenge_id")) AS "p_win",
            ( SELECT (("c"."rules" ->> 'points_draw'::"text"))::integer AS "int4"
                   FROM "public"."challenges" "c"
                  WHERE ("c"."id" = "rr"."challenge_id")) AS "p_draw",
            ( SELECT (("c"."rules" ->> 'points_loss'::"text"))::integer AS "int4"
                   FROM "public"."challenges" "c"
                  WHERE ("c"."id" = "rr"."challenge_id")) AS "p_loss"
           FROM "rr"
        )
 SELECT "challenge_id",
    "squad_id",
    "squad_name",
    "wins",
    "draws",
    "losses",
    "goals_for",
    "goals_against",
    ("goals_for" - "goals_against") AS "goal_diff",
    ((("wins" * "p_win") + ("draws" * "p_draw")) + ("losses" * "p_loss")) AS "points"
   FROM "pts"
  ORDER BY "challenge_id", ((("wins" * "p_win") + ("draws" * "p_draw")) + ("losses" * "p_loss")) DESC, ("goals_for" - "goals_against") DESC, "goals_for" DESC, "squad_name";


ALTER VIEW "public"."v_challenge_standings" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_circle_feed" WITH ("security_invoker"='on') AS
 SELECT "p"."id",
    "p"."author_profile_id",
