    "p"."body",
    "p"."visibility",
    "p"."created_at",
    "c"."id" AS "circle_id",
    "c"."name" AS "circle_name",
    "c"."circle_type",
    "public"."circle_member_count"("c"."id") AS "circle_members_count"
   FROM (("public"."posts" "p"
     JOIN "public"."post_circles" "pc" ON (("pc"."post_id" = "p"."id")))
     JOIN "public"."circles" "c" ON (("c"."id" = "pc"."circle_id")))
  WHERE (("p"."visibility" = 'circle'::"text") AND ("p"."is_deleted" = false) AND ("p"."is_hidden_admin" = false) AND ("p"."is_active" = true));


