CREATE OR REPLACE VIEW "public"."v_circle_feed_visible" WITH ("security_invoker"='on') AS
 SELECT "id",
    "author_profile_id",
    "author_user_id",
    "author_display_name",
    "body",
    "visibility",
    "created_at",
    "circle_id",
    "circle_name",
    "circle_type",
    "circle_members_count"
   FROM "public"."v_circle_feed" "f"
  WHERE ((EXISTS ( SELECT 1
           FROM "public"."circle_members" "cm"
          WHERE (("cm"."circle_id" = "f"."circle_id") AND ("cm"."member_profile_id" = (NULLIF("current_setting"('request.jwt.claim.profile_id'::"text", true), ''::"text"))::"uuid")))) OR ("circle_type" = 'public'::"text") OR (("circle_type" = 'followers'::"text") AND (EXISTS ( SELECT 1
           FROM "public"."profile_follows" "pf"
          WHERE (("pf"."follower_profile_id" = (NULLIF("current_setting"('request.jwt.claim.profile_id'::"text", true), ''::"text"))::"uuid") AND ("pf"."following_profile_id" = "f"."author_profile_id"))))))
  ORDER BY "created_at" DESC;


