     LEFT JOIN "public"."profiles" "tp" ON ((("tp"."user_id" = "mr"."target_user_id") AND ("tp"."profile_type" = 'player'::"text"))))
  WHERE (("mr"."status" = ANY (ARRAY['open'::"public"."report_status", 'triage'::"public"."report_status", 'escalated'::"public"."report_status"])) AND "public"."is_admin"("auth"."uid"()))
