CREATE OR REPLACE VIEW "public"."v_moderation_metrics" AS
 SELECT ( SELECT "count"(*) AS "count"
           FROM "auth"."users") AS "total_users",
    ( SELECT "count"(*) AS "count"
           FROM "public"."user_freezes"
          WHERE "user_freezes"."is_active") AS "users_frozen",
    ( SELECT "count"(*) AS "count"
           FROM "public"."moderation_tickets"
          WHERE ("moderation_tickets"."status" = ANY (ARRAY['open'::"text", 'reviewing'::"text"]))) AS "tickets_open",
    ( SELECT "count"(*) AS "count"
           FROM "public"."moderation_tickets"
          WHERE (("moderation_tickets"."status" = 'resolved'::"text") AND ("moderation_tickets"."created_at" >= ("now"() - '7 days'::interval)))) AS "tickets_resolved_7d",
    ( SELECT "count"(*) AS "count"
           FROM "public"."moderation_flags"
          WHERE (("moderation_flags"."severity" = ANY (ARRAY['hide'::"text", 'block'::"text"])) AND ("moderation_flags"."created_at" >= ("now"() - '7 days'::interval)))) AS "autoflags_last7";


