CREATE OR REPLACE VIEW "public"."v_rateable_after_game" AS
 WITH "ctx" AS (
         SELECT "g"."id" AS "game_id",
            "g"."creator_user_id" AS "host_user_id",
            "g"."end_at"
           FROM "public"."games" "g"
        )
 SELECT "c"."game_id",
    "rr"."user_id" AS "you_user_id",
    "r"."user_id" AS "ratee_user_id",
        CASE
            WHEN ("r"."user_id" = ( SELECT "ctx"."host_user_id"
               FROM "ctx"
              WHERE ("ctx"."game_id" = "c"."game_id"))) THEN 'organiser'::"text"
            ELSE 'player'::"text"
        END AS "ratee_role"
   FROM (("ctx" "c"
     JOIN "public"."game_roster" "rr" ON ((("rr"."game_id" = "c"."game_id") AND ("rr"."status" = 'active'::"text") AND ("rr"."user_id" = "auth"."uid"()))))
     JOIN "public"."game_roster" "r" ON ((("r"."game_id" = "c"."game_id") AND ("r"."status" = 'active'::"text"))))
  WHERE (("r"."user_id" <> "auth"."uid"()) OR (( SELECT "ctx"."host_user_id"
           FROM "ctx"
          WHERE ("ctx"."game_id" = "c"."game_id")) <> "auth"."uid"()));


ALTER VIEW "public"."v_rateable_after_game" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_recreate_candidates" AS
 WITH "personal" AS (
         SELECT "rus"."user_id",
            "rus"."context",
            "rus"."version",
            "rus"."fingerprint_hash",
            "rus"."use_count",
            "rus"."last_used_at",
            "rus"."last_payload",
            GREATEST(0.0, (1.0 - ((EXTRACT(epoch FROM ("now"() - "rus"."last_used_at")) / 86400.0) / 30.0))) AS "recency_factor"
           FROM "public"."reuse_user_stats" "rus"
          WHERE ("rus"."user_id" = "auth"."uid"())
        ), "global" AS (
         SELECT "reuse_global_stats"."context",
            "reuse_global_stats"."version",
            "reuse_global_stats"."fingerprint_hash",
            ("reuse_global_stats"."use_count")::numeric AS "g_uses"
           FROM "public"."reuse_global_stats"
        ), "joined" AS (
         SELECT "p"."context",
            "p"."version",
            "p"."fingerprint_hash",
            COALESCE("p"."use_count", 0) AS "p_uses",
            "p"."recency_factor",
            COALESCE("g"."g_uses", (0)::numeric) AS "g_uses",
            "p"."last_payload"
           FROM ("personal" "p"
             LEFT JOIN "global" "g" ON ((("g"."context" = "p"."context") AND ("g"."version" = "p"."version") AND ("g"."fingerprint_hash" = "p"."fingerprint_hash"))))
        )
 SELECT "context",
    "version",
    "fingerprint_hash",
    "last_payload" AS "suggested_payload",
    ((0.7 * (LEAST(1.0, (("p_uses")::numeric / 5.0)) * (0.5 + (0.5 * "recency_factor")))) + (0.3 * LEAST(1.0, ("g_uses" / 20.0)))) AS "score"
   FROM "joined" "j"
  ORDER BY ((0.7 * (LEAST(1.0, (("p_uses")::numeric / 5.0)) * (0.5 + (0.5 * "recency_factor")))) + (0.3 * LEAST(1.0, ("g_uses" / 20.0)))) DESC, "recency_factor" DESC, "p_uses" DESC, "g_uses" DESC;


ALTER VIEW "public"."v_recreate_candidates" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_recreate_quickpicks" AS
 SELECT ("suggested_payload" ->> 'sport'::"text") AS "sport",
    ("suggested_payload" ->> 'venue_space_id'::"text") AS "venue_space_id",
    ("suggested_payload" ->> 'capacity'::"text") AS "capacity",
    ("suggested_payload" ->> 'listing_visibility'::"text") AS "listing_visibility",
    ("suggested_payload" ->> 'join_policy'::"text") AS "join_policy",
    "suggested_payload",
    "score"
   FROM "public"."rpc_recreate_suggestions"('game'::"text", NULL::"text", 6) "rc"("suggested_payload", "score")
  ORDER BY "score" DESC;


ALTER VIEW "public"."v_recreate_quickpicks" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_reliable_teammate_candidates" AS
 WITH "cfg" AS (
         SELECT COALESCE(( SELECT (("badge_rules"."params" ->> 'window_days'::"text"))::integer AS "int4"
                   FROM "public"."badge_rules"
                  WHERE ("badge_rules"."badge_key" = 'reliable_teammate'::"text")
                 LIMIT 1), 90) AS "window_days",
            COALESCE(( SELECT (("badge_rules"."params" ->> 'min_count'::"text"))::integer AS "int4"
                   FROM "public"."badge_rules"
                  WHERE ("badge_rules"."badge_key" = 'reliable_teammate'::"text")
                 LIMIT 1), 8) AS "min_count",
            COALESCE(( SELECT (("badge_rules"."params" ->> 'min_avg'::"text"))::numeric AS "numeric"
                   FROM "public"."badge_rules"
                  WHERE ("badge_rules"."badge_key" = 'reliable_teammate'::"text")
                 LIMIT 1), 4.6) AS "min_avg"
        ), "agg" AS (
         SELECT "e"."ratee_user_id" AS "user_id",
            "round"("avg"((("e"."scores" ->> 'reliability'::"text"))::numeric), 3) AS "avg_score",
            "count"(*) FILTER (WHERE ("e"."scores" ? 'reliability'::"text")) AS "ratings_count"
           FROM "public"."user_reputation_events" "e",
            "cfg" "cfg_1"
          WHERE ("e"."created_at" >= ("now"() - ((( SELECT "cfg_2"."window_days"
                   FROM "cfg" "cfg_2") || ' days'::"text"))::interval))
          GROUP BY "e"."ratee_user_id"
        )
 SELECT "agg"."user_id",
    "agg"."avg_score",
    "agg"."ratings_count",
    "cfg"."window_days",
    "cfg"."min_count",
    "cfg"."min_avg"
   FROM "agg",
    "cfg"
  WHERE (("agg"."ratings_count" >= "cfg"."min_count") AND ("agg"."avg_score" >= "cfg"."min_avg"));


ALTER VIEW "public"."v_reliable_teammate_candidates" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_reputation_leaderboard" AS
 SELECT "ratee_user_id" AS "user_id",
    "round"("avg"((("scores" ->> 'sportsmanship'::"text"))::numeric), 2) AS "sportsmanship_avg",
    "round"("avg"((("scores" ->> 'reliability'::"text"))::numeric), 2) AS "reliability_avg",
    "count"(*) AS "ratings_count"
   FROM "public"."user_reputation_events" "e"
  WHERE ("created_at" > ("now"() - '90 days'::interval))
  GROUP BY "ratee_user_id"
  ORDER BY ("count"(*)) DESC;


