CREATE OR REPLACE VIEW "public"."v_safety_overview" AS
 SELECT ( SELECT "count"(*) AS "count"
           FROM "public"."moderation_reports"
          WHERE ("moderation_reports"."status" = ANY (ARRAY['open'::"public"."report_status", 'triage'::"public"."report_status", 'escalated'::"public"."report_status"]))) AS "reports_open",
    ( SELECT "count"(*) AS "count"
           FROM "public"."moderation_actions"
          WHERE (("moderation_actions"."action" = ANY (ARRAY['freeze'::"public"."mod_action", 'shadowban'::"public"."mod_action", 'ban'::"public"."mod_action"])) AND (("moderation_actions"."expires_at" IS NULL) OR ("moderation_actions"."expires_at" > "now"())))) AS "active_enforcements",
    ( SELECT "count"(*) AS "count"
           FROM "public"."safety_takedowns") AS "takedowns_active",
    ( SELECT "count"(*) AS "count"
           FROM "public"."audit_events"
          WHERE ("audit_events"."created_at" > ("now"() - '24:00:00'::interval))) AS "audits_24h",
    "now"() AS "as_of"
  WHERE "public"."is_admin"("auth"."uid"());


