    "sp"."name_ar" AS "sport_name_ar",
    "sp"."emoji" AS "sport_emoji",
    "vs"."sport_variant_keys",
    ( SELECT "jsonb_agg"("jsonb_build_object"('id', "sv"."id", 'variant_key', "sv"."variant_key", 'name_en', "sv"."name_en", 'name_ar', "sv"."name_ar", 'required_players', "sv"."required_players", 'players_per_side', "sv"."players_per_side")) AS "jsonb_agg"
           FROM "public"."sport_variants" "sv"
