CREATE OR REPLACE VIEW "public"."v_top_hosts_week" AS
 WITH "w" AS (
         SELECT (EXTRACT(isoyear FROM "now"()))::integer AS "isoy_now",
            (EXTRACT(week FROM "now"()))::integer AS "isow_now",
            (EXTRACT(isoyear FROM ("now"() + '7 days'::interval)))::integer AS "isoy_next",
            (EXTRACT(week FROM ("now"() + '7 days'::interval)))::integer AS "isow_next"
        )
 SELECT "m"."user_id",
    "m"."isoy",
    "m"."isow",
    "m"."games_hosted",
    "m"."fill_rate",
    "dense_rank"() OVER (ORDER BY "m"."fill_rate" DESC, "m"."games_hosted" DESC) AS "rank"
   FROM "public"."v_host_weekly_metrics" "m",
    "w"
  WHERE ((("m"."isoy" = "w"."isoy_now") AND ("m"."isow" = "w"."isow_now")) OR (("m"."isoy" = "w"."isoy_next") AND ("m"."isow" = "w"."isow_next")))
  ORDER BY ("dense_rank"() OVER (ORDER BY "m"."fill_rate" DESC, "m"."games_hosted" DESC));


ALTER VIEW "public"."v_top_hosts_week" OWNER TO "postgres";


