    "a"."city",
    COALESCE("a"."name", "v"."area") AS "area",
    "v"."is_active",
    "vs"."indoor" AS "is_indoor",
    "min"("vs"."price_per_hour") AS "price_per_hour",
    "v"."lat" AS "latitude",
    "v"."lng" AS "longitude",
    "v"."address_en" AS "address",
    "v"."phone" AS "phone_number",
    "v"."description_en" AS "description",
