    "v"."app_rating" AS "composite_score",
    "v"."created_at"
   FROM (("public"."venues" "v"
     JOIN "public"."venue_spaces" "vs" ON ((("vs"."venue_id" = "v"."id") AND ("vs"."is_active" = true))))
     LEFT JOIN "public"."areas" "a" ON (("a"."id" = "v"."area_id")))
  GROUP BY "v"."id", "vs"."sport_id", "v"."name_en", "v"."name_ar", "a"."city", "a"."name", "v"."area", "v"."is_active", "vs"."indoor", "v"."lat", "v"."lng", "v"."address_en", "v"."phone", "v"."description_en", "v"."amenities", "v"."app_rating", "v"."created_at";


