    "owner_type" "text",
    "id" "uuid" DEFAULT "gen_random_uuid"(),
    "owner_id" "uuid" NOT NULL,
    CONSTRAINT "wallets_owner_type_valid" CHECK (("owner_type" = ANY (ARRAY['user'::"text", 'venue'::"text", 'platform'::"text"])))
);


ALTER TABLE "public"."wallets" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_wallet_admin_overview" AS
 SELECT ( SELECT "count"(*) AS "count"
           FROM "auth"."users") AS "users_total",
    ( SELECT "count"(*) AS "count"
           FROM "public"."wallets"
          WHERE ("wallets"."balance_aed" > (0)::numeric)) AS "wallets_with_balance",
    ( SELECT COALESCE("sum"("wallets"."balance_aed"), (0)::numeric) AS "coalesce"
           FROM "public"."wallets") AS "total_liability_aed",
    ( SELECT "count"(*) AS "count"
           FROM "public"."payouts"
          WHERE ("payouts"."status" = ANY (ARRAY['requested'::"public"."payout_status", 'approved'::"public"."payout_status", 'processing'::"public"."payout_status"]))) AS "payouts_open",
    ( SELECT COALESCE("sum"("payouts"."amount_aed"), (0)::numeric) AS "coalesce"
           FROM "public"."payouts"
          WHERE ("payouts"."status" = ANY (ARRAY['requested'::"public"."payout_status", 'approved'::"public"."payout_status", 'processing'::"public"."payout_status"]))) AS "payouts_open_aed",
    ( SELECT "count"(*) AS "count"
           FROM "public"."game_settlements"
          WHERE ("game_settlements"."status" = 'pending'::"public"."settlement_status")) AS "settlements_pending",
    "now"() AS "as_of";


ALTER VIEW "public"."v_wallet_admin_overview" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_wallet_balance" AS
 SELECT "w"."id" AS "wallet_id",
    "w"."owner_type",
    "w"."owner_id",
    "w"."currency",
    COALESCE("sum"(
        CASE "l"."entry_type"
            WHEN 'credit'::"text" THEN "l"."amount"
            WHEN 'debit'::"text" THEN (- "l"."amount")
            ELSE NULL::numeric
        END), (0)::numeric) AS "balance"
   FROM ("public"."wallets" "w"
     LEFT JOIN "public"."financial_ledger" "l" ON (("l"."wallet_id" = "w"."id")))
  GROUP BY "w"."id", "w"."owner_type", "w"."owner_id", "w"."currency";


ALTER VIEW "public"."v_wallet_balance" OWNER TO "postgres";


